# 32b. Proving forensic time: source vs derived order, explained correlation
# ══════════════════════════════════════════════════════════════════════════


@dataclass(frozen=True)
class TimelineCheck:
    """One claim about timelines and correlation, and the evidence for it."""

    name: str
    ok: bool
    detail: str = ""


def _correlation_demo_records() -> list[CorrelationRecord]:
    """Six records: three that genuinely overlap, two that only look alike, one alone."""

    kinds = IndicatorKind
    return [
        CorrelationRecord.from_pairs(
            "rec-advisory", [(kinds.DOMAIN, "evil.example.org"),
                             (kinds.HASH, "a" * 64),
                             (kinds.EMAIL, "analyst@gmail.com"),
                             (kinds.IP, "10.0.0.5")],
            label="vendor advisory", source="https://example.com/advisory"),
        CorrelationRecord.from_pairs(
            "rec-mirror", [(kinds.DOMAIN, "EVIL.example.org."),
                           (kinds.HASH, "a" * 64)],
            label="mirror of the advisory", source="https://mirror.example.net/a"),
        CorrelationRecord.from_pairs(
            "rec-mail", [(kinds.EMAIL, "analyst@gmail.com")],
            label="mail header", source="share://mail.eml"),
        CorrelationRecord.from_pairs(
            "rec-scan", [(kinds.DOMAIN, "evil.example.org"), (kinds.IP, "10.0.0.5"),
                         (kinds.USERNAME, "admin")],
            label="proxy log", source="share://proxy.log"),
        CorrelationRecord.from_pairs(
            "rec-index-a", [(kinds.FILENAME, "index.html")],
            label="fetched page", source="https://a.example/index.html"),
        CorrelationRecord.from_pairs(
            "rec-index-b", [(kinds.FILENAME, "index.html")],
            label="another page", source="https://b.example/index.html"),
    ]


def _timeline_demo_events() -> list[TimelineEvent]:
    """Five events: two of them at the same instant, in different zones."""

    return [
        TimelineEvent(label="proxy log: CONNECT to evil.example.org",
                      at=parse_timestamp("2026-05-04T12:00:00+02:00"),
                      source="share://proxy.log", kind="log-line"),
        TimelineEvent(label="DNS query for evil.example.org",
                      at=parse_timestamp("2026-05-04T10:00:00Z"),
                      source="share://dns.log", kind="log-line"),
        TimelineEvent(label="advisory published",
                      at=parse_timestamp("04 May 2026 09:30 +0000"),
                      source="https://example.com/advisory", kind="publication"),
        TimelineEvent(label="document created",
                      at=parse_timestamp("2026-05-03T23:00:00-05:00"),
                      source="share://report.docx", kind="document-created"),
        TimelineEvent(label="timeline built",
                      at=parse_timestamp("2026-05-04T10:00:00Z",
                                         origin=TimestampOrigin.DERIVED),
                      source="this tool", kind="case-access"),
        TimelineEvent(label="undated note",
                      at=parse_timestamp("undated"), source="share://note.txt"),
    ]


def timeline_demo() -> dict[str, Any]:
    """A timeline, a correlation and a de-duplication, run for the record."""

    timeline = build_timeline(_timeline_demo_events(), title="case timeline")
    correlation = correlate_records(_correlation_demo_records())
    fixture = _artifact_fixture()
    try:
        # A renamed copy of one artefact, so the demo shows a duplicate group rather
        # than only the look-alikes that de-duplication refuses to merge.
        original = fixture.evidence / "notes.txt"
        (fixture.evidence / "notes-copy.txt").write_bytes(original.read_bytes())
        case = ArtifactCase(roots=[str(fixture.evidence)], case_dir=fixture.case_dir)
        manifest = case.walk(str(fixture.evidence))
        duplicates = deduplicate_manifest(manifest)
        artifact_timeline = timeline_from_manifest(manifest)
    finally:
        fixture.cleanup()
    return {
        "timeline": timeline.to_dict(),
        "correlation": correlation.to_dict(),
        "deduplication": duplicates.to_dict(),
        "artifact_timeline": artifact_timeline.to_dict(),
        "events": [event.to_dict() for event in timeline.events],
    }


def render_correlation_report(report: CorrelationReport) -> Group:
    """The links of one correlation, and the near-misses they left out.

    Separate from the demo renderer so ``timeline --record`` can show a correlation
    without an empty timeline table above it.
    """

    links = Table(title="correlation — every link carries its reason",
                  title_justify="left", box=None, pad_edge=False)
    links.add_column("pair", no_wrap=True)
    links.add_column("strength", no_wrap=True)
    links.add_column("explanation", overflow="fold", max_width=64)
    for link in report.links:
        colour = {"strong": "green", "moderate": "yellow"}.get(link.strength, "dim")
        links.add_row(escape(f"{link.left} ↔ {link.right}"),
                      f"[{colour}]{escape(link.strength)}[/{colour}]",
                      escape(link.explanation[:200]))
    if not report.links:
        links.add_row("—", "[dim]none[/dim]",
                      "[dim]no two records share a decisive indicator[/dim]")
    near = Text("not linked — the coincidence is the better explanation:\n"
                + "\n".join(f"  · {line[:160]}" for line in report.near_misses)
                if report.near_misses else "", style="dim")
    return Group(links, near, Text(f"\n{report.describe()}\n" + "\n".join(
        f"  · {rule}" for rule in report.rules)
        + "\na shared indicator explains a comparison; it never names a person",
        style="dim"))


def render_timeline_demo(payload: Mapping[str, Any]) -> Group:
    """The demo on screen: the order, the reason for it, and the links with sentences."""

    timeline = payload["timeline"]
    table = Table(title=f"timeline — {timeline.get('title', '')}", title_justify="left",
                  box=None, pad_edge=False)
    table.add_column("#", no_wrap=True)
    table.add_column("instant (UTC)", no_wrap=True)
    table.add_column("certainty", no_wrap=True)
    table.add_column("placed by", no_wrap=True)
    table.add_column("event", overflow="fold", max_width=34)
    for item in payload.get("events") or []:
        basis = item["ordering_basis"]
        colour = {"source-timestamp": "green", "tie-break": "yellow",
                  "derived": "cyan", "undated": "red"}.get(basis, "white")
        table.add_row(
            str(item["sequence"]),
            escape((item["at"]["utc"] or "—")[:19].replace("T", " ")),
            escape(item["at"]["certainty"]),
            f"[{colour}]{escape(basis)}[/{colour}]",
            escape(f"{item['label'][:60]} [{item['source'][:28]}]"))

    correlation = payload["correlation"]
    links = Table(title="correlation — every link carries its reason",
                  title_justify="left", box=None, pad_edge=False)
    links.add_column("pair", no_wrap=True)
    links.add_column("strength", no_wrap=True)
    links.add_column("explanation", overflow="fold", max_width=64)
    for item in correlation.get("links") or []:
        colour = {"strong": "green", "moderate": "yellow"}.get(item["strength"], "dim")
        links.add_row(escape(f"{item['left']} ↔ {item['right']}"),
                      f"[{colour}]{escape(item['strength'])}[/{colour}]",
                      escape(item["explanation"][:170]))
    near = Text("\nnot linked — the coincidence is the better explanation:\n"
                + "\n".join(f"  · {line[:150]}"
                            for line in correlation.get("near_misses") or [])
                if correlation.get("near_misses") else "", style="dim")

    duplicates = payload["deduplication"]
    dedup = Text(
        f"\nduplicate evidence: {duplicates.get('describe', '')}\n"
        + "\n".join(f"  · {line[:140]}" for line in duplicates.get("distinct") or []),
        style="dim")
    summary = Text(
        f"\n{timeline.get('describe', '')}\n"
        f"{correlation.get('describe', '')}\n"
        "a shared indicator explains a comparison; it never names a person",
        style="dim")
    return Group(table, Text(""), links, near, dedup, summary)


def render_timeline_self_test(checks: Sequence[Any]) -> Any:
    table = Table(title="timeline self-test", title_justify="left", box=None,
                  pad_edge=False)
    table.add_column("", width=2)
    table.add_column("check", no_wrap=True)
    table.add_column("detail", overflow="fold")
    for check in checks:
        glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
        table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                      escape(check.detail))
    return table


def run_timeline_self_test() -> list[TimelineCheck]:
    """Prove the two acceptance clauses, and the machinery behind each.

    Clause one: the timeline distinguishes *source* timestamps from this tool's
    *derived ordering* — so the order is never presented as a fact the sources state.
    Clause two: correlation explains why records were linked — every link carries a
    sentence naming the shared indicators and the strength, and no link claims identity.
    """

    checks: list[TimelineCheck] = []

    def add(name: str, ok: Any, detail: Any = "") -> None:
        checks.append(TimelineCheck(name=name, ok=bool(ok), detail=str(detail)[:150]))

    # ---- 1. the vocabulary -------------------------------------------------
    add("six timestamp origins are defined", len(TimestampOrigin) == 6,
        [origin.value for origin in TimestampOrigin])
    add("six certainty levels are defined", len(TimeCertainty) == 6,
        [level.value for level in TimeCertainty])
    add("only an exact timestamp is quotable",
        [level for level in TimeCertainty if level.quotable] == [TimeCertainty.EXACT])
    add("certainty is ordered from exact to unverified",
        TimeCertainty.EXACT.rank < TimeCertainty.APPROXIMATE.rank
        < TimeCertainty.AMBIGUOUS.rank < TimeCertainty.UNVERIFIED.rank)
    add("ten indicator kinds are defined", len(IndicatorKind) == 10,
        [kind.value for kind in IndicatorKind])
    add("a normalised timestamp cannot be extended",
        not _constructs(NormalisedTimestamp, original="x", reinterpreted="y"))
    add("a link has no field for an identity",
        not (set(CorrelationLink.model_fields)
             & {"person", "actor", "identity", "attribution", "owner", "suspect"}),
        sorted(set(CorrelationLink.model_fields) & {"person", "actor", "identity"}))
    add("a link can never be constructed as one",
        not _constructs(CorrelationLink, left="a", right="b", identity="someone"))
    add("a link says in words that it is not an identity",
        "do not establish" in CorrelationLink(left="a", right="b").not_identity_note)
    add("a record cannot be extended with an order",
        not _constructs(CorrelationRecord, id="r", execute=True))

    # ---- 2. normalisation preserves the original and the zone --------------
    stated = parse_timestamp("2026-05-04T12:00:00+02:00")
    add("an explicit offset is exact", stated.certainty is TimeCertainty.EXACT)
    add("an explicit offset is normalised to UTC",
        stated.utc == datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc), stated.utc)
    add("the wall clock is preserved as written",
        stated.wall_clock == datetime(2026, 5, 4, 12, 0), stated.wall_clock)
    add("the offset is preserved in minutes", stated.offset_minutes == 120)
    add("the local time can be reconstructed exactly",
        stated.local == datetime(2026, 5, 4, 12, 0,
                                 tzinfo=timezone(timedelta(hours=2))))
    add("the original string is kept verbatim",
        stated.original == "2026-05-04T12:00:00+02:00")
    add("the zone is labelled in words", stated.tz_label == "UTC+02:00", stated.tz_label)
    add("Z means UTC", parse_timestamp("2026-05-04T12:00:00Z").offset_minutes == 0)
    add("a negative offset is preserved",
        parse_timestamp("2026-05-04T12:00:00-05:00").offset_minutes == -300)
    add("two zones for one instant normalise to the same UTC",
        parse_timestamp("2026-05-04T12:00:00+02:00").utc
        == parse_timestamp("2026-05-04T10:00:00Z").utc)
    add("the same instant in two zones is not the same wall clock",
        parse_timestamp("2026-05-04T12:00:00+02:00").wall_clock
        != parse_timestamp("2026-05-04T10:00:00Z").wall_clock)
    add("normalisation is deterministic",
        parse_timestamp("2026-05-04T12:00:00+02:00").to_dict()
        == parse_timestamp("2026-05-04T12:00:00+02:00").to_dict())

    # ---- 3. uncertain timestamps are flagged ------------------------------
    no_zone = parse_timestamp("2026-05-04 12:00")
    add("a timestamp with no offset is ambiguous",
        no_zone.certainty is TimeCertainty.AMBIGUOUS)
    add("the missing offset is stated as a caveat",
        any("no UTC offset" in caveat for caveat in no_zone.caveats))
    date_only = parse_timestamp("2026-05-04")
    add("a date with no time is reduced", date_only.certainty is TimeCertainty.REDUCED)
    add("the midnight placeholder is stated",
        any("placeholder" in caveat for caveat in date_only.caveats))
    ambiguous = parse_timestamp("04/05/2026 12:00")
    add("a day/month ambiguity is marked ambiguous",
        ambiguous.certainty is TimeCertainty.AMBIGUOUS)
    add("the ambiguity is stated in words",
        any("day/month" in caveat for caveat in ambiguous.caveats))
    add("the alternative reading is preserved",
        ambiguous.alternatives == [datetime(2026, 4, 5, 12, 0)],
        [value.isoformat() for value in ambiguous.alternatives])
    add("an unambiguous slash date keeps one reading",
        parse_timestamp("13/05/2026").alternatives == []
        and parse_timestamp("13/05/2026").utc.month == 5)
    approximate = parse_timestamp("~2026-05-04T12:00:00Z")
    add("an approximate marker is flagged",
        approximate.certainty is TimeCertainty.APPROXIMATE)
    add("an approximate timestamp is not quotable", not approximate.certainty.quotable)
    add("an unrecognised value is unverified",
        parse_timestamp("sometime last spring").certainty is TimeCertainty.UNVERIFIED)
    add("an unrecognised value invents nothing",
        parse_timestamp("sometime last spring").utc is None)
    add("the refusal says nothing was assumed",
        "nothing was assumed" in " ".join(
            parse_timestamp("sometime last spring").caveats))
    add("an explicit 'unknown' is unverified",
        parse_timestamp("unknown").certainty is TimeCertainty.UNVERIFIED)
    add("an empty value is unverified", parse_timestamp("").certainty
        is TimeCertainty.UNVERIFIED)
    add("an impossible date is refused, not rolled over",
        parse_timestamp("2026-13-40T99:99:99Z").utc is None)
    add("an epoch in seconds is read as one",
        parse_timestamp("1714824000").utc == datetime(2024, 5, 4, 12, 0,
                                                     tzinfo=timezone.utc))
    add("an epoch in milliseconds is read as one",
        parse_timestamp("1714824000000").utc == parse_timestamp("1714824000").utc)
    far_off = parse_timestamp("100000000",
                              now=datetime(2026, 5, 4, tzinfo=timezone.utc))
    add("an epoch far from the case clock is flagged",
        far_off.certainty is TimeCertainty.AMBIGUOUS, far_off.certainty)
    add("the implausible epoch says the unit may be wrong",
        any("unit may be different" in caveat for caveat in far_off.caveats),
        far_off.caveats)
    add("a plausible epoch is not flagged",
        parse_timestamp("1777888800",
                        now=datetime(2026, 5, 4, tzinfo=timezone.utc)).certainty
        is TimeCertainty.EXACT)
    add("an RFC-2822 date is read",
        parse_timestamp("Mon, 04 May 2026 12:00:00 +0000").utc
        == datetime(2026, 5, 4, 12, 0, tzinfo=timezone.utc))
    add("a named month with no zone is ambiguous",
        parse_timestamp("4 May 2026 12:00").certainty is TimeCertainty.AMBIGUOUS)
    add("a bare datetime without a zone is marked ambiguous, not guessed",
        parse_timestamp(datetime(2026, 5, 4, 12, 0)).certainty
        is TimeCertainty.AMBIGUOUS)
    add("an aware datetime needs no caveat",
        parse_timestamp(datetime(2026, 5, 4, 12, 0, tzinfo=timezone.utc)).caveats == [])

    # ---- 4. the timeline separates source order from derived order --------
    timeline = build_timeline(_timeline_demo_events(), title="case")
    add("the timeline orders by instant",
        [event.at.utc for event in timeline.events
         if event.at.known] == sorted(event.at.utc for event in timeline.events
                                      if event.at.known))
    add("events in different zones are ordered by what happened",
        [event.label for event in timeline.events][:3]
        == ["document created", "advisory published",
            "DNS query for evil.example.org"],
        [event.label for event in timeline.events][:3])
    add("a zone offset changes the position, not the wall clock",
        next(event for event in timeline.events
             if event.label == "document created").at.wall_clock
        == datetime(2026, 5, 3, 23, 0),
        next(event for event in timeline.events
             if event.label == "document created").at.wall_clock)
    add("an undated event is listed last",
        timeline.events[-1].at.known is False)
    add("the undated event is marked undated",
        timeline.events[-1].ordering_basis == "undated")
    add("undated events are not interleaved",
        all(event.at.known for event in timeline.events
            if event.ordering_basis != "undated"))
    add("a source-stated instant is marked source-timestamp",
        any(event.ordering_basis == "source-timestamp" for event in timeline.events))
    add("an instant this tool recorded is marked derived",
        any(event.ordering_basis == "derived" for event in timeline.events))
    add("the derived event is the one this tool wrote",
        next(event for event in timeline.events
             if event.ordering_basis == "derived").source == "this tool")
    add("the timeline states the ordering rule",
        "ascending" in timeline.ordering_rule, timeline.ordering_rule)
    add("the timeline says the sequence is this tool's",
        any("this tool's ordering" in caveat for caveat in timeline.caveats))
    add("the timeline counts the events placed by a source",
        len(timeline.source_ordered)
        == len([event for event in timeline.events
                if event.ordering_basis == "source-timestamp"]))
    add("the timeline counts the events it timed itself",
        any("this tool" in caveat and "recorded" in caveat
            for caveat in timeline.caveats), timeline.caveats)
    add("the timeline reports the zones it read",
        any("UTC" in zone for zone in timeline.zones), timeline.zones)
    add("the timeline describes itself",
        "placed by a source timestamp" in timeline.describe(), timeline.describe())
    add("the order is not wholly derived when a source timestamp exists",
        timeline.order_is_derived is False)
    add("the timeline has a stable id",
        timeline.id == build_timeline(_timeline_demo_events(), title="case").id)
    add("the timeline is deterministic",
        timeline.to_dict()["events"][0]["id"] == timeline.events[0].id)
    add("sequence numbers are 1-based and contiguous",
        [event.sequence for event in timeline.events]
        == list(range(1, len(timeline.events) + 1)))

    # ---- 5. ties assert nothing ------------------------------------------
    tied = build_timeline([
        TimelineEvent(label="alpha", at=parse_timestamp("2026-05-04T12:00:00Z"),
                      source="a.log"),
        TimelineEvent(label="beta", at=parse_timestamp("2026-05-04T14:00:00+02:00"),
                      source="b.log"),
        TimelineEvent(label="gamma", at=parse_timestamp("2026-05-04T12:00:01Z"),
                      source="c.log")])
    add("both members of a tie are marked tie-break",
        [event.ordering_basis for event in tied.events]
        == ["tie-break", "tie-break", "source-timestamp"],
        [event.ordering_basis for event in tied.events])
    add("a tie is ordered by source, deterministically",
        [event.source for event in tied.events][:2] == ["a.log", "b.log"])
    add("tied events are not claimed as source-ordered",
        all(not event.from_source for event in tied.tied))
    add("the tie count is reported", tied.to_dict()["tie_broken"] == 2)
    derived_only = build_timeline([
        TimelineEvent(label="an access", source="this tool",
                      at=parse_timestamp(utc_now(), origin=TimestampOrigin.DERIVED)),
        TimelineEvent(label="a copy", source="this tool",
                      at=parse_timestamp(utc_now(), origin=TimestampOrigin.DERIVED))])
    add("a timeline of only derived instants says so",
        derived_only.order_is_derived is True)
    add("no event in it is claimed as source-ordered",
        derived_only.source_ordered == [])
    empty = build_timeline([])
    add("an empty timeline is honest about being empty",
        empty.events == [] and "0 dated" in empty.describe())

    # ---- 6. correlation explains every link ------------------------------
    report = correlate_records(_correlation_demo_records())
    add("the report links the records that overlap", len(report.links) >= 3,
        len(report.links))
    add("every link carries an explanation in a sentence",
        all(len(link.explanation) > 40 and "." in link.explanation
            for link in report.links))
    add("the explanation names the shared indicators",
        all(any(indicator.value in link.explanation for indicator in link.shared
                if not indicator.record_id)
            for link in report.links))
    add("the explanation names both records",
        all(link.left in link.explanation and link.right in link.explanation
            for link in report.links))
    add("the explanation states the strength",
        all("Strength:" in link.explanation for link in report.links))
    add("no link claims an identity",
        all(link.identity_claimed is False for link in report.links))
    add("every link repeats the not-an-identity note",
        all("do not establish" in link.not_identity_note for link in report.links))
    add("identical content is a strong link",
        any(link.strength == "strong" for link in report.links))
    add("the strong link is attributed to the hash",
        next(link for link in report.links
             if link.strength == "strong").basis.startswith("identical content"))
    add("two independent indicators are moderate or better",
        all(_STRENGTH_ORDER[link.strength] >= 2 for link in report.links
            if len([indicator for indicator in link.shared
                    if not _is_coincidental(indicator)[0]]) >= 2))
    add("one indicator alone is weak",
        all(link.strength == "weak" for link in report.links
            if len([indicator for indicator in link.shared
                    if not _is_coincidental(indicator)[0]]) == 1))
    add("the report lists the rules it applied",
        len(report.rules) == len(CORRELATION_RULES) and "identity" in " ".join(
            report.rules))
    add("the report says absence of a link is not independence",
        any("absence of a link" in caveat for caveat in report.caveats))
    add("the report describes itself",
        "no identity is inferred" in report.describe(), report.describe())
    add("links are ordered strongest first",
        [_STRENGTH_ORDER[link.strength] for link in report.links]
        == sorted((_STRENGTH_ORDER[link.strength] for link in report.links),
                  reverse=True))
    add("the report has a stable id",
        report.id == correlate_records(list(reversed(
            _correlation_demo_records()))).id)
    add("correlation is order-independent",
        [(link.left, link.right) for link in report.links]
        == [(link.left, link.right) for link in
            correlate_records(list(reversed(_correlation_demo_records()))).links])

    # ---- 7. coincidence is not identity ----------------------------------
    add("a free mail provider is not an identity",
        not any(link.pair() == ("rec-advisory", "rec-mail") for link in report.links))
    add("the mail near-miss is explained",
        any("free mail provider" in line for line in report.near_misses),
        report.near_misses[:1])
    add("a default file name is not an identity",
        not any(link.pair() == ("rec-index-a", "rec-index-b") for link in report.links))
    add("the file-name near-miss is explained",
        any("commonly coincides" in line for line in report.near_misses))
    add("a private address does not link two records",
        not any("10.0.0.5" in link.explanation and len(link.shared) == 1
                for link in report.links
                if link.pair() == ("rec-advisory", "rec-scan")))
    add("a default user agent never links",
        not any(link.pair() == ("a", "b") for link in correlate_records([
            CorrelationRecord.from_pairs("a", [(IndicatorKind.USER_AGENT, "Mozilla/5.0")]),
            CorrelationRecord.from_pairs("b", [(IndicatorKind.USER_AGENT, "Mozilla/5.0")]),
        ]).links))
    add("a private IP is refused as an indicator of ownership",
        _is_coincidental(Indicator(kind=IndicatorKind.IP, raw="10.0.0.5",
                                   value="10.0.0.5"))[0])
    add("a public IP is not refused",
        not _is_coincidental(Indicator(kind=IndicatorKind.IP, raw="93.184.216.34",
                                       value="93.184.216.34"))[0])
    add("a documentation-range address is refused",
        _is_coincidental(Indicator(kind=IndicatorKind.IP, raw="198.51.100.7",
                                   value="198.51.100.7"))[0])
    add("a loopback address is refused",
        _is_coincidental(Indicator(kind=IndicatorKind.IP, raw="127.0.0.1",
                                   value="127.0.0.1"))[0])
    add("a very short username is a coincidence",
        _is_coincidental(Indicator(kind=IndicatorKind.USERNAME, raw="bob",
                                   value="bob"))[0])
    add("a distinctive username is not",
        not _is_coincidental(Indicator(kind=IndicatorKind.USERNAME,
                                       raw="analyst-kestrel",
                                       value="analyst-kestrel"))[0])
    add("a coincidental overlap is listed, not dropped",
        len(report.near_misses) >= 2, report.near_misses)

    # ---- 8. indicators are normalised, and refused when they are not ------
    add("a domain is lowercased and de-www'd",
        normalise_indicator(IndicatorKind.DOMAIN, "WWW.Evil.Example.org.") 
        == "evil.example.org")
    add("a URL is normalised through the research rules",
        normalise_indicator(IndicatorKind.URL,
                            "https://WWW.Example.com:443/a/?utm_source=x#f")
        == "https://example.com/a")
    add("an email is lowercased",
        normalise_indicator(IndicatorKind.EMAIL, "Analyst@Example.ORG")
        == "analyst@example.org")
    add("a filename is reduced to its base name",
        normalise_indicator(IndicatorKind.FILENAME, "C:\\x\\Report.DOCX")
        == "report.docx")
    add("a hash is accepted at the right length",
        normalise_indicator(IndicatorKind.HASH, "A" * 64) == "a" * 64)
    add("a hash of the wrong length is refused",
        normalise_indicator(IndicatorKind.HASH, "abc123") is None)
    add("a non-hex hash is refused",
        normalise_indicator(IndicatorKind.HASH, "z" * 64) is None)
    add("an IP is canonicalised",
        normalise_indicator(IndicatorKind.IP, "2001:0db8::1") == "2001:db8::1")
    add("a non-address is refused as an IP",
        normalise_indicator(IndicatorKind.IP, "10.0.0.256") is None)
    add("a URL is refused as a domain",
        normalise_indicator(IndicatorKind.DOMAIN, "https://example.com/x") is None)
    add("an invalid indicator is dropped from a record",
        CorrelationRecord.from_pairs("r", [(IndicatorKind.IP, "not-an-ip")]).indicators
        == [])
    add("a record keeps the original beside the normalised value",
        CorrelationRecord.from_pairs(
            "r", [(IndicatorKind.DOMAIN, "EVIL.example.org")]).indicators[0].raw
        == "EVIL.example.org")

    # ---- 9. de-duplication uses content, never a name or a size -----------
    fixture = _artifact_fixture()
    try:
        evidence = fixture.evidence
        # Two identical files under different names, plus a same-size look-alike.
        (evidence / "copy-of-notes.txt").write_bytes((evidence / "notes.txt").read_bytes())
        (evidence / "same-size-different.txt").write_bytes(b"x" * (
            evidence / "nested" / "deep.log").stat().st_size)
        case = ArtifactCase(roots=[str(evidence)], case_dir=fixture.case_dir)
        manifest = case.walk(str(evidence))
        report = deduplicate_manifest(manifest)
        add("identical bytes are grouped", len(report.groups) >= 1, len(report.groups))
        group = next((group for group in report.groups
                      if any("notes.txt" in member for member in group.members)), None)
        add("the renamed copy is in the group", group is not None
            and any("copy-of-notes" in member for member in group.members))
        add("the group names the canonical member", bool(group and group.canonical))
        add("the canonical member is the first by path",
            bool(group and group.canonical
                 == sorted(group.members, key=lambda member: member)[0]))
        add("the redundant members are listed",
            bool(group and len(group.members) == len(group.redundant) + 1))
        add("the group explains itself",
            bool(group and "identical sha256" in group.explanation))
        add("a renamed copy is described as one",
            bool(group and "renamed" in group.explanation))
        add("a same-size look-alike is not a duplicate",
            not any("same-size-different" in member for member in report.redundant))
        add("the look-alike is reported, with the reason",
            any("size is not content" in line for line in report.distinct),
            report.distinct[:1])
        add("the rule is stated", "sha256" in report.rule and "size" in report.rule)
        add("a duplicate is not removed from the case",
            any("never from the case" in caveat for caveat in report.caveats))
        add("the report describes itself",
            "duplicate group" in report.describe(), report.describe())
        add("the duplicate report is deterministic",
            report.id == deduplicate_manifest(case.walk(str(evidence))).id)
        add("a manifest with no duplicates reports none",
            find_duplicate_evidence(manifest.entries[:1]).groups == [])

        # ---- 10. correlation over a real manifest -------------------------
        artifact_report_ = correlate_artifacts(manifest)
        add("a manifest correlates into records",
            len(artifact_report_.records) == len(manifest.entries)
            or len(artifact_report_.records) > 0)
        add("the manifest correlation is explained",
            all(link.explanation for link in artifact_report_.links))
        add("the manifest correlation claims no identity",
            all(link.identity_claimed is False for link in artifact_report_.links))

        # ---- 11. a timeline from a real case ------------------------------
        artifact_timeline = timeline_from_manifest(manifest)
        add("the artifact timeline has events", len(artifact_timeline.events) > 0)
        add("file times are marked as filesystem facts",
            any(event.kind == "file-modified" for event in artifact_timeline.events))
        add("the tool's own accesses are marked derived",
            any(event.kind == "case-access"
                and event.ordering_basis == "derived"
                for event in artifact_timeline.events))
        add("the artifact timeline says what it derived",
            any("this tool" in caveat for caveat in artifact_timeline.caveats))
        add("the artifact timeline is ordered",
            [event.at.utc for event in artifact_timeline.events if event.at.known]
            == sorted(event.at.utc for event in artifact_timeline.events
                      if event.at.known))
    finally:
        fixture.cleanup()

    # ---- 12. serialisation and the demo ---------------------------------
    demo = timeline_demo()
    add("the demo builds a timeline", bool(demo["timeline"]["events"]))
    add("the demo builds a correlation", bool(demo["correlation"]["links"]))
    add("the demo's correlation explains every link",
        all(item["explanation"] for item in demo["correlation"]["links"]))
    add("the demo's links all disclaim identity",
        all(item["identity_claimed"] is False
            for item in demo["correlation"]["links"]))
    add("the demo builds a de-duplication report", "groups" in demo["deduplication"])
    add("the demo builds a timeline from a manifest",
        "artifact_timeline" in demo)
    add("every piece serialises to JSON",
        bool(json.dumps(demo, default=str)))
    # ``to_dict`` adds derived display fields; the round trip is of the *model*, which
    # is what a case file stores and what a later run must be able to reload.
    rebuilt_timeline = ForensicTimeline(**json.loads(json.dumps(
        build_timeline(_timeline_demo_events(), title="case").model_dump(mode="json"))))
    add("the timeline round-trips through its own model",
        len(rebuilt_timeline.events) == len(demo["timeline"]["events"]))
    rebuilt_report = CorrelationReport(**json.loads(json.dumps(
        correlate_records(_correlation_demo_records()).model_dump(mode="json"))))
    add("the correlation round-trips through its own model",
        len(rebuilt_report.links) == len(demo["correlation"]["links"]))
    return checks


@app.command("timeline", help="Forensic time: normalise, order, correlate, de-duplicate.")
def timeline_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the source-vs-derived contract offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="A timeline, a correlation and a duplicate report."),
    path: list[str] = typer.Option([], "--path", "-p",
                                   help="An artifact case to place on a timeline. Repeatable."),
    record: list[str] = typer.Option(
        [], "--record",
        help="Correlate these records, given as 'id:kind=value;kind=value'. Repeatable."),
    timestamp: list[str] = typer.Option([], "--timestamp",
                                        help="Normalise this timestamp and show the reading."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Put evidence in order without claiming the order is evidence.

    ``--timestamp`` shows how one value is read, including what was *not* stated; to
    build a timeline from files use ``artifacts --path`` and this command's ``--path``.
    """

    console = get_console()

    if self_test:
        checks = run_timeline_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"ok": not failures,
                              "checks": [asdict(check) for check in checks]}, indent=2))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        console.print()
        console.print(render_timeline_self_test(checks))
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = timeline_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_timeline_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if timestamp:
        rows = [parse_timestamp(item) for item in timestamp]
        if as_json:
            _emit(json.dumps({"timestamps": [row.to_dict() for row in rows]}, indent=2,
                             default=str))
            raise typer.Exit(ExitCode.OK)
        table = Table(title="timestamp normalisation — what was stated, what was read",
                      title_justify="left", box=None, pad_edge=False)
        table.add_column("source value", overflow="fold", max_width=30)
        table.add_column("UTC", no_wrap=True)
        table.add_column("local", no_wrap=True)
        table.add_column("certainty", no_wrap=True)
        table.add_column("caveat", overflow="fold", max_width=44)
        for row in rows:
            table.add_row(
                escape(row.original[:40] or "—"),
                escape(row.utc.strftime("%Y-%m-%d %H:%M:%S") if row.utc else "—"),
                escape(row.local.strftime("%Y-%m-%d %H:%M:%S %z") if row.local else "—"),
                escape(row.certainty.value),
                escape("; ".join(row.caveats)[:120] or "—"))
        console.print()
        console.print(table)
        console.print(Text(
            "\nUTC is this build's reading; the local column is what the source said.\n"
            "Only 'exact' may be quoted as the time of an event.", style="dim"))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if record:
        records: list[CorrelationRecord] = []
        for item in record:
            try:
                record_id, pairs_text = item.split(":", 1)
            except ValueError:
                console.print(f"[red]✘[/red] {escape(item[:80])} is not "
                              "'id:kind=value;kind=value'")
                raise typer.Exit(ExitCode.USAGE) from None
            pairs: list[tuple[IndicatorKind, str]] = []
            for chunk in pairs_text.split(";"):
                if not chunk.strip():
                    continue
                try:
                    kind_text, value = chunk.split("=", 1)
                    pairs.append((IndicatorKind(kind_text.strip().lower()), value.strip()))
                except ValueError:
                    console.print(f"[red]✘[/red] {escape(chunk[:40])} is not "
                                  "'kind=value'; kinds are "
                                  f"{', '.join(kind.value for kind in IndicatorKind)}")
                    raise typer.Exit(ExitCode.USAGE) from None
            records.append(CorrelationRecord.from_pairs(record_id.strip(), pairs,
                                                        label=record_id.strip()))
        report = correlate_records(records)
        if as_json:
            _emit(json.dumps(report.to_dict(), indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_correlation_report(report))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if path:
        supplied = [str(Path(item).expanduser()) for item in path]
        missing = [item for item in supplied if not Path(item).exists()]
        if missing:
            console.print(f"[red]✘[/red] not found: {escape(', '.join(missing)[:160])}")
            raise typer.Exit(ExitCode.USAGE)
        base = next((item for item in supplied if Path(item).is_dir()),
                    str(Path(supplied[0]).parent))
        case = ArtifactCase(roots=[str(Path(base).resolve())],
                            case_dir=resolve_default_output_dir() / "cases",
                            actor=os.environ.get("ARGUS_OPERATOR") or "operator")
        manifests = [case.walk(item) for item in supplied]
        events: list[TimelineEvent] = []
        duplicates = DeduplicationReport()
        for manifest in manifests:
            events.extend(timeline_from_manifest(manifest).events)
            found = deduplicate_manifest(manifest)
            duplicates = DeduplicationReport(
                groups=[*duplicates.groups, *found.groups],
                distinct=sorted({*duplicates.distinct, *found.distinct}),
                rule=found.rule, caveats=found.caveats)
        timeline = build_timeline(events, title=", ".join(
            Path(manifest.root).name for manifest in manifests))
        correlation = correlate_records([
            record for manifest in manifests
            for record in correlate_artifacts(manifest).records])
        payload = {"timeline": timeline.to_dict(), "correlation": correlation.to_dict(),
                   "deduplication": duplicates.to_dict(),
                   "events": [event.to_dict() for event in timeline.events]}
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_timeline_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    console.print("[red]✘[/red] name evidence with --path, a record with --record, a "
                  "value with --timestamp, or use --demo/--self-test")
    raise typer.Exit(ExitCode.USAGE)


# ══════════════════════════════════════════════════════════════════════════
# 33. Worker outcomes: one contract, four statuses, no mission conclusions
# ══════════════════════════════════════════════════════════════════════════
#
# A Worker is the smallest unit that touches a source.  What it may hand back is
# therefore the narrowest thing in this build: a status, findings, evidence with
# provenance, the limitations it hit, and what it thinks should happen next.  It
# may *not* conclude for the mission, and it may not talk to another team — both
# are checked properties of the record, not instructions in a prompt.
#
# The section is deliberately independent of the graph in §25: the contract is a
# property of a record, so it can be enforced at every seam a Worker's output
# crosses (the runner, the review node, the Subagent's aggregate, a case file),
# and tested without running a graph at all.


class WorkerStatus(str, Enum):
    """The only four things a Worker may say about its own work.

    Four, not ten: ``pending``/``running`` describe a Worker that has not
    reported, and a report is what this contract is about.  Anything else a
    Worker wants to convey belongs in findings, limitations or follow-up.
    """

    COMPLETED = "completed"   # the unit was done, and its completion criteria were met
    PARTIAL = "partial"       # some of the unit was done; what is missing is named
    BLOCKED = "blocked"       # could not proceed: permission, scope, dependency, policy
    FAILED = "failed"         # the attempt ran and did not produce usable work

    @property
    def usable(self) -> bool:
        """Whether the work may be built on at all — partial work still counts."""

        return self in {WorkerStatus.COMPLETED, WorkerStatus.PARTIAL}

    @property
    def ok(self) -> bool:
        return self is WorkerStatus.COMPLETED

    @property
    def needs_attention(self) -> bool:
        return self is not WorkerStatus.COMPLETED


#: The four statuses as a set, so a validator can name them in one message.
WORKER_STATUSES: tuple[WorkerStatus, ...] = tuple(WorkerStatus)

#: Statuses that must say *why* they are not completed.
_NOT_COMPLETED: frozenset[WorkerStatus] = frozenset(
    {WorkerStatus.PARTIAL, WorkerStatus.BLOCKED, WorkerStatus.FAILED})


class ConclusionLeak(ValueError):
    """A Worker tried to state a mission-level conclusion.

    Raised rather than silently truncated: a Worker that reached a verdict on the
    whole mission was working outside its slice, and the reader needs to know that
    the record was refused rather than cleaned up.

    Note on where it surfaces: :func:`accept_worker_report` and :func:`check_report_text`
    raise this type directly, but a check that runs *inside* a Pydantic validator is
    wrapped by Pydantic into ``ValidationError``.  The message is preserved verbatim
    either way, which is why :func:`refusal_kind` reads the message rather than the
    type — a caller cannot control which seam a payload entered by.
    """

    def __init__(self, field: str, phrase: str, *, text: str = "") -> None:
        self.field = field
        self.phrase = phrase
        self.text = text
        super().__init__(
            f"{field} states a mission-level conclusion ({phrase!r}); a Worker reports "
            "observations and its own unit's findings — the Master draws the conclusion")


class PeerContactError(ValueError):
    """A Worker tried to address, hand work to, or share with another team.

    A Worker's only counterparties are its own Subagent (which reviewed it) and the
    mission record.  Lateral contact would bypass both the review and the ledger, so
    it is refused at the boundary and named in the record.
    """

    def __init__(self, field: str, phrase: str, *, text: str = "") -> None:
        self.field = field
        self.phrase = phrase
        self.text = text
        super().__init__(
            f"{field} addresses another team ({phrase!r}); a Worker reports only to its "
            "own Subagent and never contacts, delegates to, or shares with a peer")


# --------------------------------------------------------------------------
# 33.1 What a Worker may not say — the two prohibitions, in one place
# --------------------------------------------------------------------------

#: Phrases that assert a verdict on the whole mission rather than a finding in a
#: slice.  Deliberately blunt: a Worker has no business with these words, and a
#: false positive costs one rephrase while a false negative costs a fabricated
#: conclusion attributed to a unit that could not have reached it.
_MISSION_CONCLUSION_PHRASES: tuple[str, ...] = (
    "the mission is complete", "mission complete", "mission accomplished",
    "the mission succeeded", "the mission failed", "case closed", "case is closed",
    "case solved", "we have proven", "we have established that",
    "we have confirmed that", "we conclude", "in conclusion", "we can conclude",
    "it is confirmed that", "we have attributed", "attributed to the actor",
    "the actor is", "the threat actor is", "the perpetrator is", "the subject is",
    "this proves that", "definitively", "conclusively",
    # the linguistic tell of a verdict dressed as a summary
    "overall assessment is", "final assessment", "final verdict", "bottom line",
)

#: A mission-level verdict about the *whole* target, which no single slice can see.
_MISSION_LEVEL_SCOPE_WORDS: tuple[str, ...] = (
    "the whole mission", "the entire mission", "all subagents", "every subagent",
    "the whole investigation", "the entire investigation", "across the mission",
    "the mission as a whole", "all workers", "the whole team",
)

#: Ways of reaching sideways to another team.  A Worker's report is a record, so
#: these are mostly about *intent* recorded in free text: a hand-off, a request, a
#: broadcast, or a channel outside the mission.
_PEER_CONTACT_PHRASES: tuple[str, ...] = (
    "contacted the", "contact the other", "asked the other team", "asked another team",
    "notified the other", "shared with the other", "shared with another team",
    "handed off to", "hand off to", "handover to", "delegated to", "delegate to",
    "coordinated with", "coordinating with", "synced with", "syncing with",
    "messaged the", "messaged another", "emailed the team", "emailed another team",
    "told the other team", "briefed the other team", "escalated to the team",
    "via slack", "via email to", "on the shared channel", "in the team channel",
    "sent a message to", "sent the results to another", "forwarded to another team",
    "peer subagent", "peer worker", "another subagent", "another worker",
    "other subagents", "other workers", "sibling subagent",
)

#: A mission-level conclusion is only refused when it is asserted, so the check
#: first looks for the shape of a claim about the whole, then for a verdict word.
_CONCLUSION_WINDOW = 160


def refusal_kind(message: str) -> str:
    """Classify a refusal by its message: ``conclusion``, ``peer-contact`` or ``other``.

    Needed because Pydantic wraps a validator's ``ValueError`` subclass into
    ``ValidationError``: the *type* is lost at that seam, but the message this build
    writes is not, so the message is what a caller should read.
    """

    lowered = str(message).lower()
    if "mission-level conclusion" in lowered:
        return "conclusion"
    if "addresses another team" in lowered:
        return "peer-contact"
    return "other"


def _phrase_hits(text: str, phrases: Sequence[str]) -> list[str]:
    """Which phrases occur in the text, in the order they were declared."""

    lowered = (text or "").lower()
    return [phrase for phrase in phrases if phrase in lowered]


def mission_conclusion_phrases(text: str) -> list[str]:
    """The mission-level conclusion phrases in one string.

    A phrase alone is enough: the vocabulary above is specific enough that a
    Worker has no reason to use it, and the error message tells the Worker how to
    rephrase.  What is *not* refused is ordinary analytic language — "the proxy
    log shows a connection" is a finding in the Worker's slice.
    """

    return _phrase_hits(text, _MISSION_CONCLUSION_PHRASES)


def peer_contact_phrases(text: str) -> list[str]:
    """The phrases in one string that describe contacting another team."""

    return _phrase_hits(text, _PEER_CONTACT_PHRASES)


def _mission_scope_claim(text: str) -> list[str]:
    """Phrases that claim a scope wider than one Worker's slice."""

    return _phrase_hits(text, _MISSION_LEVEL_SCOPE_WORDS)


# --- the *structural* half of the prohibition ------------------------------
#
# Text scanning catches what a Worker says; these catch what a Worker's record
# *is*.  Both are needed: a field named ``recipients`` is a peer-contact channel
# whatever the prose says, and prose is where a conclusion actually gets written.

#: Substrings that may not appear in any field name of a Worker's report.
_FORBIDDEN_FIELDS: tuple[str, ...] = (
    "recipient", "recipients", "recipient_ids", "cc", "bcc", "to_team", "to_peer",
    "peer_id", "peer_ids", "contact", "contacted", "contact_log", "mediated_by",
    "handoff", "hand_off", "delegat", "broadcast", "channel", "slack", "webhook",
    "notify", "notification", "escalate_to", "conclusion", "conclusions",
    "verdict", "final_answer", "mission_conclusion", "attribution", "attributed_to",
    "actor", "culprit", "guilt", "accuse", "accusation", "identity",
)

#: Field names that look forbidden but are how a Worker records what it did *not*
#: establish.  The scan skips them and reads their text instead: the word is the
#: point of the field, and refusing the record for saying so would teach a Worker to
#: stop declaring it.
_FORBIDDEN_ALLOWED: frozenset[str] = frozenset({
    "identity_claimed", "identity_not_claimed", "no_identity_claim", "not_an_identity",
    "conclusion_refused", "conclusions_refused",
    # The two fields that *record* the prohibition: they hold the answer, not the
    # claim, and a record that cannot say "no conclusion, no contact" cannot be
    # checked for having made one.
    "declares_conclusion", "peer_contacts",
})


#: Field names the contract itself owns, so scanning a report's own ``to_dict``
#: output does not report ``peer_contacts`` as the thing it forbids.
_CONTRACT_FIELDS: frozenset[str] = frozenset({
    "worker_id", "subagent_id", "task_id", "attempt", "status", "summary", "findings",
    "evidence", "sources", "limitations", "follow_up", "gaps", "error",
    "declares_conclusion", "peer_contacts", "started_at", "seconds", "usable",
    "citations",
})


def forbidden_fields(payload: Mapping[str, Any], *, path: str = "",
                     allow: frozenset[str] = frozenset()) -> list[str]:
    """Every field name in a payload that the Worker contract forbids.

    Recursive, because a conclusion hides just as well one level down: a
    ``metadata`` dictionary with an ``attribution`` key is the same claim as a
    top-level one.  Returns dotted paths so the error names the exact field.
    """

    found: list[str] = []
    for key, value in payload.items():
        here = f"{path}.{key}" if path else str(key)
        lowered = str(key).lower()
        if lowered in allow or lowered in _FORBIDDEN_ALLOWED:
            continue
        if any(fragment in lowered for fragment in _FORBIDDEN_FIELDS):
            found.append(here)
        if isinstance(value, Mapping):
            found.extend(forbidden_fields(value, path=here))
        elif isinstance(value, (list, tuple)):
            for index, item in enumerate(value):
                if isinstance(item, Mapping):
                    found.extend(forbidden_fields(item, path=f"{here}[{index}]"))
    return found


def _check_text(field: str, text: str) -> str:
    """Refuse conclusion language in one free-text field.

    Returns the text unchanged when it is clean, so callers can use it inline as a
    validator.  Whitespace-only text is left alone: "missing" is a different
    complaint, made by the field's own requirement.
    """

    if not text or not text.strip():
        return text
    conclusions = mission_conclusion_phrases(text)
    if conclusions:
        raise ConclusionLeak(field, conclusions[0], text=text[:_CONCLUSION_WINDOW])
    peers = peer_contact_phrases(text)
    if peers:
        raise PeerContactError(field, peers[0], text=text[:_CONCLUSION_WINDOW])
    return text


#: Keys whose values the contract reads as prose.  Only these are scanned: an
#: artefact's path or a URL may contain any word at all, and refusing evidence
#: because a filename said "conclusion" would be a bug wearing a safeguard's coat.
_PROSE_KEYS: frozenset[str] = frozenset({
    "summary", "limitations", "statement", "scope_note", "reasoning",
    "confidence_basis", "suggestion", "reason", "detail", "message", "error",
})


def check_report_text(payload: Mapping[str, Any], *, path: str = "") -> None:
    """Refuse a conclusion or a peer contact written anywhere in a payload's prose.

    Recursive, because a finding's ``statement`` is prose and a verdict written
    there is the same claim as one in the summary.  Raises the typed error rather
    than a generic one, so a caller can tell a conclusion from a hand-off without
    reading the message.
    """

    for key, value in payload.items():
        here = f"{path}.{key}" if path else str(key)
        prose = str(key).lower() in _PROSE_KEYS
        if isinstance(value, str):
            if prose:
                _check_text(here, value)
        elif isinstance(value, Mapping):
            check_report_text(value, path=here)
        elif isinstance(value, (list, tuple)):
            for index, item in enumerate(value):
                if isinstance(item, Mapping):
                    check_report_text(item, path=f"{here}[{index}]")
                elif isinstance(item, str) and prose:
                    _check_text(f"{here}[{index}]", item)


def accept_worker_report(payload: Mapping[str, Any], *, worker_id: str = "",
                         subagent_id: str = "", attempt: int = 1) -> "WorkerReport":
    """The single gate a Worker's payload passes through: fields, prose, contract.

    In that order, and each step's complaint is more specific than the last: a
    forbidden *field* is named before any prose is read, prose is refused with the
    phrase and the field, and only then is the status's own requirements checked.
    """

    bad_fields = forbidden_fields(payload, allow=_CONTRACT_FIELDS)
    if bad_fields:
        raise ConclusionLeak(bad_fields[0], "forbidden field")
    check_report_text(payload)
    data = dict(payload)
    data.setdefault("worker_id", worker_id or "worker")
    data.setdefault("subagent_id", subagent_id or "subagent")
    data.setdefault("attempt", attempt)
    # ``from_dict`` drops the derived display keys, so a report this build wrote can
    # be checked by the same gate that checks one it did not.
    return WorkerReport.from_dict(data)


# --------------------------------------------------------------------------
# 33.2 The report: status, findings, evidence, sources, limitations, follow-up
# --------------------------------------------------------------------------

class WorkerFinding(StrictModel):
    """One thing the Worker observed, in its own slice, with what it rests on.

    A finding is not a conclusion: it names a subject, what was seen, and the
    evidence ids that show it.  ``confidence`` without ``confidence_basis`` is
    refused, for the same reason :class:`EvidenceItem` refuses it — a number with
    no account of itself is not a calibration.
    """

    statement: str = Field(min_length=1,
                           description="What was observed, in neutral language.")
    evidence_ids: list[str] = Field(min_length=1)
    kind: EvidenceKind = EvidenceKind.OBSERVATION
    scope_note: str = ""
    confidence: Confidence = Confidence.UNKNOWN
    confidence_basis: str | None = None
    reasoning: str | None = None

    @field_validator("statement", "scope_note")
    @classmethod
    def _clean(cls, value: str) -> str:
        return _check_text("finding statement", value)

    @field_validator("confidence_basis", "reasoning")
    @classmethod
    def _clean_optional(cls, value: str | None) -> str | None:
        return None if value is None else _check_text("finding reasoning", value)

    @model_validator(mode="after")
    def _epistemic_rules(self) -> "WorkerFinding":
        if not self.statement.strip():
            raise ValueError("a finding needs a statement")
        if self.kind is EvidenceKind.INFERENCE:
            if not self.reasoning or len(self.reasoning.strip()) < 8:
                raise ValueError("an inference must state the reasoning behind it")
        if self.confidence is not Confidence.UNKNOWN and not self.confidence_basis:
            raise ValueError("state confidence_basis, or leave the confidence unknown")
        if self.confidence is Confidence.HIGH and self.kind is not EvidenceKind.OBSERVATION:
            raise ValueError("only an observation may carry high confidence")
        return self

    @property
    def citations(self) -> list[str]:
        return list(self.evidence_ids)

    def describe(self) -> str:
        return f"{self.kind.value}: {self.statement} [{len(self.evidence_ids)} evidence]"


class FollowUpPriority(str, Enum):
    """How strongly a Worker thinks the follow-up matters.  Advisory only."""

    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"

    @property
    def rank(self) -> int:
        return {FollowUpPriority.LOW: 0, FollowUpPriority.MEDIUM: 1,
                FollowUpPriority.HIGH: 2}[self]


class WorkerFollowUp(StrictModel):
    """Suggested next work.  A suggestion — the Subagent or Master decides.

    ``reason`` is required because "collect more" without a reason is not a
    suggestion, it is a shrug, and the next agent has no way to judge it.
    """

    suggestion: str = Field(min_length=1)
    reason: str = Field(min_length=1)
    priority: FollowUpPriority = FollowUpPriority.MEDIUM
    blocked_by: str | None = None

    @field_validator("suggestion", "reason", "blocked_by")
    @classmethod
    def _clean(cls, value: str | None) -> str | None:
        return None if value is None else _check_text("follow-up", value)

    @model_validator(mode="after")
    def _coherent(self) -> "WorkerFollowUp":
        if not self.suggestion.strip() or not self.reason.strip():
            raise ValueError("a follow-up needs a suggestion and a reason for it")
        return self

    def describe(self) -> str:
        return f"{self.priority.value}: {self.suggestion} ({self.reason})"


#: Keys :meth:`WorkerReport.to_dict` adds for readers that are not model fields.
_DERIVED_REPORT_KEYS: frozenset[str] = frozenset({"usable", "citations", "gap_notes"})


class WorkerReport(StrictModel):
    """The only shape a Worker may return.  Everything else is refused.

    The requirements follow from the status, because the status is a claim about
    what the report contains:

    *   ``completed`` — at least one finding, at least one sourced evidence item,
        and no limitations that would undercut the completion (if a limitation
        stands, the honest status is ``partial``).
    *   ``partial`` — at least one finding *and* at least one limitation naming
        what is missing; usable work with usable provenance, or it is a failure
        wearing a reassuring label.
    *   ``blocked`` — at least one limitation saying what stopped it, and no
        requirement for findings: a blocked Worker has nothing to show.
    *   ``failed`` — an error, and the error is what the reader gets.

    ``evidence`` is the full :class:`EvidenceItem`, not an id: a Worker that
    returned ids alone would leave its findings unciteable once the payload
    crossed a process boundary, which is exactly when provenance matters.
    """

    worker_id: str = Field(min_length=1)
    subagent_id: str = Field(min_length=1)
    task_id: str = ""
    attempt: int = Field(default=1, ge=1)
    status: WorkerStatus

    #: What the Worker did, in one or two sentences.  Never a verdict.
    summary: str = ""
    #: What it saw, each statement tied to the evidence that shows it.
    findings: list[WorkerFinding] = Field(default_factory=list)
    #: Structured evidence, with the provenance the Worker actually had.
    evidence: list[EvidenceItem] = Field(default_factory=list)
    #: Where the Worker's material came from, one reference per artefact or page.
    sources: list[SourceReference] = Field(default_factory=list)
    #: What the Worker could not do, could not see, or could not establish.
    limitations: list[str] = Field(default_factory=list)
    #: What it suggests be done next — for the Subagent to judge, not to obey.
    follow_up: list[WorkerFollowUp] = Field(default_factory=list)
    #: The gaps the Worker is declaring, typed, so they can travel into the mission.
    gaps: list[UnknownValue] = Field(default_factory=list)
    error: ErrorInfo | None = None

    #: True by construction.  It is a field so that a report which crossed into
    #: another system can be checked for having claimed one.
    declares_conclusion: bool = False
    #: Names of any lateral contact attempted.  Always empty for a valid report;
    #: recorded rather than raised when a caller wants the evidence of the attempt.
    peer_contacts: list[str] = Field(default_factory=list)

    started_at: datetime | None = None
    seconds: float = Field(default=0.0, ge=0)

    @field_validator("summary")
    @classmethod
    def _clean_summary(cls, value: str) -> str:
        return _check_text("summary", value)

    @field_validator("limitations")
    @classmethod
    def _clean_limitations(cls, value: list[str]) -> list[str]:
        return [_check_text("limitation", item) for item in value]

    @field_validator("started_at", mode="before")
    @classmethod
    def _tz(cls, value: Any) -> Any:
        return normalise_datetime(value) if value is not None else None

    @model_validator(mode="after")
    def _contract(self) -> "WorkerReport":
        # 1. A Worker does not conclude, and does not reach sideways.
        if self.declares_conclusion:
            raise ConclusionLeak("declares_conclusion", "declares_conclusion")
        if self.peer_contacts:
            raise PeerContactError("peer_contacts", self.peer_contacts[0])
        _check_text("summary", self.summary)
        for limitation in self.limitations:
            _check_text("limitation", limitation)

        # 2. A status that is not "completed" must say why.
        if self.status in _NOT_COMPLETED and not self.limitations and self.error is None:
            raise ValueError(
                f"a {self.status.value} report must record at least one limitation "
                "(or an error) saying what is missing or what stopped it")

        # 3. Usable work needs usable provenance.
        if self.status.usable:
            if not self.findings:
                raise ValueError(
                    f"a {self.status.value} report needs at least one finding; "
                    "a Worker with nothing to show reports blocked or failed")
            if not self.evidence:
                raise ValueError(
                    f"a {self.status.value} report needs at least one evidence item; "
                    "a finding without evidence is an opinion")
            missing = [index for index, item in enumerate(self.evidence) if not item.sources]
            if missing:
                raise ValueError(
                    f"evidence item(s) {missing} have no source reference; partial work "
                    "must keep usable provenance, not just a conclusion it reached")
        if self.status is WorkerStatus.COMPLETED and self.limitations:
            # Complete work with standing limitations is partial work.  Saying so
            # is not pedantry: the mission's confidence is computed from statuses.
            raise ValueError(
                "a completed report may not carry limitations; record the status as "
                "partial and name what the limitations left out")

        # 4. Every finding must cite evidence the report actually contains.
        known = {item.id for item in self.evidence}
        dangling = sorted({evidence_id for finding in self.findings
                           for evidence_id in finding.evidence_ids
                           if evidence_id not in known})
        if dangling:
            raise ValueError(
                f"finding(s) cite evidence this report does not contain: {dangling[:4]}")

        # 5. The status must agree with the error.
        if self.status is WorkerStatus.FAILED and self.error is None:
            raise ValueError("a failed report must carry the error that failed it")
        if self.error is not None and self.status is WorkerStatus.COMPLETED:
            raise ValueError("a completed report may not carry an error")
        return self

    # -- derived views, all of them checked on construction ---------------

    @property
    def usable(self) -> bool:
        return self.status.usable

    @property
    def evidence_ids(self) -> list[str]:
        return [item.id for item in self.evidence]

    @property
    def citations(self) -> list[str]:
        """Every locator this report can be checked against."""

        return sorted({source.locator for source in self.sources}
                      | {source.locator for item in self.evidence for source in item.sources})

    @property
    def sourced(self) -> bool:
        """Whether every finding can be traced to a source reference."""

        located = {source.locator for source in self.sources}
        return all(any(source.locator in located or source in self.sources
                       for source in item.sources) if item.sources else False
                   for item in self.evidence)

    @property
    def has_follow_up(self) -> bool:
        return bool(self.follow_up)

    @property
    def state(self) -> bool:
        """Whether this report reached a mission-level conclusion.  Always ``False``.

        A report that did cannot be constructed, so the property has one value by
        construction.  It exists because a serialised record crosses boundaries,
        and a reader must be able to *ask* the question of a record it did not
        build.
        """

        return self.declares_conclusion is False and not self.peer_contacts

    def describe(self) -> str:
        return (f"{self.status.value}: {len(self.findings)} finding(s), "
                f"{len(self.evidence)} evidence item(s), {len(self.sources)} source(s), "
                f"{len(self.limitations)} limitation(s), {len(self.follow_up)} follow-up(s)")

    @classmethod
    def from_dict(cls, payload: Mapping[str, Any]) -> "WorkerReport":
        """Rebuild a report from :meth:`to_dict`, dropping the derived keys.

        ``to_dict`` adds ``usable`` and ``citations`` for a reader; they are
        recomputed properties, not state, so a reload must not treat them as
        fields.  Everything else is validated again on the way in — a record that
        crossed a boundary is exactly the one to re-check.
        """

        return cls.model_validate({key: value for key, value in payload.items()
                                   if key not in _DERIVED_REPORT_KEYS})

    def to_dict(self) -> dict[str, Any]:
        """Serialise, keeping every field a reader needs to re-check the work."""

        return {
            "worker_id": self.worker_id,
            "subagent_id": self.subagent_id,
            "task_id": self.task_id,
            "attempt": self.attempt,
            "status": self.status.value,
            "usable": self.usable,
            "summary": self.summary,
            "findings": [json.loads(model_to_json(finding)) for finding in self.findings],
            "evidence": [json.loads(model_to_json(item)) for item in self.evidence],
            "sources": [json.loads(model_to_json(source)) for source in self.sources],
            "citations": self.citations,
            "limitations": list(self.limitations),
            "follow_up": [json.loads(model_to_json(item)) for item in self.follow_up],
            # Structured, so the record reloads; the readable form is beside it.
            "gaps": [json.loads(model_to_json(gap)) for gap in self.gaps],
            "gap_notes": [gap.describe() for gap in self.gaps],
            "error": (json.loads(model_to_json(self.error)) if self.error else None),
            "declares_conclusion": self.declares_conclusion,
            "peer_contacts": list(self.peer_contacts),
            "seconds": round(self.seconds, 3),
        }


# --------------------------------------------------------------------------
# 33.3 Building a report from what a runner actually has
# --------------------------------------------------------------------------

def _sources_from_evidence(evidence: Sequence[EvidenceItem]) -> list[SourceReference]:
    """De-duplicate the source references the evidence already carries.

    Deduplicated by locator *and* retrieval time, not by locator alone: two
    retrievals of the same URL at different times are two facts, and collapsing
    them would hide that the second one happened.
    """

    seen: set[tuple[str, str, str]] = set()
    sources: list[SourceReference] = []
    for item in evidence:
        for source in item.sources:
            key = (source.id or source.locator, source.locator,
                   source.retrieved_at.isoformat())
            if key in seen:
                continue
            seen.add(key)
            sources.append(source)
    return sources


def report_from_evidence(
    worker_id: str,
    subagent_id: str,
    *,
    status: WorkerStatus,
    evidence: Sequence[EvidenceItem] = (),
    summary: str = "",
    findings: Sequence[WorkerFinding] = (),
    limitations: Sequence[str] = (),
    follow_up: Sequence[WorkerFollowUp] = (),
    gaps: Sequence[UnknownValue] = (),
    task_id: str = "",
    attempt: int = 1,
    error: ErrorInfo | None = None,
    started_at: datetime | None = None,
    seconds: float = 0.0,
) -> WorkerReport:
    """Build a report from a runner's evidence, inferring only what is mechanical.

    The one inference made here is a finding per evidence item when the caller
    supplies none — the statement being the evidence's own, so nothing new is
    asserted.  Everything else is passed through: a helper that invented
    limitations or follow-up would be writing the Worker's report for it.
    """

    items = list(evidence)
    derived_findings = list(findings) or [
        WorkerFinding(statement=item.statement, evidence_ids=[item.id], kind=item.kind,
                      confidence=item.confidence, confidence_basis=item.confidence_basis,
                      reasoning=item.reasoning)
        for item in items
    ]
    return WorkerReport(
        worker_id=worker_id, subagent_id=subagent_id, task_id=task_id, attempt=attempt,
        status=status, summary=summary, findings=derived_findings, evidence=items,
        sources=_sources_from_evidence(items), limitations=list(limitations),
        follow_up=list(follow_up), gaps=list(gaps), error=error,
        started_at=started_at, seconds=seconds,
    )


def blocked_report(worker_id: str, subagent_id: str, reason: str, *,
                   follow_up: Sequence[WorkerFollowUp] = (),
                   gap_reason: UnknownReason = UnknownReason.UNAVAILABLE,
                   task_id: str = "", attempt: int = 1,
                   seconds: float = 0.0) -> WorkerReport:
    """A Worker that never got to work: blocked, with the reason as a gap.

    Blocked, not failed: nothing was attempted, so nothing can be said to have
    failed, and the difference matters to the Subagent deciding whether to retry.
    """

    return WorkerReport(
        worker_id=worker_id, subagent_id=subagent_id, task_id=task_id, attempt=attempt,
        status=WorkerStatus.BLOCKED,
        summary=f"{worker_id}: not run — {reason}"[:160].rstrip(" ,;:"),
        limitations=[reason], follow_up=list(follow_up),
        # ``determined_by`` is the component that *established* the gap: the Worker
        # hit the wall, not the Subagent that assigned it.
        gaps=[UnknownValue(reason=gap_reason, detail=reason, determined_by=worker_id)],
        seconds=seconds,
    )


def failed_report(worker_id: str, subagent_id: str, exc: BaseException | str, *,
                  stage: str = "worker", attempt: int = 1, task_id: str = "",
                  follow_up: Sequence[WorkerFollowUp] = (),
                  seconds: float = 0.0) -> WorkerReport:
    """A Worker whose attempt raised: failed, with a redacted, typed error.

    Errors are the commonest secret-leak path, so the message is scrubbed here as
    well as at the field's own validator — the caller may pass an already-redacted
    string, and doing it twice is harmless.
    """

    info = (exc if isinstance(exc, ErrorInfo)
            else ErrorInfo.from_exception(exc, stage=stage, component=worker_id,
                                          attempt=attempt) if isinstance(exc, BaseException)
            else ErrorInfo(code="tool-failure", message=redact_text(str(exc)),
                           stage=stage, component=worker_id, attempt=attempt))
    return WorkerReport(
        worker_id=worker_id, subagent_id=subagent_id, task_id=task_id, attempt=attempt,
        status=WorkerStatus.FAILED,
        summary=f"{worker_id}: failed — {info.message[:120]}",
        limitations=[f"the attempt failed at {stage}: {info.message[:160]}"],
        follow_up=list(follow_up), error=info, seconds=seconds,
    )


def normalize_worker_report(payload: Any, *, worker_id: str = "",
                            subagent_id: str = "", attempt: int = 1) -> WorkerReport:
    """Turn whatever a Worker returned into the one valid shape, or refuse it.

    Accepted, in order of preference:

    *   a :class:`WorkerReport` — validated again, because it may have been
        built elsewhere and crossed a boundary since;
    *   a mapping with the contract's fields;
    *   a mapping with none of them (a bare payload) — treated as **partial**
        evidence for :func:`report_from_evidence`, not as a completed report,
        because a Worker that returned nothing but data has not said it finished;
    *   a list of evidence items.

    A mapping that tries to *say* something the contract forbids is not coerced:
    the conclusion or the peer contact is raised, so a caller cannot accidentally
    launder it into a clean record.
    """

    if isinstance(payload, WorkerReport):
        return WorkerReport.model_validate(payload.model_dump(mode="json"))

    if isinstance(payload, (list, tuple)):
        evidence = [item if isinstance(item, EvidenceItem) else EvidenceItem.model_validate(item)
                    for item in payload]
        return report_from_evidence(
            worker_id or "worker", subagent_id or "subagent",
            status=WorkerStatus.PARTIAL if evidence else WorkerStatus.FAILED,
            evidence=evidence, attempt=attempt,
            limitations=[] if evidence else ["the Worker returned no evidence"])

    if isinstance(payload, Mapping):
        data = dict(payload)
        if {"status", "findings", "evidence", "sources", "limitations"} & set(data):
            # The gate: forbidden fields, then prose, then the status's contract.
            return accept_worker_report(data, worker_id=worker_id,
                                        subagent_id=subagent_id, attempt=attempt)
        evidence = [EvidenceItem.model_validate(item)
                    for item in data.get("evidence") or []]
        return report_from_evidence(
            worker_id or "worker", subagent_id or "subagent",
            status=WorkerStatus.PARTIAL if evidence else WorkerStatus.FAILED,
            evidence=evidence, attempt=attempt,
            summary=str(data.get("summary") or "")[:200],
            limitations=[] if evidence else ["the Worker returned no usable evidence"])

    raise TypeError(f"a Worker may not return {type(payload).__name__}; "
                    "return a WorkerReport, a mapping, or a list of evidence items")


# --------------------------------------------------------------------------
# 33.4 Standing in for a failed tool: one unit's failure is not the mission's
# --------------------------------------------------------------------------

class ToolCallResult(StrictModel):
    """What one tool call actually did — enough to decide how to report it.

    ``ok`` is derived from ``status``/``error`` rather than supplied, so a caller
    cannot mark a failed call successful by forgetting to set it.
    """

    tool: str = Field(min_length=1)
    status: WorkerStatus = WorkerStatus.COMPLETED
    evidence: list[EvidenceItem] = Field(default_factory=list)
    error: ErrorInfo | None = None
    limitations: list[str] = Field(default_factory=list)
    seconds: float = Field(default=0.0, ge=0)

    @model_validator(mode="after")
    def _coherent(self) -> "ToolCallResult":
        if self.status is WorkerStatus.FAILED and self.error is None:
            raise ValueError("a failed tool call must carry the error that failed it")
        if self.status is WorkerStatus.COMPLETED and not self.evidence:
            raise ValueError("a completed tool call must return at least one evidence item")
        if not self.status.usable and not self.limitations and self.error is None:
            raise ValueError(f"a {self.status.value} tool call must say why")
        return self

    @property
    def ok(self) -> bool:
        return self.status is WorkerStatus.COMPLETED


def survive_tool_failure(
    tool: str,
    call: Callable[[], Any],
    *,
    worker_id: str,
    subagent_id: str,
    attempt: int = 1,
    gather: Callable[[Any], Sequence[EvidenceItem]] | None = None,
    follow_up: Sequence[WorkerFollowUp] = (),
) -> ToolCallResult:
    """Run one tool call and turn any failure into a result instead of an exception.

    The mission-level guarantee of this task lives here: a tool that raises, a
    tool that hangs up mid-write, a tool that returns rubbish — each becomes a
    ``ToolCallResult`` with a status and an error, never a traceback that unwinds
    the graph.  ``CancellationRequested`` is re-raised, because cancellation is an
    operator's decision and swallowing it would make Ctrl-C unreliable.

    Evidence that a failing tool already produced is *kept*: those items were
    collected, they carry their provenance, and dropping them would discard the
    usable part of a partial result.
    """

    started = time.monotonic()
    try:
        value = call()
    except CancellationRequested:
        raise
    except Exception as exc:                  # a tool failure is a result, not a crash
        partial: list[EvidenceItem] = []
        if gather is not None:
            try:
                partial = [item if isinstance(item, EvidenceItem)
                           else EvidenceItem.model_validate(item)
                           for item in gather(exc)]
            except Exception:                 # pragma: no cover - a broken salvage
                partial = []
        return ToolCallResult(
            # FAILED, not PARTIAL: the *tool* failed.  What survives the failure is
            # recorded beside it, and the Worker's own report (which folds several
            # results) is what becomes partial.  Calling the tool "partial" would
            # leave a reader unable to tell which call broke.
            tool=tool, status=WorkerStatus.FAILED,
            evidence=partial,
            error=ErrorInfo.from_exception(exc, stage="tool", component=tool,
                                           attempt=attempt),
            limitations=[f"{tool} failed: {redact_text(str(exc))[:160]}"]
                        + ([f"{len(partial)} item(s) survived the failure"] if partial else []),
            seconds=time.monotonic() - started,
        )
    collected: list[EvidenceItem] = []
    if gather is not None:
        collected = [item if isinstance(item, EvidenceItem)
                     else EvidenceItem.model_validate(item)
                     for item in gather(value)]
    elif isinstance(value, WorkerReport):     # pragma: no cover - a report is not a tool result
        collected = list(value.evidence)
    return ToolCallResult(tool=tool, status=WorkerStatus.COMPLETED if collected
                          else WorkerStatus.PARTIAL,
                          evidence=collected,
                          limitations=[] if collected else [f"{tool} returned no evidence"],
                          seconds=time.monotonic() - started)


def report_from_tool_results(
    worker_id: str, subagent_id: str, results: Sequence[ToolCallResult], *,
    attempt: int = 1, task_id: str = "",
    summary: str = "", follow_up: Sequence[WorkerFollowUp] = (),
) -> WorkerReport:
    """Fold several tool results into one Worker report.

    The status is the *worst* outcome that still leaves something usable, and
    never better than the worst tool: three good calls and one failure are a
    partial report, not a completed one.  All surviving evidence is kept, with
    its original source references.
    """

    if not results:
        return blocked_report(worker_id, subagent_id,
                              "no tool call was made for this unit", task_id=task_id,
                              attempt=attempt)
    evidence = [item for result in results for item in result.evidence]
    limitations = [line for result in results
                   for line in result.limitations if result.status is not WorkerStatus.COMPLETED]
    errors = [result.error for result in results if result.error is not None]
    if not evidence:
        return failed_report(worker_id, subagent_id, errors[0] if errors else
                             f"every tool call for this unit failed ({len(results)})",
                             attempt=attempt, task_id=task_id, follow_up=follow_up)
    status = (WorkerStatus.COMPLETED
              if all(result.ok for result in results) and evidence
              else WorkerStatus.PARTIAL)
    return report_from_evidence(
        worker_id, subagent_id, status=status, evidence=evidence,
        summary=summary or f"{len(evidence)} item(s) from {len(results)} tool call(s), "
                           f"{sum(1 for result in results if not result.ok)} of which failed",
        limitations=limitations, follow_up=follow_up,
        gaps=[UnknownValue(reason=UnknownReason.FAILED, detail=line[:160],
                           determined_by=worker_id) for line in limitations],
        attempt=attempt, task_id=task_id,
        error=(errors[0] if status is WorkerStatus.PARTIAL and errors else None))


# --------------------------------------------------------------------------
# 33.5 The seam into the flow: a WorkerReport next to a WorkerOutcome
# --------------------------------------------------------------------------

def outcome_from_report(report: WorkerReport, *, gate: FlowGate = FlowGate.NONE,
                        seconds: float = 0.0) -> "WorkerOutcome":
    """Convert a validated report into the graph's own outcome record.

    The mapping is total and lossless in the direction that matters: the status,
    the findings' evidence and the limitations all survive, and the *report* is
    carried in the payload so a reviewer can see what the Worker actually said
    rather than only how the graph summarised it.  ``WorkerOutcome`` remains the
    graph's record; this is the contract's record, and they name the same attempt.
    """

    status = {WorkerStatus.COMPLETED: EntityStatus.SUCCEEDED,
              WorkerStatus.PARTIAL: EntityStatus.BLOCKED,
              WorkerStatus.BLOCKED: EntityStatus.BLOCKED,
              WorkerStatus.FAILED: EntityStatus.FAILED}[report.status]
    resolved_gate = gate
    if report.status is WorkerStatus.PARTIAL and gate is FlowGate.NONE:
        resolved_gate = FlowGate.NONE
    elif report.status is WorkerStatus.BLOCKED and gate is FlowGate.NONE:
        resolved_gate = FlowGate.DEPENDENCY_FAILED
    elif report.status is WorkerStatus.FAILED and gate is FlowGate.NONE:
        resolved_gate = FlowGate.ERROR
    return WorkerOutcome(
        worker_id=report.worker_id, subagent_id=report.subagent_id,
        task_id=report.task_id, status=status, attempt=report.attempt,
        gate=resolved_gate, summary=report.summary[:200],
        evidence_ids=report.evidence_ids,
        payload={"evidence": [json.loads(model_to_json(item))
                              for item in report.evidence],
                 "report": report.to_dict()},
        error=(report.error.message[:200] if report.error
               else ("; ".join(report.limitations)[:200]
                     if report.status is not WorkerStatus.COMPLETED else None)),
        seconds=seconds or report.seconds,
    )


def report_from_outcome(outcome: "WorkerOutcome") -> WorkerReport:
    """Recover the contract's report from a graph outcome.

    A runner that still returns :class:`WorkerOutcome` is not exempt from the
    contract: its payload carries the report when one was produced, and when it
    does not, the outcome is *reported as partial with an explicit limitation* —
    the graph's older shape is tolerated, but its silence about provenance is not
    mistaken for a completed report.
    """

    carried = (outcome.payload or {}).get("report")
    if isinstance(carried, Mapping):
        return WorkerReport.from_dict(dict(carried))
    evidence = [EvidenceItem.model_validate(item)
                for item in (outcome.payload or {}).get("evidence") or []]
    if outcome.status is EntityStatus.SUCCEEDED:
        return report_from_evidence(
            outcome.worker_id, outcome.subagent_id,
            status=WorkerStatus.PARTIAL if evidence else WorkerStatus.BLOCKED,
            evidence=evidence, summary=outcome.summary, attempt=outcome.attempt,
            task_id=outcome.task_id,
            limitations=["the outcome carried no WorkerReport: its findings, sources and "
                         "follow-up are unknown, so this is not recorded as completed"],
            seconds=outcome.seconds)
    if outcome.status is EntityStatus.FAILED:
        return failed_report(
            outcome.worker_id, outcome.subagent_id,
            ErrorInfo(code="runner", message=outcome.error or "the Worker failed",
                      stage="worker", component=outcome.worker_id,
                      attempt=outcome.attempt) if outcome.error else outcome.error or
            "the Worker failed without an error",
            attempt=outcome.attempt, task_id=outcome.task_id, seconds=outcome.seconds)
    return blocked_report(outcome.worker_id, outcome.subagent_id,
                          outcome.error or f"the Worker reported {outcome.status.value}",
                          attempt=outcome.attempt, task_id=outcome.task_id,
                          seconds=outcome.seconds)


def _report_of(outcome: "WorkerOutcome") -> WorkerReport | None:
    """The Worker's report, when the outcome carries one.  Never raises.

    The graph calls this for every settled unit, so a malformed report — one written
    by an older build, or edited in a case file — must not take a mission down.  It
    is reported as absent instead, and the ledger's gap says why.
    """

    carried = (outcome.payload or {}).get("report")
    if not isinstance(carried, Mapping):
        return None
    try:
        return WorkerReport.from_dict(dict(carried))
    except ValueError:
        return None


def _with_worker_contract(outcome: "WorkerOutcome") -> "WorkerOutcome":
    """Attach a conforming :class:`WorkerReport` to a graph outcome, or explain itself.

    Three cases, all of them non-fatal:

    *   the payload already carries a report — revalidated, and normalised to the
        derived-key-free form so a later read cannot mistake ``to_dict``'s extras
        for fields;
    *   the unit did not succeed and carries no report — one is built from the
        outcome, so a failed unit still says what failed and what is missing;
    *   the unit succeeded without a report — its report is *attached as partial
        with a named limitation*.  The outcome's own status is left exactly as the
        reviewer judged it (demoting it would rewrite the graph's record), but the
        contract's record cannot say "completed" about work whose findings, sources
        and follow-up are unknown.  :func:`report_from_outcome` makes the same call.
    """

    if isinstance((outcome.payload or {}).get("report"), Mapping):
        report = _report_of(outcome)
        if report is None:
            report = report_from_outcome(outcome.model_copy(update={
                "payload": {key: value for key, value in (outcome.payload or {}).items()
                            if key != "report"}}))
        return outcome.model_copy(update={
            "payload": {**(outcome.payload or {}), "report": report.to_dict()}})
    report = report_from_outcome(outcome)
    return outcome.model_copy(update={
        "payload": {**(outcome.payload or {}), "report": report.to_dict()}})


def merge_reports(worker_id: str, subagent_id: str,
                  reports: Sequence[WorkerReport]) -> WorkerReport:
    """Combine a Worker's retry attempts into one report — never better than the last.

    Retries are attempts at the same unit, and the later attempt supersedes the
    earlier one's *findings* while inheriting the earlier one's *limitations*: a
    retry that succeeded on the second try still had a first try that failed, and a
    report that forgot it would overstate how straightforward the work was.
    Evidence from every attempt is kept, because it was collected.
    """

    if not reports:
        return blocked_report(worker_id, subagent_id, "no attempt was recorded")
    final = reports[-1]
    earlier = [f"attempt {report.attempt} ended {report.status.value}"
               + (f": {report.error.message[:100]}" if report.error else "")
               for report in reports[:-1]]
    evidence: list[EvidenceItem] = []
    seen: set[str] = set()
    for report in reports:
        for item in report.evidence:
            if item.id not in seen:
                seen.add(item.id)
                evidence.append(item)
    limitations = ([*final.limitations, *earlier]
                   if final.status is not WorkerStatus.COMPLETED else [])
    status = final.status
    if status is WorkerStatus.COMPLETED and earlier:
        # A completed retry after a failed attempt is still completed work; the
        # earlier failures are history, not limitations of the final attempt.
        limitations = []
    findings = list(final.findings) or [
        WorkerFinding(statement=item.statement, evidence_ids=[item.id], kind=item.kind,
                      confidence=item.confidence, confidence_basis=item.confidence_basis)
        for item in evidence]
    return WorkerReport(
        worker_id=worker_id, subagent_id=subagent_id, task_id=final.task_id,
        attempt=final.attempt, status=status, summary=final.summary,
        findings=findings, evidence=evidence,
        sources=_sources_from_evidence(evidence), limitations=limitations,
        follow_up=list(final.follow_up), gaps=list(final.gaps), error=final.error,
        started_at=final.started_at, seconds=final.seconds)


# --------------------------------------------------------------------------
# 33.6 A team-level view: statuses, provenance and gaps across many reports
# --------------------------------------------------------------------------

class OutcomeLedger(StrictModel):
    """Every Worker report for one mission, with the counts the readers need.

    The ledger's job is to make a *partial* mission legible: which units
    completed, which were partial and why, whether the partial work still has
    provenance, and what the Subagent still owes the mission.
    """

    reports: list[WorkerReport] = Field(default_factory=list)

    @property
    def by_status(self) -> dict[str, list[str]]:
        grouped: dict[str, list[str]] = {status.value: [] for status in WorkerStatus}
        for report in self.reports:
            grouped[report.status.value].append(report.worker_id)
        return grouped

    @property
    def usable(self) -> list[WorkerReport]:
        return [report for report in self.reports if report.usable]

    @property
    def partial(self) -> list[WorkerReport]:
        return [report for report in self.reports if report.status is WorkerStatus.PARTIAL]

    @property
    def blocked(self) -> list[WorkerReport]:
        return [report for report in self.reports if report.status is WorkerStatus.BLOCKED]

    @property
    def failed(self) -> list[WorkerReport]:
        return [report for report in self.reports if report.status is WorkerStatus.FAILED]

    @property
    def evidence(self) -> list[EvidenceItem]:
        return [item for report in self.reports for item in report.evidence]

    @property
    def follow_up(self) -> list[WorkerFollowUp]:
        return [item for report in self.reports for item in report.follow_up]

    @property
    def complete(self) -> bool:
        """Whether every unit completed.  One partial unit means a partial mission."""

        return bool(self.reports) and all(report.status is WorkerStatus.COMPLETED
                                          for report in self.reports)

    @property
    def provenance_intact(self) -> bool:
        """Whether *every* usable item still has a source reference.

        The acceptance clause about partial results retaining usable provenance,
        as a property of the ledger rather than of one report: partial work that
        lost its sources is not usable work.
        """

        return all(item.sources for report in self.usable for item in report.evidence)

    def gaps(self) -> list[UnknownValue]:
        gaps = [gap for report in self.reports for gap in report.gaps]
        for report in self.reports:
            # A unit that declared its own gaps has already said why; adding a
            # second for the same unit would double-count the mission's unknowns.
            if report.status.usable or report.gaps:
                continue
            detail = (report.error.message if report.error
                      else "; ".join(report.limitations)[:160] or "no reason recorded")
            gaps.append(UnknownValue(reason=UnknownReason.FAILED,
                                     determined_by=report.worker_id,
                                     detail=f"{report.worker_id}: {detail}"[:200]))
        return gaps

    def summary(self) -> str:
        counts = ", ".join(f"{len(ids)} {status}" for status, ids in self.by_status.items()
                           if ids) or "none"
        return (f"{len(self.reports)} worker report(s): {counts}; "
                f"{len(self.evidence)} evidence item(s); "
                f"provenance {'intact' if self.provenance_intact else 'incomplete'}")

    def to_dict(self) -> dict[str, Any]:
        return {
            "reports": [report.to_dict() for report in self.reports],
            "by_status": self.by_status,
            "complete": self.complete,
            "provenance_intact": self.provenance_intact,
            "evidence": len(self.evidence),
            "follow_up": [item.describe() for item in self.follow_up],
            "gaps": [gap.describe() for gap in self.gaps()],
            "summary": self.summary(),
        }


def outcome_ledger(reports: Sequence[WorkerReport]) -> OutcomeLedger:
    return OutcomeLedger(reports=list(reports))


# --------------------------------------------------------------------------
# 33.7 The scripted team: four Workers, one of every status
# --------------------------------------------------------------------------

#: The evidence a scripted Worker produces.  Real models with real source
#: references, so nothing downstream has to pretend provenance exists.
def _worker_demo_source(name: str, *, url: str | None = None,
                        path: str | None = None) -> SourceReference:
    return SourceReference(
        kind=SourceKind.PUBLIC_WEB if url else SourceKind.LOG_FILE,
        url=url, artifact_path=None if url else path,
        title=name, retrieved_at=datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc),
        retrieval_method=RetrievalMethod.HTTP if url else RetrievalMethod.LOCAL_READ,
        http_status=200 if url else None, excerpt=f"excerpt from {name}",
    )


def _worker_demo_evidence(label: str, statement: str, *, name: str,
                          url: str | None = None, path: str | None = None,
                          worker: str = "w-proxy") -> EvidenceItem:
    return EvidenceItem(
        kind=EvidenceKind.OBSERVATION, statement=statement,
        sources=[_worker_demo_source(name, url=url, path=path)],
        confidence=Confidence.LOW,
        confidence_basis="one automated retrieval of one source; not corroborated",
        collected_by=worker, observed_at=datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc),
        tags=[label],
    )


def worker_demo_reports() -> dict[str, WorkerReport]:
    """One report per status, each with the provenance its status promises.

    *   ``completed`` — the proxy log was read in full; three observations, all
        cited.  No limitations, because a completed report that hedges is a
        partial one wearing the wrong label.
    *   ``partial`` — the DNS log was readable for one day of the window, so the
        one observation it produced is real and cited, and the limitation names
        the days that are missing.
    *   ``blocked`` — the archive needs credentials nobody has; nothing was read,
        so nothing is claimed, and the gap is typed rather than described.
    *   ``failed`` — the hash tool died on a corrupt file after reading one
        record; that record survives, with its source, beside the error.

    A fifth report is *refused* rather than produced: see
    :func:`worker_demo_refusals`.
    """

    proxy_evidence = [
        _worker_demo_evidence("proxy", "the proxy log records a CONNECT to evil.example.org",
                              name="proxy.log", path="/evidence/proxy.log"),
        _worker_demo_evidence("proxy", "the same log records 412 bytes returned to "
                                       "10.0.0.5 on that CONNECT",
                              name="proxy.log", path="/evidence/proxy.log"),
        _worker_demo_evidence("proxy", "the user agent on that request is the default "
                                       "curl/8.4.0 string",
                              name="proxy.log", path="/evidence/proxy.log"),
    ]
    completed = report_from_evidence(
        "w-proxy", "sa-network", status=WorkerStatus.COMPLETED, evidence=proxy_evidence,
        summary="read the whole proxy log and extracted three cited observations",
        follow_up=[WorkerFollowUp(
            suggestion="re-read the proxy log for the two hours before the CONNECT",
            reason="the log starts mid-session, so the request that led to it is not in "
                   "the captured window",
            priority=FollowUpPriority.HIGH)],
        task_id=content_id("task", "sa-network", "w-proxy", 1),
        started_at=datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc), seconds=1.5,
    )

    dns_evidence = [_worker_demo_evidence(
        "dns", "the resolver log shows one A query for evil.example.org at 10:00:00Z",
        name="dns.log", path="/evidence/dns.log", worker="w-dns")]
    partial = report_from_evidence(
        "w-dns", "sa-network", status=WorkerStatus.PARTIAL, evidence=dns_evidence,
        summary="read one day of the resolver log; the rest of the window is missing",
        limitations=["the resolver rotates logs weekly and only 2026-05-04 survives, so "
                     "queries on the other six days cannot be checked",
                     "queries answered from cache are not logged at all"],
        follow_up=[WorkerFollowUp(
            suggestion="collect the rotated resolver logs from the backup volume",
            reason="the missing six days are the only way to test whether the query "
                   "pattern is routine or exceptional",
            priority=FollowUpPriority.HIGH, blocked_by="backup volume not mounted")],
        task_id=content_id("task", "sa-network", "w-dns", 1), seconds=0.9,
    )

    blocked = blocked_report(
        "w-archive", "sa-history", "the archive requires an API key this mission does not "
                                   "hold, and the policy forbids out-of-scope collection",
        gap_reason=UnknownReason.OUT_OF_SCOPE,
        follow_up=[WorkerFollowUp(
            suggestion="request an archive key for this objective from the operator",
            reason="the archive is the only source for the March snapshot",
            priority=FollowUpPriority.MEDIUM)],
        task_id=content_id("task", "sa-history", "w-archive", 1), seconds=0.2,
    )

    surviving = [_worker_demo_evidence(
        "hash", "the corrupt capture's first record hashes to the same digest as the "
                "advisory's sample",
        name="capture.pcap", path="/evidence/capture.pcap", worker="w-hash")]
    failed = report_from_evidence(
        "w-hash", "sa-integrity", status=WorkerStatus.FAILED, evidence=surviving,
        summary="hashed one record of the capture before the reader aborted",
        limitations=["the pcap reader aborted partway through the file, so only the first "
                     "record was hashed",
                     "the digest covers one record, not the whole capture"],
        follow_up=[WorkerFollowUp(
            suggestion="re-hash the capture with the record-boundary check disabled",
            reason="the abort was at a malformed record boundary, not in the data")],
        error=ErrorInfo(code="pcap-truncated", stage="tool", component="w-hash",
                        message="unexpected end of pcap record at offset 4096",
                        cause_type="TruncatedCapture"),
        task_id=content_id("task", "sa-integrity", "w-hash", 1), seconds=2.2,
    )
    # A failed report may still keep what was collected, but the contract requires
    # the error and the limitation to agree — see the self-test.
    return {"completed": completed, "partial": partial, "blocked": blocked,
            "failed": failed}


def worker_demo_refusals() -> dict[str, str]:
    """The two reports a Worker may not return, and the error each one raises.

    Written as failing constructions rather than as prose, so the prohibition is
    demonstrated by the same code path that enforces it.
    """

    evidence = [_worker_demo_evidence(
        "refusal", "the page's certificate expired six days before the capture",
        name="tls.json", url="https://example.com/tls.json")]
    refusals: dict[str, str] = {}

    def attempt(key: str, *,
                call: Callable[[], Any] | None = None,
                payload_extra: Mapping[str, Any] | None = None,
                **kwargs: Any) -> None:
        try:
            if call is not None:
                # The refusal may happen when the *field* is built (a finding's
                # statement is validated on construction), so the whole
                # construction is inside the try, not just the report.
                call()
            elif payload_extra is not None:
                # A field the contract forbids, in a mapping that otherwise looks
                # like a report: refused structurally, before any prose is read.
                payload = {"worker_id": "w-refuse", "subagent_id": "sa-network",
                           "status": "completed", "findings": [
                               {"statement": "the certificate expired",
                                "evidence_ids": [item.id for item in kwargs["evidence"]]}],
                           "evidence": [json.loads(model_to_json(item))
                                        for item in kwargs["evidence"]],
                           **payload_extra}
                normalize_worker_report(payload)
            else:
                report_from_evidence("w-refuse", "sa-network",
                                     status=WorkerStatus.COMPLETED, **kwargs)
        except (ConclusionLeak, PeerContactError, ValueError) as exc:
            refusals[key] = f"{type(exc).__name__}: {exc}"
        else:                                  # a prohibition that let it through
            refusals[key] = "accepted"

    attempt("conclusion_in_summary", evidence=evidence,
            summary="the mission is complete: the actor is the operator of evil.example.org")
    # The phrase is in a *finding*, not the summary: the scan is of the payload's
    # prose, and a verdict written one level down is the same claim.
    attempt("conclusion_in_a_finding", call=lambda: report_from_evidence(
        "w-refuse", "sa-network", status=WorkerStatus.COMPLETED, evidence=evidence,
        summary="read the certificate record",
        findings=[WorkerFinding(
            statement="we can conclude that the certificate was replaced deliberately",
            evidence_ids=[item.id for item in evidence])]))
    attempt("peer_contact", evidence=evidence,
            summary="read the certificate record, then delegated to the archive team")
    attempt("completed_with_limitations", evidence=evidence,
            summary="read the certificate record",
            limitations=["the page's body was not readable"])
    attempt("partial_without_provenance", evidence=[
        EvidenceItem(kind=EvidenceKind.ALLEGATION,
                     statement="a vendor says the domain was registered in March",
                     allegation_made_by="the vendor advisory")],
        summary="recorded the registration claim",
        limitations=["only a claim, no document"])
    attempt("identity_claim_field", evidence=evidence, summary="read the certificate record",
            payload_extra={"attribution": "the actor"})
    return refusals


# --------------------------------------------------------------------------
# 33.8 The runner seam: a wrapper that cannot let a failure escape
# --------------------------------------------------------------------------

class ReportingRunner:
    """Wrap a runner so every attempt yields a validated report — or a failure record.

    The graph already turns a runner exception into an outcome (§25).  This wrapper
    makes the *contract* the thing that holds: the failure is a
    :class:`WorkerReport` with a status, an error and its limitations, the report is
    kept, and the caller gets a ``WorkerOutcome`` so the graph is unchanged.  Any
    other attribute is delegated, so a wrapped runner still reviews and
    synthesises as itself.
    """

    def __init__(self, inner: Any) -> None:
        self.inner = inner
        self.reports: list[WorkerReport] = []

    # -- the one method the contract is about ------------------------------
    def run_worker(self, subagent: Any, worker: Any, *, attempt: int,
                   guidance: str = "") -> "WorkerOutcome":
        started = time.monotonic()
        try:
            outcome = self.inner.run_worker(subagent, worker, attempt=attempt,
                                            guidance=guidance)
        except CancellationRequested:
            raise
        except Exception as exc:            # a runner failure is a report, not a crash
            report = failed_report(
                getattr(worker, "id", "worker"), getattr(subagent, "id", "subagent"),
                exc, stage="runner", attempt=attempt,
                seconds=time.monotonic() - started)
        else:
            report = report_from_outcome(outcome)
        self.reports.append(report)
        converted = outcome_from_report(report)
        return converted.model_copy(update={
            "seconds": converted.seconds or (time.monotonic() - started)})

    def __getattr__(self, name: str) -> Any:      # review, synthesize, everything else
        return getattr(self.inner, name)

    # -- what the wrapper saw ----------------------------------------------
    def ledger(self) -> OutcomeLedger:
        return outcome_ledger(self.reports)


# --------------------------------------------------------------------------
# 33.9 The scripted failures: a tool that raises, and the work it kept
# --------------------------------------------------------------------------

class _CorruptCapture:
    """A stand-in tool that produces one record, then fails reading the next.

    The failure is the ordinary kind: a truncated file, discovered mid-read, after
    the first record was already parsed.  The parsed record is a real
    :class:`EvidenceItem` with a real source, so the partial result is usable — and
    that is the point of the acceptance clause.
    """

    def __init__(self) -> None:
        self.records: list[EvidenceItem] = []

    def read_record(self) -> EvidenceItem:
        item = _worker_demo_evidence(
            "capture", "the capture's first record is a TLS handshake to "
                       "evil.example.org",
            name="capture.pcap", path="/evidence/capture.pcap", worker="w-hash")
        self.records.append(item)
        return item

    def __call__(self) -> EvidenceItem:
        self.read_record()
        raise TruncatedCaptureRead(
            "unexpected end of pcap record at offset 4096 (token=api_key=abcd1234efgh)")

    def salvage(self, _exc: BaseException) -> list[EvidenceItem]:
        return list(self.records)


class TruncatedCaptureRead(Exception):
    """The demo's tool failure.  A local exception type, so the message is ours."""


def _outcome_tool_demo() -> dict[str, Any]:
    """One Worker whose third tool call fails after producing a usable record.

    Both halves of the acceptance clause are visible here at once: the failure did
    not raise, and the record the tool had already produced kept its source.
    """

    capture = _CorruptCapture()
    good = survive_tool_failure(
        "http.fetch", lambda: _worker_demo_evidence(
            "dns", "the resolver log shows one A query for evil.example.org",
            name="dns.log", path="/evidence/dns.log", worker="w-mixed"),
        worker_id="w-mixed", subagent_id="sa-network",
        gather=lambda value: [value])
    broken = survive_tool_failure(
        "pcap.read", capture, worker_id="w-mixed", subagent_id="sa-network",
        gather=capture.salvage)
    report = report_from_tool_results(
        "w-mixed", "sa-network", [good, broken],
        follow_up=[WorkerFollowUp(
            suggestion="re-read the capture with a record-boundary-tolerant reader",
            reason="the abort was at a malformed boundary; the data before it parsed")])
    return {
        "tools": [{"tool": result.tool, "status": result.status.value,
                   "ok": result.ok, "evidence": len(result.evidence),
                   "error": (result.error.message if result.error else None),
                   "limitations": result.limitations}
                  for result in (good, broken)],
        "report": report.to_dict(),
        "raised": False,
    }


def _outcome_runner_demo() -> dict[str, Any]:
    """A runner that raises, wrapped so the mission cannot see the exception."""

    class ExplodingRunner:
        def run_worker(self, subagent: Any, worker: Any, *, attempt: int,
                       guidance: str = "") -> Any:
            raise RuntimeError("the collector segfaulted while parsing the archive")

        def review_worker(self, *_args: Any, **_kwargs: Any) -> Any:
            return None

        def synthesize(self, *_args: Any, **_kwargs: Any) -> Any:
            return None

    class _Unit:
        def __init__(self, ident: str) -> None:
            self.id = ident

    wrapped = ReportingRunner(ExplodingRunner())
    outcome = wrapped.run_worker(_Unit("sa-network"), _Unit("w-explode"), attempt=1)
    return {
        "raised": False,
        "outcome_status": outcome.status.value,
        "outcome_gate": outcome.gate.value,
        "outcome_error": outcome.error,
        "report": wrapped.reports[0].to_dict(),
        "ledger": wrapped.ledger().to_dict(),
    }


def worker_outcome_demo() -> dict[str, Any]:
    """The whole contract on one screen: four statuses, six refusals, two failures."""

    reports = worker_demo_reports()
    ledger = outcome_ledger(list(reports.values()))
    return {
        "statuses": [status.value for status in WorkerStatus],
        "reports": {name: report.to_dict() for name, report in reports.items()},
        "ledger": ledger.to_dict(),
        "refusals": worker_demo_refusals(),
        "tool_failure": _outcome_tool_demo(),
        "runner_failure": _outcome_runner_demo(),
        "mission": {
            # A mission with a blocked and a failed Worker still has an aggregate:
            # this is the acceptance clause stated as data.
            "continued": True,
            "usable_workers": len(ledger.usable),
            "complete": ledger.complete,
            "provenance_intact": ledger.provenance_intact,
            "statement": ("no exception escaped a Worker: the partial reports keep their "
                          "sources, and the gaps are reported instead of raised"),
        },
    }


# --------------------------------------------------------------------------
# 33.10 Self-test — the acceptance criteria as executable checks
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class OutcomeCheck:
    name: str
    ok: bool
    detail: str = ""


def _oc(name: str, ok: Any, detail: Any = "") -> OutcomeCheck:
    return OutcomeCheck(name=name, ok=bool(ok), detail=str(detail)[:150])


def _w_evidence(statement: str, *, url: str = "https://example.com/report",
                kind: EvidenceKind = EvidenceKind.OBSERVATION,
                sources: bool = True) -> EvidenceItem:
    """One evidence item for the checks: real, cited, and boring on purpose."""

    source = SourceReference(kind=SourceKind.PUBLIC_WEB, url=url,
                             retrieved_at=datetime(2026, 5, 4, 10, tzinfo=timezone.utc))
    return EvidenceItem(
        kind=kind, statement=statement,
        sources=[source] if sources else [],
        allegation_made_by="the vendor advisory" if kind is EvidenceKind.ALLEGATION else None,
        confidence=Confidence.LOW if sources else Confidence.UNKNOWN,
        confidence_basis="one automated retrieval" if sources else None,
        collected_by="w-test")


def _refused(call: Callable[[], Any]) -> tuple[str, str]:
    """Run a construction that must be refused; return (type, message).

    ``CancellationRequested`` is included so a check can assert that cancellation
    is *not* swallowed — the one exception this contract lets through.
    """

    try:
        call()
    except (ConclusionLeak, PeerContactError, ValueError, TypeError,
            CancellationRequested) as exc:
        return type(exc).__name__, str(exc)
    return "", "accepted"


def run_outcome_self_test() -> list[OutcomeCheck]:
    """Prove the contract: four statuses, no conclusions, no peer contact, no crashes.

    The acceptance clauses are the last two groups: a failed *tool* is a report
    rather than an exception (33.9), and a partial report keeps provenance a
    reader can follow (33.2/33.6).
    """

    checks: list[OutcomeCheck] = []
    add = checks.append

    # ---- 1. the vocabulary ------------------------------------------------
    add(_oc("exactly four worker statuses are defined", len(WorkerStatus) == 4,
            [status.value for status in WorkerStatus]))
    add(_oc("the four statuses are the documented ones",
            [status.value for status in WorkerStatus]
            == ["completed", "partial", "blocked", "failed"],
            [status.value for status in WorkerStatus]))
    add(_oc("completed and partial are the usable statuses",
            [status for status in WorkerStatus if status.usable]
            == [WorkerStatus.COMPLETED, WorkerStatus.PARTIAL]))
    add(_oc("a blocked report is not usable work",
            not WorkerStatus.BLOCKED.usable and not WorkerStatus.FAILED.usable))
    add(_oc("only completed is an unqualified success",
            [status for status in WorkerStatus if status.ok] == [WorkerStatus.COMPLETED]))
    add(_oc("a follow-up has three ordered priorities",
            [item.value for item in FollowUpPriority] == ["low", "medium", "high"]
            and FollowUpPriority.LOW.rank < FollowUpPriority.HIGH.rank))
    add(_oc("a refused conclusion is a ValueError, so callers can catch it",
            issubclass(ConclusionLeak, ValueError)))
    add(_oc("a refused peer contact is a ValueError too",
            issubclass(PeerContactError, ValueError)))

    # ---- 2. the prohibition on conclusions is structural -------------------
    add(_oc("the report has no field for a conclusion, verdict or identity",
            not (set(WorkerReport.model_fields)
                 & {"conclusion", "conclusions", "verdict", "identity", "actor",
                    "attribution", "final_answer"}),
            sorted(WorkerReport.model_fields)))
    add(_oc("no report field name is on the forbidden list",
            not forbidden_fields({"x": WorkerReport.model_fields.keys()},
                                 allow=_CONTRACT_FIELDS)
            and not [name for name in WorkerReport.model_fields
                     if any(fragment in name.lower() for fragment in _FORBIDDEN_FIELDS)
                     and name not in _FORBIDDEN_ALLOWED]))
    add(_oc("a recipients field is refused",
            forbidden_fields({"recipients": ["other-team"]}) == ["recipients"]))
    add(_oc("a nested attribution field is refused",
            forbidden_fields({"metadata": {"attribution": "the actor"}})
            == ["metadata.attribution"]))
    add(_oc("a forbidden field inside a list of rows is refused",
            forbidden_fields({"rows": [{"peer_id": "sa-2"}]}) == ["rows[0].peer_id"]))
    add(_oc("a channel field is refused", bool(forbidden_fields({"channel": "slack"}))))
    add(_oc("the contract's own fields are not reported as forbidden",
            forbidden_fields(worker_demo_reports()["completed"].to_dict(),
                             allow=_CONTRACT_FIELDS) == []))
    add(_oc("a report may say it claims no identity",
            forbidden_fields({"identity_claimed": False}) == [],
            "identity_claimed is the field that records the absence of a claim"))
    add(_oc("the serialised report contains no forbidden field",
            forbidden_fields(worker_demo_reports()["partial"].to_dict(),
                             allow=_CONTRACT_FIELDS | _DERIVED_REPORT_KEYS) == []))
    add(_oc("a conclusion cannot be attached as an extra field",
            _coerce_refuses(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="blocked",
                limitations=["x"], conclusion="the case is closed"))[0]
            == "ValidationError"))
    declared = _coerce_refuses(lambda: WorkerReport(
        worker_id="w", subagent_id="s", status="blocked",
        limitations=["nothing was read"], declares_conclusion=True))
    add(_oc("there is no way to build a report that declares a conclusion",
            declared[0] == "ValidationError"
            and refusal_kind(declared[1]) == "conclusion", declared[1][:90]))
    contact = _coerce_refuses(lambda: WorkerReport(
        worker_id="w", subagent_id="s", status="blocked",
        limitations=["nothing was read"], peer_contacts=["sa-archive"]))
    add(_oc("there is no way to build a report with a peer contact",
            contact[0] == "ValidationError"
            and refusal_kind(contact[1]) == "peer-contact", contact[1][:90]))
    add(_oc("a refusal is classified by its message, not by its type",
            refusal_kind(ConclusionLeak("f", "p").args[0]) == "conclusion"
            and refusal_kind(PeerContactError("f", "p").args[0]) == "peer-contact"
            and refusal_kind("something else") == "other",
            "pydantic wraps the type; the message survives"))
    add(_oc("a valid report says it reached no conclusion", 
            worker_demo_reports()["completed"].state is True))

    # ---- 3. the prohibition holds for prose, wherever it is written --------
    summary_leak = _refused(lambda: report_from_evidence(
        "w", "s", status=WorkerStatus.COMPLETED,
        evidence=[_w_evidence("the certificate expired before the capture")],
        summary="the mission is complete: the actor is the operator of the domain"))
    add(_oc("a mission-level conclusion in the summary is refused",
            summary_leak[0] == "ValidationError", summary_leak[1][:80]))
    add(_oc("the refusal names the phrase it found",
            "mission is complete" in summary_leak[1]))
    finding_leak = _refused(lambda: WorkerFinding(
        statement="we can conclude that the certificate was replaced deliberately",
        evidence_ids=["ev-1"]))
    add(_oc("a conclusion written in a finding is refused",
            finding_leak[0] == "ValidationError", finding_leak[1][:80]))
    add(_oc("a verdict phrase is refused wherever it appears",
            all(mission_conclusion_phrases(text)
                for text in ("case closed", "we have proven the link",
                             "the threat actor is known", "conclusively",
                             "final assessment: hostile"))))
    add(_oc("ordinary analytic language is not refused",
            not mission_conclusion_phrases(
                "the proxy log shows a CONNECT to evil.example.org") and
            not mission_conclusion_phrases(
                "the certificate expired six days before the capture")))
    add(_oc("saying a value is not an identity is not refused",
            not mission_conclusion_phrases(
                "the shared address is not an identity and names no person")))
    add(_oc("an artefact path that contains a forbidden word is not scanned",
            _refused(lambda: report_from_evidence(
                "w", "s", status=WorkerStatus.COMPLETED,
                evidence=[_w_evidence("the file was present",
                                      url="https://example.com/conclusion.txt")],
                summary="read one page"))[0] == "",
            "evidence locators are data, not prose"))
    add(_oc("a hand-off in the summary is refused",
            _refused(lambda: report_from_evidence(
                "w", "s", status=WorkerStatus.COMPLETED,
                evidence=[_w_evidence("the file was present")],
                summary="finished, then delegated to the archive team"))[0]
            == "ValidationError"))
    peer = _refused(lambda: report_from_evidence(
        "w", "s", status=WorkerStatus.COMPLETED,
        evidence=[_w_evidence("the file was present")],
        summary="asked another team to confirm the record"))
    add(_oc("the peer refusal is typed and names the phrase",
            peer[0] == "ValidationError" and "asked another team" in peer[1], peer[1][:80]))
    add(_oc("every peer-contact phrase is really a contact",
            all(peer_contact_phrases(text)
                for text in ("delegated to sa-archive", "shared with another team",
                             "handed off to the timeline team", "via slack",
                             "peer subagent", "coordinated with the history team"))))
    add(_oc("a forbidden field is refused before the prose is read",
            _refused(lambda: normalize_worker_report({
                "worker_id": "w", "subagent_id": "s", "status": "completed",
                "summary": "the mission is complete", "recipients": ["sa-2"],
                "findings": [], "evidence": []}))[0] == "ConclusionLeak"))
    add(_oc("a conclusion nested in a payload's finding is refused",
            _refused(lambda: normalize_worker_report({
                "worker_id": "w", "subagent_id": "s", "status": "partial",
                "findings": [{"statement": "the case is closed",
                              "evidence_ids": ["ev-1"]}],
                "evidence": [], "limitations": ["nothing else was read"]}))[0]
            == "ConclusionLeak"))

    # ---- 4. the status contract -------------------------------------------
    evidence = _w_evidence("the proxy log records a CONNECT to evil.example.org")
    add(_oc("a completed report needs a finding",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="completed",
                evidence=[evidence]))[0] == "ValidationError"))
    add(_oc("a completed report needs evidence",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="completed",
                findings=[WorkerFinding(statement="something was seen",
                                        evidence_ids=["ev-1"])]))[0]
            == "ValidationError"))
    add(_oc("a completed report may not carry limitations",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="completed",
                evidence=[evidence],
                findings=[WorkerFinding(statement="the log records a CONNECT",
                                        evidence_ids=[evidence.id])],
                limitations=["the log starts mid-session"]))[0] == "ValidationError"))
    add(_oc("a partial report must name what is missing",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="partial",
                evidence=[evidence],
                findings=[WorkerFinding(statement="the log records a CONNECT",
                                        evidence_ids=[evidence.id])]))[0]
            == "ValidationError"))
    add(_oc("a partial report with a limitation is valid",
            worker_demo_reports()["partial"].status is WorkerStatus.PARTIAL))
    add(_oc("a blocked report needs a reason",
            _refused(lambda: WorkerReport(worker_id="w", subagent_id="s",
                                          status="blocked"))[0] == "ValidationError"))
    add(_oc("a blocked report may carry no findings and no evidence",
            (lambda report: report.status is WorkerStatus.BLOCKED
             and not report.evidence and not report.findings)(
                worker_demo_reports()["blocked"])))
    add(_oc("a failed report must carry its error",
            _refused(lambda: WorkerReport(worker_id="w", subagent_id="s",
                                          status="failed",
                                          limitations=["the tool died"]))[0]
            == "ValidationError"))
    add(_oc("a failed report keeps the evidence that survived",
            len(worker_demo_reports()["failed"].evidence) == 1))
    add(_oc("a usable report may not contain unsourced evidence",
            _refused(lambda: report_from_evidence(
                "w", "s", status=WorkerStatus.PARTIAL,
                evidence=[_w_evidence("a vendor claims the domain is new",
                                      kind=EvidenceKind.ALLEGATION, sources=False)],
                limitations=["only a claim"])[0] == "ValidationError")))
    add(_oc("a finding may not cite evidence the report does not contain",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="partial",
                evidence=[evidence],
                findings=[WorkerFinding(statement="a row was read",
                                        evidence_ids=["ev-not-here"])],
                limitations=["one row only"]))[0] == "ValidationError"))
    add(_oc("an unknown status is refused, not coerced",
            _refused(lambda: WorkerReport(worker_id="w", subagent_id="s",
                                          status="succeeded"))[0]
            == "ValidationError", "succeeded is a graph state, not a Worker status"))
    add(_oc("the status may be given as a string and is normalised",
            WorkerReport(worker_id="w", subagent_id="s", status="blocked",
                         limitations=["no key"]).status is WorkerStatus.BLOCKED))
    add(_oc("an attempt number below one is refused",
            _refused(lambda: blocked_report("w", "s", "no key", attempt=0))[0]
            == "ValidationError"))
    add(_oc("a completed report may not carry an error",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="completed",
                evidence=[evidence],
                findings=[WorkerFinding(statement="the log records a CONNECT",
                                        evidence_ids=[evidence.id])],
                error=ErrorInfo(code="x", message="something failed")))[0]
            == "ValidationError"))
    add(_oc("a finding that is an inference must state its reasoning",
            _refused(lambda: WorkerFinding(
                statement="the connection was scripted", evidence_ids=["ev-1"],
                kind=EvidenceKind.INFERENCE))[0] == "ValidationError"))
    add(_oc("high confidence on an inference is refused",
            _refused(lambda: WorkerFinding(
                statement="the connection was scripted", evidence_ids=["ev-1"],
                kind=EvidenceKind.INFERENCE, reasoning="the user agent is a default string",
                confidence=Confidence.HIGH, confidence_basis="one log line"))[0]
            == "ValidationError"))
    add(_oc("a follow-up needs a reason as well as a suggestion",
            _refused(lambda: WorkerFollowUp(suggestion="collect more",
                                            reason="  "))[0] == "ValidationError"))

    # ---- 5. the builders --------------------------------------------------
    derived = report_from_evidence("w", "s", status=WorkerStatus.COMPLETED,
                                   evidence=[evidence], summary="read one page")
    add(_oc("a report derives one finding per evidence item",
            len(derived.findings) == 1
            and derived.findings[0].evidence_ids == [evidence.id]))
    add(_oc("a derived finding repeats the evidence's own statement",
            derived.findings[0].statement == evidence.statement))
    add(_oc("the report collects the sources its evidence already carries",
            [source.locator for source in derived.sources]
            == ["https://example.com/report"]))
    later = evidence.sources[0].model_copy(
        update={"retrieved_at": datetime(2026, 5, 5, 9, tzinfo=timezone.utc)})
    reread = evidence.model_copy(update={
        "id": "ev-reread", "sources": [evidence.sources[0], later]})
    add(_oc("the same source retrieved twice is kept twice",
            len(_sources_from_evidence([reread])) == 2,
            "one retrieval each: collapsing them would hide the second"))
    add(_oc("the same retrieval cited by two items is recorded once",
            len(_sources_from_evidence([evidence, evidence.model_copy(
                update={"id": "ev-other"})])) == 1))
    blocked = blocked_report("w", "s", "the archive needs a key this mission does not hold")
    add(_oc("a blocked report is blocked, not failed",
            blocked.status is WorkerStatus.BLOCKED and blocked.error is None))
    add(_oc("a blocked report records a typed gap",
            len(blocked.gaps) == 1 and isinstance(blocked.gaps[0], UnknownValue)))
    scrubbed = failed_report("w", "s", "the collector rejected api_key=abcd1234efgh")
    add(_oc("a failure message is redacted before it reaches the record",
            "abcd1234efgh" not in scrubbed.error.message, scrubbed.error.message))
    add(_oc("a failure names the component and the stage",
            scrubbed.error.component == "w" and scrubbed.error.stage == "worker"))
    add(_oc("a failure carries a limitation saying what stopped it",
            bool(scrubbed.limitations)))

    # ---- 6. a failed tool does not crash the mission (acceptance one) -----
    tool = _outcome_tool_demo()
    add(_oc("a raising tool returns a result instead of raising", tool["raised"] is False))
    add(_oc("the failing tool is recorded as failed",
            tool["tools"][1]["status"] == "failed" and tool["tools"][1]["ok"] is False))
    add(_oc("the working tool in the same Worker is still completed",
            tool["tools"][0]["status"] == "completed"))
    add(_oc("the failure carries the error the tool raised",
            "unexpected end of pcap record" in (tool["tools"][1]["error"] or "")))
    add(_oc("the error message is redacted in the tool result",
            "abcd1234efgh" not in (tool["tools"][1]["error"] or ""),
            tool["tools"][1]["error"]))
    add(_oc("the policy-free Worker report folds to partial", 
            tool["report"]["status"] == "partial", tool["report"]["status"]))
    add(_oc("the failed tool still returns the record it had already read",
            tool["tools"][1]["evidence"] == 1, tool["tools"][1]["evidence"]))
    add(_oc("the partial report keeps the record the tool produced first",
            len(tool["report"]["evidence"]) == 2, len(tool["report"]["evidence"])))
    add(_oc("the salvaged record keeps its source reference",
            all(item["sources"] for item in tool["report"]["evidence"])))
    add(_oc("the partial report's citations include the salvaged artefact",
            "file:///evidence/capture.pcap" in tool["report"]["citations"]
            or "/evidence/capture.pcap" in " ".join(tool["report"]["citations"]),
            tool["report"]["citations"]))
    add(_oc("the partial report names the tool that failed",
            any("pcap.read" in line for line in tool["report"]["limitations"])))
    add(_oc("the partial report still has a usable status",
            tool["report"]["usable"] is True))

    class _Raises:
        def __call__(self) -> Any:
            raise RuntimeError("the collector segfaulted while parsing the archive")

        def salvage(self, _exc: BaseException) -> list[Any]:
            return []

    no_evidence = survive_tool_failure("collect", _Raises(), worker_id="w",
                                       subagent_id="s", gather=_Raises().salvage)
    add(_oc("a tool that fails with nothing to salvage is failed, not partial",
            no_evidence.status is WorkerStatus.FAILED))
    add(_oc("a tool whose evidence is empty is not reported as completed",
            survive_tool_failure("collect", lambda: None, worker_id="w",
                                 subagent_id="s").status is WorkerStatus.PARTIAL))
    def _cancelled_tool() -> Any:
        """A tool that finds the mission cancelled: raises where it is called."""

        raise CancellationRequested("operator pressed Ctrl-C")

    cancelled = _refused(lambda: survive_tool_failure(
        "collect", _cancelled_tool, worker_id="w", subagent_id="s"))
    add(_oc("cancellation is re-raised, because it is an operator's decision",
            cancelled[0] == "CancellationRequested", cancelled[1][:60]))
    add(_oc("a tool failure never leaves a Worker without a status",
            all(result["status"] in {status.value for status in WorkerStatus}
                for result in tool["tools"])))
    folded = report_from_tool_results("w", "s", [])
    add(_oc("no tool call at all is blocked rather than failed",
            folded.status is WorkerStatus.BLOCKED))

    # ---- 7. the runner seam ----------------------------------------------
    seam = _outcome_runner_demo()
    add(_oc("a runner that raises does not escape the wrapper", seam["raised"] is False))
    add(_oc("the wrapper's outcome is failed", seam["outcome_status"] == "failed"))
    add(_oc("the wrapper's report names the failure",
            "segfaulted" in (seam["report"]["error"] or {}).get("message", "")))
    add(_oc("the wrapper keeps the report it produced",
            len(seam["ledger"]["reports"]) == 1))
    add(_oc("the wrapper's ledger records the failed unit",
            seam["ledger"]["by_status"]["failed"] == ["w-explode"]))

    # ---- 8. the flow seam: statuses map both ways ------------------------
    reports = worker_demo_reports()
    mapped = {name: outcome_from_report(report)
              for name, report in reports.items()}
    add(_oc("completed maps to the graph's succeeded",
            mapped["completed"].status is EntityStatus.SUCCEEDED))
    add(_oc("partial maps to blocked, not to succeeded",
            mapped["partial"].status is EntityStatus.BLOCKED,
            "a partial unit has not succeeded, and the graph must not say it did"))
    add(_oc("blocked stays blocked and names a dependency gate",
            mapped["blocked"].status is EntityStatus.BLOCKED
            and mapped["blocked"].gate is FlowGate.DEPENDENCY_FAILED))
    add(_oc("failed maps to failed with the error gate",
            mapped["failed"].status is EntityStatus.FAILED
            and mapped["failed"].gate is FlowGate.ERROR))
    add(_oc("the outcome carries the same evidence ids as the report",
            mapped["completed"].evidence_ids == reports["completed"].evidence_ids))
    add(_oc("the outcome carries the report itself in its payload",
            "report" in mapped["completed"].payload))
    add(_oc("the graph's own record round-trips back to the contract",
            report_from_outcome(mapped["partial"]).status is WorkerStatus.PARTIAL))
    add(_oc("a round trip keeps the citations a reader needs",
            report_from_outcome(mapped["completed"]).citations
            == reports["completed"].citations))
    legacy = WorkerOutcome(
        worker_id="w", subagent_id="s", status=EntityStatus.SUCCEEDED,
        summary="collected two rows", payload={"evidence": [
            json.loads(model_to_json(evidence))]})
    recovered = report_from_outcome(legacy)
    add(_oc("an outcome without a report is not recorded as completed",
            recovered.status is WorkerStatus.PARTIAL, recovered.status.value))
    add(_oc("the recovered report says why it is partial",
            any("no WorkerReport" in line for line in recovered.limitations)))
    add(_oc("the recovered report keeps the evidence it was given",
            len(recovered.evidence) == 1))
    merged = merge_reports("w", "s", [
        failed_report("w", "s", "the source timed out", attempt=1),
        report_from_evidence("w", "s", status=WorkerStatus.COMPLETED,
                             evidence=[evidence], summary="read the page on the retry",
                             attempt=2)])
    add(_oc("a retried unit reports its final status",
            merged.status is WorkerStatus.COMPLETED and merged.attempt == 2))
    add(_oc("a retried unit keeps the evidence from both attempts",
            len(merged.evidence) >= 1))
    add(_oc("a retry after a failure keeps the findings of the last attempt",
            len(merged.findings) == 1))
    add(_oc("merging no attempts is blocked, not completed",
            merge_reports("w", "s", []).status is WorkerStatus.BLOCKED))

    # ---- 8b. the flow seam: a partial Worker reaches the aggregate ---------
    # A Subagent with one failing Worker out of two: the mission must continue,
    # the aggregate must carry the surviving evidence, and the gap must be the
    # *unit's own* — once.
    context = _selftest_context("exposure")
    units = flow_units_for(context, "exposure")
    target = next(unit for unit in units if len(unit.workers) >= 2)
    partial_flow = HierarchicalFlow(
        context=context, subagents=units,
        runner=_CountingRunner(scope=context.scope_entries,
                               failing=[target.workers[0].id]),
        # Runtime Workers off: §36 can replace a failed unit with one more Worker, which
        # is a good answer but not the one this check is about.
        policy=FlowPolicy(allow_runtime_workers=False))
    partial_result = partial_flow.run()
    partial_report = next(report for report in partial_result.reports
                          if report.subagent_id == target.id)
    add(_oc("a failed Worker does not abort the mission",
            partial_result.synthesis is not None and not partial_result.stopped))
    add(_oc("the surviving Worker's evidence reaches the aggregate",
            len(partial_report.evidence) >= 1, len(partial_report.evidence)))
    add(_oc("the failed Worker is one gap, not two",
            len(partial_report.gaps) == 1,
            [gap.describe()[:60] for gap in partial_report.gaps]))
    add(_oc("the gap names the unit that failed",
            target.workers[0].name in str(partial_report.gaps[0].detail),
            partial_report.gaps[0].describe()[:80]))
    carried = [outcome.payload.get("report") for outcome in partial_report.outcomes]
    add(_oc("every outcome the aggregate saw carried a WorkerReport",
            all(isinstance(payload, Mapping) for payload in carried)))
    add(_oc("the carried reports re-validate",
            all(WorkerReport.from_dict(payload).status in set(WorkerStatus)
                for payload in carried)))
    add(_oc("a partial Worker's report does not claim completion",
            all(WorkerReport.from_dict(payload).status is not WorkerStatus.COMPLETED
                for payload in carried)))
    silent = _with_worker_contract(WorkerOutcome(
        worker_id="w", subagent_id="s", status=EntityStatus.SUCCEEDED,
        summary="collected two rows",
        payload={"evidence": [json.loads(model_to_json(evidence))]}))
    add(_oc("a succeeding outcome without a report keeps its own status",
            silent.status is EntityStatus.SUCCEEDED,
            "the graph's record is what the reviewer judged"))
    add(_oc("a succeeding outcome without a report is restated as partial",
            _report_of(silent).status is WorkerStatus.PARTIAL,
            "the contract's record cannot claim completion it cannot describe"))
    add(_oc("a succeeding outcome with no evidence at all is blocked",
            _report_of(_with_worker_contract(WorkerOutcome(
                worker_id="w", subagent_id="s", status=EntityStatus.SUCCEEDED,
                summary="nothing came back"))).status is WorkerStatus.BLOCKED,
            "there is nothing to make a finding from, so nothing is claimed"))
    add(_oc("a wrapped outcome gains a report when the unit did not succeed",
            isinstance(_with_worker_contract(WorkerOutcome(
                worker_id="w", subagent_id="s", status=EntityStatus.FAILED,
                error="the source timed out")).payload.get("report"), Mapping)))
    add(_oc("a malformed carried report is dropped, not raised",
            _report_of(WorkerOutcome(worker_id="w", subagent_id="s",
                                     payload={"report": {"nonsense": 1}})) is None))

    # ---- 9. the ledger: a partial mission is legible ---------------------
    ledger = outcome_ledger(list(reports.values()))
    add(_oc("the ledger counts one report per status",
            {status: len(ids) for status, ids in ledger.by_status.items() if ids}
            == {"completed": 1, "partial": 1, "blocked": 1, "failed": 1},
            ledger.by_status))
    add(_oc("two of the four workers are usable", len(ledger.usable) == 2))
    add(_oc("a mission with a blocked worker is not complete",
            ledger.complete is False))
    add(_oc("every usable item still has provenance", ledger.provenance_intact is True))
    add(_oc("the ledger reports the gaps the units declared",
            len(ledger.gaps()) == 2, [gap.describe()[:60] for gap in ledger.gaps()]))
    add(_oc("a blocked unit's gap is its own, and is not counted twice",
            [gap.determined_by for gap in ledger.gaps()].count("w-archive") == 1
            and any("w-archive" in gap.describe() or gap.determined_by == "w-archive"
                    for gap in ledger.gaps()),
            [gap.describe()[:70] for gap in ledger.gaps()]))
    add(_oc("the failed unit's gap is reported beside it",
            any("offset 4096" in gap.describe() for gap in ledger.gaps())))
    add(_oc("the ledger aggregates follow-up across units",
            len(ledger.follow_up) == len([item for report in reports.values()
                                          for item in report.follow_up])
            and len(ledger.follow_up) == 4))
    add(_oc("the ledger's summary names the statuses it found",
            all(word in ledger.summary() for word in ("completed", "partial",
                                                      "blocked", "failed")),
            ledger.summary()))
    add(_oc("a ledger is complete only when every unit completed",
            outcome_ledger([reports["completed"]]).complete is True))
    unsourced = WorkerReport.model_construct(
        worker_id="w-x", subagent_id="s", status=WorkerStatus.PARTIAL,
        findings=[], evidence=[EvidenceItem.model_construct(
            id="ev-x", kind=EvidenceKind.OBSERVATION, statement="a row",
            sources=[])], limitations=["one row"], follow_up=[], gaps=[])
    add(_oc("a record that lost its sources is refused by the ledger",
            _refused(lambda: outcome_ledger([unsourced]))[0] == "ValidationError",
            "the ledger re-validates the records it is given, including records it "
            "did not build"))
    add(_oc("a ledger forced to hold an unsourced record reports provenance as broken",
            OutcomeLedger.model_construct(reports=[unsourced]).provenance_intact is False,
            "the property judges the records it is handed, even unvalidated ones"))
    add(_oc("the ledger serialises its statuses", 
            set(ledger.to_dict()["by_status"]) == {status.value for status in WorkerStatus}))

    # ---- 10. the demo ----------------------------------------------------
    demo = worker_outcome_demo()
    add(_oc("the demo covers all four statuses",
            sorted(demo["reports"]) == ["blocked", "completed", "failed", "partial"]))
    add(_oc("every demo report re-validates from its own serialisation",
            all(WorkerReport.from_dict(payload).status.value == name
                for name, payload in demo["reports"].items())))
    add(_oc("no demo refusal was accepted",
            all(value != "accepted" for value in demo["refusals"].values()),
            demo["refusals"]))
    add(_oc("the demo demonstrates six refusals", len(demo["refusals"]) == 6))
    add(_oc("the refusals cover a conclusion, a hand-off and a provenance failure",
            any("conclusion" in value.lower() for value in demo["refusals"].values())
            and any("another team" in value for value in demo["refusals"].values())
            and any("no source reference" in value for value in demo["refusals"].values())))
    add(_oc("the demo's mission continued despite a failed unit",
            demo["mission"]["continued"] is True
            and demo["mission"]["complete"] is False))
    add(_oc("the demo's mission kept usable provenance",
            demo["mission"]["provenance_intact"] is True))
    add(_oc("every demo follow-up has a reason",
            all(item["reason"] for payload in demo["reports"].values()
                for item in payload["follow_up"])))

    # ---- 11. determinism and immutability of the record -------------------
    # One evidence item, rebuilt once: two separate constructions would differ in
    # their observed_at and therefore in their ids, which is the ids working, not
    # a non-determinism.  Determinism here is of the *serialisation*, given the same
    # record.
    built = report_from_evidence("w", "s", status=WorkerStatus.COMPLETED,
                                 evidence=[_w_evidence("the log records a CONNECT")],
                                 summary="read one page")
    twice = [json.dumps(built.to_dict(), default=str) for _ in range(2)]
    add(_oc("two identical builds serialise identically", twice[0] == twice[1]))
    add(_oc("the report serialises to plain JSON",
            isinstance(json.dumps(reports["partial"].to_dict()), str)))
    add(_oc("a report reloaded from its dict keeps its citations",
            WorkerReport.from_dict(reports["completed"].to_dict()).citations
            == reports["completed"].citations))
    add(_oc("derived display keys are not accepted as fields",
            _refused(lambda: WorkerReport.model_validate(
                reports["completed"].to_dict()))[0] == "ValidationError"))
    add(_oc("a report may not carry an unknown field",
            _refused(lambda: WorkerReport(
                worker_id="w", subagent_id="s", status="blocked",
                limitations=["no key"], extra_notes="x"))[0] == "ValidationError"))
    add(_oc("the status of every serialised report is one of the four",
            all(payload["status"] in {status.value for status in WorkerStatus}
                for payload in demo["reports"].values())))

    # ---- 12. the section's own discipline ---------------------------------
    section = _source_section("# 33. Worker outcomes", "# 34.1 The output schema")
    add(_oc("the Worker-outcome section is present and bounded", bool(section),
            len(section)))
    add(_oc("the section grants no capability",
            bool(section) and "CapabilityGrant(" not in section))
    add(_oc("the section calls no model provider",
            bool(section) and "call_model(" not in section and ".complete(" not in section))
    add(_oc("the section dispatches no tool of its own",
            bool(section) and "CapabilityRouter(" not in section and ".route(" not in section))
    add(_oc("the section never imports network code of its own",
            bool(section) and "requests." not in section and "httpx." not in section))
    add(_oc("the contract names every status in one place",
            all(status.value in section for status in WorkerStatus)))
    return checks


def _coerce_refuses(call: Callable[[], Any]) -> tuple[str, str]:
    """As :func:`_refused`, for a Pydantic construction that may raise either type."""

    try:
        call()
    except Exception as exc:                  # noqa: BLE001 - the type is the assertion
        return type(exc).__name__, str(exc)
    return "", "accepted"


# --------------------------------------------------------------------------
# 33.11 Rendering
# --------------------------------------------------------------------------

_STATUS_STYLE: dict[str, str] = {"completed": "green", "partial": "yellow",
                                 "blocked": "cyan", "failed": "red"}


def render_outcome_self_test(checks: Sequence[OutcomeCheck]) -> Table:
    table = Table(title="worker-outcome self-test", title_justify="left", box=None,
                  pad_edge=False)
    table.add_column("", width=2)
    table.add_column("check", no_wrap=True)
    table.add_column("detail", overflow="fold")
    for check in checks:
        glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
        table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                      escape(check.detail))
    return table


def render_worker_reports(payload: Mapping[str, Any]) -> Table:
    """One row per Worker: what it returned, and whether it is usable."""

    table = Table(title="worker outcomes — one contract, four statuses",
                  title_justify="left", box=None, pad_edge=False)
    table.add_column("worker", no_wrap=True)
    table.add_column("status", no_wrap=True)
    table.add_column("findings", justify="right")
    table.add_column("evidence", justify="right")
    table.add_column("sources", justify="right")
    table.add_column("limits", justify="right")
    table.add_column("next", justify="right")
    table.add_column("what it said", overflow="fold", max_width=44)
    for name, report in payload["reports"].items():
        status = str(report["status"])
        colour = _STATUS_STYLE.get(status, "white")
        table.add_row(
            escape(str(report["worker_id"])),
            f"[{colour}]{escape(status)}[/{colour}]",
            str(len(report["findings"])), str(len(report["evidence"])),
            str(len(report["sources"])), str(len(report["limitations"])),
            str(len(report["follow_up"])),
            escape(str(report["summary"])[:90] or "—"),
        )
    return table


def render_outcome_demo(payload: Mapping[str, Any]) -> Group:
    """The demo on screen: the reports, the refusals, the two failures, the ledger."""

    ledger = payload["ledger"]
    refusals = Table(title="refused — what a Worker may not return",
                     title_justify="left", box=None, pad_edge=False)
    refusals.add_column("attempt", no_wrap=True)
    refusals.add_column("refused because", overflow="fold", max_width=96)
    for name, detail in payload["refusals"].items():
        refusals.add_row(escape(name), escape(_first_sentence(detail)[:180]))

    tool_rows = Table(title="a failed tool is a result, not a crash",
                      title_justify="left", box=None, pad_edge=False)
    tool_rows.add_column("tool", no_wrap=True)
    tool_rows.add_column("status", no_wrap=True)
    tool_rows.add_column("evidence kept", justify="right")
    tool_rows.add_column("error", overflow="fold", max_width=60)
    for item in payload["tool_failure"]["tools"]:
        colour = _STATUS_STYLE.get(str(item["status"]), "white")
        tool_rows.add_row(escape(str(item["tool"])),
                          f"[{colour}]{escape(str(item['status']))}[/{colour}]",
                          str(item["evidence"]), escape(str(item["error"] or "—")))

    failures = Text(
        "runner that raised → outcome "
        f"{payload['runner_failure']['outcome_status']}"
        f" · report {payload['runner_failure']['report']['status']}"
        f" · no exception escaped\n"
        f"mixed tool calls → report {payload['tool_failure']['report']['status']}"
        f" with {len(payload['tool_failure']['report']['evidence'])} evidence item(s), "
        f"{len(payload['tool_failure']['report']['citations'])} citation(s)", style="dim")

    tail = Text(
        f"\n{ledger['summary']}\n"
        "mission continued: " + ("yes" if payload["mission"]["continued"] else "no")
        + f" · complete: {'yes' if ledger['complete'] else 'no'}"
        f" · provenance: {'intact' if ledger['provenance_intact'] else 'incomplete'}\n"
        + "\n".join(f"  · gap {line[:140]}" for line in ledger["gaps"][:6])
        + "\n" + "\n".join(f"  · next {line[:140]}" for line in ledger["follow_up"][:4])
        + "\nno Worker concluded for the mission, and none contacted another team",
        style="dim")
    return Group(render_worker_reports(payload), refusals, tool_rows, failures, tail)


def _refusal_reasons(text: str) -> list[str]:
    """The validator messages inside an error, one per line, without scaffolding.

    A refusal is a list of rules that were broken, and a reader checking a report
    from another process is the reason this output exists: the framework's
    "for further information visit" lines are noise to that reader.
    """

    reasons: list[str] = []
    for line in str(text).splitlines():
        stripped = line.strip()
        if not stripped or stripped.lower().startswith(_PYDANTIC_NOISE):
            continue
        if "validation error for" in stripped.lower() or stripped.startswith("[type="):
            continue
        stripped = stripped.split("[type=")[0].split("(type=")[0].strip()
        if not stripped or stripped.startswith(("Type ", "input_value")):
            continue
        reasons.append(stripped.split("Value error,", 1)[-1].strip())
    return reasons or [str(text).strip()[:200]]


#: Lines Pydantic adds around a validator's message.  Dropped from a table cell,
#: because they say where the error was raised, not what was wrong.
_PYDANTIC_NOISE: tuple[str, ...] = ("for further information visit",
                                    "input_value=", "input_type=")


def _first_sentence(text: str) -> str:
    """The reason inside an error, without the framework's scaffolding."""

    body: list[str] = []
    for line in str(text).splitlines():
        stripped = line.strip()
        if not stripped or stripped.lower().startswith(_PYDANTIC_NOISE):
            continue
        if "validation error for" in stripped.lower():
            continue
        # Pydantic appends the error's type and the offending value on the same
        # line: cut both before deciding whether the line carries the message.
        stripped = stripped.split("[type=")[0].split("(type=")[0].strip()
        if not stripped or stripped.startswith(("Type ", "input_value")):
            continue
        if stripped.startswith("Value error,"):
            # Pydantic prefixes the validator's own message; keep the message.
            stripped = stripped.split("Value error,", 1)[1].strip()
        body.append(stripped)
        if len(" ".join(body)) > 160:
            break
    joined = " ".join(body) or str(text)
    return joined.split("[type=")[0].strip().rstrip(",;")


@app.command("outcomes", help="Worker outcomes: four statuses, findings, provenance, no verdicts.")
def outcomes_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the Worker contract offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="Four statuses, six refusals, two failures."),
    check: str | None = typer.Option(
        None, "--check", help="Validate a report file (or '-' for stdin).",
        show_default=False),
    worker: str = typer.Option("worker", "--worker", help="Worker id for --check."),
    subagent: str = typer.Option("subagent", "--subagent",
                                 help="Subagent id for --check."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Enforce the Worker contract, or show it being enforced.

    ``--check`` is the seam for a runner in another process: it reads a JSON report,
    validates it as a Worker would be validated, and exits non-zero with the reason
    when the record is not acceptable.
    """

    console = get_console()

    if self_test:
        checks = run_outcome_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"ok": not failures,
                              "checks": [asdict(check) for check in checks]}, indent=2))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        console.print()
        console.print(render_outcome_self_test(checks))
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = worker_outcome_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_outcome_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if check:
        if check != "-" and not Path(check).expanduser().exists():
            console.print(f"[red]✘[/red] no such file: {escape(check[:160])}")
            raise typer.Exit(ExitCode.USAGE)
        try:
            raw = (sys.stdin.read() if check == "-"
                   else Path(check).expanduser().read_text(encoding="utf-8"))
        except OSError as exc:
            console.print(f"[red]✘[/red] could not read {escape(check[:120])}: "
                          f"{escape(str(exc)[:120])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        try:
            loaded = json.loads(raw)
        except json.JSONDecodeError as exc:
            console.print(f"[red]✘[/red] not JSON: {escape(str(exc))}")
            raise typer.Exit(ExitCode.USAGE) from exc
        if not isinstance(loaded, Mapping):
            console.print("[red]✘[/red] a Worker report must be a JSON object")
            raise typer.Exit(ExitCode.USAGE)
        try:
            report = accept_worker_report(loaded, worker_id=worker,
                                          subagent_id=subagent)
        except (ConclusionLeak, PeerContactError, ValueError) as exc:
            # The refusal is the result: say which rule, and refuse the record.
            kind = refusal_kind(str(exc))
            if as_json:
                _emit(json.dumps({"ok": False, "refusal": kind,
                                  "reason": _first_sentence(str(exc))[:600]}, indent=2))
            else:
                console.print(f"\n[red]✘ refused[/red] ({escape(kind)})")
                for line in _refusal_reasons(str(exc)):
                    console.print(f"  [dim]·[/dim] {escape(line[:200])}")
                console.print()
            raise typer.Exit(ExitCode.POLICY) from exc
        if as_json:
            _emit(json.dumps({"ok": True, "report": report.to_dict()}, indent=2,
                             default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_worker_reports({"reports": {"checked": report.to_dict()}}))
        console.print(Text(f"\n{report.describe()}\n"
                           + "\n".join(f"  · source {line}" for line in report.citations)
                           + "\naccepted: no conclusion, no peer contact, provenance intact",
                           style="dim"))
        console.print()
        raise typer.Exit(ExitCode.OK)

    console.print("[red]✘[/red] choose --demo, --self-test or --check FILE")
    raise typer.Exit(ExitCode.USAGE)


# ══════════════════════════════════════════════════════════════════════════
# 34. Subagent quality review: every Worker result is judged, none is forwarded
# ══════════════════════════════════════════════════════════════════════════
#
# §33 fixed what a Worker may return.  This section is the other half: the parent
# Subagent's judgement of what came back, along exactly the seven dimensions the
# task names, and a decision — pass or revise — with the deficiency that caused it.
#
# Two properties are the point, and both are structural:
#
# 1.  **Nothing is forwarded unreviewed.**  The review lives inside the Worker's
#     branch, before the Subagent's join.  A failed, blocked, deferred, refused or
#     resumed result is reviewed too: a unit that produced nothing still has to be
#     judged, because "no result" is a fact the aggregate must be able to cite.
# 2.  **A failed call and a poor call are different paths.**  A failed tool call is
#     not a quality judgement: the tool broke, so re-running the same unit may
#     legitimately fix it, and the decision is `retry`/`blocked`/`failed` with the
#     error as the deficiency.  A successful call that ignores its mandate is a
#     `revise` with a *specific* deficiency and guidance, and a re-run without a
#     change of approach would just fail the same way.
#
# The reviewer is deterministic and offline.  It reads the record the Worker
# returned — statuses, evidence, sources, limitations, schema — and never asks a
# model to grade another model, because a grader that can be argued into a pass is
# not a control.


class ReviewDimension(str, Enum):
    """The seven things a Subagent checks, and nothing else.

    Naming them is not documentation: every deficiency is attached to one of these,
    so a revise that cites none of them cannot exist, and a review that skipped a
    dimension says so in :attr:`QualityReview.checked` rather than implying it
    looked.
    """

    COMPLETENESS = "completeness"      # the unit's criteria and expected volume were done
    RELEVANCE = "relevance"            # what came back is about the unit's slice
    SOURCE_QUALITY = "source-quality"  # the sources are the kind that can carry the claim
    PROVENANCE = "provenance"          # every claim is traceable to a locator
    CONSISTENCY = "consistency"        # the record does not contradict itself
    SCOPE = "scope"                    # nothing outside the authorised scope was touched
    SCHEMA = "schema"                  # the output satisfies the assignment's schema

    @property
    def rank(self) -> int:
        return list(ReviewDimension).index(self)


#: The order they are checked and reported in.  Fixed, so two runs of the same record
#: produce the same review down to the order of its deficiencies.
REVIEW_DIMENSIONS: tuple[ReviewDimension, ...] = tuple(ReviewDimension)


class DeficiencyKind(str, Enum):
    """What sort of thing is wrong.  The kind decides how a retry is handled."""

    TOOL_FAILURE = "tool-failure"        # the tool broke; the Worker did not fail
    BLOCKED = "blocked"                  # a dependency, permission or policy stop
    EMPTY = "empty"                      # the run succeeded and returned nothing usable
    INCOMPLETE = "incomplete"            # fewer items than the assignment required
    IRRELEVANT = "irrelevant"            # the work is not about the assigned slice
    WEAK_SOURCE = "weak-source"          # the source cannot carry the claim
    UNSOURCED = "unsourced"             # a claim with no locator behind it
    INCONSISTENT = "inconsistent"        # the record contradicts itself
    OUT_OF_SCOPE = "out-of-scope"        # work outside the authorised scope
    WRONG_SHAPE = "wrong-shape"          # the output does not satisfy the schema
    UNREVIEWABLE = "unreviewable"        # nothing usable to judge against
    UNREVIEWED = "unreviewed"            # the branch never produced a review

    @property
    def fault(self) -> "WorkflowFault":
        """Whose problem this is — the tool's, the mission's, or the Worker's."""

        if self is DeficiencyKind.TOOL_FAILURE:
            # The *call* failed: a different rule decides its retry (§34.4), which is
            # the whole point of separating it from bad work.
            return WorkflowFault.TOOL
        if self in {DeficiencyKind.BLOCKED, DeficiencyKind.UNREVIEWABLE}:
            return WorkflowFault.ENVIRONMENT
        if self in {DeficiencyKind.IRRELEVANT, DeficiencyKind.WEAK_SOURCE,
                    DeficiencyKind.UNSOURCED, DeficiencyKind.INCONSISTENT,
                    DeficiencyKind.OUT_OF_SCOPE, DeficiencyKind.WRONG_SHAPE,
                    DeficiencyKind.INCOMPLETE, DeficiencyKind.EMPTY}:
            return WorkflowFault.WORKER
        return WorkflowFault.UNKNOWN


class WorkflowFault(str, Enum):
    """Where a deficiency came from.  The distinction the task's clauses turn on."""

    TOOL = "tool"                # the call itself failed
    WORKER = "worker"            # the call worked; the work is not good enough
    ENVIRONMENT = "environment"  # nothing to do with the attempt's quality
    UNKNOWN = "unknown"


class ReviewDecision(str, Enum):
    """Pass, direct a revision, or record a stop.  Four outcomes, all reviewed."""

    PASS = "pass"          # forwarded to the Subagent's aggregate
    REVISE = "revise"      # sent back with the deficiency and what to change
    BLOCKED = "blocked"    # cannot be fixed by trying again: a named stop
    FAILED = "failed"      # the attempt failed and no revision is possible or left

    @property
    def forwards(self) -> bool:
        """Whether the result may be forwarded — including a partial one."""

        return self is ReviewDecision.PASS

    @property
    def actionable(self) -> bool:
        """Whether another attempt could change the outcome."""

        return self is ReviewDecision.REVISE


class ReviewDimensionError(ValueError):
    """A review that tries to pass a record with an open deficiency."""


class Deficiency(StrictModel):
    """One concrete thing wrong, the dimension it belongs to, and what fixes it.

    ``detail`` is required and must be specific: "low quality" is refused by
    length, because a deficiency a Worker cannot act on is a shrug with a field.
    """

    dimension: ReviewDimension
    kind: DeficiencyKind
    detail: str = Field(min_length=12)
    evidence_ids: list[str] = Field(default_factory=list)
    fix: str = Field(min_length=8)
    blocking: bool = True
    #: A short, citation-ready line for the aggregate; built from the fields above.
    @property
    def describe(self) -> str:
        return f"{self.dimension.value}/{self.kind.value}: {self.detail}"

    def to_dict(self) -> dict[str, Any]:
        return {
            "dimension": self.dimension.value,
            "kind": self.kind.value,
            "fault": self.kind.fault.value,
            "detail": self.detail,
            "evidence_ids": list(self.evidence_ids),
            "fix": self.fix,
            "blocking": self.blocking,
        }


class DimensionResult(StrictModel):
    """What one dimension found.  ``ok`` is derived, so a pass cannot be asserted."""

    dimension: ReviewDimension
    deficiencies: list[Deficiency] = Field(default_factory=list)
    note: str = ""

    @model_validator(mode="after")
    def _consistent(self) -> "DimensionResult":
        for deficiency in self.deficiencies:
            if deficiency.dimension is not self.dimension:
                raise ValueError(
                    f"a {self.dimension.value} result cannot hold a "
                    f"{deficiency.dimension.value} deficiency")
        return self

    @property
    def ok(self) -> bool:
        return not self.deficiencies

    @property
    def blocking(self) -> list[Deficiency]:
        return [item for item in self.deficiencies if item.blocking]

    def describe(self) -> str:
        if self.ok:
            return f"{self.dimension.value}: ok" + (f" — {self.note}" if self.note else "")
        return (f"{self.dimension.value}: {len(self.deficiencies)} deficiency(ies) — "
                + "; ".join(item.detail for item in self.deficiencies)[:160])


class QualityReview(StrictModel):
    """The parent Subagent's verdict on one Worker result.

    The acceptance clause is a field: ``reviewed`` is true on every review this
    module can build, and :class:`UnreviewedResult` is what happens when a branch
    tries to forward a result without one — there is no path from a Worker outcome
    to an aggregate that skips this record.
    """

    worker_id: str = Field(min_length=1)
    subagent_id: str = Field(min_length=1)
    task_id: str = ""
    attempt: int = Field(default=1, ge=1)
    #: What the Worker returned, restated in this section's vocabulary.
    worker_status: WorkerStatus
    decision: ReviewDecision

    #: One entry per dimension that was checked, in :data:`REVIEW_DIMENSIONS` order.
    checks: list[DimensionResult] = Field(default_factory=list)
    #: The dimensions this review actually performed, deduplicated and ordered.
    checked: list[ReviewDimension] = Field(default_factory=list)
    #: The blocking deficiencies, in the order they were found.
    deficiencies: list[Deficiency] = Field(default_factory=list)
    #: What a revision must change.  Empty on a pass; required on a revise.
    guidance: str = ""
    retry: bool = False
    #: Set when the decision is BLOCKED or FAILED: why no further attempt helps.
    stop_reason: str = ""

    #: True by construction.  A record that crossed a boundary can be asked.
    reviewed: bool = True
    reviewer: str = "subagent"
    #: How the result travelled: "runner", "tool-failure", "deferred", "refused",
    #: "adopted", "recovered".  Part of the provenance of the verdict itself.
    path: str = "runner"
    seconds: float = Field(default=0.0, ge=0)

    @model_validator(mode="after")
    def _coherent(self) -> "QualityReview":
        if not self.reviewed:
            raise ValueError("a QualityReview that was not performed is not a review")
        if not self.checked:
            raise ValueError("a review must state which dimensions it checked")
        # 1. A blocking deficiency and a pass are contradictory.
        if self.decision.forwards and self.blocking_deficiencies:
            raise ReviewDimensionError(
                f"a pass may not carry a blocking deficiency: "
                f"{self.blocking_deficiencies[0].detail}")
        if self.decision.forwards and self.retry:
            raise ValueError("a pass cannot also ask for a retry")
        # 2. A revise must say what to change, and must cite at least one deficiency.
        if self.decision is ReviewDecision.REVISE:
            if not self.deficiencies:
                raise ValueError("a revise must name the deficiency behind it")
            if not self.guidance.strip():
                raise ValueError("a revise must say what to change")
            if not self.retry:
                raise ValueError("a revise without a retry would discard the unit's work")
        # 3. A stop must give its reason.
        if self.decision in {ReviewDecision.BLOCKED, ReviewDecision.FAILED} \
                and not self.stop_reason.strip():
            raise ValueError(f"a {self.decision.value} decision must give its reason")
        # 4. Every deficiency is attached to a dimension that was checked.
        for deficiency in self.deficiencies:
            if deficiency.dimension not in self.checked:
                raise ValueError(
                    f"a {deficiency.dimension.value} deficiency was reported but that "
                    "dimension is not among those checked")
        return self

    # -- views a reader or the next stage needs ---------------------------

    @property
    def blocking_deficiencies(self) -> list[Deficiency]:
        return [item for item in self.deficiencies if item.blocking]

    @property
    def passed(self) -> bool:
        return self.decision is ReviewDecision.PASS

    @property
    def fault(self) -> WorkflowFault:
        """Whether this was the tool's failure or the Worker's poor work."""

        if not self.deficiencies:
            return WorkflowFault.UNKNOWN
        primary = self.deficiencies[0]
        return primary.kind.fault if primary.kind is not DeficiencyKind.EMPTY \
            else WorkflowFault.WORKER

    def dimension(self, dimension: ReviewDimension) -> DimensionResult | None:
        return next((check for check in self.checks if check.dimension is dimension), None)

    @classmethod
    def from_dict(cls, payload: Mapping[str, Any]) -> "QualityReview":
        """Reload a review this build wrote, dropping the derived display keys.

        A review is stored beside the case file it belongs to, so it has to come back:
        ``to_dict`` adds ``fault`` for the reader and an ``ok`` per dimension, and
        neither is a field.  Everything else is validated again on the way in.
        """

        def clean(item: Mapping[str, Any]) -> dict[str, Any]:
            """Drop the keys that are derived for the reader, at any depth."""

            out = {key: value for key, value in item.items() if key not in {"fault", "ok"}}
            for key in ("deficiencies", "checks"):
                if isinstance(out.get(key), list):
                    out[key] = [clean(entry) for entry in out[key]
                                if isinstance(entry, Mapping)]
            return out

        return cls.model_validate(clean(dict(payload)))

    def describe(self) -> str:
        return (f"{self.decision.value} on {self.worker_id} "
                f"(attempt {self.attempt}, {self.worker_status.value}): "
                f"{len(self.checked)}/{len(REVIEW_DIMENSIONS)} dimension(s) checked, "
                f"{len(self.deficiencies)} deficiency(ies)"
                + ("" if not self.guidance else f" — {self.guidance[:80]}"))

    def to_dict(self) -> dict[str, Any]:
        return {
            "worker_id": self.worker_id,
            "subagent_id": self.subagent_id,
            "task_id": self.task_id,
            "attempt": self.attempt,
            "worker_status": self.worker_status.value,
            "decision": self.decision.value,
            "reviewed": self.reviewed,
            "path": self.path,
            "fault": self.fault.value,
            "checked": [dimension.value for dimension in self.checked],
            "checks": [{"dimension": check.dimension.value, "ok": check.ok,
                        "note": check.note,
                        "deficiencies": [item.to_dict() for item in check.deficiencies]}
                       for check in self.checks],
            "deficiencies": [item.to_dict() for item in self.deficiencies],
            "guidance": self.guidance,
            "retry": self.retry,
            "stop_reason": self.stop_reason,
            "reviewer": self.reviewer,
            "seconds": round(self.seconds, 3),
        }


class UnreviewedResult(RuntimeError):
    """Raised when a Worker result would be forwarded with no review at all.

    A programming error, not a mission failure: it exists so that an edit which
    wires an aggregate straight to a runner fails loudly in the self-test, instead
    of quietly forwarding work nobody judged.
    """

    def __init__(self, worker_id: str, *, stage: str = "aggregate") -> None:
        self.worker_id = worker_id
        self.stage = stage
        super().__init__(
            f"{stage}: worker {worker_id!r} has no review; a result may not be "
            "forwarded until its parent Subagent has judged it")


# --------------------------------------------------------------------------
# 34.1 The output schema each Worker was assigned, as a real check
# --------------------------------------------------------------------------

#: What each schema in :data:`OUTPUT_SCHEMAS` requires of the record, stated as the
#: predicate the reviewer applies.  One row per schema, so a schema that no check
#: covers cannot be added to the plan without this table changing.
SCHEMA_REQUIREMENTS: dict[str, str] = {
    "TaskResult": "a summary and at least one finding",
    "EvidenceSet": "findings with evidence and a source reference",
    "TimelineTable": "a dated instant on every event",
    "HashManifest": "a content hash on the evidence",
    "CorrelationTable": "evidence sharing an indicator kind with another item",
    "SnapshotList": "each item retrievable at a stated time",
}


#: A digest carried in a tag: the algorithm and its hex, or bare 64 hex characters.
_HASH_TAG = re.compile(r"^(?:sha(?:1|256|512)|md5):[0-9a-f]{16,}$|^[0-9a-f]{64}$", re.I)


def _schema_problem(report: WorkerReport, schema: str) -> str:
    """Why this report does not satisfy ``schema``; empty when it does.

    Deliberately literal: each schema asks for something the record either has or
    does not.  A schema that required a judgement would be a rubric, not a schema.
    """

    if not report.evidence and not report.findings:
        return f"{schema}: the report contains neither evidence nor findings"
    if schema == "EvidenceSet":
        if not report.findings:
            return "EvidenceSet: findings are required, and none were returned"
        if not any(item.sources for item in report.evidence):
            return "EvidenceSet: every item must carry a source reference, and none does"
    elif schema == "TimelineTable":
        undated = [item.id for item in report.evidence if item.observed_at is None]
        if not report.evidence or len(undated) == len(report.evidence):
            return "TimelineTable: no event carries an observed instant"
    elif schema == "HashManifest":
        def hashed(item: EvidenceItem) -> bool:
            custody_hash = item.custody.integrity_hash if item.custody else None
            # A ``sha256:<hex>`` tag, or a 64-hex tag on its own.  Matching on the
            # word "hash" alone would accept the *label* of a hash with no digest.
            return (custody_hash is not None
                    or any(_HASH_TAG.match(tag) is not None for tag in item.tags))

        if not any(hashed(item) for item in report.evidence):
            return "HashManifest: no item carries a hash"
    elif schema == "CorrelationTable":
        # Items of a *kind* that more than one item shares: an indicator observed once
        # is not a correlation, however many tags it carries.
        shared = Counter(item.kind for item in report.evidence)
        if sum(1 for count in shared.values() if count >= 2) < 1:
            return "CorrelationTable: correlation needs at least two items sharing a kind"
    elif schema == "SnapshotList":
        # ``retrieved_at`` is defaulted at construction, so it is always present and
        # would make this check unfalsifiable.  What a snapshot list needs is the
        # *method*: how the capture was made, stated rather than assumed.
        stated = [item for item in report.evidence if item.sources and all(
            source.retrieval_method is not RetrievalMethod.UNKNOWN
            for source in item.sources)]
        if not stated or len(stated) != len(report.evidence):
            return "SnapshotList: each item must state how it was captured"
    elif schema == "TaskResult":
        if not report.summary.strip():
            return "TaskResult: a summary is required"
    return ""


# --------------------------------------------------------------------------
# 34.2 The reviewer: seven dimensions, one decision
# --------------------------------------------------------------------------

#: Source kinds that can carry a load-bearing observation on their own.  The rest
#: are usable, but only beside something better: a search-engine result page, a
#: social post or a republished mirror is not a primary record.
_PRIMARY_SOURCE_KINDS: frozenset[SourceKind] = frozenset({
    SourceKind.PUBLIC_WEB, SourceKind.API, SourceKind.DNS, SourceKind.WHOIS,
    SourceKind.CERTIFICATE_LOG, SourceKind.LOCAL_ARTIFACT, SourceKind.DOCUMENT,
    SourceKind.ARTIFACT_IMAGE, SourceKind.MEMORY_IMAGE, SourceKind.LOG_FILE,
    SourceKind.ARCHIVE,
})

#: Phrases that make a statement an assessment rather than an observation, which a
#: Worker's record may not contain (§33) — checked again here because a record can
#: be constructed by another process and arrive with one.
_ASSESSMENT_PHRASES: tuple[str, ...] = ("we conclude", "this proves", "the actor is",
                                        "in conclusion", "case closed")

#: Words that show a statement is about the Worker's own slice.  Relevance is judged
#: with a blunt lexical overlap against the unit's mandate, because a reviewer that
#: guessed at meaning could be argued with.
_RELEVANCE_STOPWORDS: frozenset[str] = frozenset({
    "the", "a", "an", "and", "or", "of", "for", "to", "in", "on", "with", "by", "from",
    "that", "this", "each", "every", "all", "any", "at", "as", "is", "are", "be", "it",
    "its", "their", "one", "per", "least", "more", "than", "into", "not", "no", "has",
    "have", "was", "were", "will", "would", "can", "may", "should", "must", "unit",
    "worker", "collect", "collected", "record", "records", "item", "items", "source",
    "sources", "row", "rows", "data", "value", "values", "with", "and", "its",
})


def _tokens(text: str) -> set[str]:
    return {word for word in re.findall(r"[a-z0-9][a-z0-9._-]{2,}", (text or "").lower())
            if word not in _RELEVANCE_STOPWORDS}


def _mandate_tokens(worker: "FlowWorker") -> set[str]:
    return _tokens(" ".join([worker.work_unit, worker.objective, worker.expected_evidence,
                             *worker.completion_criteria]))


class SubagentReviewer:
    """Judge one Worker result on the seven dimensions, and decide.

    The reviewer is the parent Subagent's judgement, expressed as code: it reads the
    record (a :class:`WorkerReport` in §33's vocabulary plus the graph's outcome),
    never the Worker's internal state.  Nothing here depends on the clock, the
    network or a model, so the same record reviews identically every time — which is
    what makes it a control rather than a conversation.
    """

    def __init__(self, *, scope: Sequence[str] = (), primary_sources_only: bool = False,
                 minimum_items: int | None = None,
                 minimum_sources: int | None = None) -> None:
        self.scope = [entry for entry in scope if str(entry).strip()]
        self.primary_sources_only = primary_sources_only
        self.minimum_items = minimum_items
        self.minimum_sources = minimum_sources

    # -- the whole review --------------------------------------------------

    def review(self, worker: "FlowWorker", report: WorkerReport, *,
               subagent_id: str, attempt: int = 1, path: str = "runner",
               observations: Sequence[Deficiency] = ()) -> QualityReview:
        """Judge one report.  Every dimension is checked; the decision follows.

        ``observations`` are deficiencies the *graph* already knows about — a
        deferred unit, a refused capability, a result adopted from a checkpoint —
        passed in as findings so they reach the same record as everything else
        rather than living beside it in a separate note.
        """

        findings = list(observations)
        findings.extend(self._completeness(worker, report))
        findings.extend(self._relevance(worker, report))
        findings.extend(self._source_quality(worker, report))
        findings.extend(self._provenance(report))
        findings.extend(self._consistency(worker, report))
        findings.extend(self._scope(worker, report))
        findings.extend(self._schema(worker, report))

        grouped: dict[ReviewDimension, list[Deficiency]] = {
            dimension: [] for dimension in REVIEW_DIMENSIONS}
        for deficiency in findings:
            grouped[deficiency.dimension].append(deficiency)
        checks = [DimensionResult(dimension=dimension, deficiencies=grouped[dimension])
                  for dimension in REVIEW_DIMENSIONS]
        return self._decide(worker, report, checks, subagent_id=subagent_id,
                            attempt=attempt, path=path)

    def _decide(self, worker: "FlowWorker", report: WorkerReport,
                checks: Sequence[DimensionResult], *, subagent_id: str,
                attempt: int, path: str) -> QualityReview:
        """Turn the findings into pass / revise / blocked / failed.

        This is where the task's two clauses separate:

        *   the run **failed or was blocked** — the *tool* did not work.  There is no
            quality to judge, so the deficiencies are the environment's; a retry is
            possible while the Worker's budget allows one, and otherwise the unit
            stops with a reason.
        *   the run **succeeded or was partial** and the work is deficient — the tool
            worked and the *work* is wrong.  That is a revise, with the specific
            deficiency and a specific instruction, never a silent re-run.
        """

        deficiencies = [item for check in checks for item in check.deficiencies]
        blocking = [item for item in deficiencies if item.blocking]
        environment = [item for item in blocking
                       if item.kind.fault is WorkflowFault.ENVIRONMENT]
        poor_work = [item for item in blocking if item not in environment]

        if report.status is WorkerStatus.FAILED:
            # Not a quality call: the call failed.  Report it as such, keep what
            # survived, and let the budget decide whether another attempt happens.
            # Complaints that follow *from* the failure — a missing hash, a short
            # schema — are consequences, not separate findings, and counting them
            # would blame the Worker for the tool's fault.
            reason = (report.error.message if report.error
                      else "; ".join(report.limitations)[:200] or "the attempt failed")
            causal = [item for item in blocking
                      if item.kind.fault in {WorkflowFault.TOOL, WorkflowFault.ENVIRONMENT}]
            can_retry = attempt < max(worker.max_attempts, 1)
            return QualityReview(
                worker_id=worker.id, subagent_id=subagent_id,
                task_id=report.task_id, attempt=attempt,
                worker_status=report.status,
                decision=(ReviewDecision.REVISE if can_retry else ReviewDecision.FAILED),
                checks=list(checks), checked=list(REVIEW_DIMENSIONS),
                deficiencies=causal or [Deficiency(
                    dimension=ReviewDimension.COMPLETENESS,
                    kind=DeficiencyKind.TOOL_FAILURE,
                    detail=f"the attempt failed at the tool: {reason}"[:200],
                    fix="re-run the same unit; if the tool fails again, record the gap")],
                guidance=("retry the same unit: the failure was the tool's, not the "
                          "work's" if can_retry else ""),
                retry=can_retry,
                stop_reason="" if can_retry else f"attempts exhausted after {attempt}: {reason}"[:220],
                path=path)

        if report.status is WorkerStatus.BLOCKED:
            reason = "; ".join(report.limitations)[:200] or "the unit was blocked"
            return QualityReview(
                worker_id=worker.id, subagent_id=subagent_id,
                task_id=report.task_id, attempt=attempt,
                worker_status=report.status, decision=ReviewDecision.BLOCKED,
                checks=list(checks), checked=list(REVIEW_DIMENSIONS),
                deficiencies=blocking or [Deficiency(
                    dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.BLOCKED,
                    detail=f"the unit could not run: {reason}"[:200],
                    fix="resolve the block before the unit is attempted again")],
                guidance="", retry=False, stop_reason=reason, path=path)

        if blocking:
            # The tool worked and the work is not good enough: a revise, never a
            # silent re-run, and never a pass with a note nobody reads.
            return QualityReview(
                worker_id=worker.id, subagent_id=subagent_id,
                task_id=report.task_id, attempt=attempt,
                worker_status=report.status, decision=ReviewDecision.REVISE,
                checks=list(checks), checked=list(REVIEW_DIMENSIONS),
                deficiencies=blocking,
                guidance=self._guidance(poor_work or blocking),
                retry=attempt < max(worker.max_attempts, 1),
                stop_reason=("" if attempt < max(worker.max_attempts, 1)
                             else f"attempts exhausted after {attempt}"),
                path=path)

        # Nothing blocking.  A partial report with only an *environmental* note is
        # forwarded: its work is usable and its gaps are on the record.
        return QualityReview(
            worker_id=worker.id, subagent_id=subagent_id,
            task_id=report.task_id, attempt=attempt, worker_status=report.status,
            decision=ReviewDecision.PASS, checks=list(checks),
            checked=list(REVIEW_DIMENSIONS),
            deficiencies=[item for item in deficiencies if not item.blocking],
            path=path)

    @staticmethod
    def _guidance(deficiencies: Sequence[Deficiency]) -> str:
        """What the Worker must change, phrased as instructions in its own terms."""

        fixes: list[str] = []
        for deficiency in deficiencies:
            if deficiency.fix not in fixes:
                fixes.append(deficiency.fix)
        head = f"{len(deficiencies)} blocking deficiency(ies): " if len(deficiencies) > 1 else ""
        return (head + "; ".join(fixes[:3]))[:400]

    # -- 1. completeness ---------------------------------------------------

    def _completeness(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Were the unit's own criteria met, with the volume the assignment stated?"""

        problems: list[Deficiency] = []
        if not report.status.usable:
            # A blocked or failed unit never had the chance to return the volume the
            # assignment expected.  Counting its absence as a further incompleteness
            # would blame the Worker for the wall it hit.
            return problems
        if not report.findings:
            problems.append(Deficiency(
                dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.EMPTY,
                detail="the run was reported as usable but contains no finding",
                fix="return at least one finding, or report the unit as blocked"))
        criteria = [item for item in worker.completion_criteria if item.strip()]
        covered = " ".join([report.summary, *[item.statement for item in report.findings],
                            *report.limitations]).lower()
        if report.status is WorkerStatus.COMPLETED and criteria:
            unmet = [criterion for criterion in criteria
                     if not _tokens(criterion) & set(re.findall(r"[a-z0-9._-]{3,}", covered))]
            if unmet:
                problems.append(Deficiency(
                    dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.INCOMPLETE,
                    detail=f"the report does not address: {unmet[0][:80]}",
                    fix="answer each completion criterion explicitly, or name the one "
                        "that could not be met and report the unit as partial"))
        if self.minimum_items and len(report.evidence) < self.minimum_items:
            problems.append(Deficiency(
                dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.INCOMPLETE,
                detail=f"{len(report.evidence)} item(s) returned, "
                       f"{self.minimum_items} were required",
                fix=f"collect at least {self.minimum_items} item(s) for this unit"))
        if self.minimum_sources and len({source.locator for source in report.sources}) \
                < self.minimum_sources:
            problems.append(Deficiency(
                dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.INCOMPLETE,
                detail=f"{len(report.sources)} distinct source(s), "
                       f"{self.minimum_sources} were required",
                fix="cite distinct sources rather than one source repeatedly"))
        return problems

    # -- 2. relevance ------------------------------------------------------

    def _relevance(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Is the work about the slice it was assigned, or about something else?"""

        problems: list[Deficiency] = []
        mandate = _mandate_tokens(worker)
        statements = [item.statement for item in report.findings]
        if statements and mandate:
            overlap = sum(1 for statement in statements
                          if _tokens(statement) & mandate)
            if overlap == 0:
                problems.append(Deficiency(
                    dimension=ReviewDimension.RELEVANCE, kind=DeficiencyKind.IRRELEVANT,
                    detail=(f"none of the {len(statements)} finding(s) mentions anything "
                            f"in this unit's mandate ({worker.work_unit[:40]})"),
                    evidence_ids=[item.id for item in report.evidence][:4],
                    fix="return only observations about this unit's own slice; a "
                        "neighbouring unit's material belongs to that unit"))
        if report.status is WorkerStatus.COMPLETED and not report.evidence \
                and not report.findings:
            problems.append(Deficiency(
                dimension=ReviewDimension.RELEVANCE, kind=DeficiencyKind.EMPTY,
                detail="a completed report with nothing in it cannot be relevant to anything",
                fix="return the observations, or report the unit as blocked"))
        return problems

    # -- 3. source quality -------------------------------------------------

    def _source_quality(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Can these sources carry the claim the finding makes?"""

        problems: list[Deficiency] = []
        weak = [item for item in report.evidence
                if item.sources and all(source.kind not in _PRIMARY_SOURCE_KINDS
                                        for source in item.sources)]
        if weak and len(weak) == len(report.evidence):
            problems.append(Deficiency(
                dimension=ReviewDimension.SOURCE_QUALITY, kind=DeficiencyKind.WEAK_SOURCE,
                detail=(f"all {len(weak)} item(s) rest on secondary sources "
                        f"({', '.join(sorted({source.kind.value for item in weak for source in item.sources}))[:60]})"),
                evidence_ids=[item.id for item in weak][:4],
                fix="cite the primary record (the log, the advisory itself) rather than "
                    "a search result or a republished copy"))
        thin = [item for item in report.evidence
                if item.sources and item.confidence in {Confidence.MEDIUM, Confidence.HIGH}
                and len({source.locator for source in item.sources}) < 2]
        if thin:
            problems.append(Deficiency(
                dimension=ReviewDimension.SOURCE_QUALITY,
                kind=DeficiencyKind.INCONSISTENT,
                detail=(f"{len(thin)} item(s) claim medium or high confidence from a "
                        "single source"),
                evidence_ids=[item.id for item in thin][:4],
                fix="lower the confidence, or corroborate the item from a second source"))
        if self.primary_sources_only:
            unpreserved = [item for item in report.evidence
                           if item.sources and not any(
                               getattr(source, "content_hash", None) is not None
                               or getattr(source, "http_status", None)
                               for source in item.sources)]
            if unpreserved:
                problems.append(Deficiency(
                    dimension=ReviewDimension.SOURCE_QUALITY,
                    kind=DeficiencyKind.UNSOURCED,
                    detail=(f"{len(unpreserved)} item(s) cite a source with no capture "
                            "evidence (no hash, no HTTP status)"),
                    evidence_ids=[item.id for item in unpreserved][:4],
                    fix="capture the source (hash or status) so the claim can be "
                        "checked after the page changes"))
        return problems

    # -- 4. provenance -----------------------------------------------------

    def _provenance(self, report: WorkerReport) -> list[Deficiency]:
        """Can every claim be traced to a locator, and every locator to a claim?"""

        problems: list[Deficiency] = []
        unsourced = [item.id for item in report.evidence if not item.sources]
        if unsourced and report.status.usable:
            problems.append(Deficiency(
                dimension=ReviewDimension.PROVENANCE, kind=DeficiencyKind.UNSOURCED,
                detail=f"{len(unsourced)} evidence item(s) carry no source reference",
                evidence_ids=unsourced[:4],
                fix="attach a SourceReference to each item, or drop the item"))
        known = set(report.evidence_ids)
        dangling = sorted({evidence_id for finding in report.findings
                           for evidence_id in finding.evidence_ids
                           if evidence_id not in known})
        if dangling:
            problems.append(Deficiency(
                dimension=ReviewDimension.PROVENANCE, kind=DeficiencyKind.UNSOURCED,
                detail=f"{len(dangling)} finding(s) cite evidence the report does not hold",
                evidence_ids=dangling[:4],
                fix="cite only evidence that is in this report"))
        located = {source.locator for source in report.sources}
        outside = sorted({source.locator for item in report.evidence
                          for source in item.sources if source.locator not in located})
        if outside and report.status.usable:
            problems.append(Deficiency(
                dimension=ReviewDimension.PROVENANCE, kind=DeficiencyKind.UNSOURCED,
                detail=(f"{len(outside)} cited source(s) are not listed in the report's "
                        f"sources ({outside[0][:50]})"),
                fix="list every cited source in the report's sources, so a reader can "
                    "enumerate them"))
        return problems

    # -- 5. internal consistency -------------------------------------------

    def _consistency(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Does the record agree with itself — status, error, findings, limitations?"""

        problems: list[Deficiency] = []
        if report.error is not None and report.status is WorkerStatus.COMPLETED:
            problems.append(Deficiency(
                dimension=ReviewDimension.CONSISTENCY,
                kind=DeficiencyKind.INCONSISTENT,
                detail="a completed report carries an error",
                fix="report the status the error implies"))
        if report.status is WorkerStatus.PARTIAL and not report.limitations:
            problems.append(Deficiency(
                dimension=ReviewDimension.CONSISTENCY,
                kind=DeficiencyKind.INCONSISTENT,
                detail="a partial report names no limitation",
                fix="state what the partial result leaves out"))
        ids = [item.id for item in report.evidence]
        if len(set(ids)) != len(ids):
            problems.append(Deficiency(
                dimension=ReviewDimension.CONSISTENCY,
                kind=DeficiencyKind.INCONSISTENT,
                detail="the same evidence id appears more than once",
                fix="de-duplicate the evidence before returning it"))
        statements = [item.statement.strip().lower() for item in report.findings]
        if len(set(statements)) != len(statements):
            problems.append(Deficiency(
                dimension=ReviewDimension.CONSISTENCY,
                kind=DeficiencyKind.INCONSISTENT,
                detail="two findings say exactly the same thing",
                fix="report each observation once, with all the evidence for it"))
        for finding in report.findings:
            lowered = finding.statement.lower()
            if any(phrase in lowered for phrase in _ASSESSMENT_PHRASES):
                problems.append(Deficiency(
                    dimension=ReviewDimension.CONSISTENCY,
                    kind=DeficiencyKind.INCONSISTENT,
                    detail=f"a finding states an assessment: {finding.statement[:70]}",
                    evidence_ids=list(finding.evidence_ids)[:2],
                    fix="state the observation, not the conclusion it suggests"))
        return problems

    # -- 6. scope compliance -----------------------------------------------

    def _scope(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Was anything touched that the mission did not authorise?"""

        problems: list[Deficiency] = []
        if not self.scope:
            return problems
        allowed = [entry.lower() for entry in self.scope]
        outside: list[str] = []
        for item in report.evidence:
            for source in item.sources:
                locator = source.locator.lower()
                if not any(entry in locator or locator in entry for entry in allowed):
                    outside.append(source.locator)
        if outside:
            problems.append(Deficiency(
                dimension=ReviewDimension.SCOPE, kind=DeficiencyKind.OUT_OF_SCOPE,
                detail=(f"{len(outside)} cited source(s) fall outside the authorised "
                        f"scope ({outside[0][:60]})"),
                evidence_ids=[item.id for item in report.evidence
                              if any(source.locator == outside[0] for source in item.sources)][:3],
                fix="collect only within the mission's scope; anything outside it is "
                    "dropped and reported as a gap"))
        return problems

    # -- 7. output schema ---------------------------------------------------

    def _schema(self, worker: "FlowWorker", report: WorkerReport) -> list[Deficiency]:
        """Does the result satisfy the shape the assignment asked for?"""

        schema = getattr(worker, "output_schema", "") or "TaskResult"
        if not report.status.usable:
            # A unit that failed or was blocked could not return the shape it was
            # asked for; its own deficiency already says so, and a schema complaint
            # here would blame the Worker for the wall it hit.
            return []
        problem = _schema_problem(report, schema)
        if not problem:
            return []
        return [Deficiency(
            dimension=ReviewDimension.SCHEMA, kind=DeficiencyKind.WRONG_SHAPE,
            detail=problem[:200],
            fix=f"return the record in the {schema} shape the assignment names "
                f"({SCHEMA_REQUIREMENTS.get(schema, 'see the assignment')})")]


# --------------------------------------------------------------------------
# 34.3 The gate: one record per Worker, and no way around it
# --------------------------------------------------------------------------

class ReviewedWorkerResult(StrictModel):
    """A Worker's outcome *and* its parent's review, as one record.

    Pairing them is the acceptance clause made structural: the aggregate asks for a
    pair, so a bare outcome has nowhere to go, and :func:`require_review` refuses
    what a caller insists on.
    """

    worker_id: str = Field(min_length=1)
    subagent_id: str = Field(min_length=1)
    outcome: "WorkerOutcome"
    #: The contract's report, when one could be recovered from the outcome.
    report: WorkerReport | None = None
    #: The judgement.  Not optional, and not defaulted.
    review: QualityReview

    @model_validator(mode="after")
    def _pair_names_the_same_unit(self) -> "ReviewedWorkerResult":
        if self.review.worker_id != self.worker_id:
            raise ValueError(
                f"the review is for {self.review.worker_id!r} but the outcome is for "
                f"{self.worker_id!r}")
        if not self.review.reviewed:
            raise ValueError("a result carries an unreviewed verdict")
        return self

    @property
    def forwarded(self) -> bool:
        """Whether this result may enter the Subagent's aggregate's evidence."""

        # ``forwards`` is a property of the decision; ``passed`` is the review's.  Asking
        # the review is the honest question here: the decision alone does not know
        # whether a blocking deficiency was recorded.
        return self.review.passed

    def to_dict(self) -> dict[str, Any]:
        return {"worker_id": self.worker_id, "subagent_id": self.subagent_id,
                "is_reviewed": True, "forwarded": self.forwarded,
                "review": self.review.to_dict(),
                "report": self.report.to_dict() if self.report else None,
                "status": self.outcome.status.value}


def review_worker_result(
    worker: "FlowWorker", outcome: "WorkerOutcome", *, subagent_id: str,
    reviewer: SubagentReviewer, path: str = "runner",
    report: WorkerReport | None = None,
    observations: Sequence[Deficiency] = (),
) -> ReviewedWorkerResult:
    """Review one outcome and pair it with the verdict.  Total over every status.

    Every path into a Worker's branch ends here — success, partial, tool failure,
    deferral, refused capability, checkpoint adoption — because the graph's worker
    node calls it on the way out.  The ``path`` is recorded rather than inferred, so
    a reader can tell a reviewed failure from a reviewed success.
    """

    recovered = report if report is not None else report_from_outcome(outcome)
    verdict = reviewer.review(worker, recovered, subagent_id=subagent_id,
                              attempt=outcome.attempt, path=path,
                              observations=observations)
    return ReviewedWorkerResult(worker_id=outcome.worker_id, subagent_id=subagent_id,
                                outcome=outcome, report=recovered, review=verdict)


def require_review(result: Any, *, stage: str = "aggregate") -> ReviewedWorkerResult:
    """Refuse anything that is not a reviewed result.

    The single place the graph's aggregate is allowed to take a Worker's output from.
    A bare :class:`WorkerOutcome` reaching this point is a wiring error, and saying
    so loudly is the whole acceptance criterion: no result is forwarded unreviewed.
    """

    if isinstance(result, ReviewedWorkerResult):
        return result
    if isinstance(result, WorkerOutcome):
        raise UnreviewedResult(result.worker_id, stage=stage)
    raise UnreviewedResult(getattr(result, "worker_id", "?"), stage=stage)


def _observations_for_path(gate: "FlowGate | None", why: str) -> list[Deficiency]:
    """The deficiency the *graph* already knows about, as a review observation.

    A unit that never ran is still a result to review, and its deficiency is not a
    quality judgement: the tool was never called.  Encoding it here keeps that
    distinction out of the dimension checks, which are about work that happened.
    """

    if gate is None:
        return []
    kind = {FlowGate.BUDGET: DeficiencyKind.BLOCKED,
            FlowGate.CANCELLED: DeficiencyKind.BLOCKED,
            FlowGate.DEPENDENCY_FAILED: DeficiencyKind.BLOCKED}.get(gate,
                                                                    DeficiencyKind.TOOL_FAILURE)
    return [Deficiency(
        dimension=ReviewDimension.COMPLETENESS, kind=kind,
        detail=f"the unit did not run: {why or gate.value}"[:200],
        fix=("resolve the dependency or the budget, then attempt the unit again"
             if kind is DeficiencyKind.BLOCKED
             else "re-run the unit; the call did not complete"),
    )]


# --------------------------------------------------------------------------
# 34.4 What the Subagent does with the verdict
# --------------------------------------------------------------------------

class ReviewPolicy(StrictModel):
    """How the Subagent acts on a review.  One place, so the behaviour is testable.

    The default is the task's rule: a failed call may be retried, poor work must be
    revised, and a stop is honoured.  ``retry_tool_failures`` exists because a
    tool failure is not the Worker's fault; ``max_attempts`` is the Worker's own
    budget, not a second one invented here.
    """

    #: A revise must be attempted, and it must carry guidance.  Turning this off
    #: would forward unrevised work, which the acceptance clause forbids.
    require_guidance: bool = True
    #: Whether a failed call is retried within the budget.  False means fail fast.
    retry_tool_failures: bool = True
    #: How many times a *quality* revise may be attempted for one unit.
    max_revisions: int = Field(default=2, ge=0, le=10)

    @model_validator(mode="after")
    def _coherent(self) -> "ReviewPolicy":
        if not self.require_guidance:
            raise ValueError(
                "require_guidance cannot be disabled: a revise with no instruction "
                "would forward the same work again")
        return self


def next_step(review: QualityReview, *, policy: ReviewPolicy | None = None,
              revisions_so_far: int = 0) -> str:
    """What happens next for one reviewed unit: ``forward``, ``retry`` or ``stop``.

    The task's central distinction, as one function a caller can test:

    *   a **failed tool call** — ``retry`` while the budget allows, else ``stop``;
    *   **poor work on a call that succeeded** — ``retry`` with the revision, while
        the revision budget allows, else ``stop`` with the deficiency on record;
    *   a **pass** — ``forward``.  There is no fourth outcome.
    """

    agreed = policy or ReviewPolicy()
    if review.decision.forwards:
        return "forward"
    if review.decision is ReviewDecision.REVISE:
        if not review.retry:
            return "stop"
        if review.fault is WorkflowFault.TOOL and not agreed.retry_tool_failures:
            return "stop"
        if review.fault is WorkflowFault.WORKER and revisions_so_far >= agreed.max_revisions:
            return "stop"
        return "retry"
    return "stop"


class RevisionDirective(StrictModel):
    """What a revise sends back, and how many times it may be sent.

    Kept separate from the verdict so a resume can see that a unit was already
    revised twice, without re-reading every review in the ledger.
    """

    worker_id: str = Field(min_length=1)
    attempt: int = Field(default=1, ge=1)
    #: The deficiencies that caused it, by dimension and kind.
    because: list[str] = Field(min_length=1)
    instruction: str = Field(min_length=8)
    #: True when the failure was the tool's: the instruction is "try again", not
    #: "do it differently", and a Worker that is told the wrong one of those will
    #: change work that was never the problem.
    tool_failure: bool = False

    @property
    def describe(self) -> str:
        cause = "tool failure" if self.tool_failure else "quality"
        return f"attempt {self.attempt} ({cause}): {self.instruction[:120]}"


def revision_directive(review: QualityReview) -> RevisionDirective:
    """Turn a revise into the instruction the next attempt receives."""

    if review.decision is not ReviewDecision.REVISE:
        raise ValueError(f"{review.decision.value} is not a revise and carries no directive")
    tool_failure = review.fault is WorkflowFault.TOOL
    return RevisionDirective(
        worker_id=review.worker_id, attempt=review.attempt,
        because=[f"{item.dimension.value}/{item.kind.value}" for item in review.deficiencies],
        instruction=review.guidance or "revise the unit and return it again",
        tool_failure=tool_failure)


# --------------------------------------------------------------------------
# 34.5 The ledger: every unit's verdict, and the refusal to skip one
# --------------------------------------------------------------------------

class ReviewLedger(StrictModel):
    """Every reviewed result for one mission, and the two properties that matter.

    :attr:`forwarded` lists what entered the aggregate and :attr:`withheld` what did
    not, each with the review that decided it — so "nothing was forwarded without
    review" and "nothing reviewed was silently dropped" are both checkable.
    """

    results: list[ReviewedWorkerResult] = Field(default_factory=list)

    @model_validator(mode="after")
    def _every_result_is_reviewed(self) -> "ReviewLedger":
        for result in self.results:
            if not result.review.reviewed:
                raise UnreviewedResult(result.worker_id, stage="ledger")
        return self

    @property
    def forwarded(self) -> list[ReviewedWorkerResult]:
        return [result for result in self.results if result.forwarded]

    @property
    def withheld(self) -> list[ReviewedWorkerResult]:
        return [result for result in self.results if not result.forwarded]

    @property
    def complete(self) -> bool:
        """Whether every result passed — i.e. the mission may forward all of it."""

        return bool(self.results) and all(result.forwarded for result in self.results)

    @property
    def reviewed_count(self) -> int:
        return sum(1 for result in self.results if result.review.reviewed)

    def for_worker(self, worker_id: str) -> ReviewedWorkerResult | None:
        return next((result for result in self.results
                     if result.worker_id == worker_id), None)

    def deficiencies(self) -> list[Deficiency]:
        return [item for result in self.results for item in result.review.deficiencies]

    def by_decision(self) -> dict[str, list[str]]:
        grouped: dict[str, list[str]] = {decision.value: [] for decision in ReviewDecision}
        for result in self.results:
            grouped[result.review.decision.value].append(result.worker_id)
        return grouped

    def paths(self) -> dict[str, int]:
        counts: dict[str, int] = {}
        for result in self.results:
            counts[result.review.path] = counts.get(result.review.path, 0) + 1
        return counts

    def summary(self) -> str:
        decisions = ", ".join(f"{len(ids)} {name}"
                              for name, ids in self.by_decision().items() if ids) or "none"
        return (f"{len(self.results)} result(s): {decisions}; "
                f"{len(self.forwarded)} forwarded, {len(self.withheld)} withheld; "
                f"every result reviewed: "
                f"{'yes' if self.reviewed_count == len(self.results) else 'no'}")

    def to_dict(self) -> dict[str, Any]:
        return {
            "results": [result.to_dict() for result in self.results],
            "forwarded": [result.worker_id for result in self.forwarded],
            "withheld": [result.worker_id for result in self.withheld],
            "by_decision": self.by_decision(),
            "paths": self.paths(),
            "complete": self.complete,
            "reviewed": self.reviewed_count,
            "deficiencies": [item.describe for item in self.deficiencies()],
            "summary": self.summary(),
        }


def review_ledger(results: Sequence[ReviewedWorkerResult]) -> ReviewLedger:
    return ReviewLedger(results=list(results))


# --------------------------------------------------------------------------
# 34.6 Wiring the review into the flow
# --------------------------------------------------------------------------


def _reviewer_for(worker: "FlowWorker", *, scope: Sequence[str] = (),
                  minimum_items: int | None = None,
                  minimum_sources: int | None = None) -> SubagentReviewer:
    """The reviewer a Subagent uses for one of its Workers.

    Built per Worker because the *expectation* is per Worker: the assignment's
    expected volume belongs to that unit, not to the Subagent's average.
    """

    return SubagentReviewer(scope=scope, minimum_items=minimum_items,
                            minimum_sources=minimum_sources)


def _expected_volume(worker: "FlowWorker") -> tuple[int | None, int | None]:
    """The item and source counts in a Worker's ``expected_evidence`` line.

    ``ExpectedEvidence.describe`` renders as "≥2 observation item(s) from ≥1
    source(s)", so the numbers the plan *stated* can be read back rather than
    guessed.  Nothing found means ``None``: an unstated expectation is not a zero.
    """

    text = worker.expected_evidence or ""
    items = re.search(r"≥\s*(\d+)\s+\S*\s*item", text)
    sources = re.search(r"from\s*≥\s*(\d+)\s*source", text)
    return (int(items.group(1)) if items else None,
            int(sources.group(1)) if sources else None)


def review_outcome(outcome: "WorkerOutcome", *, worker: "FlowWorker",
                   subagent_id: str, scope: Sequence[str] = (),
                   path: str = "runner",
                   observations: Sequence[Deficiency] = ()) -> ReviewedWorkerResult:
    """Review one graph outcome with the expectations its own assignment stated."""

    items, sources = _expected_volume(worker)
    reviewer = _reviewer_for(worker, scope=scope, minimum_items=items,
                             minimum_sources=sources)
    return review_worker_result(worker, outcome, subagent_id=subagent_id,
                                reviewer=reviewer, path=path,
                                observations=observations)


def review_summary(reviews: Sequence[QualityReview]) -> dict[str, Any]:
    """The counts a reader wants from a set of reviews, without the records."""

    decisions: dict[str, list[str]] = {decision.value: [] for decision in ReviewDecision}
    dimensions: dict[str, int] = {dimension.value: 0 for dimension in REVIEW_DIMENSIONS}
    for review in reviews:
        decisions[review.decision.value].append(review.worker_id)
        for deficiency in review.deficiencies:
            dimensions[deficiency.dimension.value] += 1
    return {"reviews": len(reviews),
            "decisions": {name: ids for name, ids in decisions.items() if ids},
            "deficiencies_by_dimension": {name: count for name, count in dimensions.items()
                                          if count},
            "faults": {fault.value: sum(1 for review in reviews
                                        if review.fault is fault)
                       for fault in WorkflowFault if any(
                           review.fault is fault for review in reviews)},
            "reviewed": all(review.reviewed for review in reviews)}


# --------------------------------------------------------------------------
# 34.7 Scripted results: one of every kind the reviewer has to handle
# --------------------------------------------------------------------------

def _review_source(name: str, *, url: str | None = None, path: str | None = None,
                   kind: SourceKind | None = None) -> SourceReference:
    return SourceReference(
        kind=kind or (SourceKind.PUBLIC_WEB if url else SourceKind.LOG_FILE),
        url=url, artifact_path=None if url else path, title=name,
        retrieved_at=datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc),
        retrieval_method=RetrievalMethod.HTTP if url else RetrievalMethod.LOCAL_READ,
        http_status=200 if url else None)


def _review_evidence(statement: str, *, tag: str, url: str | None = None,
                     path: str | None = None, kind: SourceKind | None = None,
                     confidence: Confidence = Confidence.LOW,
                     basis: str | None = "one retrieval",
                     observed: datetime | None = None) -> EvidenceItem:
    return EvidenceItem(
        kind=EvidenceKind.OBSERVATION, statement=statement,
        sources=[_review_source(tag, url=url, path=path, kind=kind)],
        confidence=confidence, confidence_basis=basis, tags=[tag],
        observed_at=observed or datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc))


def _review_worker(name: str = "w-proxy", *,
                   criteria: Sequence[str] = ("each proxy event has a timestamp",),
                   schema: str = "EvidenceSet", unit: str = "") -> "FlowWorker":
    """One Worker as the graph sees it, with a mandate the reviewer can check."""

    return FlowWorker(
        id=f"worker-{name}", name=name, work_unit=unit or f"{name} records",
        objective=f"collect the {name} records that answer this part of the assignment",
        completion_criteria=list(criteria), output_schema=schema,
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        max_attempts=2)


def review_demo_cases() -> dict[str, Any]:
    """Six results a parent Subagent has to judge, and what it decides for each.

    Each case's Worker carries the mandate its report is answering — the reviewer
    judges relevance and completeness against *that unit's own* criteria, so a case
    that mixed two mandates would test the fixture instead of the reviewer.

    *   ``good`` — a complete, sourced report answering its criteria.  Pass.
    *   ``weak_source`` — a real observation resting on a search-engine result page
        only.  Revise: the claim may be true, but its source cannot carry it.
    *   ``needs_revision`` — a successful call that ignored its mandate: a mailbox
        receipt when the unit was asked for a timeline, and no instant to place.
    *   ``partial`` — one day of a log, with the missing days named.  Pass: partial
        work with usable provenance and its gaps stated is forwardable.
    *   ``tool_failure`` — the tool died mid-read, one record survived.  Retry (the
        failure was the tool's), not a quality revise.
    *   ``blocked`` — the archive needs a key.  Blocked, not failed, and not revised.
    """

    scope = ["example.com", "/evidence"]
    cases: dict[str, Any] = {}

    good_worker = _review_worker(
        "w-proxy", criteria=("each proxy event has a timestamp",),
        unit="proxy events", schema="EvidenceSet")
    good_report = report_from_evidence(
        "worker-w-proxy", "sa-network", status=WorkerStatus.COMPLETED,
        evidence=[_review_evidence(
            "the proxy event at 10:00:00Z has a timestamp and a CONNECT to "
            "evil.example.org", tag="proxy event", path="/evidence/proxy.log")],
        summary="read the proxy log; every proxy event carries a timestamp")
    cases["good"] = {
        "worker": good_worker,
        "review": review_outcome(outcome_from_report(good_report),
                                 worker=good_worker, subagent_id="sa-network",
                                 scope=scope),
    }

    weak_worker = _review_worker(
        "w-advisory", criteria=("the advisory names a registration date",),
        unit="advisory registration", schema="EvidenceSet")
    weak_report = report_from_evidence(
        "worker-w-advisory", "sa-network", status=WorkerStatus.COMPLETED,
        evidence=[_review_evidence(
            "the advisory names a registration date of March 2026 for the domain",
            tag="advisory registration", url="https://example.com/search/result?id=7",
            kind=SourceKind.SEARCH_ENGINE)],
        summary="read the advisory registration date from a search result")
    cases["weak_source"] = {
        "worker": weak_worker,
        "review": review_outcome(outcome_from_report(weak_report),
                                 worker=weak_worker, subagent_id="sa-network",
                                 scope=scope),
    }

    # A successful call whose work is wrong: the output schema was TimelineTable and
    # nothing carries an instant, and the finding is about another unit's slice.
    wrong_worker = _review_worker(
        "w-timeline", schema="TimelineTable",
        criteria=("every timeline event is placed on the timeline",),
        unit="timeline events")
    wrong_report = WorkerReport(
        worker_id="worker-w-timeline", subagent_id="sa-network",
        status=WorkerStatus.COMPLETED, summary="collected the records",
        findings=[WorkerFinding(statement="a subscription receipt was found in the mailbox",
                                evidence_ids=["ev-receipt"])],
        evidence=[EvidenceItem(
            id="ev-receipt", kind=EvidenceKind.OBSERVATION,
            statement="a subscription receipt was found in the mailbox",
            sources=[_review_source("receipt", path="/evidence/mail.eml")],
            confidence=Confidence.LOW, confidence_basis="one retrieval",
            tags=["receipt"], observed_at=None)],
        sources=[_review_source("receipt", path="/evidence/mail.eml")])
    cases["needs_revision"] = {
        "worker": wrong_worker,
        "review": review_outcome(outcome_from_report(wrong_report),
                                 worker=wrong_worker, subagent_id="sa-network",
                                 scope=scope),
    }

    partial_worker = _review_worker(
        "w-dns", criteria=("each dns query has a timestamp",), unit="dns queries",
        schema="EvidenceSet")
    partial_report = report_from_evidence(
        "worker-w-dns", "sa-network", status=WorkerStatus.PARTIAL,
        evidence=[_review_evidence(
            "the dns query for evil.example.org has a timestamp of 09:30:00Z",
            tag="dns query", path="/evidence/dns.log")],
        summary="read one day of the resolver log; the other six are missing",
        limitations=["the rotated logs for the other six days are not on this host"])
    cases["partial"] = {
        "worker": partial_worker,
        "review": review_outcome(outcome_from_report(partial_report),
                                 worker=partial_worker, subagent_id="sa-network",
                                 scope=scope),
    }

    failure_worker = _review_worker(
        "w-hash", schema="HashManifest", criteria=("the capture is hashed",),
        unit="capture hashes")
    failure_report = report_from_evidence(
        "worker-w-hash", "sa-network", status=WorkerStatus.FAILED,
        evidence=[_review_evidence(
            "the capture's first record hashes to the advisory's sample digest",
            tag="capture hashes", path="/evidence/capture.pcap")],
        summary="hashed one record before the reader aborted",
        limitations=["the pcap reader aborted at a malformed record boundary"],
        error=ErrorInfo(code="pcap-truncated", stage="tool", component="w-hash",
                        message="unexpected end of pcap record at offset 4096"))
    cases["tool_failure"] = {
        "worker": failure_worker,
        "review": review_outcome(outcome_from_report(failure_report),
                                 worker=failure_worker, subagent_id="sa-network",
                                 scope=scope),
    }

    blocked_worker = _review_worker(
        "w-archive", schema="SnapshotList",
        criteria=("the snapshot list has dates",), unit="archive snapshots")
    cases["blocked"] = {
        "worker": blocked_worker,
        "review": review_outcome(
            outcome_from_report(blocked_report(
                "worker-w-archive", "sa-network",
                "the archive requires an API key this mission does not hold")),
            worker=blocked_worker, subagent_id="sa-network", scope=scope),
    }
    return cases


def review_quality_demo() -> dict[str, Any]:
    """The six cases, their decisions, and the two different next steps."""

    cases = review_demo_cases()
    results = [case["review"] for case in cases.values()]
    ledger = review_ledger(results)
    reviews = [result.review for result in results]
    failure = cases["tool_failure"]["review"].review
    revision = cases["needs_revision"]["review"].review
    return {
        "dimensions": [dimension.value for dimension in REVIEW_DIMENSIONS],
        "cases": {
            name: {
                "worker": case["worker"].name,
                "schema": case["worker"].output_schema,
                "review": case["review"].review.to_dict(),
                "next": next_step(case["review"].review),
                "directive": (revision_directive(case["review"].review).model_dump(mode="json")
                              if case["review"].review.decision is ReviewDecision.REVISE
                              else None),
            }
            for name, case in cases.items()
        },
        "ledger": ledger.to_dict(),
        "summary": review_summary(reviews),
        "contrast": {
            "failed_tool_call": {
                "decision": failure.decision.value,
                "fault": failure.fault.value,
                "next": next_step(failure),
                "guidance": failure.guidance,
                "because": [item.describe for item in failure.deficiencies],
                "treatment": "retry the same unit: the tool broke, the work did not",
            },
            "low_quality_success": {
                "decision": revision.decision.value,
                "fault": revision.fault.value,
                "next": next_step(revision),
                "guidance": revision.guidance,
                "because": [item.describe for item in revision.deficiencies],
                "treatment": "revise with the named deficiency: re-running unchanged "
                             "would fail the same way",
            },
        },
    }


# --------------------------------------------------------------------------
# 34.8 Self-test — the acceptance criteria as executable checks
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class ReviewCheck:
    name: str
    ok: bool
    detail: str = ""


def _rc(name: str, ok: Any, detail: Any = "") -> ReviewCheck:
    return ReviewCheck(name=name, ok=bool(ok), detail=str(detail)[:150])


def _refuses(call: Callable[[], Any]) -> tuple[str, str]:
    try:
        call()
    except (ValueError, TypeError, UnreviewedResult) as exc:
        return type(exc).__name__, str(exc)
    return "", "accepted"


def run_review_self_test() -> list[ReviewCheck]:
    """Prove the review contract: seven dimensions, one decision, no skips.

    The acceptance clause is group 8: every Worker result — including a failed, a
    partial, a deferred and an adopted one — is reviewed before it can be forwarded.
    Group 9 is the other half: a failed tool call and a poor but successful call are
    decided, instructed and counted differently.
    """

    checks: list[ReviewCheck] = []
    add = checks.append

    # ---- 1. the vocabulary ------------------------------------------------
    add(_rc("exactly seven review dimensions are defined", len(ReviewDimension) == 7,
            [dimension.value for dimension in ReviewDimension]))
    add(_rc("the seven dimensions are the ones the task names",
            [dimension.value for dimension in ReviewDimension]
            == ["completeness", "relevance", "source-quality", "provenance",
                "consistency", "scope", "schema"]))
    add(_rc("the dimensions are ordered deterministically",
            REVIEW_DIMENSIONS == tuple(ReviewDimension)
            and ReviewDimension.SCOPE.rank > ReviewDimension.RELEVANCE.rank))
    add(_rc("four review decisions are defined", len(ReviewDecision) == 4,
            [decision.value for decision in ReviewDecision]))
    add(_rc("only a pass forwards the result",
            [decision for decision in ReviewDecision if decision.forwards]
            == [ReviewDecision.PASS]))
    add(_rc("only a revise is actionable",
            [decision for decision in ReviewDecision if decision.actionable]
            == [ReviewDecision.REVISE]))
    add(_rc("a deficiency knows whose fault it is",
            DeficiencyKind.TOOL_FAILURE.fault is WorkflowFault.TOOL
            and DeficiencyKind.BLOCKED.fault is WorkflowFault.ENVIRONMENT
            and DeficiencyKind.UNSOURCED.fault is WorkflowFault.WORKER
            and DeficiencyKind.OUT_OF_SCOPE.fault is WorkflowFault.WORKER))
    add(_rc("there is a decision for every status a Worker can return",
            set(WorkerStatus) == {WorkerStatus.COMPLETED, WorkerStatus.PARTIAL,
                                  WorkerStatus.BLOCKED, WorkerStatus.FAILED}))

    # ---- 2. a pass cannot carry a blocking deficiency ---------------------
    demo = review_quality_demo()
    cases = demo["cases"]
    # The live records behind the demo's serialised view: assertions about the model
    # go through these, not through the dicts the demo renders.
    objects = review_demo_cases()
    good = cases["good"]["review"]
    add(_rc("a good result passes", good["decision"] == "pass", good["decision"]))
    add(_rc("a pass names every dimension it checked",
            good["checked"] == [dimension.value for dimension in REVIEW_DIMENSIONS],
            good["checked"]))
    add(_rc("a pass carries no blocking deficiency", not good["deficiencies"]))
    add(_rc("every review says it was performed", good["reviewed"] is True))
    pass_with_deficiency = _refuses(lambda: QualityReview(
        worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
        decision=ReviewDecision.PASS, checked=list(REVIEW_DIMENSIONS),
        deficiencies=[Deficiency(dimension=ReviewDimension.PROVENANCE,
                                 kind=DeficiencyKind.UNSOURCED,
                                 detail="an item has no source at all",
                                 fix="attach a source")]))
    add(_rc("a pass with a blocking deficiency cannot be built",
            pass_with_deficiency[0] in {"ReviewDimensionError", "ValidationError"}
            and "blocking deficiency" in pass_with_deficiency[1],
            pass_with_deficiency[1][:100]))
    add(_rc("a review with no dimensions checked cannot be built",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.PASS))[0] == "ValidationError"))
    add(_rc("a review that says it was not performed cannot be built",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.PASS, checked=list(REVIEW_DIMENSIONS),
                reviewed=False))[0] == "ValidationError"))
    add(_rc("a deficiency on an unchecked dimension cannot be reported",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.REVISE, guidance="fix it properly",
                retry=True, checked=[ReviewDimension.COMPLETENESS],
                deficiencies=[Deficiency(dimension=ReviewDimension.SCHEMA,
                                         kind=DeficiencyKind.WRONG_SHAPE,
                                         detail="the shape is wrong for this unit",
                                         fix="return the assigned shape")]))[0]
            == "ValidationError"))

    # ---- 3. a revise is concrete -----------------------------------------
    revision = cases["needs_revision"]["review"]
    add(_rc("poor work is revised, not passed", revision["decision"] == "revise",
            revision["decision"]))
    add(_rc("a revise carries a concrete deficiency",
            bool(revision["deficiencies"])
            and all(item["detail"] for item in revision["deficiencies"])))
    add(_rc("the deficiency names its dimension",
            {item["dimension"] for item in revision["deficiencies"]}
            <= {dimension.value for dimension in REVIEW_DIMENSIONS}))
    add(_rc("a revise says what to change", len(revision["guidance"]) >= 12,
            revision["guidance"][:100]))
    add(_rc("a revise asks for another attempt", revision["retry"] is True))
    add(_rc("a revise cannot be built without a deficiency",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.REVISE, checked=list(REVIEW_DIMENSIONS),
                guidance="do it again", retry=True))[0] == "ValidationError"))
    add(_rc("a revise cannot be built without guidance",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.REVISE, checked=list(REVIEW_DIMENSIONS),
                retry=True,
                deficiencies=[Deficiency(dimension=ReviewDimension.PROVENANCE,
                                         kind=DeficiencyKind.UNSOURCED,
                                         detail="an item has no source at all",
                                         fix="attach a source reference")]))[0]
            == "ValidationError"))
    add(_rc("a revise that would discard the work cannot be built",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.COMPLETED,
                decision=ReviewDecision.REVISE, checked=list(REVIEW_DIMENSIONS),
                guidance="do it again", retry=False,
                deficiencies=[Deficiency(dimension=ReviewDimension.PROVENANCE,
                                         kind=DeficiencyKind.UNSOURCED,
                                         detail="an item has no source at all",
                                         fix="attach a source reference")]))[0]
            == "ValidationError"))
    add(_rc("a stop must give its reason",
            _refuses(lambda: QualityReview(
                worker_id="w", subagent_id="s", worker_status=WorkerStatus.BLOCKED,
                decision=ReviewDecision.BLOCKED, checked=list(REVIEW_DIMENSIONS)))[0]
            == "ValidationError"))
    directive = cases["needs_revision"]["directive"]
    add(_rc("a revise becomes a directive with an instruction", 
            bool(directive) and len(directive["instruction"]) >= 8))
    add(_rc("the directive cites the deficiency it came from",
            bool(directive["because"])
            and directive["because"][0] in
            {f"{item['dimension']}/{item['kind']}" for item in revision["deficiencies"]}))
    add(_rc("a directive cannot be built from a pass",
            _refuses(lambda: revision_directive(
                QualityReview.from_dict(good)))[0] == "ValueError"))

    # ---- 4. each dimension actually bites --------------------------------
    worker = _review_worker("w-check", criteria=("every event has a timestamp",))
    reviewer = SubagentReviewer(scope=["example.com", "/evidence"])
    perfect = report_from_evidence(
        "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
        evidence=[_review_evidence("the event has a timestamp of 10:00:00Z",
                                   tag="event", path="/evidence/log.txt")],
        summary="read the log")
    clean = reviewer.review(worker, perfect, subagent_id="sa-network")
    add(_rc("a clean result has no deficiency in any dimension",
            not clean.deficiencies, [item.describe for item in clean.deficiencies]))

    irrelevant = reviewer.review(
        worker, report_from_evidence(
            "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[_review_evidence("a subscription receipt was found",
                                       tag="receipt", path="/evidence/mail.eml")],
            summary="read the mailbox"), subagent_id="sa-network")
    add(_rc("a result about another slice fails relevance",
            (irrelevant.dimension(ReviewDimension.RELEVANCE) or DimensionResult(
                dimension=ReviewDimension.RELEVANCE)).ok is False,
            [item.describe for item in irrelevant.deficiencies]))

    weak = reviewer.review(
        worker, report_from_evidence(
            "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[_review_evidence("the event has a timestamp per the search snippet",
                                       tag="event", url="https://search.example/x",
                                       kind=SourceKind.SEARCH_ENGINE)],
            summary="read a search snippet"), subagent_id="sa-network")
    add(_rc("a secondary-only source fails source quality",
            not (weak.dimension(ReviewDimension.SOURCE_QUALITY) or
                 DimensionResult(dimension=ReviewDimension.SOURCE_QUALITY)).ok,
            [item.describe for item in weak.deficiencies]))
    add(_rc("the source deficiency names the secondary kind",
            any("secondary" in item.detail.lower() for item in weak.deficiencies)))

    overconfident = reviewer.review(
        worker, report_from_evidence(
            "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[_review_evidence("the event has a timestamp of 10:00:00Z",
                                       tag="event", path="/evidence/log.txt",
                                       confidence=Confidence.HIGH,
                                       basis="one source, judged reliable")],
            summary="read the log"), subagent_id="sa-network")
    add(_rc("high confidence from one source is a deficiency",
            any("single source" in item.detail for item in overconfident.deficiencies),
            [item.describe for item in overconfident.deficiencies]))

    unscoped = reviewer.review(
        worker, report_from_evidence(
            "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[_review_evidence("the event has a timestamp of 10:00:00Z",
                                       tag="event", url="https://elsewhere.org/log")],
            summary="read a log elsewhere"), subagent_id="sa-network")
    add(_rc("a source outside the authorised scope fails scope compliance",
            any(item.dimension is ReviewDimension.SCOPE
                for item in unscoped.deficiencies),
            [item.describe for item in unscoped.deficiencies]))
    no_scope = SubagentReviewer(scope=[]).review(worker, perfect,
                                                 subagent_id="sa-network")
    add(_rc("scope is judged against the mission's own entries: no entries, no refusal",
            (no_scope.dimension(ReviewDimension.SCOPE) or
             DimensionResult(dimension=ReviewDimension.SCOPE)).ok is True,
            "an empty scope cannot be violated, and is not guessed at"))

    schema_worker = _review_worker("w-schema", schema="TimelineTable",
                                   criteria=("every event is placed on the timeline",))
    wrong_shape = SubagentReviewer(scope=["/evidence"]).review(
        schema_worker, report_from_evidence(
            "worker-w-schema", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[EvidenceItem(kind=EvidenceKind.OBSERVATION,
                                   statement="an event is placed on the timeline at 10:00",
                                   sources=[_review_source("timeline",
                                                           path="/evidence/log.txt")],
                                   tags=["event"])],
            summary="placed the events"), subagent_id="sa-network")
    add(_rc("a result that does not satisfy its output schema is a deficiency",
            any(item.dimension is ReviewDimension.SCHEMA and "TimelineTable" in item.detail
                for item in wrong_shape.deficiencies),
            [item.describe for item in wrong_shape.deficiencies]))
    add(_rc("every schema the plan can assign has a requirement",
            set(SCHEMA_REQUIREMENTS) == set(OUTPUT_SCHEMAS),
            sorted(set(OUTPUT_SCHEMAS) - set(SCHEMA_REQUIREMENTS))))
    # A valid record whose *shape* is wrong for the assigned schema: a snapshot list
    # needs a retrieval time, and this source was never retrieved from.
    snapshot_source = SourceReference(kind=SourceKind.LOCAL_ARTIFACT,
                                      artifact_path="/evidence/snapshots/index.txt")
    snapshot_report = WorkerReport(
        worker_id="w", subagent_id="s", status=WorkerStatus.COMPLETED,
        summary="listed the snapshots from the index",
        findings=[WorkerFinding(statement="a snapshot of the page exists",
                                evidence_ids=["ev-snapshot"])],
        evidence=[EvidenceItem(id="ev-snapshot", kind=EvidenceKind.OBSERVATION,
                               statement="a snapshot of the page exists",
                               sources=[snapshot_source.model_copy(
                                   update={"retrieval_method": RetrievalMethod.UNKNOWN})],
                               tags=["snapshot"])])
    add(_rc("a snapshot list check asks how each item was captured",
            "state how it was captured" in _schema_problem(snapshot_report, "SnapshotList"),
            _schema_problem(snapshot_report, "SnapshotList")))
    tagged = snapshot_report.model_copy(update={
        "evidence": [snapshot_report.evidence[0].model_copy(
            update={"tags": ["sha256:" + "a" * 64]})]})
    add(_rc("a hash manifest check asks for a hash",
            "no item carries a hash" in _schema_problem(snapshot_report, "HashManifest")
            and _schema_problem(tagged, "HashManifest") == "",
            _schema_problem(snapshot_report, "HashManifest")))

    duplicated = SubagentReviewer(scope=["/evidence"]).review(
        worker, report_from_evidence(
            "worker-w-check", "sa-network", status=WorkerStatus.COMPLETED,
            evidence=[_review_evidence("the event has a timestamp of 10:00:00Z",
                                       tag="event", path="/evidence/log.txt"),
                      _review_evidence("the event has a timestamp of 10:00:00Z",
                                       tag="event", path="/evidence/log.txt")],
            summary="read the log"), subagent_id="sa-network")
    add(_rc("the same statement twice is an inconsistency",
            any("same thing" in item.detail for item in duplicated.deficiencies),
            [item.describe for item in duplicated.deficiencies]))

    short = SubagentReviewer(scope=["/evidence"], minimum_items=3).review(
        worker, perfect, subagent_id="sa-network")
    add(_rc("fewer items than the assignment expected is incomplete",
            any(item.dimension is ReviewDimension.COMPLETENESS
                and item.kind is DeficiencyKind.INCOMPLETE
                for item in short.deficiencies),
            [item.describe for item in short.deficiencies]))
    add(_rc("the numeric expectation is read back from the assignment",
            all(isinstance(value, int) for value in _expected_volume(worker)),
            _expected_volume(worker)))

    # ---- 5. a failed call is not a quality judgement ---------------------
    # These are live records, so they are read as attributes; the demo's own view is
    # asserted separately, where the serialisation is what is being tested.
    failure = objects["tool_failure"]["review"].review
    add(_rc("a failed tool call is reviewed too", failure.reviewed is True))
    add(_rc("a failed call is the tool's fault, not the Worker's",
            failure.fault is WorkflowFault.TOOL, failure.fault.value))
    add(_rc("a failed call is retried while the budget allows",
            failure.decision is ReviewDecision.REVISE and failure.retry is True,
            (failure.decision.value, failure.retry)))
    add(_rc("the retry instruction is to try again, not to work differently",
            "the failure was the tool's" in failure.guidance, failure.guidance))
    add(_rc("the failed call keeps the record that survived",
            len(objects["tool_failure"]["review"].outcome.evidence_ids) == 1,
            objects["tool_failure"]["review"].outcome.evidence_ids))
    exhausted = review_outcome(
        outcome_from_report(report_from_evidence(
            "worker-w-hash", "sa-network", status=WorkerStatus.FAILED,
            evidence=[_review_evidence("the first record hashes to the digest",
                                       tag="hash", path="/evidence/capture.pcap")],
            summary="hashed one record", attempt=2,
            error=ErrorInfo(code="pcap", message="the reader aborted"))),
        worker=_review_worker("w-hash"), subagent_id="sa-network")
    add(_rc("a failed call with no attempts left stops, with a reason",
            exhausted.review.decision is ReviewDecision.FAILED
            and bool(exhausted.review.stop_reason),
            (exhausted.review.decision.value, exhausted.review.stop_reason[:60])))
    add(_rc("a stop does not pretend another attempt is coming",
            exhausted.review.retry is False))

    # ---- 6. a blocked unit is not a failure ------------------------------
    blocked = objects["blocked"]["review"].review
    add(_rc("a blocked unit is reviewed and blocked, not failed",
            blocked.decision is ReviewDecision.BLOCKED, blocked.decision.value))
    add(_rc("a blocked unit is not revised: another attempt would hit the same wall",
            blocked.retry is False))
    add(_rc("a blocked unit's reason reaches the review",
            "API key" in blocked.stop_reason, blocked.stop_reason[:80]))
    add(_rc("a blocked unit's deficiency is the environment's, not the Worker's",
            all(item.kind.fault in {WorkflowFault.ENVIRONMENT, WorkflowFault.TOOL}
                for item in blocked.deficiencies)
            and all(item.kind.fault is not WorkflowFault.WORKER
                    for item in blocked.deficiencies),
            [item.describe for item in blocked.deficiencies]))

    # ---- 7. a partial result can be forwarded ----------------------------
    partial = objects["partial"]["review"].review
    add(_rc("a partial result with provenance passes",
            partial.decision is ReviewDecision.PASS,
            [item.describe for item in partial.deficiencies]))
    add(_rc("a partial result is not described as complete",
            partial.worker_status is WorkerStatus.PARTIAL))

    # ---- 8. nothing is forwarded unreviewed (the acceptance clause) ------
    ledger = review_ledger([case["review"] for case in objects.values()])
    add(_rc("every demo case produced a review", len(ledger.results) == len(cases)))
    add(_rc("the ledger states every result was reviewed",
            ledger.reviewed_count == len(ledger.results), ledger.reviewed_count))
    add(_rc("the ledger splits forwarded from withheld",
            len(ledger.forwarded) + len(ledger.withheld) == len(ledger.results)))
    add(_rc("a bare outcome is refused at the aggregate",
            _refuses(lambda: require_review(WorkerOutcome(
                worker_id="worker-x", subagent_id="sa"))) [0] == "UnreviewedResult"))
    add(_rc("the refusal names the unit and the stage",
            "worker-x" in (lambda exc: exc)("worker-x")
            and "aggregate" in str(_refuses(lambda: require_review(
                WorkerOutcome(worker_id="worker-x", subagent_id="sa"),
                stage="aggregate"))[1])))
    add(_rc("a ledger refuses a result whose verdict was not performed",
            _refuses(lambda: ReviewLedger.model_validate({"results": [
                ReviewedWorkerResult.model_construct(
                    worker_id="w", subagent_id="s",
                    outcome=WorkerOutcome(worker_id="w", subagent_id="s"),
                    report=None,
                    review=QualityReview.model_construct(
                        reviewed=False, worker_id="w", subagent_id="s",
                        worker_status=WorkerStatus.COMPLETED,
                        decision=ReviewDecision.PASS,
                        checked=list(REVIEW_DIMENSIONS), checks=[],
                        deficiencies=[])).model_dump()]}))[0]
            in {"UnreviewedResult", "ValidationError"},
            "a verdict that was not performed cannot reach the ledger, whether the "
            "review or the ledger refuses it"))
    add(_rc("a reviewed result cannot pair a review with another unit",
            _refuses(lambda: ReviewedWorkerResult(
                worker_id="worker-a", subagent_id="sa",
                outcome=WorkerOutcome(worker_id="worker-a", subagent_id="sa"),
                review=good and QualityReview.model_validate(good)))[0]
            == "ValidationError"))
    add(_rc("a failed result is reviewed before the aggregate sees it",
            ledger.for_worker("worker-w-hash") is not None
            and ledger.for_worker("worker-w-hash").review.reviewed is True))
    add(_rc("a blocked result is reviewed before the aggregate sees it",
            ledger.for_worker("worker-w-archive") is not None
            and ledger.for_worker("worker-w-archive").review.reviewed is True))

    # the flow's own seam: run a real mission and check the ledger it produced
    context = _selftest_context("exposure")
    units = flow_units_for(context, "exposure")
    flow = HierarchicalFlow(context=context, subagents=units,
                            runner=_CountingRunner(scope=context.scope_entries))
    flow.run_with_reviews()
    flow_ledger = flow.review_ledger()
    add(_rc("a real mission reviews every Worker result",
            flow_ledger.reviewed_count == len(flow_ledger.results)
            and len(flow_ledger.results) >= sum(len(unit.workers) for unit in units),
            flow_ledger.summary()))
    add(_rc("a real mission forwards only what passed",
            all(result.forwarded for result in flow_ledger.forwarded)
            and all(not result.forwarded for result in flow_ledger.withheld)))
    add(_rc("the reviews name all seven dimensions",
            all(len(result.review.checked) == len(REVIEW_DIMENSIONS)
                for result in flow_ledger.results)))
    add(_rc("every forwarded result has a report a reader can follow",
            all(result.report is not None for result in flow_ledger.forwarded)))

    # A Worker that fails inside a *multi-Worker* Subagent: the unit's failure must
    # not take its subagent — or the mission — down with it.
    mixed = next(unit for unit in units if len(unit.workers) >= 2)
    flow_failing = HierarchicalFlow(
        context=context, subagents=units,
        runner=_CountingRunner(scope=context.scope_entries,
                               failing=[mixed.workers[0].id]))
    failing_result = flow_failing.run_with_reviews()
    failing_ledger = flow_failing.review_ledger()
    add(_rc("a failed Worker is still reviewed in a real mission",
            failing_ledger.reviewed_count == len(failing_ledger.results),
            failing_ledger.summary()))
    add(_rc("a failed Worker does not stop the mission",
            failing_result.synthesis is not None and not failing_result.stopped,
            failing_result.stop_reason))
    add(_rc("the failed unit's review is on the record",
            any(result.review.decision is not ReviewDecision.PASS
                for result in failing_ledger.results),
            failing_ledger.by_decision()))
    add(_rc("the mission's result carries every review",
            failing_result.reviews is not None
            and len(failing_result.reviews.results) == len(failing_ledger.results)))
    add(_rc("the mission's result summarises the decisions",
            bool(failing_result.review_summary.get("decisions")),
            failing_result.review_summary))
    failed_unit = next(result for result in failing_ledger.results
                       if result.worker_id == mixed.workers[0].id)
    add(_rc("the failed unit's review names the tool as the cause",
            failed_unit.review.fault is WorkflowFault.TOOL,
            [item.describe for item in failed_unit.review.deficiencies]))
    add(_rc("the failed unit's work is withheld from its Subagent's aggregate",
            not failed_unit.forwarded))
    add(_rc("the surviving Worker's work is forwarded",
            any(result.forwarded for result in failing_ledger.results
                if result.worker_id != mixed.workers[0].id)))

    # ---- 9. a failed call and a poor call are handled differently --------
    contrast = demo["contrast"]
    add(_rc("a failed tool call and a poor call are attributed differently",
            contrast["failed_tool_call"]["fault"]
            != contrast["low_quality_success"]["fault"],
            (contrast["failed_tool_call"]["fault"],
             contrast["low_quality_success"]["fault"])))
    add(_rc("a failed tool call and a poor call are told different things",
            contrast["failed_tool_call"]["guidance"]
            != contrast["low_quality_success"]["guidance"]
            and "retry" in contrast["failed_tool_call"]["guidance"]))
    add(_rc("a failed call is retried as-is, a poor call is revised",
            contrast["failed_tool_call"]["treatment"].startswith("retry the same unit")
            and contrast["low_quality_success"]["treatment"].startswith("revise")))
    add(_rc("the difference is the fault, not the severity",
            contrast["failed_tool_call"]["fault"] == "tool"
            and contrast["low_quality_success"]["fault"] == "worker"))
    add(_rc("a failed call is told to retry, a poor call is told what to change",
            "retry" in contrast["failed_tool_call"]["treatment"]
            and len(contrast["low_quality_success"]["guidance"]) >= 12))
    add(_rc("a fresh failed call is retried", next_step(failure) == "retry",
            next_step(failure)))
    add(_rc("a fresh quality revise is retried",
            next_step(objects["needs_revision"]["review"].review) == "retry"))
    add(_rc("a revise beyond the revision budget stops",
            next_step(objects["needs_revision"]["review"].review,
                      revisions_so_far=ReviewPolicy().max_revisions) == "stop"))
    add(_rc("a failed call with no attempts left stops",
            next_step(exhausted.review) == "stop", next_step(exhausted.review)))
    add(_rc("a failed call is not retried when the policy forbids it",
            next_step(failure, policy=ReviewPolicy(retry_tool_failures=False)) == "stop"))
    add(_rc("a pass always forwards",
            next_step(QualityReview.from_dict(good)) == "forward"))
    add(_rc("a review reloads from its own serialisation",
            QualityReview.from_dict(
                objects["tool_failure"]["review"].review.to_dict()
            ).decision is ReviewDecision.REVISE,
            "a review stored with a case file must come back"))
    add(_rc("the guidance cannot be switched off",
            _refuses(lambda: ReviewPolicy(require_guidance=False))[0]
            == "ValidationError", "a revise with no instruction would repeat the work"))
    add(_rc("the two paths are distinguishable in the ledger",
            set(ledger.paths()) >= {"runner"}))

    # ---- 10. determinism, serialisation, and the section's discipline ----
    again = review_quality_demo()
    add(_rc("two runs of the demo decide identically",
            [case["review"]["decision"] for case in demo["cases"].values()]
            == [case["review"]["decision"] for case in again["cases"].values()]))
    add(_rc("a review serialises to plain JSON",
            isinstance(json.dumps(objects["weak_source"]["review"].review.to_dict()),
                       str)))
    add(_rc("a review records which dimensions it checked",
            cases["weak_source"]["review"]["checked"] == [d.value for d in REVIEW_DIMENSIONS]))
    add(_rc("a serialised review carries the deficiency's fix",
            all(item["fix"] for case in demo["cases"].values()
                for item in case["review"]["deficiencies"])))
    add(_rc("every deficiency's detail is long enough to act on",
            all(len(item.detail) >= 12 and len(item.fix) >= 8
                for item in ledger.deficiencies())))
    section = _source_section(
        "# 34. Subagent quality review: every Worker result is judged, none is forwarded",
        "# 35. Entry point")
    add(_rc("the review section is present and bounded", bool(section), len(section)))
    add(_rc("the review section calls no model",
            bool(section) and "call_model(" not in section))
    add(_rc("the review section grants no capability",
            bool(section) and "CapabilityGrant(" not in section))
    add(_rc("the review section dispatches no tool",
            bool(section) and "CapabilityRouter(" not in section and ".route(" not in section))
    add(_rc("the review section names every dimension",
            all(dimension.value in section for dimension in ReviewDimension)))
    return checks


# --------------------------------------------------------------------------
# 34.9 Rendering
# --------------------------------------------------------------------------

_DECISION_STYLE: dict[str, str] = {"pass": "green", "revise": "yellow",
                                   "blocked": "cyan", "failed": "red"}


def render_review_self_test(checks: Sequence[ReviewCheck]) -> Table:
    table = Table(title="review self-test", title_justify="left", box=None,
                  pad_edge=False)
    table.add_column("", width=2)
    table.add_column("check", no_wrap=True)
    table.add_column("detail", overflow="fold")
    for check in checks:
        glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
        table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                      escape(check.detail))
    return table


def render_review_record(review: QualityReview) -> Group:
    """One review, dimension by dimension, with the decision under it."""

    table = Table(title=f"{review.decision.value} — {review.worker_id} "
                        f"(attempt {review.attempt}, {review.worker_status.value})",
                  title_justify="left", box=None, pad_edge=False)
    table.add_column("dimension", no_wrap=True)
    table.add_column("", width=2)
    table.add_column("finding", overflow="fold", max_width=78)
    for check in review.checks:
        glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
        table.add_row(escape(check.dimension.value),
                      f"[{colour}]{glyph}[/{colour}]",
                      escape("; ".join(item.detail for item in check.deficiencies)
                             or check.note or "ok"))
    colour = _DECISION_STYLE.get(review.decision.value, "white")
    rows: list[Any] = [table, Text("")]
    if review.guidance:
        rows.append(Text(f"what to change: {review.guidance}", style="yellow"))
    if review.stop_reason:
        rows.append(Text(f"stop reason: {review.stop_reason}", style="dim"))
    # A ``Text`` with a style does not parse markup, so the verdict is a span rather
    # than a tag: an operator should never see "[yellow]" printed at them.
    verdict = Text("\n", style="dim")
    verdict.append(review.decision.value, style=colour)
    verdict.append(f" · fault: {review.fault.value} · next: {next_step(review)} · "
                   f"{review.describe()}", style="dim")
    rows.append(verdict)
    return Group(*rows)


def render_review_demo(payload: Mapping[str, Any]) -> Group:
    """The seven dimensions, six verdicts, and the two different next steps."""

    table = Table(title="every Worker result, judged by its parent Subagent",
                  title_justify="left", box=None, pad_edge=False)
    table.add_column("result", no_wrap=True)
    table.add_column("returned", no_wrap=True)
    table.add_column("decision", no_wrap=True)
    table.add_column("fault", no_wrap=True)
    table.add_column("dims", justify="right")
    table.add_column("deficiencies", overflow="fold", max_width=52)
    for name, case in payload["cases"].items():
        review = case["review"]
        colour = _DECISION_STYLE.get(review["decision"], "white")
        table.add_row(
            escape(name), escape(str(review["worker_status"])),
            f"[{colour}]{escape(review['decision'])}[/{colour}]",
            escape(str(review["fault"])),
            f"{len(review['checked'])}/{len(payload['dimensions'])}",
            escape("; ".join(item["detail"] for item in review["deficiencies"])[:150]
                   or "—"))

    contrast = payload["contrast"]
    sides = Table(title="two failures, two paths", title_justify="left", box=None,
                  pad_edge=False)
    sides.add_column("", no_wrap=True)
    sides.add_column("failed tool call", overflow="fold", max_width=42)
    sides.add_column("low-quality success", overflow="fold", max_width=42)
    for label, key in (("decision", "decision"), ("fault", "fault"),
                       ("next step", "next"), ("treatment", "treatment")):
        sides.add_row(escape(label), escape(str(contrast["failed_tool_call"][key])[:120]),
                      escape(str(contrast["low_quality_success"][key])[:120]))

    ledger = payload["ledger"]
    tail = Text(
        f"\n{ledger['summary']}\n"
        f"{len(REVIEW_DIMENSIONS)} dimensions per review: "
        + ", ".join(payload["dimensions"]) + "\n"
        "no Worker result is forwarded until its parent Subagent has judged it — "
        "including the failed, blocked and partial ones",
        style="dim")
    return Group(table, sides, tail)


@app.command("review", help="Subagent quality review: seven dimensions, pass or revise.")
def review_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the review contract offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="Six results judged: pass, revise, blocked, failed."),
    check: str | None = typer.Option(
        None, "--check", help="Review a Worker report file ('-' for stdin).",
        show_default=False),
    worker: str = typer.Option("worker", "--worker", help="Worker id for --check."),
    subagent: str = typer.Option("subagent", "--subagent",
                                 help="Parent Subagent id for --check."),
    criteria: list[str] = typer.Option(
        [], "--criteria", help="The unit's completion criteria for --check. Repeatable."),
    schema: str = typer.Option("EvidenceSet", "--schema",
                               help="The output schema the unit was assigned."),
    scope: list[str] = typer.Option(
        [], "--scope", help="An authorised scope entry. Repeatable."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Judge a Worker result the way its parent Subagent would, or show it happening.

    ``--check`` is the seam for a result produced elsewhere: it reviews one report and
    exits **7 (policy)** when the verdict is not a pass, so a pipeline can withhold
    work exactly as the aggregate would.
    """

    console = get_console()

    if self_test:
        checks = run_review_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"ok": not failures,
                              "checks": [asdict(check) for check in checks]}, indent=2))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        console.print()
        console.print(render_review_self_test(checks))
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = review_quality_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_review_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if check:
        if schema not in OUTPUT_SCHEMAS:
            console.print(f"[red]✘[/red] unknown schema {escape(schema)}; choose from: "
                          f"{', '.join(OUTPUT_SCHEMAS)}")
            raise typer.Exit(ExitCode.USAGE)
        if check != "-" and not Path(check).expanduser().exists():
            console.print(f"[red]✘[/red] no such file: {escape(check[:160])}")
            raise typer.Exit(ExitCode.USAGE)
        try:
            raw = (sys.stdin.read() if check == "-"
                   else Path(check).expanduser().read_text(encoding="utf-8"))
            report = WorkerReport.from_dict(json.loads(raw))
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            console.print(f"[red]✘[/red] not a Worker report: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        judged_worker = FlowWorker(
            id=report.worker_id, name=worker or report.worker_id,
            objective=report.summary or report.worker_id,
            work_unit=worker or report.worker_id,
            completion_criteria=list(criteria), output_schema=schema)
        judged = review_outcome(
            outcome_from_report(report), worker=judged_worker,
            subagent_id=subagent or report.subagent_id, scope=list(scope))
        review = judged.review
        if as_json:
            _emit(json.dumps({"review": review.to_dict(),
                              "next": next_step(review),
                              "directive": (revision_directive(review).model_dump(mode="json")
                                            if review.decision is ReviewDecision.REVISE
                                            else None)}, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if review.passed else ExitCode.POLICY)
        console.print()
        console.print(render_review_record(review))
        console.print()
        raise typer.Exit(ExitCode.OK if review.passed else ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --check FILE")
    raise typer.Exit(ExitCode.USAGE)


# --------------------------------------------------------------------------
# 35. Targeted retasking: a revise that says exactly what to change
# --------------------------------------------------------------------------
#
# §34 decides *that* a result must be revised.  This section decides what the next
# attempt is told, and it is the difference between a retry and a re-run:
#
#   *   a **re-run** hands the Worker the same prompt and hopes;
#   *   a **retask** hands it its own objective, the exact deficiencies the parent
#       Subagent found, the corrections those imply, and the evidence it already
#       collected — and nothing it already did.
#
# Four properties make that checkable rather than aspirational: the assignment is a
# record (so "the prompt was specific" is a field, not a claim), the same review
# produces the same retask (deterministic), every attempt is kept (history), and the
# retry count is the *configured* one (a limit that is read, not re-derived).


class RetaskItem(StrictModel):
    """One thing the next attempt must change, traced back to the review that said so."""

    dimension: ReviewDimension
    kind: DeficiencyKind
    #: The deficiency, verbatim: the Worker should not have to infer the complaint.
    detail: str = Field(min_length=8)
    #: What that deficiency requires of the next attempt, in the imperative.
    correction: str = Field(min_length=8)
    #: The report's own criteria this deficiency touches, when it touches any.
    criteria: list[str] = Field(default_factory=list)

    @property
    def describe(self) -> str:
        return f"{self.dimension.value}: {self.correction}"


class PriorEvidence(StrictModel):
    """The part of an earlier attempt worth carrying forward — and why it is worth it.

    Only evidence the parent Subagent did not fault: a weak source, an unciteable
    row or an out-of-scope item is not a head start, it is the same defect again.
    """

    item_id: str = Field(min_length=1)
    statement: str = Field(min_length=1)
    #: ``supports`` (evidence with no finding on it yet) or ``cited`` (already
    #: carried by a finding the parent Subagent accepted).
    relation: str = Field(pattern="^(supports|cited)$")
    statement_hash: str = Field(min_length=8)
    reason: str = Field(min_length=8)

    @model_validator(mode="after")
    def _check(self) -> "PriorEvidence":
        if self.statement_hash != _statement_hash(self.statement):
            raise ValueError(
                "prior evidence does not match its own statement; a carried-forward "
                "item must be the record that was reviewed")
        return self

    def check(self) -> "PriorEvidence":
        """Re-assert the invariant for a record that crossed a boundary."""

        return self._check()


def _statement_hash(statement: str) -> str:
    return hashlib.sha256(" ".join(statement.split()).encode("utf-8")).hexdigest()[:16]


class AttemptHistory(StrictModel):
    """One attempt, as it happened: what it was told, what it returned, how it was judged."""

    attempt: int = Field(ge=1)
    task_id: str = ""
    status: EntityStatus
    summary: str = ""
    error: str | None = None
    evidence_ids: list[str] = Field(default_factory=list)
    #: The deficiencies that attempt produced, by dimension/kind.
    deficiencies: list[str] = Field(default_factory=list)
    decision: ReviewDecision | None = None
    fault: WorkflowFault | None = None
    #: Evidence this attempt added on top of what it inherited — never its whole set.
    produced_ids: list[str] = Field(default_factory=list)
    #: The retask it received, if it received one.
    guidance: str = ""
    seconds: float = 0.0


class RetaskFailure(StrictModel):
    """Why a revision could not be produced: refused, not silently skipped."""

    worker_id: str = Field(min_length=1)
    attempt: int = Field(ge=1)
    reason: str = Field(min_length=8)


class RetaskedWorker(StrictModel):
    """The revised assignment one attempt runs under.

    ``objective`` is the Worker's original objective, unchanged: a retask narrows what
    to *do*, it never quietly changes what the unit is for.  :attr:`fingerprint`
    covers the parts that must differ between attempts, so two retasks that differ
    only in wording are detectable as the same instruction — which is exactly the
    failure the acceptance clause is about.
    """

    worker_id: str = Field(min_length=1)
    subagent_id: str = Field(min_length=1)
    work_unit: str = ""
    #: 1-based: this assignment is for the attempt after ``attempt``.
    attempt: int = Field(ge=2)
    objective: str = Field(min_length=1)
    criteria: list[str] = Field(default_factory=list)
    output_schema: str = "TaskResult"
    #: The deficiencies, structurally.
    corrections: list[RetaskItem] = Field(default_factory=list)
    #: What to carry forward, structurally.
    prior_evidence: list[PriorEvidence] = Field(default_factory=list)
    #: What must not be collected, restated: the cost of a second attempt already paid.
    already_collected: list[str] = Field(default_factory=list)
    #: The instruction as the model reads it.  Built by :func:`render_retask_prompt`
    #: and re-attached by :func:`retask_worker`; empty only mid-construction.
    prompt: str = ""
    #: Rendered deficiencies, for a reader who wants them flat.
    deficiencies: list[str] = Field(default_factory=list)
    #: The guidance the graph's own runner verdict carried, kept for provenance.
    guidance: str = ""
    fault: WorkflowFault = WorkflowFault.UNKNOWN
    #: True when the failure was the tool's: the prompt says *try again*, not *do it
    #: differently*, and carries no invented deficiency.
    tool_failure: bool = False
    #: The review that caused this retask.
    because_of: str = Field(min_length=1)
    fingerprint: str = ""

    @field_validator("corrections")
    @classmethod
    def _one_per_dimension(cls, value: list[RetaskItem]) -> list[RetaskItem]:
        seen: list[ReviewDimension] = []
        for item in value:
            if item.dimension in seen:
                raise ValueError(
                    f"two corrections for {item.dimension.value}: one statement of "
                    "the problem per dimension, or the Worker is asked twice")
            seen.append(item.dimension)
        return value

    @field_validator("prior_evidence")
    @classmethod
    def _distinct_prior(cls, value: list[PriorEvidence]) -> list[PriorEvidence]:
        ids = [item.item_id for item in value]
        if len(set(ids)) != len(ids):
            raise ValueError("the same evidence cannot be carried forward twice")
        return [item.check() for item in value]

    @model_validator(mode="after")
    def _coherent(self) -> "RetaskedWorker":
        if self.tool_failure:
            if any(item.kind not in {DeficiencyKind.TOOL_FAILURE, DeficiencyKind.BLOCKED,
                                     DeficiencyKind.UNREVIEWABLE}
                   for item in self.corrections):
                raise ValueError(
                    "a tool failure retask may not carry quality corrections: the "
                    "work was never the problem")
        elif not self.corrections:
            raise ValueError(
                "a quality retask must name at least one deficiency; repeating the "
                "instruction unchanged is a retry, not a retask")
        if self.attempt < 2:
            raise ValueError("a retask is for a second or later attempt")
        return self

    @field_validator("prompt")
    @classmethod
    def _prompt_is_an_instruction(cls, value: str) -> str:
        if value and len(value.strip()) < 40:
            raise ValueError(
                "a retask prompt must state the objective, the deficiencies and the "
                "corrections; a line or two is the same prompt again")
        return value

    @property
    def corrects(self) -> list[str]:
        return [item.dimension.value for item in self.corrections]

    @property
    def carried_ids(self) -> list[str]:
        return [item.item_id for item in self.prior_evidence]

    @property
    def describe(self) -> str:
        cause = "tool" if self.tool_failure else "quality"
        parts = [f"attempt {self.attempt} ({cause})"]
        if self.corrections:
            parts.append(f"correct {len(self.corrections)}: " + ", ".join(self.corrects))
        if self.prior_evidence:
            parts.append(f"carry {len(self.prior_evidence)} item(s)")
        if self.already_collected:
            parts.append(f"do not recollect {len(self.already_collected)}")
        return "; ".join(parts)

    #: Derived keys :meth:`to_dict` adds for a reader.  Declared here so
    #: :meth:`from_dict` can strip exactly what it added, and reloading a record never
    #: depends on remembering which fields were "real".
    DERIVED: ClassVar[tuple[str, ...]] = ("describe", "corrects", "carried_ids")

    def to_dict(self) -> dict[str, Any]:
        return {**json.loads(model_to_json(self)), "describe": self.describe,
                "corrects": self.corrects, "carried_ids": self.carried_ids}

    @classmethod
    def from_dict(cls, payload: Mapping[str, Any]) -> "RetaskedWorker":
        return cls.model_validate(
            {key: value for key, value in payload.items() if key not in cls.DERIVED})


# --------------------------------------------------------------------------
# 35.1 Building the retask from the review, the record and the budget
# --------------------------------------------------------------------------

#: What each deficiency asks of the next attempt.  A correction that could be said of
#: any defect in its dimension is not a correction, so each kind gets its own words.
_CORRECTIONS: dict[DeficiencyKind, str] = {
    DeficiencyKind.TOOL_FAILURE:
        "re-run the same unit: the failure was the tool's, and the work did not run",
    DeficiencyKind.BLOCKED:
        "the block below must be resolved before this unit can run; re-running it "
        "unchanged will fail the same way",
    DeficiencyKind.EMPTY:
        "return at least one sourced item: an empty result cannot be judged, only "
        "withheld",
    DeficiencyKind.INCOMPLETE:
        "answer the completion criteria listed below explicitly, or report the unit as "
        "partial naming the one that could not be met",
    DeficiencyKind.IRRELEVANT:
        "return only observations about this unit's own slice; move the neighbouring "
        "material out of the result",
    DeficiencyKind.WEAK_SOURCE:
        "replace the secondary source with the primary record it summarises; a search "
        "result or a republished copy cannot carry the claim",
    DeficiencyKind.UNSOURCED:
        "attach the source reference for every finding, or drop the finding",
    DeficiencyKind.INCONSISTENT:
        "reconcile the status, the error and the limitations so they agree, and say "
        "which one was wrong",
    DeficiencyKind.OUT_OF_SCOPE:
        "remove or replace every source outside the authorised scope entries below",
    DeficiencyKind.WRONG_SHAPE:
        "return the record in the shape the assignment named, filling the fields the "
        "check below says are missing",
    DeficiencyKind.UNREVIEWABLE:
        "return a result the parent Subagent can judge: a status, evidence and the "
        "limitations that apply",
    DeficiencyKind.UNREVIEWED:
        "return the result through the review gate: a verdict that was not performed "
        "is not a verdict",
}


def correct_for(deficiency: Deficiency) -> str:
    """The instruction one deficiency carries.  Total over the kinds, by construction."""

    return _CORRECTIONS.get(
        deficiency.kind,
        f"address the {deficiency.dimension.value} deficiency and return the unit again")


def _criteria_for(deficiency: Deficiency, criteria: Sequence[str]) -> list[str]:
    """Which of the report's criteria this deficiency is about.

    Matched through the detail, because that is how the reviewer names them; no
    match means no attribution rather than a guess across all of them.
    """

    lowered = deficiency.detail.lower()
    return [criterion for criterion in criteria
            if criterion.lower() in lowered
            or lowered in criterion.lower()
            or _tokens(criterion) & _tokens(deficiency.detail)]



def _faulted_ids(review: QualityReview) -> set[str]:
    """The evidence the review actually faulted — the rest is worth carrying."""

    faulted: set[str] = set()
    for deficiency in review.deficiencies:
        faulted.update(deficiency.evidence_ids)
    return faulted


def carryable_evidence(report: "WorkerReport | None", review: QualityReview, *,
                       inherited: Sequence[str] = ()) -> list[PriorEvidence]:
    """Evidence from the reviewed attempt the next attempt should not collect again.

    Three filters, each for a reason:

    *   **not faulted** — a weak source or an unciteable row is the defect itself;
    *   **cited by an accepted finding, or on no finding at all** — a finding the
        parent Subagent faulted is being redone, and its evidence goes with it;
    *   **not inherited** — evidence the attempt itself received is not new work, and
        re-offering it as prior evidence would launder an earlier failure forward.
    """

    if report is None or not report.usable:
        return []
    faulted = _faulted_ids(review)
    cited_by_faulted: set[str] = set()
    accepted_citations: set[str] = set()
    for finding in report.findings:
        if _finding_faulted(finding, review):
            cited_by_faulted.update(finding.evidence_ids)
        else:
            accepted_citations.update(finding.evidence_ids)
    known = set(inherited)
    carried: list[PriorEvidence] = []
    seen_statements: set[str] = set()
    for item in report.evidence:
        if item.id in faulted or item.id in known:
            continue
        relation = "cited" if item.id in accepted_citations else (
            "supports" if item.id not in cited_by_faulted else "")
        if relation == "cited":
            reason = ("an accepted finding already cites it; re-use it rather than "
                      "re-collecting it")
        elif relation == "supports":
            reason = "collected and sound, but not yet on any finding; it is usable"
            relation = "supports"
        else:
            continue
        statement = _statement_hash(item.statement)
        if statement in seen_statements:
            continue
        seen_statements.add(statement)
        if item.kind.name not in _CARRIABLE_KINDS:
            continue
        carried.append(PriorEvidence(item_id=item.id, statement=item.statement,
                                     relation=relation, statement_hash=statement,
                                     reason=reason))
    return carried


#: Evidence kinds that are a record of something observed.  An inference or an allegation
#: is not carried forward as if it were collected fact (§19's record/claim split), and a
#: retask that did so would launder an earlier conclusion into the next attempt.
_CARRIABLE_KINDS = frozenset({"OBSERVATION"})


def _finding_faulted(finding: Any, review: QualityReview) -> bool:
    """Whether the review faults this finding's evidence.

    The reviewer records what it faulted by evidence id, so a finding is implicated
    when the evidence it cites is.  A relevance or completeness deficiency that names
    no ids is about the result as a whole, not about any one finding.
    """

    faulted = _faulted_ids(review)
    return bool(faulted) and bool(set(finding.evidence_ids) & faulted)


def retask_worker(review: QualityReview, *, report: "WorkerReport | None" = None,
                  attempt: int | None = None, objective: str = "",
                  criteria: Sequence[str] = (), output_schema: str = "TaskResult",
                  subagent_id: str = "", work_unit: str = "",
                  inherited: Sequence[str] = (), guidance: str = "") -> RetaskedWorker:
    """Build the next attempt's assignment from the review that rejected this one.

    Refuses rather than improvises: a revise with nothing to correct gets no retask,
    because sending the same instruction again is the behaviour this section exists to
    prevent.
    """

    if review.decision is not ReviewDecision.REVISE:
        raise ValueError(f"{review.decision.value} does not produce a retask")
    tool_failure = review.fault is WorkflowFault.TOOL
    items: list[RetaskItem] = []
    seen: set[ReviewDimension] = set()
    for deficiency in review.deficiencies:
        if deficiency.dimension in seen:
            # The dimension is stated once; the second detail joins the first, so the
            # Worker reads one instruction per dimension instead of two overlapping ones.
            for existing in items:
                if existing.dimension is deficiency.dimension:
                    existing.detail = f"{existing.detail}; {deficiency.detail}"[:400]
            continue
        seen.add(deficiency.dimension)
        items.append(RetaskItem(
            dimension=deficiency.dimension, kind=deficiency.kind,
            detail=deficiency.detail, correction=correct_for(deficiency),
            criteria=_criteria_for(deficiency, list(criteria))))
    next_attempt = attempt or review.attempt + 1
    carried = carryable_evidence(report, review, inherited=inherited)
    assignment = RetaskedWorker(
        worker_id=review.worker_id, subagent_id=subagent_id or review.subagent_id,
        work_unit=work_unit, attempt=next_attempt,
        objective=objective or review.worker_id, criteria=list(criteria),
        output_schema=output_schema, corrections=items, prior_evidence=carried,
        already_collected=[item.item_id for item in carried],
        guidance=guidance or review.guidance, fault=review.fault,
        tool_failure=tool_failure,
        because_of=f"{review.decision.value} on attempt {review.attempt} "
                   f"({review.describe()[:120]})",
        prompt="", deficiencies=[item.describe for item in review.deficiencies])
    return assignment.model_copy(update={"prompt": render_retask_prompt(assignment),
                                         "fingerprint": retask_fingerprint(assignment)})


def review_from_verdict(verdict: "ReviewVerdict", *, worker_id: str, subagent_id: str,
                        attempt: int, worker_status: WorkerStatus,
                        path: str = "runner") -> QualityReview:
    """A revise built from the runner's own verdict, for the retask it must produce.

    The seven dimensions are the *Subagent's* judgement (§34) and a verdict is the
    graph's, and they can disagree: a Worker can return a shape-correct, sourced report
    and still fail the Subagent's own research criteria.  When that happens the retry
    still has to be a retask, so the verdict's findings are carried into the same
    structure — as completeness deficiencies, because what the verdict judges is
    whether the attempt met its criteria — rather than the retry falling back to the
    one-line guidance the section exists to replace.
    """

    findings = [finding for finding in verdict.findings if len(finding.strip()) >= 12]
    if not findings:
        findings = [f"the Subagent rejected the attempt: {verdict.verdict}"]
    deficiencies = [
        Deficiency(dimension=ReviewDimension.COMPLETENESS, kind=DeficiencyKind.INCOMPLETE,
                   detail=finding[:300],
                   fix="answer this criterion explicitly in the next attempt")
        for finding in findings]
    return QualityReview(
        worker_id=worker_id, subagent_id=subagent_id, attempt=attempt,
        worker_status=worker_status, decision=ReviewDecision.REVISE,
        checks=[DimensionResult(dimension=dimension) for dimension in REVIEW_DIMENSIONS
                if dimension is not ReviewDimension.COMPLETENESS]
        + [DimensionResult(dimension=ReviewDimension.COMPLETENESS,
                           deficiencies=deficiencies)],
        checked=list(REVIEW_DIMENSIONS), deficiencies=deficiencies,
        guidance=(verdict.guidance or findings[0])[:300], retry=True, path=path)


def render_retask_prompt(assignment: RetaskedWorker) -> str:
    """The instruction the next attempt receives.  Every line is a reason to act.

    Deliberately shaped like a brief rather than a scolding: what the unit is for, what
    was wrong, what to do about it, what is already in hand, and what not to spend on
    again.  A Worker given only "try harder" learns nothing from the first attempt.
    """

    lines = [
        f"RETASK — attempt {assignment.attempt} of unit {assignment.work_unit or assignment.worker_id}",
        "",
        f"ORIGINAL OBJECTIVE (unchanged): {assignment.objective}",
    ]
    if assignment.criteria:
        lines += ["ORIGINAL COMPLETION CRITERIA:"] + [
            f"  - {criterion}" for criterion in assignment.criteria]
    lines += ["", "WHY THE LAST ATTEMPT WAS NOT ACCEPTED: " + assignment.because_of, ""]
    if assignment.corrections:
        lines.append("WHAT MUST CHANGE (each line is a blocking deficiency):")
        for index, item in enumerate(assignment.corrections, start=1):
            lines.append(f"  {index}. [{item.dimension.value}/{item.kind.value}] {item.detail}")
            lines.append(f"     -> {item.correction}")
            if item.criteria:
                lines += [f"     criterion: {criterion}" for criterion in item.criteria]
    if assignment.tool_failure:
        lines.append("This was a tool failure, not a quality failure: the work was never "
                     "judged. Re-run it unchanged; do not rewrite what already succeeded.")
    if assignment.prior_evidence:
        lines += ["", "EVIDENCE YOU ALREADY HAVE (do not collect it again):"]
        for item in assignment.prior_evidence:
            lines.append(f"  - {item.item_id}: {item.statement[:180]} — {item.reason}")
    else:
        # Silence would be read as "there was nothing worth keeping".  Say which it is:
        # the last attempt was thrown away, so this one starts from nothing.
        lines += ["", "EVIDENCE YOU ALREADY HAVE: none — nothing from the last attempt "
                      "survived review, so collect this unit from the start."]
    if assignment.already_collected:
        lines += [
            "",
            "DO NOT RE-COLLECT: " + ", ".join(assignment.already_collected),
            "Return only what is new, plus these items re-cited by their existing ids.",
        ]
    lines += ["", f"OUTPUT SHAPE: {assignment.output_schema}"]
    return "\n".join(lines)


def retask_fingerprint(assignment: RetaskedWorker) -> str:
    """A digest of the parts that make this instruction different from the last one.

    Not the prompt's words: a re-worded version of the same instruction is the same
    instruction, and the point of the fingerprint is to catch exactly that.
    """

    payload = {
        "worker": assignment.worker_id,
        "corrects": [[item.dimension.value, item.kind.value, item.correction]
                     for item in assignment.corrections],
        "schema": assignment.output_schema,
        "fault": assignment.fault.value,
    }
    return content_id("retask", payload, length=12)


#: How two attempts compare.  A revise that changed nothing is not a revision.
RETASK_COMPARISON_KEYS: tuple[str, ...] = (
    "objective", "corrects", "corrections", "carried_ids", "output_schema", "attempt")


def compare_retasks(before: RetaskedWorker | None, after: RetaskedWorker) -> dict[str, Any]:
    """Which fields moved between two retasks — and whether any of the substance did."""

    if before is None:
        return {"attempt": before, "changed": True, "fields": list(RETASK_COMPARISON_KEYS),
                "substantive": True, "same_fingerprint": False}
    fields = [key for key in RETASK_COMPARISON_KEYS
              if _comparable(getattr(before, key)) != _comparable(getattr(after, key))]
    substantive = bool({"corrects", "corrections", "carried_ids"} & set(fields))
    return {"attempt": after.attempt, "fields": fields, "changed": bool(fields),
            "substantive": substantive,
            "same_fingerprint": before.fingerprint == after.fingerprint}


def _comparable(value: Any) -> Any:
    if isinstance(value, list):
        return [str(item) for item in value]
    return str(value)


def retask_repeats(before: RetaskedWorker | None, after: RetaskedWorker) -> bool:
    """True when two attempts would be given the same instruction twice."""

    return before is not None and before.fingerprint == after.fingerprint


# --------------------------------------------------------------------------
# 35.2 The budget: the retry limit, read rather than re-derived
# --------------------------------------------------------------------------

class RetryBudget(StrictModel):
    """How many attempts one unit gets, and where that number came from.

    Two limits exist and both bind: the Worker's own ``max_attempts`` (§from the plan)
    and the Subagent's :class:`ReviewPolicy`.  The effective limit is the smaller, and
    it is recorded with its source so a mission can *show* why a third attempt did not
    happen instead of stopping unexplained.
    """

    worker_id: str = Field(min_length=1)
    max_attempts: int = Field(default=2, ge=1, le=10)
    max_revisions: int = Field(default=2, ge=0, le=10)
    #: ``worker``, ``policy`` or ``tool``: which ceiling binds, and why.
    source: str = Field(pattern="^(worker|policy|tool)$")

    @property
    def limit(self) -> int:
        return min(self.max_attempts, self.max_revisions + 1)


def retry_budget(worker: "FlowWorker", *, policy: ReviewPolicy,
                 tool_failure: bool = False) -> RetryBudget:
    """The effective attempt budget for one unit, and the ceiling that sets it."""

    if tool_failure and not policy.retry_tool_failures:
        return RetryBudget(worker_id=worker.id, max_attempts=worker.max_attempts,
                           max_revisions=policy.max_revisions, source="tool")
    limit_from_worker = worker.max_attempts
    limit_from_policy = policy.max_revisions + 1
    source = "worker" if limit_from_worker <= limit_from_policy else "policy"
    return RetryBudget(worker_id=worker.id, max_attempts=worker.max_attempts,
                       max_revisions=policy.max_revisions, source=source)


# --------------------------------------------------------------------------
# 35.3 History: the retasks, and the status a spent budget leaves behind
# --------------------------------------------------------------------------

class RetaskLedger(StrictModel):
    """Every retask and every attempt for one unit, in order.

    ``history`` is append-only: a revision that overwrote the previous assignment would
    destroy the record of what the Worker was told, which is the only thing that makes
    "the retry prompt was observably specific" checkable after the fact.
    """

    worker_id: str = Field(min_length=1)
    objective: str = ""
    retasks: list[RetaskedWorker] = Field(default_factory=list)
    attempts: list[AttemptHistory] = Field(default_factory=list)
    budget: RetryBudget | None = None
    #: Deficiencies that no attempt resolved, when the budget ran out.
    unresolved: list[str] = Field(default_factory=list)
    final_status: EntityStatus | None = None

    @model_validator(mode="after")
    def _ordered(self) -> "RetaskLedger":
        attempts = [attempt.attempt for attempt in self.attempts]
        if attempts != sorted(set(attempts)):
            raise ValueError("attempt history must be ordered and free of duplicates")
        targets = [retask.attempt for retask in self.retasks]
        if targets != sorted(set(targets)):
            raise ValueError("retasks must be ordered and free of duplicates")
        return self

    @property
    def retries(self) -> int:
        return max(0, len(self.attempts) - 1)

    @property
    def exhausted(self) -> bool:
        """Whether the budget is spent — the fact that decides partial versus retry."""

        return self.budget is not None and len(self.attempts) >= self.budget.limit

    def latest(self) -> RetaskedWorker | None:
        return self.retasks[-1] if self.retasks else None

    def for_attempt(self, attempt: int) -> RetaskedWorker | None:
        return next((retask for retask in self.retasks if retask.attempt == attempt), None)

    def repeated(self) -> list[int]:
        """Attempts that were handed an instruction identical to the one before."""

        repeats: list[int] = []
        for index, retask in enumerate(self.retasks):
            if index and retask.fingerprint == self.retasks[index - 1].fingerprint:
                repeats.append(retask.attempt)
        return repeats

    def summary(self) -> dict[str, Any]:
        return {"worker": self.worker_id, "attempts": len(self.attempts),
                "retasks": len(self.retasks),
                "limit": self.budget.limit if self.budget else None,
                "exhausted": self.exhausted,
                "repeated_instructions": self.repeated(),
                "unresolved": list(self.unresolved),
                "final_status": self.final_status.value if self.final_status else None}


def attempt_record(outcome: "WorkerOutcome", review: QualityReview, *,
                   retask: RetaskedWorker | None = None,
                   inherited: Sequence[str] = ()) -> AttemptHistory:
    """One attempt as history: what it returned, how it was judged, what it added."""

    report = _report_of(outcome)
    evidence_ids = list(report.evidence_ids) if report is not None else list(
        outcome.evidence_ids)
    inherited_ids = set(inherited)
    return AttemptHistory(
        attempt=outcome.attempt, task_id=outcome.task_id, status=outcome.status,
        summary=outcome.summary, error=outcome.error, evidence_ids=evidence_ids,
        deficiencies=[f"{item.dimension.value}/{item.kind.value}"
                      for item in review.deficiencies]
        if review.attempt == outcome.attempt else [],
        decision=review.decision if review.attempt == outcome.attempt else None,
        fault=review.fault if review.attempt == outcome.attempt else None,
        produced_ids=[item for item in evidence_ids if item not in inherited_ids],
        guidance=retask.prompt if retask is not None else "",
        seconds=round(outcome.seconds, 3))


def retask_ledger(worker: "FlowWorker", entries: Sequence[tuple["WorkerOutcome",
                                                                QualityReview]],
                  *, policy: ReviewPolicy | None = None,
                  assignments: Sequence[RetaskedWorker] = (),
                  inherited: Sequence[str] = ()) -> RetaskLedger:
    """Assemble one unit's history from the attempts that actually happened."""

    agreed = policy or ReviewPolicy()
    retasks = sorted(assignments, key=lambda retask: retask.attempt)
    by_attempt = {retask.attempt: retask for retask in retasks}
    attempts = [
        attempt_record(outcome, review, retask=by_attempt.get(outcome.attempt),
                       # Only an attempt after a retask inherited anything: the first
                       # one was given the assignment, not a head start.
                       inherited=inherited if outcome.attempt > 1 else ())
        for outcome, review in entries]
    tool_failure = bool(entries) and entries[-1][1].fault is WorkflowFault.TOOL
    budget = retry_budget(worker, policy=agreed, tool_failure=tool_failure)
    return RetaskLedger(worker_id=worker.id, objective=worker.objective,
                        retasks=retasks, attempts=attempts, budget=budget)


def exhausted_outcome(worker: "FlowWorker", *, entries: Sequence[tuple["WorkerOutcome",
                                                                     QualityReview]],
                      policy: ReviewPolicy | None = None,
                      inherited: Sequence[str] = (),
                      status: EntityStatus | None = None) -> tuple[
                          "WorkerOutcome", RetaskLedger]:
    """What one unit returns when its retry budget is spent.

    The acceptance clause's second half: **stop at the limit** and return a partial or
    blocked status that still names what is unresolved.  The earlier attempts' evidence
    is carried into the final report — an exhausted unit is not an empty one — and the
    status says which of the two honest labels applies: ``partial`` when it produced
    usable work, ``blocked`` when it produced none.
    """

    ledger = retask_ledger(worker, entries, policy=policy, inherited=inherited)
    unresolved = [f"{item.dimension.value}/{item.kind.value}: {item.detail}"
                  for item in entries[-1][1].deficiencies] if entries else []
    last = entries[-1][0] if entries else None
    # A unit with no attempts at all still has a parent: the report has to say which
    # Subagent's budget it exhausted, and the Worker's id is the only other fact here.
    subagent_id = (last.subagent_id if last and last.subagent_id
                   else worker.id)

    # What the exhausted unit still has is the reports its attempts produced: the
    # same evidence, with the same provenance, restated at the status that honours
    # what is missing.  An attempt whose own report was unusable contributes nothing,
    # which is how "partial" and "blocked" come to differ without being guessed.
    evidence: list[EvidenceItem] = []
    for outcome, _review in entries:
        entry_report = _report_of(outcome)
        if entry_report is None or not entry_report.usable:
            continue
        known = {seen.id for seen in evidence}
        evidence.extend(item for item in entry_report.evidence if item.id not in known)
    final = status or (EntityStatus.BLOCKED if evidence else EntityStatus.FAILED)
    ledger = ledger.model_copy(update={"unresolved": unresolved, "final_status": final})
    report = report_from_evidence(
        worker.id, subagent_id,
        status=(WorkerStatus.PARTIAL if evidence else WorkerStatus.FAILED),
        evidence=evidence,
        findings=[WorkerFinding(statement=f"{worker.name}: attempt {attempt.attempt} "
                                          f"returned evidence that no review accepted",
                                evidence_ids=[row.id for row in evidence
                                              if row.id in attempt.produced_ids])
                  for attempt in ledger.attempts
                  if attempt.decision is not ReviewDecision.PASS
                  and any(row.id in attempt.produced_ids for row in evidence)],
        summary=(f"{worker.name}: {len(entries)} attempt(s) spent the "
                 f"{ledger.budget.limit if ledger.budget else 0}-attempt budget with "
                 f"{len(unresolved)} deficiency(ies) unresolved"),
        limitations=unresolved or ["the unit never produced a reviewable attempt"],
        task_id=content_id("task", worker.id, "exhausted", len(entries)),
        attempt=len(entries) or 1,
        error=ErrorInfo(code="retry-exhausted",
                        message="retry budget exhausted: "
                                + ("; ".join(unresolved[:3]) if unresolved
                                   else "no attempt was reviewable"),
                        stage="review", component=worker.id,
                        attempt=len(entries) or 1),
    )
    outcome = outcome_from_report(report, gate=FlowGate.RETRY_EXHAUSTED).model_copy(
        update={"status": final})
    return outcome, ledger


# --------------------------------------------------------------------------
# 35.4 Scripted retasks: an accepted attempt, a revised one, a spent budget
# --------------------------------------------------------------------------

def _retask_worker_spec(index: int = 1, **overrides: Any) -> "FlowWorker":
    """A Worker to retask: a real FlowWorker, with the fields the retask reads."""

    payload: dict[str, Any] = {
        "id": f"wrk-retask-{index}", "name": f"retask-demo-{index}",
        "objective": "correlate each proxy CONNECT with the resolver query that caused it",
        "work_unit": "proxy correlation",
        "completion_criteria": [
            "every CONNECT is paired with the resolver query that precedes it",
            "each pair cites the log lines it came from",
        ],
        "expected_evidence": "≥2 observation item(s) from ≥2 source(s)",
        "output_schema": "CorrelationTable",
        "max_attempts": 3,
    }
    payload.update(overrides)
    return FlowWorker(**payload)


def _retask_source(name: str, kind: SourceKind, *, path: str | None = None,
                   method: RetrievalMethod = RetrievalMethod.LOCAL_READ) -> SourceReference:
    return SourceReference(kind=kind, artifact_path=path, title=name,
                           retrieved_at=utc_now(), retrieval_method=method,
                           excerpt=f"{name} excerpt")


def _retask_attempt_one() -> tuple["WorkerOutcome", QualityReview, "FlowWorker"]:
    """A first attempt that got half the job done: two sound rows, one weak source."""

    worker = _retask_worker_spec()
    log = _retask_source("resolver log", SourceKind.LOG_FILE, path="/evidence/dns.log")
    proxy = _retask_source("proxy log", SourceKind.LOG_FILE, path="/evidence/proxy.log")
    search = _retask_source("search result", SourceKind.SEARCH_ENGINE,
                            path="/evidence/cached.html")
    evidence = [
        EvidenceItem(kind=EvidenceKind.OBSERVATION,
                     statement="the CONNECT to evil.example.org at 10:00:00Z follows the "
                               "resolver query at 09:59:58Z",
                     sources=[proxy, log], confidence=Confidence.LOW,
                     confidence_basis="two log lines read in order",
                     collected_by=worker.id, observed_at=utc_now()),
        EvidenceItem(kind=EvidenceKind.OBSERVATION,
                     statement="the resolver query for evil.example.org at 09:59:58Z came "
                               "from host-07",
                     sources=[log], confidence=Confidence.LOW,
                     confidence_basis="one log line",
                     collected_by=worker.id, observed_at=utc_now()),
        EvidenceItem(kind=EvidenceKind.OBSERVATION,
                     statement="a search summary says host-07 is the office gateway",
                     sources=[search], confidence=Confidence.LOW,
                     confidence_basis="one retrieval of a secondary source",
                     collected_by=worker.id, observed_at=utc_now()),
    ]
    findings = [
        WorkerFinding(statement="the CONNECT follows the resolver query by two seconds",
                      evidence_ids=[evidence[0].id]),
        WorkerFinding(statement="host-07 issued the query",
                      evidence_ids=[evidence[1].id]),
        WorkerFinding(statement="host-07 is the office gateway",
                      evidence_ids=[evidence[2].id]),
    ]
    report = report_from_evidence(
        worker.id, "sa-retask", status=WorkerStatus.COMPLETED, evidence=evidence,
        findings=findings, summary="paired one CONNECT and identified the host",
        task_id="task-retask-1", attempt=1)
    outcome = outcome_from_report(report)
    # The review the parent Subagent would actually write for that result.
    review = QualityReview(
        worker_id=worker.id, subagent_id="sa-retask", task_id=outcome.task_id,
        attempt=1, worker_status=WorkerStatus.COMPLETED,
        decision=ReviewDecision.REVISE,
        checks=[DimensionResult(dimension=dimension) for dimension in REVIEW_DIMENSIONS
                if dimension is not ReviewDimension.SOURCE_QUALITY]
        + [DimensionResult(dimension=ReviewDimension.SOURCE_QUALITY, deficiencies=[
            Deficiency(dimension=ReviewDimension.SOURCE_QUALITY,
                       kind=DeficiencyKind.WEAK_SOURCE,
                       detail="the gateway claim rests on a search summary, not the "
                              "inventory record",
                       evidence_ids=[evidence[2].id],
                       fix="cite the inventory record for host-07")])],
        checked=list(REVIEW_DIMENSIONS),
        deficiencies=[Deficiency(dimension=ReviewDimension.SOURCE_QUALITY,
                                 kind=DeficiencyKind.WEAK_SOURCE,
                                 detail="the gateway claim rests on a search summary, "
                                        "not the inventory record",
                                 evidence_ids=[evidence[2].id],
                                 fix="cite the inventory record for host-07")],
        guidance="cite the inventory record for host-07 instead of a search summary",
        retry=True, path="runner")
    return outcome, review, worker


def _retask_second_attempt(worker: "FlowWorker", retask: RetaskedWorker) -> tuple[
        "WorkerOutcome", QualityReview]:
    """The attempt the retask produced: it re-cites what it had and adds the inventory row.

    The evidence it already held keeps its ids — that is what "not duplicated" means in
    practice: the second attempt returns three items, not five, because the two it
    inherited are cited rather than collected again.
    """

    inventory = _retask_source("inventory export", SourceKind.LOCAL_ARTIFACT,
                               path="/evidence/inventory.csv")
    carried = [
        EvidenceItem(kind=EvidenceKind.OBSERVATION,
                     statement="the CONNECT to evil.example.org at 10:00:00Z follows the "
                               "resolver query at 09:59:58Z",
                     sources=[_retask_source("proxy log", SourceKind.LOG_FILE,
                                             path="/evidence/proxy.log")],
                     confidence=Confidence.MEDIUM,
                     confidence_basis="two corroborating log lines, re-read",
                     collected_by=worker.id, observed_at=utc_now()),
        EvidenceItem(kind=EvidenceKind.OBSERVATION,
                     statement="the resolver query for evil.example.org at 09:59:58Z came "
                               "from host-07",
                     sources=[_retask_source("resolver log", SourceKind.LOG_FILE,
                                             path="/evidence/dns.log")],
                     confidence=Confidence.MEDIUM,
                     confidence_basis="one log line, corroborated by the inventory",
                     collected_by=worker.id, observed_at=utc_now()),
    ]
    added = EvidenceItem(kind=EvidenceKind.OBSERVATION,
                         statement="the inventory export lists host-07 as the office gateway",
                         sources=[inventory], confidence=Confidence.HIGH,
                         confidence_basis="the authoritative inventory record",
                         collected_by=worker.id, observed_at=utc_now())
    evidence = [*carried, added]
    report = report_from_evidence(
        worker.id, "sa-retask", status=WorkerStatus.COMPLETED, evidence=evidence,
        findings=[WorkerFinding(statement="host-07 issued the query and is the gateway",
                                evidence_ids=[carried[1].id, added.id])],
        summary="re-cited the two accepted rows and added the inventory record",
        task_id="task-retask-2", attempt=2)
    outcome = outcome_from_report(report)
    review = QualityReview(
        worker_id=worker.id, subagent_id="sa-retask", task_id=outcome.task_id,
        attempt=2, worker_status=WorkerStatus.COMPLETED,
        decision=ReviewDecision.PASS,
        checks=[DimensionResult(dimension=dimension) for dimension in REVIEW_DIMENSIONS],
        checked=list(REVIEW_DIMENSIONS), path="runner",
        guidance="")
    return outcome, review


def retask_demo_cases() -> dict[str, Any]:
    """Three units: the retask that worked, the retask that repeated, the spent budget."""

    outcome_one, review_one, worker = _retask_attempt_one()
    first = retask_worker(
        review_one, report=report_from_outcome(outcome_one), attempt=2,
        objective=worker.objective, criteria=worker.completion_criteria,
        output_schema=worker.output_schema, subagent_id="sa-retask",
        work_unit=worker.work_unit, guidance=review_one.guidance)
    outcome_two, review_two = _retask_second_attempt(worker, first)

    # A second revise that finds exactly what the first did: the same complaint, a new
    # attempt number.  This is the failure mode the task names — a retry in place of a
    # retask — and the fingerprint is what makes it visible.
    repeat_review = review_one.model_copy(update={"attempt": 2, "task_id": "task-retask-2"})
    repeated = retask_worker(repeat_review, report=report_from_outcome(outcome_one),
                             attempt=3, objective=worker.objective,
                             criteria=worker.completion_criteria,
                             output_schema=worker.output_schema, subagent_id="sa-retask",
                             work_unit=worker.work_unit)

    # A unit that never passes: three attempts, one unresolved deficiency each time.
    stuck_worker = _retask_worker_spec(2, max_attempts=2)
    stuck_entries: list[tuple["WorkerOutcome", QualityReview]] = []
    for attempt in (1, 2):
        line = EvidenceItem(
            kind=EvidenceKind.OBSERVATION,
            statement=f"attempt {attempt}: the CONNECT at 10:00:00Z has no matching query",
            sources=[_retask_source("proxy log", SourceKind.LOG_FILE,
                                    path="/evidence/proxy.log")],
            confidence=Confidence.LOW, confidence_basis="one log line read",
            collected_by=stuck_worker.id, observed_at=utc_now())
        report = report_from_evidence(
            stuck_worker.id, "sa-retask", status=WorkerStatus.COMPLETED,
            evidence=[line],
            findings=[WorkerFinding(statement="the CONNECT has no matching query",
                                    evidence_ids=[line.id])],
            summary=f"attempt {attempt}: no query matched the CONNECT",
            task_id=f"task-stuck-{attempt}", attempt=attempt)
        outcome = outcome_from_report(report)
        stuck_entries.append((outcome, QualityReview(
            worker_id=stuck_worker.id, subagent_id="sa-retask",
            task_id=outcome.task_id, attempt=attempt,
            worker_status=WorkerStatus.COMPLETED, decision=ReviewDecision.REVISE,
            checks=[DimensionResult(dimension=dimension) for dimension in REVIEW_DIMENSIONS
                    if dimension is not ReviewDimension.COMPLETENESS]
            + [DimensionResult(dimension=ReviewDimension.COMPLETENESS, deficiencies=[
                Deficiency(dimension=ReviewDimension.COMPLETENESS,
                           kind=DeficiencyKind.INCOMPLETE,
                           detail="no CONNECT is paired with the resolver query that "
                                  "precedes it",
                           fix="pair at least one CONNECT, or report the unit partial")])],
            checked=list(REVIEW_DIMENSIONS),
            deficiencies=[Deficiency(dimension=ReviewDimension.COMPLETENESS,
                                     kind=DeficiencyKind.INCOMPLETE,
                                     detail="no CONNECT is paired with the resolver query "
                                            "that precedes it",
                                     fix="pair at least one CONNECT, or report partial")],
            guidance="pair at least one CONNECT with the query before it",
            retry=True, path="runner")))
    spent_outcome, spent_ledger = exhausted_outcome(
        stuck_worker, entries=stuck_entries, policy=ReviewPolicy(max_revisions=1))

    ledger = retask_ledger(worker, [(outcome_one, review_one), (outcome_two, review_two)],
                           policy=ReviewPolicy(max_revisions=2), assignments=[first])
    return {
        "worker": worker,
        "attempts": (outcome_one, outcome_two),
        "reviews": (review_one, review_two),
        "retask": first,
        "repeated": repeated,
        "comparison": compare_retasks(first, repeated),
        "first_instruction": revision_directive(review_one),
        "ledger": ledger,
        "stuck": spent_ledger,
        "stuck_result": spent_outcome,
        "stuck_worker": stuck_worker,
    }


def _retask_payload(cases: Mapping[str, Any]) -> dict[str, Any]:
    """The demo, serialised: what a reader or a test consumes."""

    first: RetaskedWorker = cases["retask"]
    return {
        "objective": first.objective,
        "retask": first.to_dict(),
        "prompt": first.prompt,
        "prior_evidence": [item.model_dump(mode="json") for item in first.prior_evidence],
        "comparison": cases["comparison"],
        "repeated": cases["repeated"].to_dict(),
        "first_instruction": cases["first_instruction"].model_dump(mode="json"),
        "ledger": cases["ledger"].summary(),
        "budget": cases["ledger"].budget.model_dump(mode="json"),
        "stuck": cases["stuck"].summary(),
        "stuck_result": json.loads(model_to_json(cases["stuck_result"])),
        "attempts": [
            {"attempt": attempt.attempt, "status": attempt.status.value,
             "produced": len(attempt.produced_ids), "decision": attempt.decision.value
             if attempt.decision else None,
             "deficiencies": attempt.deficiencies}
            for attempt in cases["ledger"].attempts],
    }


def retask_quality_demo() -> dict[str, Any]:
    """The retasking demo as the CLI prints and ``--json`` exports it."""

    cases = retask_demo_cases()
    payload = _retask_payload(cases)
    payload["contrast"] = task_contrast(cases["first_instruction"], cases["retask"])
    specificity = retask_specificity(cases["retask"])
    payload["acceptance"] = {
        "specific": specificity["specific"],
        "signals": specificity["signals"],
        "counts_enforced": cases["stuck"].exhausted,
        "limit": cases["stuck"].budget.limit if cases["stuck"].budget else None,
        "attempts": len(cases["stuck"].attempts),
        "history": len(cases["ledger"].retasks) + len(cases["ledger"].attempts),
        "unresolved": list(cases["stuck"].unresolved),
        "repeated": cases["ledger"].repeated(),
        "duplicate_prompt": retask_repeats(cases["retask"], cases["repeated"]),
    }
    return payload


# --------------------------------------------------------------------------
# 35.5 Observability: is this retask specific, and is it different?
# --------------------------------------------------------------------------

#: Words that make an instruction look specific without saying anything.  A retask
#: containing only these is the same prompt in a new envelope.
VAGUE_PHRASES: tuple[str, ...] = (
    "try again", "do better", "be more careful", "improve quality", "retry",
    "review the result", "make sure", "ensure quality", "fix the issues",
    "address the deficiencies", "follow the instructions",
)


def retask_specificity(retask: RetaskedWorker) -> dict[str, Any]:
    """Whether this instruction could be acted on by someone who never saw the review.

    Five things count, and each is a field rather than an opinion: the objective is
    restated, the deficiencies are quoted, each carries a correction, the earlier
    evidence is listed, and the prompt refuses vague-only vocabulary.
    """

    prompt = retask.prompt.lower()
    vague_only = all(
        phrase in prompt for phrase in ("try again",)) and not retask.corrections
    signals = {
        "restates_objective": bool(retask.objective)
        and retask.objective.strip() in retask.prompt,
        "quotes_deficiencies": bool(retask.corrections) and all(
            item.detail[:40] in retask.prompt for item in retask.corrections),
        "gives_corrections": bool(retask.corrections) and all(
            len(item.correction) >= 20 for item in retask.corrections),
        # Either the items are listed or the prompt says there were none: both are
        # specific, and a silent omission is neither.
        "carries_prior_evidence": bool(retask.prior_evidence)
        or "EVIDENCE YOU ALREADY HAVE: none" in retask.prompt,
        "names_output_shape": retask.output_schema.lower() in prompt,
        "not_vague_only": not vague_only,
    }
    return {"signals": signals, "score": sum(signals.values()),
            "specific": all(signals.values()), "vague_only": vague_only}


def task_contrast(directive: RevisionDirective, retask: RetaskedWorker) -> dict[str, Any]:
    """The one-line instruction of §34 beside the assignment rebuilt from it."""

    return {
        "directive": {"instruction": directive.instruction,
                      "because": list(directive.because),
                      "chars": len(directive.instruction)},
        "retask": {"objective": retask.objective,
                   "corrections": [item.describe for item in retask.corrections],
                   "carry": retask.carried_ids, "chars": len(retask.prompt),
                   "attempt": retask.attempt},
        "specificity": retask_specificity(retask),
        "difference": compare_retasks(None, retask),
    }


# --------------------------------------------------------------------------
# 35.6 Self-test — the acceptance clause, as executable checks
# --------------------------------------------------------------------------

def run_retask_self_test() -> list[ReviewCheck]:
    """Prove the retasking contract.

    The acceptance clause names three properties, and they are groups 4, 5 and 6:
    retry prompts are observably specific, retry counts are enforced, and earlier
    evidence is not duplicated unnecessarily.
    """

    checks: list[ReviewCheck] = []
    add = checks.append
    cases = retask_demo_cases()
    worker: FlowWorker = cases["worker"]
    retask: RetaskedWorker = cases["retask"]
    first_outcome, second_outcome = cases["attempts"]
    first_review, second_review = cases["reviews"]

    # ---- 1. the retask exists, and says what it is ----------------------
    add(_rc("a revise produces a revised assignment", isinstance(retask, RetaskedWorker)))
    add(_rc("the assignment carries the original objective",
            retask.objective == worker.objective, retask.objective[:60]))
    add(_rc("it is for the attempt after the one that failed", retask.attempt == 2,
            retask.attempt))
    add(_rc("it keeps the unit's own criteria and shape",
            retask.criteria == worker.completion_criteria
            and retask.output_schema == worker.output_schema))
    add(_rc("it names the review that caused it", bool(retask.because_of),
            retask.because_of[:80]))
    add(_rc("it records the fault it was written for",
            retask.fault is WorkflowFault.WORKER, retask.fault))

    # ---- 2. the exact deficiencies, and a correction for each -----------
    add(_rc("every deficiency of the review is carried, verbatim",
            [item.detail for item in retask.corrections]
            == [item.detail for item in first_review.deficiencies],
            [item.detail[:50] for item in retask.corrections]))
    add(_rc("every deficiency is also on the flat record",
            retask.deficiencies == [item.describe for item in first_review.deficiencies]))
    add(_rc("each deficiency gets a correction of its own",
            all(item.correction and item.correction != item.detail
                for item in retask.corrections)))
    add(_rc("the correction names what to do, not just what was wrong",
            all(len(item.correction) >= 20 for item in retask.corrections),
            [item.correction[:40] for item in retask.corrections]))
    add(_rc("two deficiencies in one dimension are merged, not duplicated",
            len({item.dimension for item in retask.corrections})
            == len(retask.corrections)))
    add(_rc("every deficiency kind has a correction",
            all(correct_for(Deficiency(
                dimension=ReviewDimension.COMPLETENESS, kind=kind,
                detail="a specific deficiency of the required length",
                fix="apply the correction this kind carries"))
                for kind in DeficiencyKind)))

    # ---- 3. the relevant prior evidence, and only that -------------------
    add(_rc("the attempt's sound evidence is carried forward",
            len(retask.prior_evidence) == 2, retask.carried_ids))
    add(_rc("the item the review faulted is not carried",
            not ({item.id for item in report_from_outcome(first_outcome).evidence
                  if item.statement.startswith("a search summary")} & set(retask.carried_ids)),
            retask.carried_ids))
    add(_rc("each carried item says why it is worth carrying",
            all(len(item.reason) >= 20 for item in retask.prior_evidence)))
    add(_rc("each carried item is the record that was reviewed",
            all(item.check() and item.statement_hash == _statement_hash(item.statement)
                for item in retask.prior_evidence)))
    add(_rc("a carried item cannot be attached to a different statement",
            bool(_refuses(lambda: PriorEvidence(
                item_id="ev-x", statement="the original statement",
                relation="cited", statement_hash="0" * 16,
                reason="it was reviewed and was not faulted"))[0])))
    add(_rc("evidence the attempt itself inherited is not carried again",
            not ({i.item_id for i in carryable_evidence(
                report_from_outcome(first_outcome), first_review,
                inherited=[item.id for item in report_from_outcome(first_outcome).evidence])}
                & set(retask.carried_ids))))
    add(_rc("an inference is not carried forward as if it were collected",
            carryable_evidence(
                report_from_evidence(
                    "wrk-x", "sa-x", status=WorkerStatus.PARTIAL,
                    evidence=[EvidenceItem(
                        kind=EvidenceKind.INFERENCE,
                        statement="the write was probably made by the updater",
                        sources=[_retask_source("log", SourceKind.LOG_FILE,
                                                path="/evidence/log")],
                        confidence=Confidence.LOW, confidence_basis="one log line",
                        reasoning="the timestamp falls inside the updater's window")],
                    findings=[], limitations=["only one log line survived"]),
                first_review) == []))
    add(_rc("a failed attempt carries nothing forward",
            carryable_evidence(report_from_outcome(WorkerOutcome(
                worker_id="wrk-x", subagent_id="sa-x", status=EntityStatus.FAILED,
                attempt=1, gate=FlowGate.ERROR, summary="the tool broke",
                error="unexpected end of pcap record")), first_review) == []))

    # ---- 4. retry prompts are observably specific -----------------------
    specificity = retask_specificity(retask)
    add(_rc("the retask scores specific on every signal", specificity["specific"],
            specificity["signals"]))
    add(_rc("the prompt restates the objective it is revising",
            retask.objective in retask.prompt))
    add(_rc("the prompt quotes the deficiency, not a summary of it",
            all(item.detail[:40] in retask.prompt for item in retask.corrections)))
    add(_rc("the prompt carries the correction, not just the complaint",
            all(item.correction[:40] in retask.prompt for item in retask.corrections)))
    add(_rc("the prompt names the evidence already in hand",
            all(item.item_id in retask.prompt for item in retask.prior_evidence)))
    add(_rc("the prompt names the output shape", retask.output_schema in retask.prompt))
    add(_rc("the prompt says what not to collect again",
            "DO NOT RE-COLLECT" in retask.prompt))
    # A revise whose evidence was all thrown away says so, rather than going quiet.
    bare = retask_worker(first_review, report=None, attempt=2,
                         objective=worker.objective, criteria=worker.completion_criteria,
                         output_schema=worker.output_schema, subagent_id="sa-retask")
    add(_rc("a retask with nothing to carry says there is nothing",
            "EVIDENCE YOU ALREADY HAVE: none" in bare.prompt, bare.prompt[-180:]))
    add(_rc("an empty carry still scores specific", retask_specificity(bare)["specific"],
            retask_specificity(bare)["signals"]))
    add(_rc("an empty carry lists no ids", bare.carried_ids == []))
    add(_rc("the prompt is longer than the one-line directive it came from",
            len(retask.prompt) > 4 * len(cases["first_instruction"].instruction),
            f"{len(retask.prompt)} vs {len(cases['first_instruction'].instruction)}"))
    vague = RetaskedWorker.model_validate({
        **_tool_retask_payload(retask),
        "prompt": "try again. be more careful. improve quality. " * 3,
        "corrections": [], "prior_evidence": [], "already_collected": [],
        "objective": worker.objective})
    add(_rc("a vague-only instruction does not score specific",
            not retask_specificity(vague)["specific"],
            retask_specificity(vague)["signals"]))
    add(_rc("the same review produces the same instruction twice",
            retask.fingerprint == retask_worker(
                first_review, report=report_from_outcome(first_outcome), attempt=2,
                objective=worker.objective, criteria=worker.completion_criteria,
                output_schema=worker.output_schema, subagent_id="sa-retask",
                work_unit=worker.work_unit).fingerprint))
    add(_rc("an instruction identical to the previous one is detected",
            retask_repeats(retask, cases["repeated"]),
            (retask.fingerprint, cases["repeated"].fingerprint)))
    add(_rc("the repeat is reported with no substantive change",
            cases["comparison"]["same_fingerprint"] is True
            and cases["comparison"]["substantive"] is False, cases["comparison"]))
    add(_rc("a different deficiency is not reported as a repeat",
            not retask_repeats(retask, retask_worker(
                first_review.model_copy(update={
                    "deficiencies": [first_review.deficiencies[0].model_copy(
                        update={"detail": "the gateway claim rests on a cached page "
                                          "with no publisher named"})]}),
                report=report_from_outcome(first_outcome), attempt=3,
                objective=worker.objective, subagent_id="sa-retask"))))
    add(_rc("the comparison of a first retask is substantive by definition",
            compare_retasks(None, retask)["substantive"]))

    # ---- 5. the retry count is enforced, and read ----------------------
    spent: RetaskLedger = cases["stuck"]
    add(_rc("the budget is the Worker's own limit", spent.budget is not None
            and spent.budget.limit == 2, spent.budget))
    add(_rc("the budget records which ceiling binds", spent.budget.source in
            {"worker", "policy", "tool"}, spent.budget.source))
    add(_rc("a smaller policy limit binds instead of the Worker's",
            retry_budget(worker, policy=ReviewPolicy(max_revisions=0)).limit == 1,
            retry_budget(worker, policy=ReviewPolicy(max_revisions=0)).limit))
    add(_rc("a worker with a two-attempt budget stops after two",
            retry_budget(_retask_worker_spec(3, max_attempts=2),
                         policy=ReviewPolicy(max_revisions=5)).limit == 2))
    add(_rc("a tool failure is not retried when the policy forbids it",
            retry_budget(worker, policy=ReviewPolicy(retry_tool_failures=False),
                         tool_failure=True).source == "tool"))
    add(_rc("the exhausted unit used exactly its limit",
            len(spent.attempts) == spent.budget.limit, len(spent.attempts)))
    add(_rc("the exhausted unit says so", spent.exhausted))
    add(_rc("the final result is not a pass",
            cases["stuck_result"].status is not EntityStatus.SUCCEEDED,
            cases["stuck_result"].status))
    add(_rc("it says in the record that the work is partial",
            _report_of(cases["stuck_result"]) is not None
            and _report_of(cases["stuck_result"]).status is WorkerStatus.PARTIAL,
            _report_of(cases["stuck_result"]).status
            if _report_of(cases["stuck_result"]) else None))
    add(_rc("the final result stops on the retry gate",
            cases["stuck_result"].gate is FlowGate.RETRY_EXHAUSTED,
            cases["stuck_result"].gate))
    add(_rc("the unresolved deficiencies are on the final result",
            len(spent.unresolved) == 1 and "incomplete" in spent.unresolved[0],
            spent.unresolved))
    add(_rc("those deficiencies are in the error the caller reads",
            "unresolved" in (cases["stuck_result"].error or "")
            or "budget" in (cases["stuck_result"].error or ""),
            cases["stuck_result"].error))
    add(_rc("an exhausted unit keeps the evidence its attempts produced",
            bool(cases["stuck_result"].evidence_ids),
            cases["stuck_result"].evidence_ids))
    add(_rc("a unit that produced nothing is failed, not partial",
            _report_of(exhausted_outcome(cases["stuck_worker"], entries=[],
                                         policy=ReviewPolicy())[0])
            .status is WorkerStatus.FAILED))
    add(_rc("one more attempt than the limit is refused by the budget, not run",
            retry_budget(cases["stuck_worker"],
                         policy=ReviewPolicy(max_revisions=1)).limit == 2))

    # ---- 6. earlier evidence is not duplicated -------------------------
    ledger: RetaskLedger = cases["ledger"]
    add(_rc("every attempt is in the history", len(ledger.attempts) == 2,
            [attempt.attempt for attempt in ledger.attempts]))
    add(_rc("the history records what each attempt produced",
            len(ledger.attempts[0].produced_ids) == 3
            and len(ledger.attempts[1].produced_ids) == 3,
            [len(attempt.produced_ids) for attempt in ledger.attempts]))
    add(_rc("the second attempt re-cites the carried evidence instead of recollecting it",
            len(report_from_outcome(second_outcome).evidence)
            == len(report_from_outcome(first_outcome).evidence),
            f"{len(report_from_outcome(second_outcome).evidence)} vs "
            f"{len(report_from_outcome(first_outcome).evidence)}"))
    add(_rc("no evidence id appears twice in the second attempt",
            len({item.id for item in report_from_outcome(second_outcome).evidence})
            == len(report_from_outcome(second_outcome).evidence)))
    add(_rc("the retask names exactly the ids it carries",
            retask.carried_ids == [item.item_id for item in retask.prior_evidence]))
    add(_rc("the prompt lists them so the Worker does not go looking again",
            all(item_id in retask.prompt for item_id in retask.carried_ids)))
    add(_rc("the history keeps the instruction the second attempt received",
            ledger.attempts[1].guidance == retask.prompt, ledger.attempts[1].guidance[:60]))
    add(_rc("the first attempt records no instruction, because it had none",
            ledger.attempts[0].guidance == ""))
    add(_rc("the attempt that carried evidence was told it already had it",
            "EVIDENCE YOU ALREADY HAVE" in retask.prompt))
    add(_rc("the evidence the second attempt collected itself is not listed as inherited",
            not (set(retask.carried_ids)
                 & {item.id for item in report_from_outcome(second_outcome).evidence
                    if item.statement.startswith("the inventory")}),
            retask.carried_ids))

    # ---- 7. a retask that repeats is refused, not issued ----------------
    add(_rc("a revise with no deficiency gets no retask",
            bool(_refuses(lambda: retask_worker(
                first_review.model_copy(update={"deficiencies": []}),
                report=report_from_outcome(first_outcome)))[0])))
    add(_rc("a pass gets no retask",
            bool(_refuses(lambda: retask_worker(
                second_review, report=report_from_outcome(second_outcome)))[0])))
    add(_rc("an assignment with no correction is refused",
            bool(_refuses(lambda: RetaskedWorker.model_validate(
                {**_retask_payload(retask), "corrections": []}))[0])))
    add(_rc("two corrections for one dimension are refused",
            bool(_refuses(lambda: RetaskedWorker.model_validate(
                {**_tool_retask_payload(retask),
                 "corrections": [first_review.deficiencies[0].model_dump(mode="json"),
                                 first_review.deficiencies[0].model_dump(mode="json")],
                 "tool_failure": False}))[0])))
    add(_rc("a tool-failure retask may not carry quality corrections",
            bool(_refuses(lambda: RetaskedWorker.model_validate(
                {**_tool_retask_payload(retask),
                 "corrections": [first_review.deficiencies[0].model_dump(mode="json")]}))[0])))
    add(_rc("the same evidence cannot be carried forward twice",
            bool(_refuses(lambda: RetaskedWorker.model_validate(
                {**_retask_payload(retask),
                 "prior_evidence": [retask.prior_evidence[0].model_dump(mode="json")] * 2}))[0])))
    add(_rc("a retask for a first attempt is refused",
            bool(_refuses(lambda: RetaskedWorker.model_validate(
                {**_retask_payload(retask), "attempt": 1}))[0])))

    # ---- 8. a tool failure is retasked differently ----------------------
    tool_review = first_review.model_copy(update={
        "fault": WorkflowFault.TOOL,
        "checks": [DimensionResult(dimension=dimension) for dimension in REVIEW_DIMENSIONS],
        "deficiencies": [Deficiency(dimension=ReviewDimension.COMPLETENESS,
                                    kind=DeficiencyKind.TOOL_FAILURE,
                                    detail="the attempt failed at the tool: unexpected "
                                           "end of pcap record at offset 4096",
                                    fix="re-run the same unit after the tool recovers")],
        "guidance": "retry the same unit: the failure was the tool's, not the work's"})
    tool_retask = retask_worker(tool_review, report=None, attempt=2,
                                objective=worker.objective, subagent_id="sa-retask")
    add(_rc("a tool failure retask says the work was not judged",
            "never judged" in tool_retask.prompt, tool_retask.prompt[-160:]))
    add(_rc("it tells the Worker not to rewrite what succeeded",
            "do not rewrite" in tool_retask.prompt.lower()))
    add(_rc("it carries no prior evidence, because none was produced",
            tool_retask.prior_evidence == []))
    add(_rc("it is marked as a tool failure", tool_retask.tool_failure))
    add(_rc("a quality retask is not marked as one", not retask.tool_failure))

    # ---- 9. the history and its renderer -------------------------------
    add(_rc("the history is ordered and duplicate-free",
            [attempt.attempt for attempt in ledger.attempts] == [1, 2]))
    add(_rc("the history summarises the budget it spent",
            ledger.summary()["limit"] == 3 and ledger.summary()["attempts"] == 2,
            ledger.summary()))
    add(_rc("an out-of-order history is refused",
            bool(_refuses(lambda: RetaskLedger.model_validate(
                {"worker_id": "wrk-x", "attempts": [
                    {"attempt": 2, "status": "succeeded"}, {"attempt": 1, "status": "failed"}]}))[0])))
    add(_rc("the demo payload carries the prompt and the comparison",
            {"prompt", "comparison", "ledger", "stuck", "acceptance"}
            <= set(retask_quality_demo()), sorted(retask_quality_demo())))
    demo = retask_quality_demo()
    add(_rc("the demo's acceptance block is green",
            demo["acceptance"]["specific"] is True
            and demo["acceptance"]["counts_enforced"] is True
            and bool(demo["acceptance"]["unresolved"]), demo["acceptance"]))
    add(_rc("the demo shows the repeated prompt it refused to send",
            demo["acceptance"]["duplicate_prompt"] is True, demo["acceptance"]))
    add(_rc("the retask reloads from its own serialisation",
            RetaskedWorker.from_dict(retask.to_dict()).fingerprint == retask.fingerprint))
    add(_rc("reloading keeps the prompt the Worker was given",
            RetaskedWorker.from_dict(retask.to_dict()).prompt == retask.prompt))
    return checks


def _tool_retask_payload(retask: RetaskedWorker) -> dict[str, Any]:
    """The serialised retask, with the tool-failure shape it is being tested against."""

    payload = json.loads(model_to_json(retask))
    return {**payload, "tool_failure": True}


# --------------------------------------------------------------------------
# 35.7 Rendering: the instruction, the corrections and the history
# --------------------------------------------------------------------------

def render_retask(assignment: RetaskedWorker, *, show_prompt: bool = True) -> Group:
    """One retask: what the Worker is told, and why each line is there."""

    head = Table(title=f"retask — attempt {assignment.attempt} of {assignment.worker_id}",
                 title_justify="left", box=None, pad_edge=False)
    head.add_column("field", style="dim", no_wrap=True)
    head.add_column("value", overflow="fold", max_width=78)
    head.add_row("objective", escape(assignment.objective))
    head.add_row("work unit", escape(assignment.work_unit or "—"))
    head.add_row("output shape", escape(assignment.output_schema))
    head.add_row("caused by", escape(assignment.because_of[:160]))
    head.add_row("fault", escape(assignment.fault.value))
    head.add_row("fingerprint", escape(assignment.fingerprint))

    corrections = Table(title="what must change", title_justify="left", box=None,
                        pad_edge=False)
    corrections.add_column("dimension", no_wrap=True)
    corrections.add_column("deficiency", overflow="fold", max_width=40)
    corrections.add_column("correction", overflow="fold", max_width=40)
    for item in assignment.corrections:
        corrections.add_row(escape(item.dimension.value), escape(item.detail[:180]),
                            escape(item.correction[:180]))

    rows: list[Any] = [head, Text(""), corrections]
    if assignment.prior_evidence:
        carried = Table(title="evidence already in hand", title_justify="left", box=None,
                        pad_edge=False)
        carried.add_column("item", no_wrap=True)
        carried.add_column("relation", no_wrap=True)
        carried.add_column("statement", overflow="fold", max_width=56)
        for item in assignment.prior_evidence:
            carried.add_row(escape(item.item_id), escape(item.relation),
                            escape(item.statement[:150]))
        rows += [Text(""), carried,
                 Text(f"carried forward, not re-collected: "
                      f"{len(assignment.prior_evidence)} item(s)", style="dim")]
    if show_prompt:
        rows += [Text(""), Panel(Text(assignment.prompt), title="the instruction it sends",
                                 title_align="left", border_style="cyan", expand=False)]
    return Group(*rows)


def render_retask_demo(payload: Mapping[str, Any]) -> Group:
    """The demo: one retask, the repeat it refused, and the budget it spent."""

    contrast = payload["contrast"]
    sides = Table(title="one line of guidance, beside the assignment it becomes",
                  expand=False,
                  title_justify="left", box=None, pad_edge=False)
    sides.add_column("", style="dim", no_wrap=True)
    sides.add_column("§34 directive", overflow="fold", max_width=36)
    sides.add_column("§35 retask", overflow="fold", max_width=46)
    sides.add_row("content", escape(contrast["directive"]["instruction"][:200]),
                  escape("; ".join(contrast["retask"]["corrections"])[:260]))
    sides.add_row("size", f"{contrast['directive']['chars']} chars",
                  f"{contrast['retask']['chars']} chars")
    sides.add_row("carries evidence", "no",
                  ", ".join(contrast["retask"]["carry"]) or "none")

    signals = Table(title="is the retry prompt observably specific?", title_justify="left",
                    box=None, pad_edge=False, expand=False)
    signals.add_column("", width=2)
    signals.add_column("signal", no_wrap=True)
    for name, ok in payload["acceptance"]["signals"].items():
        glyph, colour = ("✔", "green") if ok else ("✘", "red")
        signals.add_row(f"[{colour}]{glyph}[/{colour}]", escape(name.replace("_", " ")))

    history = Table(title="attempt history", title_justify="left", box=None,
                    pad_edge=False, expand=False)
    history.add_column("attempt", justify="right", no_wrap=True)
    history.add_column("status", no_wrap=True)
    history.add_column("decision", no_wrap=True)
    history.add_column("deficiencies", overflow="fold", max_width=40)
    history.add_column("new evidence", justify="right")
    for attempt in payload["attempts"]:
        history.add_row(str(attempt["attempt"]), escape(attempt["status"]),
                        escape(str(attempt["decision"] or "—")),
                        escape(", ".join(attempt["deficiencies"]) or "—"),
                        str(attempt["produced"]))

    budget = payload["budget"] or {}
    stuck = payload["stuck"]
    tail = Text(
        f"\nhistory: {payload['ledger']['attempts']} attempt(s), "
        f"{payload['ledger']['retasks']} retask(s), limit "
        f"{payload['ledger']['limit']} ({budget.get('source', '?')} binds)\n"
        f"repeated instruction detected: "
        f"{payload['acceptance']['duplicate_prompt']}\n"
        f"spent budget: {stuck['attempts']}/{stuck['limit']} attempt(s), "
        f"final status {stuck['final_status']}, "
        f"{len(stuck['unresolved'])} unresolved\n"
        "a retry is a retask: the objective is restated, the deficiencies are quoted, "
        "each one carries its correction, and the evidence already collected is carried "
        "rather than collected twice",
        style="dim")
    return Group(render_retask(RetaskedWorker.from_dict(payload["retask"])),
                 Text(""), sides, Text(""), signals, Text(""), history, tail)


@app.command("retask", help="Targeted retasking: a revise becomes a specific assignment.")
def retask_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the retasking contract offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="One retask, one repeat, one spent budget."),
    next_report: str | None = typer.Option(
        None, "--next", help="Build the retask for a reviewed Worker report ('-' for stdin).",
        show_default=False),
    objective: str = typer.Option("", "--objective",
                                  help="The unit's original objective for --next."),
    criteria: list[str] = typer.Option(
        [], "--criteria", help="A completion criterion for --next. Repeatable."),
    schema: str = typer.Option("EvidenceSet", "--schema",
                               help="The output schema the unit was assigned."),
    worker: str = typer.Option("worker", "--worker", help="Worker id for --next."),
    subagent: str = typer.Option("subagent", "--subagent",
                                 help="Parent Subagent id for --next."),
    attempt: int = typer.Option(1, "--attempt", help="The attempt the report is."),
    scope: list[str] = typer.Option(
        [], "--scope", help="An authorised scope entry. Repeatable."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Turn a rejected result into the assignment the next attempt runs under.

    ``--next`` is the seam for a pipeline: it reviews one report, and when the verdict
    is a revise it prints the retask — the prompt, its corrections, and the evidence to
    carry — exiting **7 (policy)** so the caller can withhold the work.
    """

    console = get_console()

    if self_test:
        checks = run_retask_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"ok": not failures,
                              "checks": [asdict(check) for check in checks]}, indent=2))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        console.print()
        table = Table(title="retask self-test", title_justify="left", box=None,
                      pad_edge=False)
        table.add_column("", width=2)
        table.add_column("check", no_wrap=True)
        table.add_column("detail", overflow="fold")
        for check in checks:
            glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
            table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                          escape(check.detail))
        console.print(table)
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = retask_quality_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_retask_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if next_report:
        if schema not in OUTPUT_SCHEMAS:
            console.print(f"[red]✘[/red] unknown schema {escape(schema)}; choose from: "
                          f"{', '.join(OUTPUT_SCHEMAS)}")
            raise typer.Exit(ExitCode.USAGE)
        if next_report != "-" and not Path(next_report).expanduser().exists():
            console.print(f"[red]✘[/red] no such file: {escape(next_report[:160])}")
            raise typer.Exit(ExitCode.USAGE)
        try:
            raw = (sys.stdin.read() if next_report == "-"
                   else Path(next_report).expanduser().read_text(encoding="utf-8"))
            report = WorkerReport.from_dict(json.loads(raw))
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            console.print(f"[red]✘[/red] not a Worker report: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        # The report names its own Worker; the flag is for a report whose id the
        # operator wants judged under a different unit.  Defaulting to "worker" would
        # put two names for one attempt on the record.
        judged_worker = FlowWorker(
            id=report.worker_id, name=worker or report.worker_id,
            objective=objective or report.summary or report.worker_id,
            work_unit=worker or report.worker_id,
            completion_criteria=list(criteria), output_schema=schema)
        judged = review_outcome(
            outcome_from_report(report), worker=judged_worker,
            subagent_id=subagent or report.subagent_id, scope=list(scope))
        review = judged.review
        if review.decision is not ReviewDecision.REVISE:
            if as_json:
                _emit(json.dumps({"review": review.to_dict(), "next_step": "forward",
                                  "retask": None}, indent=2, default=str))
                raise typer.Exit(ExitCode.OK if review.passed else ExitCode.POLICY)
            console.print()
            console.print(render_review_record(review))
            console.print(Text("\nno retask: the decision is not a revise", style="dim"))
            raise typer.Exit(ExitCode.OK if review.passed else ExitCode.POLICY)
        assignment = retask_worker(
            review, report=report, attempt=max(2, attempt + 1),
            objective=judged_worker.objective, criteria=judged_worker.completion_criteria,
            output_schema=schema, subagent_id=judged.subagent_id,
            work_unit=judged_worker.work_unit, guidance=review.guidance)
        if as_json:
            _emit(json.dumps({"review": review.to_dict(), "retask": assignment.to_dict(),
                              "specificity": retask_specificity(assignment),
                              "next_step": "retry"}, indent=2, default=str))
            raise typer.Exit(ExitCode.POLICY)
        console.print()
        console.print(render_retask(assignment))
        console.print()
        raise typer.Exit(ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --next FILE")
    raise typer.Exit(ExitCode.USAGE)

# --------------------------------------------------------------------------
# 36. Subagent aggregation: only reviewed work, and only when it is ready
# --------------------------------------------------------------------------
#
# §34 decided what may be forwarded, §35 what a retry is told.  This section is the
# Subagent's own judgement of its *team*: it may not begin until every Worker it
# requires has reached a terminal state, it takes only what the reviews forwarded, and
# it answers four questions in the record it writes — what was the same, what
# disagreed, what failed, and whether the Subagent's own completion criteria were met.
#
# When a critical gap remains and the budget allows, the Subagent may plan one more
# Worker.  That Worker goes through the *same* planning, review and retask path as the
# planned ones (§34, §35): a runtime Worker is not a shortcut around the gates, and its
# number is bounded by a licence that cannot be topped up.


class Reconciliation(StrictModel):
    """What was the same across the reviewed results, and which copy was kept.

    Duplicates are not deleted evidence: two Workers independently finding the same
    record is corroboration, and the record has to say so.  One copy is kept as the
    canonical one; the others are named as supporting it, with their ids intact.
    """

    #: Rows judged to be the same observation, by normalised statement.
    merged: int = Field(default=0, ge=0)
    #: How sameness was decided.  Stated, so a reader can disagree with it.
    rule: str = (
        "two rows are the same observation when their statements are identical after "
        "whitespace and case normalisation; a shared subject with a different claim is "
        "not a duplicate")
    groups: list["ReconciledGroup"] = Field(default_factory=list)
    #: The rows the reconciliation worked on, so a reader can see the merge decision.
    rows: list["AggregateRow"] = Field(default_factory=list)
    #: Rows kept, one per group plus every row that was not in a group.
    kept_ids: list[str] = Field(default_factory=list)
    #: Ids that corroborate a kept row rather than standing alone.
    supporting_ids: list[str] = Field(default_factory=list)

    @property
    def distinct(self) -> int:
        return len(self.kept_ids)

    def explain(self) -> str:
        if not self.merged:
            return ("no two reviewed rows made the same claim, so nothing was reconciled "
                    "away")
        return (f"{self.merged} duplicate row(s) in {len(self.groups)} group(s) merged; "
                f"{len(self.kept_ids)} distinct row(s) kept")

    def to_dict(self) -> dict[str, Any]:
        return {"merged": self.merged, "rule": self.rule,
                "groups": [_plain(group) for group in self.groups],
                "rows": [_plain(row) for row in self.rows],
                "kept_ids": list(self.kept_ids),
                "supporting_ids": list(self.supporting_ids),
                "explanation": self.explain()}


class ReconciledGroup(StrictModel):
    """One set of rows that made the same claim."""

    statement: str = Field(min_length=1)
    #: The row that was kept.  ``canonical`` is the same id under its §36.2 name.
    kept: str = Field(min_length=1)
    canonical: str = Field(min_length=1)
    #: Worker ids that independently found the same thing.
    also_found_by: list[str] = Field(default_factory=list)
    #: The evidence ids folded into the kept row as corroboration.
    merged: list[str] = Field(default_factory=list)
    redundant: list[str] = Field(default_factory=list)


class DisagreementSide(StrictModel):
    """One Worker's claim in a disagreement, and what it rests on."""

    worker_id: str = Field(min_length=1)
    statement: str = Field(min_length=1)
    evidence_ids: list[str] = Field(default_factory=list)


class AggregateRow(StrictModel):
    """One reviewed statement, as the reconciliation sees it."""

    statement: str = Field(min_length=1)
    worker_id: str = Field(min_length=1)
    confidence: str = "unknown"
    evidence_ids: list[str] = Field(default_factory=list)
    supporting_ids: list[str] = Field(default_factory=list)

    @property
    def subject(self) -> set[str]:
        return _subject(self.statement)


class Disagreement(StrictModel):
    """Two reviewed results that cannot both be right, preserved rather than settled.

    The Subagent's job is to keep the disagreement visible and say what would settle
    it.  Picking the more confident side would delete the other Worker's finding, which
    is the outcome this record exists to prevent.
    """

    topic: str = Field(min_length=3)
    left_worker: str = Field(min_length=1)
    right_worker: str = Field(min_length=1)
    left_statement: str = Field(min_length=1)
    right_statement: str = Field(min_length=1)
    #: ``negation``, ``value`` or ``presence`` — how the two were found to conflict.
    kind: str = Field(default="negation", pattern="^(negation|value|presence)$")
    left_evidence: list[str] = Field(default_factory=list)
    right_evidence: list[str] = Field(default_factory=list)
    #: What would settle it.  A disagreement nobody can act on is just noise.
    resolution: str = Field(min_length=12)
    resolved: bool = False

    @model_validator(mode="after")
    def _two_sides(self) -> "Disagreement":
        if self.left_worker == self.right_worker:
            raise ValueError("a disagreement is between two Workers, not one")
        if not self.left_evidence and not self.right_evidence:
            raise ValueError(
                "a disagreement must cite the evidence on at least one side, or it is "
                "an impression")
        return self

    @property
    def sides(self) -> list[DisagreementSide]:
        """Both sides of the conflict, in the order they were found."""

        return [DisagreementSide(worker_id=self.left_worker, statement=self.left_statement,
                                 evidence_ids=list(self.left_evidence)),
                DisagreementSide(worker_id=self.right_worker,
                                 statement=self.right_statement,
                                 evidence_ids=list(self.right_evidence))]

    @property
    def describe(self) -> str:
        state = "resolved" if self.resolved else "unresolved"
        return (f"{self.kind} on {self.topic}: {self.left_worker} vs {self.right_worker} "
                f"({state}) — {self.resolution[:110]}")

    def to_dict(self) -> dict[str, Any]:
        return {"topic": self.topic, "kind": self.kind,
                "sides": [{"worker_id": self.left_worker, "statement": self.left_statement,
                           "evidence_ids": list(self.left_evidence)},
                          {"worker_id": self.right_worker,
                           "statement": self.right_statement,
                           "evidence_ids": list(self.right_evidence)}],
                "resolution": self.resolution, "resolved": self.resolved,
                "describe": self.describe}


def _plain(model: Any) -> dict[str, Any]:
    """A model's fields as JSON-ready values, without pydantic's json-mode detours."""

    return json.loads(model_to_json(model))


class FailedSubtask(StrictModel):
    """One subtask that did not deliver, and what the aggregate did about it.

    A list, not a count: "3 of 5 Workers failed" is not actionable, and the mission
    cannot say what it is missing if it only knows how much.
    """

    worker_id: str = Field(min_length=1)
    name: str = ""
    status: str = Field(min_length=1)
    #: ``review-rejected``, ``retry-exhausted``, ``failed``, ``blocked``, ``deferred``
    #: or ``error`` — the gate that decided it.
    gate: str = ""
    reason: str = Field(min_length=1)
    #: What the mission loses because of it, in the Subagent's words.
    consequence: str = Field(min_length=8)
    attempts: int = Field(default=0, ge=0)
    #: What was done about it: ``retasked``, ``runtime-worker`` or ``recorded``.
    handled: str = Field(default="recorded", pattern="^(retasked|runtime-worker|recorded)$")
    #: The gap string a runtime Worker planned to replace this subtask closes, so a
    #: later round can tell whether the replacement actually delivered.
    gap: str = ""

    @property
    def describe(self) -> str:
        return (f"{self.name or self.worker_id} {self.status} ({self.gate or 'unknown'}): "
                f"{self.reason[:90]} — {self.consequence[:90]}")

    def to_dict(self) -> dict[str, Any]:
        return {"worker_id": self.worker_id, "name": self.name, "status": self.status,
                "gate": self.gate, "reason": self.reason,
                "consequence": self.consequence, "attempts": self.attempts,
                "handled": self.handled, "gap": self.gap, "describe": self.describe}


class CriterionCheck(StrictModel):
    """Whether one of the Subagent's own completion criteria was met, and the proof."""

    criterion: str = Field(min_length=8)
    met: bool
    #: The evidence ids that satisfy it, or the gap that prevents it.
    evidence_ids: list[str] = Field(default_factory=list)
    #: Why it is unmet — always populated when ``met`` is false.
    shortfall: str = ""
    #: Whether the shortfall is critical (the report may not claim the objective) or
    #: merely incomplete (the report is partial and says so).
    critical: bool = True

    @model_validator(mode="after")
    def _proof(self) -> "CriterionCheck":
        if self.met and not self.evidence_ids:
            raise ValueError(
                "a met criterion must cite the evidence that meets it; otherwise the "
                "claim is the Subagent's opinion of itself")
        if not self.met and not self.shortfall.strip():
            raise ValueError("an unmet criterion must say what is missing")
        return self

    @property
    def describe(self) -> str:
        if self.met:
            return f"met: {self.criterion} ({len(self.evidence_ids)} item(s))"
        return f"unmet ({'critical' if self.critical else 'partial'}): {self.criterion} — " \
               f"{self.shortfall[:100]}"

    def to_dict(self) -> dict[str, Any]:
        return {"criterion": self.criterion, "met": self.met,
                "evidence_ids": list(self.evidence_ids),
                "shortfall": self.shortfall, "critical": self.critical,
                "describe": self.describe}


class Readiness(StrictModel):
    """The state :func:`assess_readiness` decides: ready, expandable, or bounded.

    Its three answers map onto the task's three branches — aggregate now, plan one more
    Worker, or return a bounded partial report — and every one of them is decided from
    the record rather than from a feeling that the Subagent is "done enough".
    """

    subagent_id: str = Field(min_length=1)
    ready: bool
    #: ``ready``, ``expand`` or ``partial``.
    decision: str = Field(pattern="^(ready|expand|partial)$")
    #: Workers the aggregate required, and the ones that reached a terminal state.
    required: list[str] = Field(default_factory=list)
    settled: list[str] = Field(default_factory=list)
    missing: list[str] = Field(default_factory=list)
    #: Open questions from the plan this Subagent was created to answer.
    open_questions: list[str] = Field(default_factory=list)
    unmet_criteria: list[str] = Field(default_factory=list)
    critical_gaps: list[str] = Field(default_factory=list)
    #: Why it may *not* expand, when it wanted to.
    expansion_refusals: list[str] = Field(default_factory=list)
    runtime_spawned: int = Field(default=0, ge=0)
    runtime_remaining: int = Field(default=0, ge=0)

    @property
    def explained(self) -> bool:
        """Every decision carries its reason, including the boring ones."""

        if self.decision == "ready":
            return self.ready and not self.missing and not self.unmet_criteria
        if self.decision == "expand":
            return bool(self.critical_gaps) and not self.expansion_refusals
        return True

    def summary(self) -> str:
        if self.decision == "ready":
            return (f"ready: {len(self.settled)}/{len(self.required)} worker(s) settled, "
                    f"every criterion met")
        if self.decision == "expand":
            return (f"expand: {len(self.critical_gaps)} critical gap(s), "
                    f"{self.runtime_remaining} runtime Worker seat(s) left")
        return (f"partial: {len(self.critical_gaps)} critical gap(s) remain and the "
                f"budget does not allow another Worker ("
                + ", ".join(self.expansion_refusals) + ")")

    def to_dict(self) -> dict[str, Any]:
        return {"subagent_id": self.subagent_id, "ready": self.ready,
                "decision": self.decision, "required": list(self.required),
                "settled": list(self.settled), "missing": list(self.missing),
                "open_questions": list(self.open_questions),
                "unmet_criteria": list(self.unmet_criteria),
                "critical_gaps": list(self.critical_gaps),
                "expansion_refusals": list(self.expansion_refusals),
                "runtime_spawned": self.runtime_spawned,
                "runtime_remaining": self.runtime_remaining,
                "summary": self.summary()}


class RuntimePlan(StrictModel):
    """The Subagent's proposal for one more Worker, before anything is created.

    Narrow by construction: one Worker, one gap, one question.  A Subagent that could
    ask for "more research" would be re-planning its whole assignment at the end of it,
    which is the Master's job and not a remedy for a specific gap.
    """

    subagent_id: str = Field(min_length=1)
    #: The gap this Worker exists to close: a criterion or an open question.
    gap: str = Field(min_length=12)
    name: str = Field(min_length=3)
    objective: str = Field(min_length=15)
    work_unit: str = Field(min_length=3)
    tools: list[str] = Field(min_length=1)
    expected_evidence: str = Field(min_length=12)
    output_schema: str = "EvidenceSet"
    completion_criteria: list[str] = Field(min_length=1)
    max_attempts: int = Field(default=2, ge=1, le=10)
    #: Where the gap came from: ``criterion`` or ``question``.
    source: str = Field(default="criterion", pattern="^(criterion|question)$")
    #: The criterion or question itself, so a later round can tell whether the gap a
    #: runtime Worker was planned for is still open.
    target: str = ""
    #: How the plan is justified, in one line the record keeps.
    rationale: str = Field(min_length=12)

    @model_validator(mode="after")
    def _narrow(self) -> "RuntimePlan":
        if len(self.completion_criteria) > 1:
            raise ValueError(
                "a runtime Worker closes one gap: several completion criteria is a "
                "second plan, not a remedy")
        unbounded = unbounded_instruction(self.objective) or next(
            (phrase for criterion in self.completion_criteria
             for phrase in [unbounded_instruction(criterion)] if phrase), "")
        if unbounded:
            # §38: an instruction with no end condition is the one loop no detector can
            # catch — there is no repetition to see, only a unit that never returns.
            raise ValueError(
                f"a runtime Worker's objective must name a bounded amount of work; "
                f"{unbounded!r} has no end condition the mission can test")
        if any(word in self.objective.lower() for word in ("everything", "all of", "any")):
            raise ValueError("a runtime Worker's objective must name the gap it closes")
        return self

    def to_dict(self) -> dict[str, Any]:
        return {"subagent_id": self.subagent_id, "gap": self.gap, "target": self.target,
                "source": self.source, "name": self.name, "objective": self.objective,
                "work_unit": self.work_unit, "tools": list(self.tools),
                "expected_evidence": self.expected_evidence,
                "output_schema": self.output_schema,
                "completion_criteria": list(self.completion_criteria),
                "max_attempts": self.max_attempts, "rationale": self.rationale}


class RuntimeSpawnRecord(StrictModel):
    """One runtime Worker: what it was planned for, and what became of it."""

    subagent_id: str = ""
    worker_id: str = Field(min_length=1)
    name: str = ""
    gap: str = ""
    plan: "RuntimePlan | None" = None
    round: int = Field(default=1, ge=1)
    attempt: int = Field(default=1, ge=1)
    spawned: bool = True
    refusal: str = ""
    answered: bool = False
    review_decision: str = ""
    licence_remaining: int = Field(default=0, ge=0)
    evidence_ids: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def _consistent(self) -> "RuntimeSpawnRecord":
        if self.plan is not None and self.plan.subagent_id not in ("", self.subagent_id):
            raise ValueError("a spawn record's plan belongs to another Subagent")
        if self.spawned and self.refusal:
            raise ValueError("a spawned Worker was not refused and carries no refusal")
        if not self.spawned and not self.refusal:
            raise ValueError("a refused spawn must say why")
        return self

    @property
    def describe(self) -> str:
        if not self.spawned:
            return f"refused: {self.gap[:60]} — {self.refusal[:80]}"
        verdict = "answered the gap" if self.answered else "did not answer the gap"
        return f"runtime Worker for {self.gap[:60]}: {verdict}"


# --------------------------------------------------------------------------
# 36.1 Readiness: never aggregate early, and know when to stop
# --------------------------------------------------------------------------

class EarlyAggregate(PrematureAggregate):
    """A Subagent tried to aggregate while one of its Workers was still running."""

    def __init__(self, subagent_id: str, outstanding: Sequence[str],
                 settled: Sequence[str] = ()) -> None:
        self.subagent_id = subagent_id
        self.outstanding = list(outstanding)
        super().__init__(JoinBarrier(
            stage=f"subagent-aggregate:{subagent_id}",
            expected=[*settled, *self.outstanding], received=list(settled),
            missing=self.outstanding))


def terminal_states() -> frozenset[EntityStatus]:
    """The statuses a Worker branch can settle in — the only ones a join accepts."""

    return frozenset({EntityStatus.SUCCEEDED, EntityStatus.FAILED, EntityStatus.BLOCKED,
                      EntityStatus.CANCELLED, EntityStatus.SKIPPED,
                      EntityStatus.BUDGET_EXCEEDED})


def outstanding_workers(required: Sequence[str], settled: Sequence[str],
                        outcomes: Sequence["WorkerOutcome"]) -> list[str]:
    """Workers still without a terminal outcome.

    Two independent facts must agree: the branch reported settled, and the branch
    produced an outcome in a terminal state.  A branch that reported settled without the
    outcome is as unfinished as one that never reported at all.
    """

    reported = set(settled)
    finished = {outcome.worker_id for outcome in outcomes
                if outcome.status in terminal_states()}
    return [worker_id for worker_id in required
            if worker_id not in reported or worker_id not in finished]


def check_ready(subagent_id: str, required: Sequence[str], settled: Sequence[str],
                outcomes: Sequence["WorkerOutcome"]) -> JoinBarrier:
    """The gate: no aggregate until every required Worker is terminal.

    Raises :class:`EarlyAggregate` naming exactly what is outstanding, so a mis-wired
    edge fails loudly instead of summarising a team that is still working.
    """

    outstanding = outstanding_workers(required, settled, outcomes)
    if outstanding:
        raise EarlyAggregate(subagent_id, outstanding,
                             settled=[wid for wid in required if wid in set(settled)
                                      and wid not in set(outstanding)])
    # ``received`` is what arrived, not what was required re-read: the barrier is the
    # record of an arrival, and a barrier that echoes its own expectation proves nothing.
    received = list(dict.fromkeys(outcome.worker_id for outcome in outcomes))
    return check_join(f"subagent-aggregate:{subagent_id}", required, received)


# --------------------------------------------------------------------------
# 36.2 Reconciling duplicates, preserving disagreements
# --------------------------------------------------------------------------

#: Words that flip a claim's polarity.  Used only to decide that two statements *disagree*,
#: never to decide which one is right.
_NEGATIONS: frozenset[str] = frozenset({"no", "not", "never", "none", "absent",
                                        "missing", "without", "unable", "failed",
                                        "did", "does", "cannot", "unknown"})


def _claim_key(statement: str) -> str:
    return " ".join("".join(ch for ch in statement.lower() if ch.isalnum() or ch == " ")
                    .split())


def _claim_stem(word: str) -> str:
    """A crude plural/verb agreement fold, for comparing two claims about one thing.

    Only the trailing ``s`` is removed, and never from a word that already ends in
    ``ss``: "affects" and "affect" are the same claim, "access" and "acces" are not.
    """

    if len(word) > 4 and word.endswith("s") and not word.endswith("ss"):
        return word[:-1]
    return word


def _subject(statement: str) -> set[str]:
    """The words a claim is *about*, with the polarity words removed and stems folded."""

    return {_claim_stem(word) for word in _claim_key(statement).split()
            if word not in _NEGATIONS}


def _reconciliation_rows(evidence: Sequence["EvidenceItem"]) -> list["AggregateRow"]:
    """The rows a reconciliation kept: one per distinct statement.

    ``supporting_ids`` is the corroboration the canonical row absorbed — the redundant
    copies' ids — so a reader can see that two Workers found this, not merely that two
    copies were deleted.
    """

    return [AggregateRow(statement=item.statement, worker_id=item.collected_by or "",
                         confidence=item.confidence.value, evidence_ids=[item.id],
                         supporting_ids=list(dict.fromkeys([*item.supports, item.id])))
            for item in evidence]


def reconcile(evidence: Sequence["EvidenceItem"]) -> tuple[list["EvidenceItem"],
                                                          Reconciliation]:
    """Collapse rows that make the same claim, keeping one canonical copy.

    The kept row carries the corroboration: the redundant ids move into its ``supports``
    so the second Worker's finding is still visible as agreement rather than vanishing.
    """

    groups: dict[str, list["EvidenceItem"]] = {}
    order: list[str] = []
    for item in evidence:
        key = _claim_key(item.statement)
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(item)
    kept: list[EvidenceItem] = []
    reconciled = Reconciliation()
    for key in order:
        group = groups[key]
        canonical = group[0]
        if len(group) > 1:
            redundant = [item.id for item in group[1:]]
            supporting = list(dict.fromkeys([*canonical.supports, *redundant]))
            canonical = canonical.model_copy(update={"supports": supporting})
            reconciled.groups.append(ReconciledGroup(
                statement=canonical.statement, canonical=canonical.id,
                kept=canonical.id,
                also_found_by=[item.collected_by or "" for item in group[1:]],
                merged=redundant, redundant=redundant))
            reconciled.merged += len(group) - 1
            reconciled.supporting_ids.extend(redundant)
        kept.append(canonical)
        reconciled.kept_ids.append(canonical.id)
    reconciled.rows = _reconciliation_rows(kept)
    return kept, reconciled


def _finding_rows(report: "WorkerReport | None", worker_id: str,
                  forwarded_ids: set[str]) -> list[tuple[str, str, str, list[str]]]:
    """``(worker_id, statement, confidence, evidence_ids)`` for one reviewed report."""

    if report is None:
        return []
    rows: list[tuple[str, str, str, list[str]]] = []
    for finding in report.findings:
        cited = [item for item in finding.evidence_ids if item in forwarded_ids]
        if finding.evidence_ids and not cited:
            # Its evidence was withheld: the finding did not survive review, so it is
            # not something this Subagent may assert (§34).
            continue
        rows.append((worker_id, finding.statement, finding.confidence.value, cited))
    return rows


def _contradicts(left: str, right: str, *, minimum_overlap: int = 2) -> bool:
    """Whether two statements cannot both be true, by the same rules the aggregate uses."""

    left_key, right_key = _claim_key(left), _claim_key(right)
    if left_key == right_key:
        return False
    left_subject, right_subject = _subject(left), _subject(right)
    if len(left_subject & right_subject) < minimum_overlap:
        return False
    if left_subject == right_subject and left_key != right_key:
        return True
    return bool(_numbers(left) and _numbers(right) and _numbers(left) != _numbers(right)
                and len(left_subject & right_subject) >= 3)


def find_disagreements(rows: Sequence[tuple[str, str, str, list[str]]]) -> list[Disagreement]:
    """Two Workers asserting opposite things about the same subject.

    Deliberately conservative: only statements that share their subject words and differ
    in polarity, or that quantify the same thing differently, are reported.  A looser
    rule would fill the record with false conflicts and train a reader to ignore them.
    """

    disagreements: list[Disagreement] = []
    seen: set[tuple[str, str]] = set()
    for index, (left_worker, left, left_confidence, left_ids) in enumerate(rows):
        for right_worker, right, right_confidence, right_ids in rows[index + 1:]:
            if left_worker == right_worker:
                continue
            pair = tuple(sorted((left_worker, right_worker)))
            left_key, right_key = _claim_key(left), _claim_key(right)
            if left_key == right_key:
                continue
            left_subject, right_subject = _subject(left), _subject(right)
            overlap = left_subject & right_subject
            if len(overlap) < 2:
                continue
            kind = ""
            if (left_subject - _NEGATIONS) == (right_subject - _NEGATIONS) \
                    and left_key != right_key:
                kind = "negation"
            elif _numbers(left) and _numbers(right) and _numbers(left) != _numbers(right) \
                    and len(overlap) >= 3:
                kind = "value"
            if not kind:
                continue
            topic = " ".join(sorted(left_subject & right_subject)[:4])
            if (pair, topic) in seen:
                continue
            seen.add((pair, topic))
            disagreements.append(Disagreement(
                topic=topic, left_worker=left_worker, right_worker=right_worker,
                left_statement=left[:300], right_statement=right[:300], kind=kind,
                left_evidence=left_ids, right_evidence=right_ids,
                resolution=(f"re-read the primary record both Workers cite for "
                            f"{topic[:60]}; one of the two statements is wrong and the "
                            f"record, not the confidence, decides which")))
    return disagreements


def _numbers(statement: str) -> set[str]:
    return set(re.findall(r"\d+(?:\.\d+)?", statement))


# --------------------------------------------------------------------------
# 36.3 Did this Subagent meet its own criteria?
# --------------------------------------------------------------------------

def assess_criteria(criteria: Sequence[str], *, evidence: Sequence["EvidenceItem"],
                    reports: Sequence["WorkerReport"], scope: Sequence[str] = (),
                    gaps: Sequence["UnknownValue"] = (),
                    questions: Sequence[str] = ()) -> list[CriterionCheck]:
    """Judge each of the Subagent's own criteria against what actually came back.

    Four mechanical tests, one per kind of criterion this build's plans write, each
    answered from the record:

    *   ``every``/``each`` — every named item is covered by some cited evidence;
    *   ``at least N`` — the volume is there;
    *   ``integrity``/``hash`` — every forwarded item is hashed;
    *   ``attributed``/``named`` — a candidate is named, or the absence is stated.

    A criterion of none of those kinds is *not* silently declared met: it is reported as
    unmet-but-checkable-by-a-reader, because a Subagent marking its own homework with no
    test behind it is the failure mode this section is written against.
    """

    lowered = [criterion.lower() for criterion in criteria]
    ids = [item.id for item in evidence]
    checks: list[CriterionCheck] = []
    for criterion, text in zip(criteria, lowered):
        volume = re.search(r"at least (\d+)", text)
        if volume:
            want = int(volume.group(1))
            checks.append(CriterionCheck(
                criterion=criterion, met=len(evidence) >= want, evidence_ids=ids[:want],
                shortfall="" if len(evidence) >= want else
                (f"{len(evidence)} item(s) came back, the criterion asks for {want}"),
                critical=True))
            continue
        # Custody before coverage: "every item carries a hash" is a hash question, and
        # the coverage rule would answer it from statement overlap instead.
        if any(word in text for word in ("integrity", "hash")):
            hashed = [item for item in evidence if item.custody and item.custody.integrity_hash]
            checks.append(CriterionCheck(
                criterion=criterion, met=bool(hashed) and len(hashed) == len(evidence),
                evidence_ids=[item.id for item in hashed],
                shortfall="" if hashed and len(hashed) == len(evidence) else
                (f"{len(evidence) - len(hashed)} forwarded item(s) carry no recorded hash"),
                critical=True))
            continue
        if "every" in text or "each" in text:
            subjects = [item for item in evidence if _matches_subject(item, text,
                                                                     reports)]
            checks.append(CriterionCheck(
                criterion=criterion, met=bool(subjects) and not _uncovered(text, reports),
                evidence_ids=[item.id for item in subjects],
                shortfall="" if subjects and not _uncovered(text, reports) else
                ("no reviewed item addresses this criterion" if not subjects else
                 f"no item addresses: {_uncovered(text, reports)[0][:80]}"),
                critical=True))
            continue
        if questions and not any(word in text for word in ("integrity", "hash")) \
                and any(_shares_subject(text, question) for question in questions):
            # The criterion restates a question the Subagent had to answer.  "Answered"
            # means a reviewed item addresses it *and* an earlier criterion covering the
            # same subject was met — the aggregate may not call it answered by fiat.
            answered = [check for check in checks if check.met]
            addressed = [item for item in evidence if _matches_subject(item, text, reports)]
            checks.append(CriterionCheck(
                criterion=criterion, met=bool(answered) and bool(addressed),
                evidence_ids=[item.id for item in addressed],
                shortfall="" if answered and addressed else
                ("no reviewed item addresses the question this criterion restates"
                 if not addressed else
                 "the question is not answered by any criterion that was met"),
                critical=True))
            continue
        if any(word in text for word in ("attributed", "candidate", "named")):
            named = [item for item in evidence
                     if re.search(r"process|pid|binary|/usr/|/bin/", item.statement.lower())]
            stated = [gap for gap in gaps if "process" in gap.detail.lower()]
            checks.append(CriterionCheck(
                criterion=criterion, met=bool(named) or bool(stated),
                evidence_ids=[item.id for item in named],
                shortfall="" if named or stated else
                "no reviewed item names a candidate process and no gap states its absence",
                critical=True))
            continue
        checks.append(CriterionCheck(
            criterion=criterion, met=False,
            shortfall=("no mechanical test exists for this criterion; a reader must "
                       "check it against the report"),
            critical=False))
    return checks


def _shares_subject(criterion: str, question: str) -> bool:
    """Whether a criterion is a restatement of a question the plan had to answer."""

    left = {word for word in _claim_key(criterion).split()
            if len(word) > 3 and word not in _RELEVANCE_STOPWORDS}
    right = {word for word in _claim_key(question).split()
             if len(word) > 3 and word not in _RELEVANCE_STOPWORDS}
    return len(left & right) >= 2


def _matches_subject(item: "EvidenceItem", criterion: str,
                     reports: Sequence["WorkerReport"]) -> bool:
    tokens = {word for word in _claim_key(criterion).split()
              if len(word) > 3 and word not in _RELEVANCE_STOPWORDS}
    return bool(tokens & set(_claim_key(item.statement).split()))


def _uncovered(criterion: str, reports: Sequence["WorkerReport"]) -> list[str]:
    """The ``each``-named items no finding addresses."""

    names = re.findall(r"each ([a-z /-]{3,40})", criterion)
    if not names:
        return []
    covered: list[str] = []
    for report in reports:
        covered.extend(finding.statement.lower() for finding in report.findings)
    joined = " ".join(covered)
    return [name.strip() for name in names if name.strip() not in joined]


# --------------------------------------------------------------------------
# 36.4 Whether another Worker may be planned at all
# --------------------------------------------------------------------------

def assess_readiness(subagent: "FlowSubagent", *, checks: Sequence[CriterionCheck],
                     gaps: Sequence["UnknownValue"], settled: Sequence[str],
                     required: Sequence[str], runtime_spawned: int,
                     runtime_limit: int, refusals: Sequence[str] = (),
                     runtime_gaps: Sequence[str] = (),
                     failed: Sequence["FailedSubtask"] = ()) -> Readiness:
    """The three-way decision, from the record and the budget only."""

    unmet = [check for check in checks if not check.met]
    # A gap a runtime Worker was already planned for is not a gap that justifies *another*
    # Worker: sending a second copy to the same question would be a repeat, not a remedy.
    # Planned gaps therefore drop out of the critical list, and the round that planned
    # them is recorded as the round that answered them (§36.4).
    covered = {word for gap in runtime_gaps for word in _claim_key(gap).split()
               if len(word) > 3}
    critical = [check for check in unmet if check.critical
                and not (_words(check.criterion) <= covered)]
    critical_gaps = [f"{check.criterion}: {check.shortfall}"[:300] for check in critical]
    missing = [worker_id for worker_id in required if worker_id not in set(settled)]
    remaining = max(0, runtime_limit - runtime_spawned)
    open_questions = list(subagent.addresses_questions)
    unanswered = [question for question in open_questions
                  if not _question_answered(question, checks)
                  and not (_words(question) <= covered)]
    # A subtask that ran and whose work was withheld is a critical gap of its own: the
    # Subagent lost a unit's finding, and no criterion passing can make that untrue.  A
    # replacement retires the gap only by actually forwarding — ``runtime_gaps`` carries
    # forward-only records, so ``covered`` means "a replacement delivered", not "was tried".
    failed_gaps = [f"{item.name or item.worker_id}: {item.reason[:160]}" for item in failed
                   if not (_words(item.gap) <= covered)]
    gaps_and_questions = list(dict.fromkeys([
        *critical_gaps, *failed_gaps,
        *[f"question: {question}" for question in unanswered]]))
    if not gaps_and_questions:
        decision = "ready"
    elif remaining > 0 and not refusals:
        decision = "expand"
    else:
        decision = "partial"
    return Readiness(
        subagent_id=subagent.id, ready=decision == "ready", decision=decision,
        required=list(required), settled=list(settled), missing=missing,
        open_questions=unanswered,
        unmet_criteria=[check.criterion for check in unmet],
        critical_gaps=gaps_and_questions,
        expansion_refusals=list(refusals), runtime_spawned=runtime_spawned,
        runtime_remaining=remaining)


def _words(text: str) -> set[str]:
    """The content words of a criterion or question, for the "already planned" test."""

    return {word for word in _claim_key(text).split()
            if len(word) > 3 and word not in _RELEVANCE_STOPWORDS}


def _question_answered(question: str, checks: Sequence[CriterionCheck]) -> bool:
    """Whether a *met* criterion answers this question, by shared content words.

    Only met checks count: an unmet criterion whose wording happens to match the
    question is the gap, not its closure.
    """

    tokens = {word for word in _claim_key(question).split()
              if len(word) > 4 and word not in _RELEVANCE_STOPWORDS}
    if not tokens:
        return True
    return any(check.met and tokens & set(_claim_key(check.criterion).split())
               for check in checks)


def expansion_refusals(subagent: "FlowSubagent", *, policy: "FlowPolicy",
                       runtime_spawned: int, licence_remaining: int | None,
                       deadline_expired: bool = False,
                       cancelled: bool = False) -> list[str]:
    """Every reason this Subagent may not plan another Worker, in order of precedence.

    All of them are checked and all of them are reported: an operator asked "why did it
    stop here?" deserves the whole list, not the first branch that returned.
    """

    reasons: list[str] = []
    if cancelled:
        reasons.append("the mission was cancelled")
    if deadline_expired:
        reasons.append("the mission deadline has expired")
    if not policy.allow_runtime_workers:
        reasons.append("runtime Workers are disabled for this mission")
    if runtime_spawned >= policy.max_runtime_workers_per_subagent:
        reasons.append(f"the runtime Worker budget of "
                       f"{policy.max_runtime_workers_per_subagent} is spent")
    if licence_remaining is not None and licence_remaining <= 0:
        reasons.append("the Subagent's SpawnLedger licence is exhausted")
    return reasons


class AggregationOutcome(StrictModel):
    """One pass of the Subagent's aggregation, before it is written as a report."""

    barrier: JoinBarrier
    forwarded: list["ReviewedWorkerResult"] = Field(default_factory=list)
    withheld: list["ReviewedWorkerResult"] = Field(default_factory=list)
    evidence: list["EvidenceItem"] = Field(default_factory=list)
    reconciliation: Reconciliation = Field(default_factory=Reconciliation)
    disagreements: list[Disagreement] = Field(default_factory=list)
    failed: list[FailedSubtask] = Field(default_factory=list)
    checks: list[CriterionCheck] = Field(default_factory=list)
    gaps: list["UnknownValue"] = Field(default_factory=list)

    @model_validator(mode="after")
    def _only_reviewed_evidence(self) -> "AggregationOutcome":
        forwarded_ids = {item.id for result in self.forwarded
                         for item in (result.report.evidence if result.report else [])}
        stray = [item.id for item in self.evidence if item.id not in forwarded_ids]
        if stray:
            raise ValueError(
                "an aggregate may only contain evidence a review forwarded; "
                f"{len(stray)} item(s) came from somewhere else")
        return self

    @property
    def forwardable(self) -> int:
        return len(self.forwarded)

    @property
    def unresolved(self) -> list[Disagreement]:
        """The disagreements nothing has settled yet — the ones a report must carry."""

        return [item for item in self.disagreements if not item.resolved]

    def to_dict(self) -> dict[str, Any]:
        return {"barrier": {**_plain(self.barrier),
                            "satisfied": self.barrier.satisfied,
                            "describe": self.barrier.describe()},
                "forwarded": [result.worker_id for result in self.forwarded],
                "withheld": [result.worker_id for result in self.withheld],
                "evidence": [item.id for item in self.evidence],
                "reconciliation": self.reconciliation.to_dict(),
                "disagreements": [item.to_dict() for item in self.disagreements],
                "failed": [item.to_dict() for item in self.failed],
                "checks": [item.to_dict() for item in self.checks],
                "gaps": [gap.detail for gap in self.gaps],
                "summary": self.summary()}

    def summary(self) -> str:
        return (f"{self.forwardable} forwarded, {len(self.withheld)} withheld; "
                f"{self.reconciliation.merged} duplicate(s) merged, "
                f"{len(self.disagreements)} disagreement(s), "
                f"{len(self.failed)} failed subtask(s); "
                f"{sum(1 for check in self.checks if check.met)}/"
                f"{len(self.checks)} criteria met")


# --------------------------------------------------------------------------
# 36.5 The aggregate the Subagent writes
# --------------------------------------------------------------------------

def aggregate_subagent(subagent: "FlowSubagent", *, outcomes: Sequence["WorkerOutcome"],
                       judged: Sequence["ReviewedWorkerResult"],
                       settled: Sequence[str], gaps: Sequence["UnknownValue"] = (),
                       scope: Sequence[str] = (),
                       reconciliation: Reconciliation | None = None,
                       required: Sequence[str] | None = None) -> AggregationOutcome:
    """Build the aggregate from reviewed results only, and check it is not early.

    The order is the contract: **barrier first** (nothing is summarised until every
    required Worker is terminal), **review second** (a result with no verdict is
    refused), and only then the four reconciliation questions.  A caller that has the
    outcomes but not the reviews gets an :class:`UnreviewedResult`, not an aggregate
    with the unreviewed rows quietly dropped.
    """

    barrier = check_ready(
        subagent.id,
        [worker.id for worker in subagent.workers] if required is None else list(required),
        settled, outcomes)
    by_worker = {result.worker_id: result for result in judged}
    forwarded: list[ReviewedWorkerResult] = []
    withheld: list[ReviewedWorkerResult] = []
    for outcome in outcomes:
        result = by_worker.get(outcome.worker_id)
        if result is None:
            raise UnreviewedResult(outcome.worker_id, stage="subagent-aggregate")
        require_review(result, stage="subagent-aggregate")
        (forwarded if result.forwarded else withheld).append(result)

    # Only forwarded work contributes evidence or findings.
    evidence = [item for result in forwarded for item in (result.report.evidence
                                                         if result.report else [])]
    kept, reconciled = reconcile(evidence)
    if reconciliation is not None:
        reconciled = reconciliation
    reports = [result.report for result in forwarded if result.report is not None]
    # Disagreements are found on the *raw* rows, one per Worker, before the duplicates
    # are collapsed: after reconciliation the two sides of a conflict can land on the
    # same canonical id, and the pair would then look like agreement (§36.2).
    rows = [row for result in forwarded
            for row in _finding_rows(result.report, result.worker_id,
                                     {item.id for item in evidence})]
    failed = [
        FailedSubtask(
            worker_id=result.worker_id,
            name=next((worker.name for worker in subagent.workers
                       if worker.id == result.worker_id), ""),
            status=(result.review.worker_status.value
                    or result.outcome.status.value),
            gate=result.review.path if result.review.decision is not ReviewDecision.PASS
            else "",
            reason=(result.review.deficiencies[0].detail if result.review.deficiencies
                    else (result.outcome.error or result.review.stop_reason
                          or f"{result.review.decision.value} on attempt "
                             f"{result.review.attempt}")),
            consequence=_consequence_for(subagent, result),
            attempts=result.review.attempt,
            handled="recorded",
            gap=f"subtask {result.worker_id}: {result.review.decision.value}")
        for result in withheld]
    checks = assess_criteria(subagent.completion_criteria, evidence=kept, reports=reports,
                             scope=scope, gaps=gaps, questions=subagent.addresses_questions)
    return AggregationOutcome(
        barrier=barrier, forwarded=forwarded, withheld=withheld, evidence=kept,
        reconciliation=reconciled, disagreements=find_disagreements(rows),
        failed=failed, checks=checks, gaps=list(gaps))


def _consequence_for(subagent: "FlowSubagent", result: ReviewedWorkerResult) -> str:
    """What the mission loses because this result was withheld, in one line."""

    report = result.report
    if report is not None and report.gaps:
        return f"the unit declared its own gap: {report.gaps[0].detail[:120]}"
    if result.review.decision is ReviewDecision.BLOCKED:
        return (f"the unit never ran ({result.review.stop_reason[:100]}), so anything "
                f"only it could observe is missing from this report")
    if report is not None and report.limitations:
        return f"the unit's own limitation stands: {report.limitations[0][:120]}"
    return ("the unit's work was not forwarded, so its finding is not in this report "
            "and is not counted as met")


# --------------------------------------------------------------------------
# 36.6 Planning one more Worker, at run time, through the same gates
# --------------------------------------------------------------------------

def plan_runtime_worker(subagent: "FlowSubagent", *, readiness: Readiness,
                        plan: RuntimePlan | None = None) -> RuntimePlan:
    """The Subagent's proposal for the Worker its gap needs.

    A plan may be supplied (a caller that knows what is missing); otherwise one is
    derived from the *first* critical gap — one Worker, one gap — because a Subagent that
    could spawn "a few more units" would be re-planning its assignment, which is the
    Master's decision (§25) and not a remedy for a named shortfall.
    """

    if plan is not None:
        if plan.subagent_id != subagent.id:
            raise ValueError("a runtime plan belongs to the Subagent that proposed it")
        return plan
    gap = next((item for item in readiness.critical_gaps if not item.startswith("question:")),
               None) or next((item for item in readiness.critical_gaps), "")
    if not gap:
        raise ValueError("this Subagent has no critical gap to close, so it needs no "
                         "runtime Worker")
    source = "question" if gap.startswith("question:") else "criterion"
    target = gap.split(":", 1)[1].strip() if source == "question" else gap.split(":")[0].strip()
    tools = _tools_for_runtime_worker(subagent)
    derived = RuntimePlan(
        subagent_id=subagent.id, gap=gap,
        name=f"gap-{content_id('gap', gap, length=6)}",
        target=target,
        objective=f"close this gap for {subagent.role}: {target[:120]}",
        work_unit=f"{subagent.role} gap closure",
        tools=tools,
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        output_schema="EvidenceSet",
        completion_criteria=[f"the result addresses: {target[:80]}"],
        source=source,
        rationale=f"the reviewed results left the gap '{target[:80]}' open and the "
                  f"Subagent still holds a runtime Worker seat")
    return derived


def _tools_for_runtime_worker(subagent: "FlowSubagent") -> list[str]:
    """The narrowest tool set any of the Subagent's own Workers already holds."""

    for worker in subagent.workers:
        if worker.tools:
            return [worker.tools[0]]
    return ["evidence.read"]


def runtime_worker_from_plan(plan: RuntimePlan, *, index: int,
                             subagent: "FlowSubagent") -> "FlowWorker":
    """Materialise the plan as a Worker the graph can run.

    The same shape as a planned Worker, so every downstream gate — the join, the seven
    dimensions, the retask, the aggregate — applies without a special case.
    """

    return FlowWorker(
        id=content_id("wrk", subagent.id, plan.name, index),
        name=plan.name, objective=plan.objective, work_unit=plan.work_unit,
        tools=list(plan.tools), input_names=["the reviewed results so far"],
        completion_criteria=list(plan.completion_criteria),
        expected_evidence=plan.expected_evidence, output_schema=plan.output_schema,
        max_attempts=plan.max_attempts)


def runtime_spawn_allowed(subagent: "FlowSubagent", *, policy: "FlowPolicy",
                          spawned: int, licence_remaining: int | None,
                          deadline_expired: bool = False,
                          cancelled: bool = False) -> tuple[bool, list[str]]:
    """Whether one more runtime Worker may be created, and every reason it may not."""

    reasons = expansion_refusals(
        subagent, policy=policy, runtime_spawned=spawned, licence_remaining=licence_remaining,
        deadline_expired=deadline_expired, cancelled=cancelled)
    return (not reasons, reasons)


def _verdict_of(result: "ReviewedWorkerResult") -> "ReviewVerdict":
    """The graph's verdict for a reviewed result, derived from the review (§34.6)."""

    review = result.review
    return ReviewVerdict(
        worker_id=result.worker_id, approved=review.passed,
        verdict=("pass" if review.passed else
                 "revise" if review.decision is ReviewDecision.REVISE else "reject"),
        # The criteria the *review* was judged against are the Subagent's; the report's
        # own list is the Worker's, which is the clearer record of what was asked.
        criteria=[],
        findings=[item.describe for item in review.deficiencies] or
                 [f"no deficiency recorded ({review.decision.value})"],
        retry=review.retry, guidance=review.guidance or review.stop_reason or
        "record the gap and stop this unit", reviewer="subagent-review")


# --------------------------------------------------------------------------
# 36.7 The bounded partial report
# --------------------------------------------------------------------------

def bounded_partial_report(outcome: AggregationOutcome, readiness: Readiness, *,
                           subagent: "FlowSubagent",
                           spawned: Sequence["RuntimeSpawnRecord"] = ()) -> "SubagentOutcome":
    """The report a Subagent returns when it cannot close its gaps.

    *Bounded* means three things, and each is in the record: the report claims only what
    the reviews forwarded, it names every gap it could not close, and it says why no
    further Worker was planned.  The status is ``BLOCKED`` rather than ``FAILED`` when
    something usable came back — the mission continues with a named uncertainty, which
    is the whole point of not stopping early (§34's blocking rule).
    """

    gaps = list(outcome.gaps)
    gaps.extend(UnknownValue(
        reason=UnknownReason.FAILED, determined_by=subagent.id,
        detail=f"{item.name or item.worker_id}: {item.reason[:200]}")
        for item in outcome.failed)
    # Only a *critical* unmet criterion becomes a gap.  A criterion no mechanical test
    # covers is still reported — in ``criteria_checks``, for a reader to judge — but
    # promoting every uncheckable sentence to a mission gap would bury the real ones.
    for check in outcome.checks:
        if not check.met and check.critical:
            gaps.append(UnknownValue(
                reason=UnknownReason.UNAVAILABLE, determined_by=subagent.id,
                detail=f"{check.criterion[:120]}: {check.shortfall[:160]}"))
    for disagreement in outcome.disagreements:
        if not disagreement.resolved:
            gaps.append(UnknownValue(
                reason=UnknownReason.UNKNOWN, determined_by=subagent.id,
                detail=disagreement.describe[:240]))
    evidence = outcome.evidence
    return SubagentOutcome(
        subagent_id=subagent.id, role=subagent.role, objective=subagent.objective,
        status=(EntityStatus.FAILED if not evidence else EntityStatus.BLOCKED),
        gate=(FlowGate.REVIEW_REJECTED if not evidence else FlowGate.NONE),
        # Every unit that ran, not only the ones that were forwarded: `withheld` says
        # which of them were refused, and a report that omitted them would make a
        # reviewed-and-refused unit indistinguishable from one that never ran.
        outcomes=[result.outcome for result in [*outcome.forwarded, *outcome.withheld]],
        reviews=[_verdict_of(result) for result in [*outcome.forwarded, *outcome.withheld]],
        evidence=evidence, aggregate_basis=outcome.barrier,
        open_questions=readiness.open_questions, gaps=gaps,
        withheld=[result.worker_id for result in outcome.withheld],
        # The four answers the task asks for travel with the report even when it is
        # bounded: a partial report that dropped them would be a summary of a summary.
        reconciliation=outcome.reconciliation, disagreements=list(outcome.disagreements),
        failed=list(outcome.failed), criteria_checks=list(outcome.checks),
        readiness=readiness, runtime_workers=list(spawned))


def complete_report(outcome: AggregationOutcome, readiness: Readiness, *,
                    subagent: "FlowSubagent", retries: int = 0,
                    seconds: float = 0.0,
                    spawned: Sequence["RuntimeSpawnRecord"] = ()) -> "SubagentOutcome":
    """The report when every required Worker settled and every criterion is met."""

    return SubagentOutcome(
        subagent_id=subagent.id, role=subagent.role, objective=subagent.objective,
        status=EntityStatus.SUCCEEDED, gate=FlowGate.NONE,
        # Every unit that ran, not only the ones that were forwarded: `withheld` says
        # which of them were refused, and a report that omitted them would make a
        # reviewed-and-refused unit indistinguishable from one that never ran.
        outcomes=[result.outcome for result in [*outcome.forwarded, *outcome.withheld]],
        reviews=[_verdict_of(result) for result in [*outcome.forwarded, *outcome.withheld]],
        evidence=outcome.evidence, aggregate_basis=outcome.barrier,
        open_questions=list(subagent.addresses_questions), gaps=list(outcome.gaps),
        withheld=[result.worker_id for result in outcome.withheld],
        reconciliation=outcome.reconciliation, disagreements=list(outcome.disagreements),
        failed=list(outcome.failed), criteria_checks=list(outcome.checks),
        retries=retries, seconds=seconds, readiness=readiness,
        runtime_workers=list(spawned))


def render_aggregate(outcome: AggregationOutcome, readiness: Readiness | None = None,
                     *, subagent: "FlowSubagent | None" = None) -> Group:
    """One aggregate: what it waited for, what it merged, and what it refused to hide."""

    head = Table(title="aggregate — the four questions", title_justify="left", box=None,
                 pad_edge=False)
    head.add_column("question", style="dim", no_wrap=True)
    head.add_column("answer", overflow="fold", max_width=78)
    head.add_row("ready?", escape(outcome.barrier.describe() + (
        "" if outcome.barrier.satisfied else " — REFUSED")))
    head.add_row("forwarded", escape(", ".join(
        result.worker_id for result in outcome.forwarded) or "nothing"))
    head.add_row("withheld", escape(", ".join(
        result.worker_id for result in outcome.withheld) or "nothing"))
    head.add_row("what was the same", escape(outcome.reconciliation.explain()))
    head.add_row("what disagreed", escape(
        f"{len(outcome.disagreements)} disagreement(s), "
        f"{len(outcome.unresolved)} unresolved" if outcome.disagreements
        else "no two reviewed results contradicted each other"))
    head.add_row("what failed", escape(
        f"{len(outcome.failed)} failed subtask(s)" if outcome.failed
        else "every subtask that ran was forwarded"))

    rows: list[Any] = [head]

    if outcome.reconciliation.groups:
        merged = Table(title="duplicates reconciled", title_justify="left", box=None,
                       pad_edge=False)
        merged.add_column("kept", no_wrap=True)
        merged.add_column("merged in", overflow="fold", max_width=30)
        merged.add_column("what they both said", overflow="fold", max_width=44)
        for group in outcome.reconciliation.groups:
            merged.add_row(escape(group.kept), escape(", ".join(group.merged) or "—"),
                           escape(group.statement[:150]))
        rows += [Text(""), merged]

    if outcome.disagreements:
        disputed = Table(title="disagreements preserved, not resolved", title_justify="left",
                         box=None, pad_edge=False)
        disputed.add_column("kind", no_wrap=True)
        disputed.add_column("side", no_wrap=True)
        disputed.add_column("claim", overflow="fold", max_width=38)
        disputed.add_column("resolution", overflow="fold", max_width=38)
        for disagreement in outcome.disagreements:
            for side in disagreement.sides:
                disputed.add_row(escape(disagreement.kind), escape(side.worker_id),
                                 escape(f"{side.statement[:90]} "
                                        f"[{', '.join(side.evidence_ids) or 'no evidence'}]"),
                                 escape(disagreement.resolution[:120]))
        rows += [Text(""), disputed]

    if outcome.failed:
        failures = Table(title="failed subtasks", title_justify="left", box=None,
                         pad_edge=False)
        failures.add_column("unit", no_wrap=True)
        failures.add_column("status", no_wrap=True)
        failures.add_column("reason", overflow="fold", max_width=34)
        failures.add_column("what the mission loses", overflow="fold", max_width=34)
        for item in outcome.failed:
            failures.add_row(escape(item.name or item.worker_id), escape(item.status),
                             escape(item.reason[:140]), escape(item.consequence[:140]))
        rows += [Text(""), failures]

    if outcome.checks:
        criteria = Table(title="its own completion criteria", title_justify="left", box=None,
                         pad_edge=False)
        criteria.add_column("", width=2)
        criteria.add_column("criterion", overflow="fold", max_width=44)
        criteria.add_column("how it was judged", overflow="fold", max_width=40)
        for check in outcome.checks:
            glyph, colour = ("✔", "green") if check.met else ("✘", "red")
            criteria.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.criterion[:160]),
                             escape(check.evidence_ids[0] if check.met and check.evidence_ids
                                    else check.shortfall[:160] or "met"))
        rows += [Text(""), criteria]
    else:
        rows += [Text(""), Text("no completion criteria were declared, so none were "
                                "judged — an aggregate does not mark its own homework",
                                style="dim")]

    if readiness is not None:
        rows += [Text(""), render_readiness(readiness)]
    return Group(*rows)


def render_readiness(readiness: Readiness) -> Group:
    """The decision, and *every* reason behind it — including the boring ones."""

    table = Table(title="readiness", title_justify="left", box=None, pad_edge=False)
    table.add_column("field", style="dim", no_wrap=True)
    table.add_column("value", overflow="fold", max_width=78)
    table.add_row("decision", escape(readiness.decision.upper()))
    table.add_row("workers", escape(f"{len(readiness.settled)}/{len(readiness.required)} "
                                    f"settled"))
    if readiness.missing:
        table.add_row("still outstanding", escape(", ".join(readiness.missing)))
    seats = readiness.runtime_spawned + readiness.runtime_remaining
    table.add_row("runtime workers",
                  escape(f"{readiness.runtime_spawned} of {seats} seat(s) spent"))
    if readiness.critical_gaps:
        table.add_row("critical gaps", escape("; ".join(readiness.critical_gaps)[:400]))
    if readiness.expansion_refusals:
        table.add_row("may not expand because",
                      escape("; ".join(readiness.expansion_refusals)))
    return Group(table, Text(readiness.summary(), style="dim"))


def render_report(report: "SubagentOutcome") -> Group:
    """A whole Subagent report as a reader sees it: evidence, gaps, and the four answers."""

    head = Table(title=f"{report.role} — {report.status.value}", title_justify="left",
                 box=None, pad_edge=False)
    head.add_column("field", style="dim", no_wrap=True)
    head.add_column("value", overflow="fold", max_width=78)
    head.add_row("subagent", escape(report.subagent_id))
    head.add_row("objective", escape(report.objective))
    head.add_row("evidence", str(len(report.evidence)))
    head.add_row("gaps", str(len(report.gaps)))
    head.add_row("withheld", escape(", ".join(report.withheld) or "none"))
    head.add_row("runtime workers", escape(
        ", ".join(item.describe for item in report.runtime_workers) or "none"))
    rows: list[Any] = [head]
    if report.gaps:
        gaps = Table(title="gaps this report carries", title_justify="left", box=None,
                     pad_edge=False)
        gaps.add_column("reason", no_wrap=True)
        gaps.add_column("detail", overflow="fold", max_width=72)
        for gap in report.gaps:
            gaps.add_row(escape(str(gap.reason)), escape(gap.detail[:240]))
        rows += [Text(""), gaps]
    if report.reconciliation.groups or report.disagreements or report.failed:
        rows += [Text(""), render_aggregate(
            AggregationOutcome(barrier=report.aggregate_basis or JoinBarrier(
                stage="adopted", expected=[], received=[], missing=[]),
                evidence=list(report.evidence), reconciliation=report.reconciliation,
                disagreements=list(report.disagreements), failed=list(report.failed),
                checks=list(report.criteria_checks)), report.readiness)]
    return Group(*rows)


# --------------------------------------------------------------------------
# 36.8 Scripted results: an aggregate that has something to reconcile
# --------------------------------------------------------------------------

def _aggregate_evidence(statement: str, *, tag: str, worker: str,
                        url: str) -> "EvidenceItem":
    return EvidenceItem(
        id=content_id("ev", worker, statement, length=10),
        kind=EvidenceKind.OBSERVATION, statement=statement,
        sources=[SourceReference(
            kind=SourceKind.PUBLIC_WEB, url=url, title=tag,
            retrieved_at=datetime(2026, 5, 4, 10, 0, tzinfo=timezone.utc),
            retrieval_method=RetrievalMethod.HTTP, http_status=200)],
        confidence=Confidence.LOW, confidence_basis="one retrieval",
        collected_by=worker)


def _demo_pair() -> list["ReviewedWorkerResult"]:
    """The demo's three reviewed results, shared with the self-test's early case."""

    return _build_demo_cases()[1]


def _build_demo_cases() -> tuple[dict[str, Any], list["ReviewedWorkerResult"]]:
    """Three aggregates: one clean, one that reconciles, and one that must stop.

    The middle case is the section's argument.  Two Workers found the same advisory and
    one of them found its mirror: the statement is the same claim twice, and the
    *corroboration* is the thing worth keeping.  A third Worker says the affected
    component is something else, and that is a disagreement the report must carry rather
    than settle.
    """

    # The same claim, word for word, from two independent sources: this is the duplicate
    # the reconciliation must merge.  The forum's claim shares the subject and disagrees
    # with both, which is the disagreement it must preserve rather than settle.
    merged_claim = "CVE-2026-1188 affects the edge gateway session handling"
    clash = "CVE-2026-1188 does not affect the edge gateway session handling"

    # Keyed by Worker, not by statement: two Workers finding the same claim hold two
    # distinct items, and that distinction is the corroboration being reconciled.
    evidence: list["EvidenceItem"] = [
        _aggregate_evidence(merged_claim, tag="vendor advisory", worker="wrk-a",
                            url="https://vendor.test/a"),
        _aggregate_evidence(merged_claim, tag="mirror", worker="wrk-b",
                            url="https://mirror.test/a"),
        _aggregate_evidence(clash, tag="forum post", worker="wrk-c",
                            url="https://forum.test/a"),
    ]
    worker = FlowWorker(
        id="wrk-clean", name="advisory-reader", objective="read the vendor advisories",
        work_unit="advisory reading", tools=["advisory.fetch"],
        completion_criteria=["at least 1 source retrieved"],
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        output_schema="EvidenceSet")
    clean_report = WorkerReport(
        worker_id="wrk-clean", subagent_id="sa-demo", status=WorkerStatus.COMPLETED,
        summary="read one advisory", evidence=evidence[:1],
        sources=list(evidence[0].sources),
        findings=[WorkerFinding(statement=evidence[0].statement,
                                evidence_ids=[evidence[0].id],
                                confidence=Confidence.LOW,
                                confidence_basis="one retrieval on record")],
        attempt=1)
    reviewed = ReviewedWorkerResult(
        worker_id="wrk-clean", subagent_id="sa-demo",
        outcome=outcome_from_report(clean_report), report=clean_report,
        review=review_outcome(outcome_from_report(clean_report), worker=worker,
                              subagent_id="sa-demo").review)
    barrier = check_join("subagent-aggregate:sa-demo", ["wrk-clean"], ["wrk-clean"])
    clean = aggregate_subagent(
        FlowSubagent(id="sa-demo", role="advisory", objective="read the advisories",
                     workers=[worker]), outcomes=[reviewed.outcome], judged=[reviewed],
        settled=["wrk-clean"])
    clean = clean.model_copy(update={"barrier": barrier})

    # ---- the case with something to reconcile -------------------------------
    # One item each: the demo is about what the *aggregate* does with three reviewed
    # results, so every result is one the review forwarded.
    reader = FlowWorker(
        id="wrk-a", name="advisory-reader", objective="read the vendor advisory",
        work_unit="edge gateway advisory", tools=["advisory.fetch"],
        completion_criteria=["at least 1 source retrieved"],
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        output_schema="EvidenceSet")
    mirror_reader = FlowWorker(
        id="wrk-b", name="mirror-reader", objective="read the mirror of the advisory",
        work_unit="edge gateway advisory", tools=["advisory.fetch"],
        completion_criteria=["at least 1 source retrieved"],
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        output_schema="EvidenceSet")
    forum = FlowWorker(
        id="wrk-c", name="forum-scout", objective="read the operator forum thread",
        work_unit="edge gateway advisory", tools=["forum.fetch"],
        completion_criteria=["at least 1 source retrieved"],
        expected_evidence="≥1 observation item(s) from ≥1 source(s)",
        output_schema="EvidenceSet")
    pair: list[ReviewedWorkerResult] = []
    for unit, statements in ((reader, [merged_claim]), (mirror_reader, [merged_claim]),
                             (forum, [clash])):
        items = [item for item in evidence
                 if item.collected_by == unit.id and item.statement in statements]
        report = WorkerReport(
            worker_id=unit.id, subagent_id="sa-demo", status=WorkerStatus.COMPLETED,
            summary=(f"{unit.name}: read {len(items)} source(s); at least 1 source "
                     f"retrieved; advisory component named"), evidence=list(items),
            sources=[source for item in items for source in item.sources],
            findings=[WorkerFinding(statement=item.statement, evidence_ids=[item.id],
                                    confidence=Confidence.LOW,
                                    confidence_basis="one retrieval on record")
                      for item in items],
            attempt=1)
        reviewed_pair = ReviewedWorkerResult(
            worker_id=unit.id, subagent_id="sa-demo",
            outcome=outcome_from_report(report), report=report,
            review=review_outcome(outcome_from_report(report), worker=unit,
                                  subagent_id="sa-demo").review)
        pair.append(reviewed_pair)
    team = FlowSubagent(
        id="sa-demo", role="advisory", objective="read the advisories and say what they mean",
        workers=[reader, mirror_reader, forum],
        completion_criteria=["at least 2 sources retrieved"],
        addresses_questions=["the published advisories name the affected component"])
    reconciled = aggregate_subagent(team, outcomes=[item.outcome for item in pair],
                                    judged=pair,
                                    settled=[item.worker_id for item in pair])

    # ---- the case that must stop -------------------------------------------
    blocked = pair[1].model_copy(update={
        "review": pair[1].review.model_copy(update={
            "decision": ReviewDecision.BLOCKED, "passed": False, "blocking": True,
            "stop_reason": "the mirror refused every request"})})
    stopped = aggregate_subagent(
        FlowSubagent(id="sa-demo2", role="advisory", objective="read the advisories",
                     workers=[reader, mirror_reader],
                     completion_criteria=["at least 2 sources retrieved"],
                     addresses_questions=["the published advisories name the affected "
                                          "component"]),
        outcomes=[pair[0].outcome, blocked.outcome], judged=[pair[0], blocked],
        settled=[pair[0].worker_id, blocked.worker_id])
    readiness = assess_readiness(
        FlowSubagent(id="sa-demo2", role="advisory", objective="read the advisories",
                     workers=[reader, mirror_reader],
                     completion_criteria=["at least 2 sources retrieved"]),
        checks=stopped.checks, gaps=stopped.gaps, settled=[item.worker_id for item in pair],
        required=[reader.id, mirror_reader.id], runtime_spawned=0, runtime_limit=0,
        refusals=["the runtime Worker budget of 0 is spent"], failed=stopped.failed)
    return ({"clean": {"outcome": clean, "readiness": None},
             "reconciled": {"outcome": reconciled, "readiness": None},
             "stopped": {"outcome": stopped, "readiness": readiness}}, pair)


def aggregate_demo_cases() -> dict[str, dict[str, Any]]:
    """The three cases, without the helper's second return value."""

    cases, _pair = _build_demo_cases()
    return cases


def aggregate_demo() -> dict[str, Any]:
    """The demo payload: three aggregates and the acceptance signals over them."""

    cases = aggregate_demo_cases()
    reconciled = cases["reconciled"]["outcome"]
    clean = cases["clean"]["outcome"]
    stopped = cases["stopped"]["outcome"]
    signals = {
        "the aggregate waited for a terminal outcome": clean.barrier.satisfied,
        "a duplicate claim was merged": bool(reconciled.reconciliation.groups),
        "the corroborating copy was kept": any(
            group.merged for group in reconciled.reconciliation.groups),
        "two contradictory claims were preserved": bool(reconciled.disagreements),
        "the disagreement was not auto-resolved": not any(
            item.resolved for item in reconciled.disagreements),
        "a withheld result is listed as a failed subtask": bool(stopped.failed),
        "the criteria were judged against the evidence": bool(reconciled.checks),
        "the stopped aggregate says why it cannot expand": bool(
            cases["stopped"]["readiness"] is not None
            and cases["stopped"]["readiness"].expansion_refusals),
    }
    return {"cases": {name: {"outcome": case["outcome"].summary(),
                             "readiness": (case["readiness"].summary()
                                           if case["readiness"] else None)}
                      for name, case in cases.items()},
            "evidence": [{"worker": item.collected_by, "statement": item.statement}
                         for item in reconciled.evidence],
            "reconciliation": reconciled.reconciliation.to_dict(),
            "reconciliation_line": reconciled.reconciliation.explain(),
            "disagreements": [item.to_dict() for item in reconciled.disagreements],
            "failed": [item.describe for item in stopped.failed],
            "checks": [item.describe for item in reconciled.checks],
            "signals": signals,
            "acceptance": {"all_signals": all(signals.values()),
                           "signals": signals}}


def render_aggregate_demo(payload: Mapping[str, Any]) -> Group:
    """The demo: one merged claim, one preserved disagreement, one bounded stop."""

    signals = Table(title="is the aggregate honest about its own team?", title_justify="left",
                    box=None, pad_edge=False, expand=False)
    signals.add_column("", width=2)
    signals.add_column("signal", overflow="fold", max_width=64)
    for name, ok in payload["acceptance"]["signals"].items():
        glyph, colour = ("✔", "green") if ok else ("✘", "red")
        signals.add_row(f"[{colour}]{glyph}[/{colour}]", escape(name.replace("_", " ")))

    merged = Table(title=f"the same claim, twice — {payload['reconciliation_line']}",
                   title_justify="left", box=None, pad_edge=False, expand=False)
    merged.add_column("worker", no_wrap=True)
    merged.add_column("statement", overflow="fold", max_width=72)
    for item in payload["evidence"]:
        merged.add_row(escape(item["worker"] or "—"), escape(item["statement"][:150]))

    disagreements = Table(title="preserved, not decided", title_justify="left", box=None,
                          pad_edge=False, expand=False)
    disagreements.add_column("the two claims", overflow="fold", max_width=44)
    disagreements.add_column("what would settle it", overflow="fold", max_width=40)
    seen_resolution: set[str] = set()
    for item in payload["disagreements"]:
        sides = " vs ".join(side["worker_id"] for side in item["sides"])
        shown = ("" if item["resolution"] in seen_resolution
                 else item["resolution"][:160])
        seen_resolution.add(item["resolution"])
        disagreements.add_row(escape(f"{sides}: {item['sides'][0]['statement'][:60]}"),
                              escape(shown))

    failures = Table(title="failed subtasks stay visible", title_justify="left", box=None,
                     pad_edge=False, expand=False)
    failures.add_column("subtask", overflow="fold", max_width=86)
    for item in payload["failed"]:
        failures.add_row(escape(item[:200]))

    tail = Text("a bounded partial report names what it could not get, and why it stopped "
                "asking", style="dim")
    rows: list[Any] = [signals, Text(""), merged, Text(""), disagreements]
    if payload["failed"]:
        rows += [Text(""), failures]
    rows += [Text(""), tail]
    return Group(*rows)


@app.command("aggregate",
             help="Subagent aggregation: reviewed work only, and only when it is ready.")
def aggregate_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the aggregation contract offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="One merge, one disagreement, one bounded stop."),
    next_report: str | None = typer.Option(
        None, "--next",
        help="Aggregate a Subagent's reviewed reports from JSON ('-' for stdin)."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
    runtime_workers: int | None = typer.Option(
        None, "--runtime-workers",
        help="Override the per-Subagent runtime Worker budget for this aggregation."),
) -> None:
    """Aggregate reviewed Worker reports, or explain why the aggregate cannot start."""

    console = get_console()

    if self_test:
        checks = run_aggregate_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"checks": [check.to_dict() for check in checks],
                              "passed": len(checks) - len(failures),
                              "failed": len(failures)}, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        table = Table(box=None, pad_edge=False)
        table.add_column("check", no_wrap=True)
        table.add_column("detail", overflow="fold")
        for check in checks:
            glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
            table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                          escape(check.detail))
        console.print(table)
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = aggregate_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_aggregate_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if next_report:
        try:
            raw = (sys.stdin.read() if next_report == "-"
                   else Path(next_report).expanduser().read_text(encoding="utf-8"))
            payload = json.loads(raw)
        except (OSError, json.JSONDecodeError) as exc:
            console.print(f"[red]✘[/red] not a Subagent report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        try:
            subagent = FlowSubagent.model_validate(payload["subagent"])
            judged = [ReviewedWorkerResult.model_validate(item)
                      for item in payload["results"]]
            settled = [str(item) for item in payload.get("settled") or
                       [result.worker_id for result in judged]]
            spawned = [RuntimeSpawnRecord.model_validate(item)
                       for item in payload.get("spawned") or []]
            gaps = [UnknownValue.model_validate(item) for item in payload.get("gaps") or []]
        except (KeyError, ValueError) as exc:
            console.print(f"[red]✘[/red] not a Subagent report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        budget = (FlowPolicy().max_runtime_workers_per_subagent
                  if runtime_workers is None else runtime_workers)
        policy = FlowPolicy(max_runtime_workers_per_subagent=budget)
        try:
            outcome = aggregate_subagent(
                subagent, outcomes=[result.outcome for result in judged], judged=judged,
                settled=settled, gaps=gaps,
                required=[worker.id for worker in subagent.workers]
                + [record.worker_id for record in spawned])
        except PrematureAggregate as exc:
            # The acceptance clause itself: an aggregate that would have started early is
            # refused, with the units it was waiting for named.
            if as_json:
                _emit(json.dumps({"refused": str(exc), "outstanding": exc.barrier.missing,
                                  "decision": "wait"}, indent=2, default=str))
                raise typer.Exit(ExitCode.POLICY) from exc
            console.print()
            console.print(f"[red]✘[/red] this aggregate is not ready: "
                          f"{escape(exc.barrier.describe())}")
            console.print(Text("nothing was summarised; a Subagent that aggregates before "
                               "its Workers are terminal is reporting on its own "
                               "impatience", style="dim"))
            raise typer.Exit(ExitCode.POLICY) from exc
        refusals = expansion_refusals(
            subagent, policy=policy, runtime_spawned=len(spawned),
            licence_remaining=policy.max_runtime_workers_per_subagent - len(spawned))
        readiness = assess_readiness(
            subagent, checks=outcome.checks, gaps=outcome.gaps, settled=settled,
            required=[worker.id for worker in subagent.workers], runtime_spawned=len(spawned),
            runtime_limit=budget, refusals=refusals, failed=outcome.failed)
        plan = None
        if readiness.decision == "expand":
            try:
                plan = plan_runtime_worker(subagent, readiness=readiness)
            except ValueError:
                plan = None
        if as_json:
            _emit(json.dumps({
                "aggregate": outcome.summary(),
                "reconciliation": outcome.reconciliation.to_dict(),
                "disagreements": [item.to_dict() for item in outcome.disagreements],
                "failed": [item.describe for item in outcome.failed],
                "criteria": [item.describe for item in outcome.checks],
                "readiness": readiness.to_dict(),
                "next_worker": plan.to_dict() if plan else None,
                "decision": readiness.decision,
            }, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if readiness.ready else ExitCode.POLICY)
        console.print()
        console.print(render_aggregate(outcome, readiness))
        if plan is not None:
            console.print()
            console.print(Text("one more Worker, through the same gates: "
                               f"{plan.objective}", style="dim"))
        console.print()
        raise typer.Exit(ExitCode.OK if readiness.ready else ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --next FILE")
    raise typer.Exit(ExitCode.USAGE)


class AggregateCheck(StrictModel):
    """One assertion in the §36 self-test."""

    name: str = Field(min_length=1)
    ok: bool
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "ok": self.ok, "detail": self.detail}


def _demo_team() -> "FlowSubagent":
    """One Worker, so a report can be built for a Subagent the demo already described."""

    return FlowSubagent(
        id="sa-demo2", role="advisory", objective="read the advisories",
        workers=[FlowWorker(id="wrk-demo", name="demo", objective="read the advisory",
                            tools=["advisory.fetch"],
                            completion_criteria=["at least 1 source retrieved"])])


def run_aggregate_self_test() -> list[AggregateCheck]:
    """Prove the acceptance clause: no early aggregate, bounded extra Workers, visible gaps."""

    checks: list[AggregateCheck] = []

    def add(name: str, ok: bool, detail: Any = "") -> None:
        checks.append(AggregateCheck(name=name, ok=bool(ok), detail=str(detail)[:150]))

    def raises(fn: Callable[[], Any], exc: type[BaseException]) -> bool:
        try:
            fn()
        except exc:
            return True
        except Exception:                     # noqa: BLE001 - a wrong error is a failure
            return False
        return False

    cases = aggregate_demo_cases()
    clean, reconciled = cases["clean"]["outcome"], cases["reconciled"]["outcome"]
    stopped, stop_ready = cases["stopped"]["outcome"], cases["stopped"]["readiness"]

    # ---- 1. aggregation never begins early -----------------------------
    add("a complete join aggregates", clean.barrier.satisfied,
        clean.barrier.describe())
    add("the barrier names what it waited for", clean.barrier.expected == ["wrk-clean"],
        clean.barrier.expected)

    def aggregate_early() -> None:
        aggregate_subagent(
            FlowSubagent(id="sa-early", role="r", objective="o", workers=[
                FlowWorker(id="wrk-1", name="a", objective="o", completion_criteria=["c"]),
                FlowWorker(id="wrk-2", name="b", objective="o", completion_criteria=["c"])]),
            outcomes=[_demo_pair()[0].outcome], judged=[_demo_pair()[0]],
            settled=[_demo_pair()[0].worker_id])

    add("aggregating with a Worker still running raises", raises(aggregate_early,
                                                                 PrematureAggregate))
    add("the refusal is an EarlyAggregate, not a generic one",
        raises(aggregate_early, EarlyAggregate))

    def early_names_the_outstanding() -> None:
        try:
            aggregate_early()
        except EarlyAggregate as exc:
            # Both Workers are outstanding: neither has a terminal outcome yet, and the
            # refusal has to name them rather than describe a count.
            assert set(exc.outstanding) == {"wrk-1", "wrk-2"}, exc.outstanding
            raise

    add("the refusal names the outstanding Worker", raises(early_names_the_outstanding,
                                                           EarlyAggregate))
    # A terminal outcome from one Worker and nothing from the other: the branch that
    # reported *settled* without a terminal state is still outstanding.
    add("a branch that settled without a terminal outcome is not ready",
        outstanding_workers(
            ["a", "b"], ["a", "b"],
            [WorkerOutcome(worker_id="a", subagent_id="s",
                           status=EntityStatus.SUCCEEDED, attempt=1)]) == ["b"],
        outstanding_workers(
            ["a", "b"], ["a", "b"],
            [WorkerOutcome(worker_id="a", subagent_id="s",
                           status=EntityStatus.SUCCEEDED, attempt=1)]))
    add("every terminal state satisfies the join",
        all(not outstanding_workers(["a"], ["a"], [
            WorkerOutcome(worker_id="a", subagent_id="s", status=state, attempt=1)])
            for state in terminal_states()),
        [state.name for state in terminal_states()])
    add("an unreviewed result cannot be aggregated",
        raises(lambda: require_review(
            _demo_pair()[0].outcome, stage="test"), UnreviewedResult))
    add("a reviewed result may be aggregated",
        require_review(_demo_pair()[0], stage="test") is not None)

    # ---- 2. duplicates are reconciled, corroboration is kept ------------
    add("the same claim from two Workers becomes one row",
        len(reconciled.reconciliation.groups) >= 1,
        reconciled.reconciliation.explain())
    add("the merged copy is kept as corroboration",
        any(group.merged for group in reconciled.reconciliation.groups),
        [_plain(group) for group in reconciled.reconciliation.groups])
    add("the canonical row cites the corroborating item",
        any(row.supporting_ids for row in reconciled.reconciliation.rows),
        [row.supporting_ids for row in reconciled.reconciliation.rows])
    # Two Workers made the same claim, so those two rows become one; the third is a
    # different claim and stays.  Nothing else is discarded (§36.2).
    add("reconciliation merges the duplicate rows and keeps the rest",
        len(reconciled.evidence) == 2, len(reconciled.evidence))
    add("a claim made once is not merged", all(
        not group.merged for group in clean.reconciliation.groups))
    add("the reconciliation can explain itself", bool(reconciled.reconciliation.explain()))

    # ---- 3. disagreements are preserved, never resolved ----------------
    add("two contradictory claims are a disagreement", bool(reconciled.disagreements),
        [item.describe for item in reconciled.disagreements])
    add("the disagreement names both sides",
        all(len(item.sides) >= 2 for item in reconciled.disagreements))
    add("a disagreement carries a resolution note, not a verdict",
        all(item.resolution and not item.resolved for item in reconciled.disagreements),
        [item.resolution[:60] for item in reconciled.disagreements])
    add("a negation counts as a contradiction",
        _contradicts("the gateway is affected", "the gateway is not affected"))
    add("another value of the same property is a contradiction",
        _contradicts("the attack began at 04:00", "the attack began at 05:30"))
    add("an agreeing restatement is not a contradiction",
        not _contradicts("the gateway is affected", "the gateway was affected"))
    add("a disagreement with no evidence on either side is refused",
        raises(lambda: Disagreement(
            statement="x", kind="value", sides=[
                DisagreementSide(worker_id="a", statement="one", evidence_ids=[]),
                DisagreementSide(worker_id="b", statement="two", evidence_ids=[])],
            resolution="the two Workers were asked again with the same brief"),
            ValueError))
    add("an agreement is not reported as a disagreement",
        not find_disagreements([
            ("a", "the gateway is affected", "low", ["ev-1"]),
            ("b", "the gateway is affected", "low", ["ev-2"])]))
    add("the reconciled rows are the ones that were kept",
        len(reconciled.reconciliation.rows) == len(reconciled.evidence),
        f"{len(reconciled.reconciliation.rows)} row(s), "
        f"{len(reconciled.evidence)} item(s)")

    # ---- 4. failed subtasks stay visible -------------------------------
    add("the withheld result is a failed subtask", bool(stopped.failed),
        [item.describe for item in stopped.failed])
    add("the failed subtask names its unit",
        stopped.failed and stopped.failed[0].worker_id == "wrk-b",
        [item.worker_id for item in stopped.failed])
    add("the failed subtask says what the mission loses",
        stopped.failed and len(stopped.failed[0].consequence) >= 8,
        stopped.failed[0].consequence if stopped.failed else "")
    add("the failed subtask records its attempt count",
        stopped.failed and stopped.failed[0].attempts >= 1)
    add("a forwarded result is not a failed subtask",
        not any(item.worker_id == "wrk-a" for item in stopped.failed))
    add("a failed subtask becomes a gap on the report",
        any("mirror-reader" in gap.detail or "wrk-b" in gap.detail
            for gap in bounded_partial_report(
                stopped, stop_ready,
                subagent=_demo_team()).gaps))

    # ---- 5. its own criteria are assessed, not asserted ----------------
    add("criteria are judged", bool(reconciled.checks), len(reconciled.checks))
    add("a met criterion cites the evidence that met it",
        all(check.evidence_ids for check in reconciled.checks if check.met),
        [check.evidence_ids for check in reconciled.checks])
    add("an unmet criterion states its shortfall",
        all(check.shortfall for check in reconciled.checks if not check.met),
        [check.shortfall for check in reconciled.checks if not check.met])
    checks_volume = assess_criteria(["at least 3 sources retrieved"], evidence=[
        _aggregate_evidence("one", tag="a", worker="w", url="https://a.test"),
        _aggregate_evidence("two", tag="b", worker="w", url="https://b.test")], reports=[])
    add("a volume criterion is counted, not assumed",
        checks_volume and not checks_volume[0].met and "2 item(s)" in checks_volume[0].shortfall,
        checks_volume[0].shortfall if checks_volume else "")
    checks_uncheckable = assess_criteria(["the report is convincing"], evidence=[
        _aggregate_evidence("one", tag="a", worker="w", url="https://a.test")], reports=[])
    add("an uncheckable criterion is not silently marked met",
        checks_uncheckable and not checks_uncheckable[0].met
        and "no mechanical test" in checks_uncheckable[0].shortfall,
        checks_uncheckable[0].shortfall if checks_uncheckable else "")
    add("an uncheckable criterion is not made critical",
        checks_uncheckable and not checks_uncheckable[0].critical)
    checks_hash = assess_criteria(["every item carries an integrity hash"], evidence=[
        _aggregate_evidence("one", tag="a", worker="w", url="https://a.test")], reports=[])
    add("a custody criterion is judged against the custody records",
        checks_hash and not checks_hash[0].met
        and "no recorded hash" in checks_hash[0].shortfall,
        checks_hash[0].shortfall if checks_hash else "")
    add("the aggregate declares no criteria rather than inventing them",
        not clean.checks, [check.describe for check in clean.checks])

    # ---- 6. the readiness decision, and every reason behind it ---------
    add("a clean aggregate is ready", clean.barrier.satisfied)
    add("a stopped aggregate is bounded, not ready", stop_ready.decision == "partial",
        stop_ready.summary())
    add("a bounded aggregate lists its critical gaps", bool(stop_ready.critical_gaps),
        stop_ready.critical_gaps)
    add("a bounded aggregate says why it cannot expand",
        bool(stop_ready.expansion_refusals), stop_ready.expansion_refusals)
    add("every refusal is reported, not just the first",
        len(expansion_refusals(
            _demo_team(),
            policy=FlowPolicy(allow_runtime_workers=False,
                              max_runtime_workers_per_subagent=0),
            runtime_spawned=1, licence_remaining=0)) >= 3,
        expansion_refusals(_demo_team(),
                           policy=FlowPolicy(allow_runtime_workers=False,
                                             max_runtime_workers_per_subagent=0),
                           runtime_spawned=1, licence_remaining=0))
    add("a cancelled mission may not expand",
        any("cancelled" in reason for reason in expansion_refusals(
            _demo_team(), policy=FlowPolicy(),
            runtime_spawned=0, licence_remaining=8, cancelled=True)))
    add("an expired deadline stops expansion",
        any("deadline" in reason for reason in expansion_refusals(
            _demo_team(), policy=FlowPolicy(),
            runtime_spawned=0, licence_remaining=8, deadline_expired=True)))
    add("a spent per-Subagent budget stops expansion",
        any("budget" in reason for reason in expansion_refusals(
            _demo_team(), policy=FlowPolicy(),
            runtime_spawned=2, licence_remaining=8)))
    add("an exhausted licence stops expansion",
        any("licence" in reason for reason in expansion_refusals(
            _demo_team(), policy=FlowPolicy(),
            runtime_spawned=0, licence_remaining=0)))
    add("the readiness summary is never empty", all(
        readiness.summary() for readiness in (stop_ready,)))
    add("a missing Worker is named as outstanding",
        assess_readiness(_demo_team(),
                         checks=[], gaps=[], settled=["a"], required=["a", "b"],
                         runtime_spawned=0, runtime_limit=2).missing == ["b"])

    # ---- 7. one more Worker, narrow and bounded ------------------------
    team = FlowSubagent(
        id="sa-plan", role="advisory", objective="read the advisories",
        workers=[FlowWorker(id="wrk-1", name="a", objective="read", tools=["advisory.fetch"],
                            completion_criteria=["at least 1 source retrieved"],
                            expected_evidence="≥1 observation item(s) from ≥1 source(s)")],
        completion_criteria=["at least 4 sources retrieved"],
        addresses_questions=["the published advisories name the affected component"])
    expand_ready = assess_readiness(team, checks=assess_criteria(
        team.completion_criteria, evidence=[], reports=[], questions=team.addresses_questions),
        gaps=[], settled=["wrk-1"], required=["wrk-1"], runtime_spawned=0, runtime_limit=2)
    add("an unmet criterion with budget is expandable", expand_ready.decision == "expand",
        expand_ready.summary())
    plan = plan_runtime_worker(team, readiness=expand_ready)
    add("the plan names the gap it closes", bool(plan.gap), plan.gap)
    add("the plan closes one gap, not all of them", len(plan.completion_criteria) == 1,
        plan.completion_criteria)
    add("the plan inherits the narrowest tool set it has",
        plan.tools == ["advisory.fetch"], plan.tools)
    add("the plan refuses to re-plan the whole assignment",
        raises(lambda: RuntimePlan(
            subagent_id="sa-plan", gap="close the whole mission", name="gap",
            objective="research everything about the target", work_unit="all",
            tools=["web.fetch"], expected_evidence="≥1 observation item(s) from ≥1 source",
            completion_criteria=["all of it"], rationale="the Subagent wants another go"),
            ValueError))
    add("a Subagent with no gap needs no Worker",
        raises(lambda: plan_runtime_worker(FlowSubagent(
            id="s", role="r", objective="o"), readiness=Readiness(
                subagent_id="s", ready=True, decision="ready")), ValueError))
    runtime_worker = runtime_worker_from_plan(plan, index=2, subagent=team)
    add("the runtime Worker is a Worker like any other",
        runtime_worker.output_schema and runtime_worker.completion_criteria,
        runtime_worker.name)
    add("the runtime Worker has its own id", runtime_worker.id not in
        {worker.id for worker in team.workers})
    add("the runtime Worker is bounded by the same attempts",
        runtime_worker.max_attempts <= 10)
    add("a license seat is spent, not borrowed",
        RuntimeSpawnRecord(subagent_id="sa-plan", worker_id=runtime_worker.id,
                           plan=plan, round=2, licence_remaining=6).licence_remaining == 6)

    # ---- 8. the flow really runs a runtime Worker ----------------------
    context = _selftest_context("exposure")
    units = flow_units_for(context, "exposure")
    flow = HierarchicalFlow(context=context, subagents=units,
                            runner=_CountingRunner(scope=context.scope_entries),
                            policy=FlowPolicy(max_review_rounds=2))
    result = flow.run()
    add("the mission completes with runtime Workers enabled",
        result.synthesis is not None and not result.stopped, result.stop_reason)
    aggregate_events = [event for event in result.trace
                        if event["stage"] == FlowStage.SUBAGENT_AGGREGATE.value]
    add("an aggregate can run more than once", len(aggregate_events) > len(units),
        f"{len(aggregate_events)} aggregate(s) for {len(units)} subagent(s)")
    runtime_rows = [row for report in result.reports for row in report.runtime_workers]
    add("a runtime Worker is recorded on the report", bool(runtime_rows),
        [row.describe for row in runtime_rows])
    add("the runtime Worker went through review",
        all(row.review_decision for row in runtime_rows),
        [row.review_decision for row in runtime_rows])
    add("the runtime Worker answered the gap it was planned for",
        all(row.answered for row in runtime_rows), [row.answered for row in runtime_rows])
    add("every report says whether it is ready", all(
        report.readiness is not None for report in result.reports))
    add("every report carries its reconciliation", all(
        report.reconciliation is not None for report in result.reports))
    add("a ready report met its criteria", all(
        report.readiness.ready for report in result.reports))

    # ``allow_runtime_workers`` binds the *Subagent's* own §36 expansion.  The Master's
    # §37 follow-up is a different budget on purpose, so it is switched off here too:
    # this check is about one switch, not about a mission with no expansion at all.
    bounded = HierarchicalFlow(
        context=context, subagents=flow_units_for(context, "exposure"),
        runner=_CountingRunner(scope=context.scope_entries),
        policy=FlowPolicy(max_review_rounds=2, allow_runtime_workers=False,
                          allow_follow_ups=False)).run()
    add("with expansion off no runtime Worker is created",
        not any(report.runtime_workers for report in bounded.reports),
        [len(report.runtime_workers) for report in bounded.reports])
    add("with expansion off the mission still reports",
        bool(bounded.reports) and bounded.synthesis is not None)
    add("the aggregate still waits for every Worker with expansion off",
        all(report.aggregate_basis and report.aggregate_basis.satisfied
            for report in bounded.reports))

    # §36's cap is the Subagent's own ceiling; §37's follow-up Workers are counted
    # against the Master's separate budget and are therefore excluded here on purpose.
    # Anything the Subagent itself planned beyond one is a breach of the cap.
    ceiling = HierarchicalFlow(
        context=context, subagents=flow_units_for(context, "exposure"),
        runner=_CountingRunner(scope=context.scope_entries),
        policy=FlowPolicy(max_review_rounds=2,
                          max_runtime_workers_per_subagent=1)).run()
    # A follow-up Worker is named ``follow-up-<id>`` by ``_follow_up_plan``; a Worker the
    # Subagent planned for its own gap is named ``gap-<id>`` by ``plan_runtime_worker``.
    self_planned = lambda report: [row for row in report.runtime_workers  # noqa: E731
                                   if row.spawned
                                   and not row.name.startswith("follow-up-")]
    add("the per-Subagent ceiling binds", all(
        len(self_planned(report)) <= 1 for report in ceiling.reports),
        [[row.name for row in self_planned(report)] for report in ceiling.reports])
    add("a mission at its ceiling still returns a report",
        bool(ceiling.reports) and ceiling.synthesis is not None)

    # ---- 9. the bounded partial report -------------------------------
    partial = bounded_partial_report(stopped, stop_ready, subagent=_demo_team())
    add("a bounded report is blocked rather than failed when anything survived",
        partial.status in {EntityStatus.BLOCKED, EntityStatus.FAILED},
        partial.status)
    add("a bounded report carries its gaps", bool(partial.gaps))
    add("a bounded report carries the failed subtasks", bool(partial.failed))
    add("a bounded report carries the criteria it missed",
        bool(partial.criteria_checks) or not stopped.checks)
    add("a bounded report keeps the readiness record", partial.readiness is not None)
    add("a bounded report with no evidence at all is a failure",
        bounded_partial_report(
            stopped.model_copy(update={"evidence": [], "forwarded": []}), stop_ready,
            subagent=_demo_team()).status is EntityStatus.FAILED)
    complete = complete_report(clean, Readiness(subagent_id="sa-demo", ready=True,
                                                decision="ready"),
                               subagent=_demo_team())
    add("a complete report succeeds", complete.succeeded, complete.status)
    add("a complete report keeps the reconciliation", complete.reconciliation is not None)

    # ---- 10. the record survives serialisation ------------------------
    payload = reconciled.to_dict()
    add("the aggregate serialises", payload["barrier"]["satisfied"])
    add("the serialised aggregate keeps its disagreements",
        len(payload["disagreements"]) == len(reconciled.disagreements))
    add("the serialised aggregate keeps its failed subtasks",
        len(payload["failed"]) == len(reconciled.failed))
    add("the readiness record serialises",
        stop_ready.to_dict()["decision"] == "partial")
    add("the plan serialises", plan.to_dict()["gap"] == plan.gap)
    demo = aggregate_demo()
    add("the demo payload is serialisable",
        json.loads(json.dumps(demo, default=str))["acceptance"]["all_signals"])
    add("the demo shows every signal passing",
        all(demo["acceptance"]["signals"].values()),
        [name for name, ok in demo["acceptance"]["signals"].items() if not ok])
    return checks


# ══════════════════════════════════════════════════════════════════════════
# 37. Master review and bounded replanning: a mission that knows when to stop
# --------------------------------------------------------------------------
#
# §36 gave a Subagent the right to plan one more Worker for its *own* gaps.  This
# section gives the Master the same right over the mission — and, more importantly,
# the obligation to refuse it.  After every Subagent has reported the Master asks
# five questions of each report: is it about this mission (relevance), can it carry
# its claims (sufficiency), does it contradict another report (contradictions), does
# it repeat one (duplication), and what does nobody cover (coverage).  Those five
# answers become a bounded follow-up assignment — to an existing Subagent, or to a
# new runtime Subagent that goes through the same specification gates as the planned
# ones (§22, §23).
#
# The acceptance clause is not "the Master may replan".  It is *the system cannot
# loop indefinitely and always reaches a final or partial report*.  So the loop is
# bounded in five independent places, and every one of them is on the record:
#
# 1.  **A round cap.**  ``FlowPolicy.max_replan_rounds`` (default 1) limits how many
#     follow-up rounds a mission may open at all.  The cap is a *policy* number, not
#     a recursion limit: the graph's own limit is left free, so the bound is one a
#     reader can point at in the result rather than one that arrives as an exception.
# 2.  **A review budget.**  ``FlowPolicy.max_master_reviews`` (default 3) limits how
#     many times the Master may review in one mission.  Round cap and review budget
#     are deliberately two numbers: with ``max_replan_rounds=0`` the mission still
#     reviews once, which is what makes "review without replanning" a real mode.
# 3.  **A spawn licence.**  A new runtime Subagent costs a seat out of the Master's
#     :class:`SpawnLedger` licence, which cannot be topped up.  A follow-up to an
#     existing Subagent costs nothing from that licence — but it still has to fit in
#     that Subagent's own runtime Worker budget (§36), so neither route is free.
# 4.  **The mission deadline.**  An expired deadline refuses the next round, and the
#     partial report says so instead of starting work it cannot finish.
# 5.  **Saturation.**  A round that collects no new evidence (nothing the mission did
#     not already hold) ends the loop even if every other bound still has room: more
#     identical work is not more evidence, and "we could look again" is not a reason
#     to.
#
# Every refusal is *recorded*, not merely obeyed.  A ``MasterDecision`` that says
# `stop` carries the whole list — round cap, licence, deadline, saturation — so the
# final report can explain why it stopped asking rather than leaving the reader to
# guess.  That is the same discipline §36 applied to a Subagent's readiness, one
# level up.


class StopCondition(str, Enum):
    """Why the Master stopped asking for more work.

    The five conditions are the task's own list, and drawing a *complete* boundary
    around them is what makes the loop analysable: a mission that finished has
    exactly one of these on its record, and every one of them is either a success
    (the work is done, or further work is provably useless) or a bound the operator
    set.  ``NONE`` exists for the single review a stopped mission never reaches —
    it is never the reason a loop ended, because a loop that never ran did not end.
    """

    NONE = "none"                  # no stop: the loop is still running
    COMPLETE = "complete"          # every mission completion criterion is met
    SATURATION = "saturation"      # another round added no new evidence
    BUDGET = "budget"              # the round cap or the review budget is spent
    DEADLINE = "deadline"          # the mission deadline has expired
    BLOCKED = "blocked"            # the remaining work cannot be done at all

    @property
    def is_success(self) -> bool:
        """Whether stopping here means the mission actually finished its work."""

        return self in {StopCondition.COMPLETE, StopCondition.SATURATION}

    @property
    def explains_itself(self) -> bool:
        """Every condition except ``NONE`` is a bound the record can describe."""

        return self is not StopCondition.NONE


class ReviewLens(str, Enum):
    """The five questions the Master asks of every Subagent report.

    These are lenses, not scores: each one produces at most one finding per report,
    with the evidence it looked at and the remedy it implies.  A lens that found
    nothing says so, because "the Master looked and had no complaint" is a different
    fact from "the Master did not look" — and only the first one belongs in a report.
    """

    RELEVANCE = "relevance"            # is this about the mission at all?
    SUFFICIENCY = "sufficiency"        # can this report carry its claims?
    CONTRADICTIONS = "contradictions"  # does it disagree with another report?
    DUPLICATION = "duplication"        # does it repeat work already done?
    COVERAGE = "coverage"              # what does nobody cover?


class LensVerdict(str, Enum):
    """What one lens concluded about one report.

    ``SATISFIED`` and ``CONCERNS`` are the two ordinary outcomes; ``NOT_APPLICABLE``
    is for a lens with nothing to judge (a report that collected no evidence cannot
    duplicate anything).  Keeping the third case explicit is what stops the review
    from quietly treating "no data" as "no problem".
    """

    SATISFIED = "satisfied"
    CONCERNS = "concerns"
    NOT_APPLICABLE = "not-applicable"


class MasterLensFinding(StrictModel):
    """One lens's conclusion about one report, with what a remedy would target.

    ``target`` is the part of the report the finding is about — a claim, a question,
    a role — and it is what a follow-up assignment points at.  A finding with no
    target is a complaint the Master cannot act on, so the model refuses one.
    """

    lens: ReviewLens
    verdict: LensVerdict = LensVerdict.SATISFIED
    #: What the lens looked at, kept so a reader can reproduce the judgement.
    checked: str = ""
    target: str = ""
    detail: str = ""
    #: The evidence ids the finding rests on, when it rests on evidence.
    evidence_ids: list[str] = Field(default_factory=list)
    #: Whether a follow-up assignment would be a remedy.  A lens may find a concern
    #: that no further work can fix (a source that does not exist), and saying so is
    #: the difference between a plan and a wish.
    actionable: bool = False
    remedy: str = ""

    @model_validator(mode="after")
    def _consistent(self) -> "MasterLensFinding":
        if self.verdict is LensVerdict.SATISFIED and (self.detail or self.target):
            raise ValueError("a satisfied lens has nothing to complain about, so it "
                             "names no target and no detail")
        if self.verdict is LensVerdict.CONCERNS:
            if len(self.detail.strip()) < 12:
                raise ValueError("a concern must say what is wrong, in a sentence a "
                                 "reader can check")
            if not self.target.strip():
                raise ValueError("a concern must name the target a remedy would act on")
        if self.actionable and not self.remedy.strip():
            raise ValueError("an actionable finding must say what would remedy it")
        if self.verdict is LensVerdict.NOT_APPLICABLE and self.actionable:
            raise ValueError("a lens with nothing to judge has nothing to remedy")
        return self

    @property
    def concerning(self) -> bool:
        return self.verdict is LensVerdict.CONCERNS

    def describe(self) -> str:
        if self.verdict is LensVerdict.SATISFIED:
            return f"{self.lens.value}: satisfied — {self.checked[:120]}"
        if self.verdict is LensVerdict.NOT_APPLICABLE:
            return f"{self.lens.value}: not applicable — {self.checked[:120]}"
        tail = f" → {self.remedy[:100]}" if self.actionable else " (no remedy available)"
        return f"{self.lens.value}: {self.detail[:140]}{tail}"


class ReportReview(StrictModel):
    """One Subagent report, judged on all five lenses.

    The record is deliberately per-report rather than per-lens-over-the-mission:
    a concern belongs to the report it is about, so the follow-up it justifies has
    an owner.  Mission-wide coverage gaps are the one exception, and they are
    attached to the report whose scope they fall nearest to — with ``covers_all``
    set when the gap is nobody's in particular.
    """

    subagent_id: str = Field(min_length=1)
    role: str = ""
    status: EntityStatus = EntityStatus.SUCCEEDED
    findings: list[MasterLensFinding] = Field(default_factory=list)

    @model_validator(mode="after")
    def _all_five_lenses(self) -> "ReportReview":
        seen = [finding.lens for finding in self.findings]
        missing = [lens.value for lens in ReviewLens if lens not in seen]
        if missing:
            raise ValueError(f"a report review answers all five lenses; missing "
                             f"{', '.join(missing)}")
        if len(seen) != len(set(seen)):
            raise ValueError("a report review answers each lens once")
        return self

    def finding(self, lens: ReviewLens) -> MasterLensFinding:
        return next(item for item in self.findings if item.lens is lens)

    @property
    def concerns(self) -> list[MasterLensFinding]:
        return [item for item in self.findings if item.concerning]

    @property
    def actionable(self) -> list[MasterLensFinding]:
        return [item for item in self.concerns if item.actionable]

    @property
    def satisfied(self) -> bool:
        return not self.concerns

    def summary(self) -> str:
        if self.satisfied:
            return f"{self.role or self.subagent_id}: all five lenses satisfied"
        names = ", ".join(finding.lens.value for finding in self.concerns)
        return (f"{self.role or self.subagent_id}: {len(self.concerns)} concern(s) "
                f"({names}); {len(self.actionable)} actionable")

    def to_dict(self) -> dict[str, Any]:
        return {"subagent_id": self.subagent_id, "role": self.role,
                "status": self.status.value,
                "findings": [{"lens": finding.lens.value,
                              "verdict": finding.verdict.value,
                              "target": finding.target, "detail": finding.detail,
                              "checked": finding.checked,
                              "evidence_ids": list(finding.evidence_ids),
                              "actionable": finding.actionable,
                              "remedy": finding.remedy}
                             for finding in self.findings],
                "concerns": len(self.concerns), "actionable": len(self.actionable),
                "summary": self.summary()}


class CoverageGap(StrictModel):
    """A question or criterion no report answers, and how it was established.

    A gap is only worth a follow-up if it is *checkable*: ``checked_by`` names the
    rule that decided it, so the Master cannot open a round on a hunch.  ``owner``
    is the report nearest the gap when one exists, which is what makes a follow-up
    to an existing Subagent possible instead of always creating a new one.
    """

    target: str = Field(min_length=1)
    #: ``question``, ``criterion`` or ``objective``.
    kind: str = Field(default="question", pattern="^(question|criterion|objective)$")
    #: The role whose report should have covered it, when one should have.
    owner: str = ""
    checked_by: str = ""
    detail: str = ""

    @property
    def owned(self) -> bool:
        return bool(self.owner.strip())

    def describe(self) -> str:
        where = f" (nearest: {self.owner})" if self.owned else " (unassigned)"
        return f"{self.kind}: {self.target[:160]}{where}"


class FollowUpAssignment(StrictModel):
    """One bounded piece of extra work, addressed to somebody specific.

    The task allows two routes and this model is both of them: ``EXISTING`` means
    the assignment goes to a Subagent the mission already has (it plans one more
    Worker for the gap, through §36's gates), and ``NEW`` means the Master spends a
    licence seat on a Subagent that did not exist.  ``route`` is a field rather than
    an inference so the record says which bound applied: an existing Subagent's
    runtime budget or the Master's spawn licence.
    """

    route: str = Field(pattern="^(existing|new)$")
    target_subagent: str = ""
    role: str = Field(min_length=3)
    objective: str = Field(min_length=15)
    #: The gap, quoted from the review that found it.
    gap: str = Field(min_length=12)
    #: Which lens justified the assignment.  A follow-up with no lens behind it is
    #: the Master re-planning the mission, which is not what this loop is for.
    lens: ReviewLens
    #: What the assignment must return, in countable terms.
    completion_criteria: list[str] = Field(min_length=1)
    #: The tools it may use — the narrowest set the mission already holds, never a
    #: widened grant.
    tools: list[str] = Field(default_factory=list)
    justification: str = Field(min_length=15)
    #: The round this assignment belongs to, so a later round can tell whether the
    #: gap it was created for is still open.
    round: int = Field(default=1, ge=1)
    #: The seat it spent, when it spent one: ``""`` for an existing Subagent.
    licence_remaining: int | None = None

    @model_validator(mode="after")
    def _route_is_carried_through(self) -> "FollowUpAssignment":
        if self.route == "existing" and not self.target_subagent.strip():
            raise ValueError("a follow-up to an existing Subagent must name it")
        if self.route == "new" and self.target_subagent.strip():
            raise ValueError("a follow-up that creates a Subagent cannot also name an "
                             "existing one")
        if self.route == "existing" and self.licence_remaining is not None:
            raise ValueError("only a new Subagent spends the Master's licence")
        unbounded = unbounded_instruction(self.objective)
        if unbounded:
            raise ValueError(
                f"a follow-up must stop somewhere; {unbounded!r} has no end condition "
                "the next review could test")
        if any(word in self.objective.lower()
               for word in ("everything", "all of the", "any remaining")):
            raise ValueError("a follow-up closes one gap: an objective that restates "
                             "the whole mission is a replan, not a remedy")
        return self

    def describe(self) -> str:
        where = (f"→ {self.target_subagent}" if self.route == "existing"
                 else "→ new subagent")
        return (f"round {self.round} {where} for {self.lens.value}: "
                f"{self.objective[:110]}")

    def to_dict(self) -> dict[str, Any]:
        return {"route": self.route, "target_subagent": self.target_subagent,
                "role": self.role, "objective": self.objective, "gap": self.gap,
                "lens": self.lens.value,
                "completion_criteria": list(self.completion_criteria),
                "tools": list(self.tools), "justification": self.justification,
                "round": self.round, "licence_remaining": self.licence_remaining}


class MasterReview(StrictModel):
    """One pass of the Master over every report it has received.

    The review is the *decision input*, not the decision: it records what each lens
    saw and what the mission still does not cover, and :func:`decide_master` turns
    that into a stop-or-continue with every refusal listed.  Splitting them is what
    lets the self-test hold the observations fixed and vary only the budget.
    """

    #: Which review of the mission this is: 1-based, and never renumbered.
    round: int = Field(default=1, ge=1)
    observations: list[ReportReview] = Field(default_factory=list)
    #: Mission-level gaps: what no report covers.
    coverage: list[CoverageGap] = Field(default_factory=list)
    #: The mission criteria this review judged, and whether each was met.
    criteria_met: list[str] = Field(default_factory=list)
    criteria_unmet: list[str] = Field(default_factory=list)
    #: Evidence the mission held when this review began, so the next round can
    #: tell what it added.
    evidence_ids: list[str] = Field(default_factory=list)
    #: What this review waited for, as §36 does one level down.
    barrier: JoinBarrier | None = None

    @model_validator(mode="after")
    def _one_observation_per_report(self) -> "MasterReview":
        ids = [item.subagent_id for item in self.observations]
        if len(ids) != len(set(ids)):
            raise ValueError("a review observes each report once; a duplicate "
                             "observation would double-count its evidence")
        return self

    @property
    def concerns(self) -> list[MasterLensFinding]:
        return [finding for item in self.observations for finding in item.concerns]

    @property
    def actionable(self) -> list[MasterLensFinding]:
        """Concerns a follow-up could actually address, in report order."""

        return [finding for item in self.observations for finding in item.actionable]

    @property
    def complete(self) -> bool:
        """Whether the mission's own completion criteria are all met.

        Vacuously true is not true: a review that judged no mission criteria has not
        established that the mission is finished, so it has to say so rather than
        claim a completeness it never tested.
        """

        return bool(self.criteria_met) and not self.criteria_unmet

    @property
    def open_targets(self) -> list[str]:
        """Every gap worth another round: actionable concerns, then coverage gaps."""

        targets = [f"{finding.lens.value}: {finding.target}"[:200]
                   for finding in self.actionable]
        targets.extend(gap.describe() for gap in self.coverage)
        return list(dict.fromkeys(targets))

    def by_satisfaction(self) -> dict[str, int]:
        satisfied = sum(1 for item in self.observations if item.satisfied)
        return {"satisfied": satisfied, "concerns": len(self.observations) - satisfied}

    def summary(self) -> str:
        counts = self.by_satisfaction()
        return (f"review {self.round}: {counts['satisfied']} report(s) satisfied, "
                f"{counts['concerns']} with concerns "
                f"({len(self.actionable)} actionable); {len(self.coverage)} coverage "
                f"gap(s); {len(self.criteria_unmet)} unmet criterion/criteria")

    def to_dict(self) -> dict[str, Any]:
        return {"round": self.round,
                "observations": [item.to_dict() for item in self.observations],
                "coverage": [gap.describe() for gap in self.coverage],
                "criteria_met": list(self.criteria_met),
                "criteria_unmet": list(self.criteria_unmet),
                "evidence": len(self.evidence_ids),
                "barrier": self.barrier.describe() if self.barrier else "not met",
                "summary": self.summary()}


class MasterDecision(StrictModel):
    """Stop or continue, with every bound that had a say.

    ``continue`` is only reachable when *no* bound refused the round and at least one
    actionable gap exists.  ``refusals`` is therefore never empty on a ``stop`` that
    was not a success: an operator who asks "why did it stop here?" gets the whole
    list rather than the first branch that returned.
    """

    #: ``continue``, ``stop`` or ``final`` — ``final`` is a stop the Master reached
    #: by finishing the mission's own criteria, and it is kept separate so a report
    #: can say "done" without also having to say "and here is why I could not go on".
    action: str = Field(pattern="^(continue|stop|final)$")
    condition: StopCondition = StopCondition.NONE
    round: int = Field(default=1, ge=1)
    #: The assignments the next round would run, in priority order.  Empty on a stop.
    assignments: list[FollowUpAssignment] = Field(default_factory=list)
    #: Every bound that refused more work, in precedence order.
    refusals: list[str] = Field(default_factory=list)
    basis: str = Field(min_length=12)

    @model_validator(mode="after")
    def _consistent(self) -> "MasterDecision":
        if self.action == "continue":
            if not self.assignments:
                raise ValueError("a continue decision carries the work it continues "
                                 "with; otherwise it is a stop in disguise")
            if self.refusals:
                raise ValueError("a continue decision has no bound refusing it")
            if self.condition is not StopCondition.NONE:
                raise ValueError("continuing is not a stop condition")
        else:
            if self.assignments:
                raise ValueError("a stop decision does not carry assignments: the work "
                                 "it would have done is the refusal, not a plan")
            if self.condition is StopCondition.NONE:
                raise ValueError("a stop decision names the condition that stopped it")
        if self.action == "final" and self.condition is not StopCondition.COMPLETE:
            raise ValueError("a final decision means the completion criteria were met")
        return self

    @property
    def stopped(self) -> bool:
        return self.action != "continue"

    @property
    def finished(self) -> bool:
        """Whether the mission may synthesise a complete answer."""

        return self.action == "final"

    def summary(self) -> str:
        if self.action == "continue":
            return (f"continue (round {self.round}): {len(self.assignments)} "
                    f"assignment(s) — {self.basis[:120]}")
        if self.action == "final":
            return f"final: {self.basis[:140]}"
        return (f"stop ({self.condition.value}): {self.basis[:120]}"
                + (f" [{len(self.refusals)} refusal(s)]" if self.refusals else ""))

    def to_dict(self) -> dict[str, Any]:
        return {"action": self.action, "condition": self.condition.value,
                "round": self.round,
                "assignments": [item.to_dict() for item in self.assignments],
                "refusals": list(self.refusals), "basis": self.basis,
                "summary": self.summary()}


class ReplanRound(StrictModel):
    """One round of the review → decide → assign loop, as it happened.

    Kept because the loop's *history* is the evidence that it was bounded: a mission
    that opened three rounds and stopped at the cap has a record of three, and a
    reader can check each one against the budget instead of trusting a boolean.
    """

    round: int = Field(ge=1)
    review: MasterReview
    decision: MasterDecision
    #: Evidence count before and after the round, so saturation is checkable.
    evidence_before: int = Field(default=0, ge=0)
    evidence_after: int = Field(default=0, ge=0)
    #: The Subagent ids this round created, and the ones it asked for more work.
    created: list[str] = Field(default_factory=list)
    revisited: list[str] = Field(default_factory=list)
    seconds: float = Field(default=0.0, ge=0)

    @property
    def added(self) -> int:
        """Net new evidence this round: the saturation signal, as a number."""

        return max(0, self.evidence_after - self.evidence_before)

    def to_dict(self) -> dict[str, Any]:
        return {"round": self.round, "review": self.review.to_dict(),
                "decision": self.decision.to_dict(),
                "evidence_before": self.evidence_before,
                "evidence_after": self.evidence_after, "added": self.added,
                "created": list(self.created), "revisited": list(self.revisited),
                "seconds": round(self.seconds, 3)}



# --------------------------------------------------------------------------
# 37.6 The demo's own check record
# --------------------------------------------------------------------------


class MasterReviewCheck(StrictModel):
    """One assertion in the §37 self-test."""

    name: str = Field(min_length=1)
    ok: bool
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "ok": self.ok, "detail": self.detail}



# --------------------------------------------------------------------------
# 37.1 The five lenses, applied to a report
# --------------------------------------------------------------------------


def _topic_words(text: str) -> set[str]:
    """The content words of a statement, folded and stop-worded.

    Deliberately the same fold the aggregate uses (§36.2), so "the same thing" means
    the same thing across the two sections: a reader comparing a Subagent's
    reconciliation with the Master's duplication lens is comparing like with like.

    One difference is deliberate.  ``_claim_key`` drops hyphens, because two spellings
    of one claim should compare equal; for *topic* matching that is wrong — an
    objective about "advisory-backed risks" and a role called "published-advisories"
    share a subject, and folding both to one word loses it.  Word separators are
    therefore split before the fold here, and only here.
    """

    split = re.sub(r"[^a-z0-9]+", " ", text.lower())
    return {word for word in _claim_key(split).split()
            if len(word) > 3 and word not in _RELEVANCE_STOPWORDS}


def _objective_focus(objective: str) -> set[str]:
    """The words of the mission objective that a report must be *about*.

    Two words is the threshold everywhere else in this build, and it is the right one
    here too: a report that shares one word with the objective ("example.com") shares a
    noun, not a subject.
    """

    return _topic_words(objective)


def _report_statements(report: "SubagentOutcome") -> list[str]:
    """Everything a report asserts, in the order it asserts it."""

    lines = [item.statement for item in report.evidence]
    lines.extend(outcome.summary for outcome in report.outcomes if outcome.summary)
    return [line for line in lines if line.strip()]


#: Phrases that make a line a *bookkeeping* record rather than a claim about the
#: target: a count of what a Worker did, or a restatement of the assignment it was
#: given.  Both are honest, and neither is evidence about the world, so the
#: contradiction and duplication lenses read past them.  Without this, two Workers
#: given different jobs look like two Workers contradicting each other about one.
_BOOKKEEPING = re.compile(
    r"observation\(s\) collected|the result addresses|^gapgap|^gap-", re.IGNORECASE)


def _is_bookkeeping(line: str) -> bool:
    """True when a statement reports what a Worker did rather than what it found."""

    return bool(_BOOKKEEPING.search(_claim_key(line)[:80])) or bool(
        _BOOKKEEPING.search(line))


def _relevance_finding(report: "SubagentOutcome", focus: set[str],
                       scope: set[str] | None = None) -> MasterLensFinding:
    """Is this report about the mission, or about something adjacent to it?

    "About" is judged against the report's whole record — the assignment it was given
    and the assertions it returned — because a Worker whose own statement is narrow
    ("every record type has a value or an unknown") is still doing mission work if its
    assignment names the mission's subject.  A test that only read the statements would
    call honest narrow work irrelevant, which would make the lens useless.

    Three tests, in decreasing strength, and any one of them settles it:

    1.  **two content words** shared with the mission objective — the same threshold
        §36 uses for "the same subject", so the two sections agree about what "about"
        means;
    2.  **one objective word and one scope word** — the report names both the mission's
        subject and its authorised target, which is specific even when the vocabulary
        is thin;
    3.  **two words** shared between the report's *objective* and the mission's — the
        assignment itself is on-mission, whatever the rows came back saying.

    A report with no assertions, no objective and no role is not *irrelevant*: there is
    nothing to be relevant.  That is the sufficiency lens's problem, and this one says
    so rather than inventing a concern.
    """

    scope = scope or set()
    statements = _report_statements(report)
    assignment = " ".join(part for part in (report.role, report.objective) if part)
    if not statements and not assignment.strip():
        return MasterLensFinding(
            lens=ReviewLens.RELEVANCE, verdict=LensVerdict.NOT_APPLICABLE,
            checked="the report asserts nothing and was assigned nothing, so relevance "
                    "has no subject")
    checked_lines = [assignment] if assignment.strip() else []
    checked_lines.extend(line for line in statements if not _is_bookkeeping(line))
    strong: list[str] = []
    weak: list[str] = []
    for line in checked_lines:
        words = _topic_words(line)
        if len(words & focus) >= 2:
            strong.append(line)
        elif len(words & focus) >= 1 and len(words & scope) >= 1:
            weak.append(line)
    in_scope_of_work = len(_topic_words(assignment) & focus) >= 2
    if strong or in_scope_of_work:
        return MasterLensFinding(
            lens=ReviewLens.RELEVANCE, verdict=LensVerdict.SATISFIED,
            checked=(f"{len(strong)} line(s) share two content words with the objective; "
                     f"the assignment is on-mission: "
                     f"{'yes' if in_scope_of_work else 'no'}"))
    if weak:
        return MasterLensFinding(
            lens=ReviewLens.RELEVANCE, verdict=LensVerdict.SATISFIED,
            checked=(f"{len(weak)} line(s) name both the mission's subject and its "
                     f"authorised target"))
    return MasterLensFinding(
        lens=ReviewLens.RELEVANCE, verdict=LensVerdict.CONCERNS,
        target=(report.role or report.subagent_id),
        detail=("nothing it asserts and nothing it was assigned shares two content "
                "words with the mission objective, and nothing it names is in scope"),
        actionable=True,
        remedy=(f"re-point {report.role or report.subagent_id} at the objective and "
                f"re-read its own sources for what bears on it"))


def _sufficiency_finding(report: "SubagentOutcome") -> MasterLensFinding:
    """Can this report carry its claims: evidence, a join, and no withheld gap.

    Sufficiency is not "enough evidence" in the abstract — the mission has no such
    threshold and inventing one would make the review arbitrary.  It is three
    checkable things: the report brought evidence, its aggregate waited for its
    Workers, and nothing it withheld was left unexplained.
    """

    problems: list[str] = []
    if not report.evidence:
        problems.append("it carries no evidence at all")
    if report.aggregate_basis is not None and not report.aggregate_basis.satisfied:
        problems.append(f"its join was not met ({report.aggregate_basis.describe()})")
    unexplained = [item for item in report.failed if not item.consequence.strip()]
    if unexplained:
        problems.append(f"{len(unexplained)} withheld unit(s) have no stated consequence")
    if report.readiness is not None and report.readiness.missing:
        problems.append(f"{len(report.readiness.missing)} required Worker(s) never settled")
    if not problems:
        return MasterLensFinding(
            lens=ReviewLens.SUFFICIENCY, verdict=LensVerdict.SATISFIED,
            checked=(f"{len(report.evidence)} evidence item(s), join met, "
                     f"{len(report.withheld)} withheld unit(s) explained"),
            evidence_ids=report.evidence_ids[:10])
    return MasterLensFinding(
        lens=ReviewLens.SUFFICIENCY, verdict=LensVerdict.CONCERNS,
        target=(report.role or report.subagent_id),
        detail=("; ".join(problems))[:300],
        evidence_ids=report.evidence_ids[:10],
        actionable=not report.evidence,
        remedy=("give the report evidence to carry: one sourced observation per claim"
                if not report.evidence else
                "re-run the units whose work was withheld and forward what passes"))


def _contradiction_findings(report: "SubagentOutcome",
                            others: Sequence["SubagentOutcome"]) -> MasterLensFinding:
    """Does this report disagree with another one — and is the disagreement visible?

    The Master's job here is *not* to settle the conflict; §36 already froze it with
    both sides and what would settle it.  The Master's job is to notice a conflict the
    reports did not record for themselves, which is the case that would otherwise
    reach synthesis as two flatly contradictory claims with nothing marking them.
    """

    recorded = list(report.disagreements)
    # Worker bookkeeping ("advisory-reader: 1 observation(s) collected") differs only in
    # the count, so a naive comparison reads two Workers doing different jobs as a
    # disagreement about the target.  Contradictions are about the *target*, so the
    # statements considered here are the ones that are not bookkeeping.
    left_rows = [line for line in _report_statements(report) if not _is_bookkeeping(line)]
    for other in others:
        right_rows = [line for line in _report_statements(other) if not _is_bookkeeping(line)]
        for left in left_rows:
            for right in right_rows:
                if not _contradicts(left, right):
                    continue
                if any(left[:60] == item.left_statement[:60]
                       and right[:60] == item.right_statement[:60]
                       for item in recorded):
                    continue
                return MasterLensFinding(
                    lens=ReviewLens.CONTRADICTIONS, verdict=LensVerdict.CONCERNS,
                    target=(report.role or report.subagent_id),
                    detail=(f"contradicts {other.role or other.subagent_id} without "
                            f"recording it: {left[:90]} vs {right[:90]}")[:300])
    if recorded:
        return MasterLensFinding(
            lens=ReviewLens.CONTRADICTIONS, verdict=LensVerdict.SATISFIED,
            checked=(f"{len(recorded)} disagreement(s) frozen with both sides and a "
                     f"stated resolution path"))
    return MasterLensFinding(
        lens=ReviewLens.CONTRADICTIONS, verdict=LensVerdict.SATISFIED,
        checked="no statement in this report contradicts another report")


def _duplication_finding(report: "SubagentOutcome",
                         others: Sequence["SubagentOutcome"]) -> MasterLensFinding:
    """Does this report repeat another one — and was the repetition reconciled?

    Two Workers finding the same record is corroboration and §36 keeps it.  Two
    *reports* making the same claim is duplication: nothing new was learned, and the
    mission is paying licence and time for a second opinion that is really a first
    one.  The lens therefore measures claims that normalise to the same statement
    across reports, and asks whether the reports noticed.
    """

    # Only substantive assertions are candidates for duplication: a bookkeeping line
    # ("3 observation(s) collected") is about the Worker, and two Workers reporting
    # their own counts is not the mission learning the same thing twice.
    own = [_claim_key(line) for line in _report_statements(report)
           if not _is_bookkeeping(line)]
    if not own:
        return MasterLensFinding(
            lens=ReviewLens.DUPLICATION, verdict=LensVerdict.NOT_APPLICABLE,
            checked="the report asserts nothing, so it duplicates nothing")
    shared = 0
    example = ""
    for other in others:
        theirs = {_claim_key(line) for line in _report_statements(other)
                  if not _is_bookkeeping(line)}
        hits = [key for key in own if key in theirs]
        if hits:
            shared += len(hits)
            example = example or hits[0]
    if not shared:
        return MasterLensFinding(
            lens=ReviewLens.DUPLICATION, verdict=LensVerdict.SATISFIED,
            checked=f"none of its {len(own)} assertion(s) repeats another report")
    reconciled = bool(report.reconciliation.merged)
    if reconciled:
        return MasterLensFinding(
            lens=ReviewLens.DUPLICATION, verdict=LensVerdict.SATISFIED,
            checked=(f"{shared} claim(s) repeat another report and were reconciled "
                     f"inside the aggregate"))
    return MasterLensFinding(
        lens=ReviewLens.DUPLICATION, verdict=LensVerdict.CONCERNS,
        target=(report.role or report.subagent_id),
        detail=(f"{shared} assertion(s) restate another report and the aggregate did not "
                f"reconcile them; e.g. {example[:120]}"),
        actionable=False,
        remedy="")


def _coverage_gaps(reports: Sequence["SubagentOutcome"], *,
                   questions: Sequence[str] = (),
                   criteria: Sequence[str] = ()) -> list[CoverageGap]:
    """What nobody covers: unanswered questions, then unmet mission criteria.

    The test for "answered" is deliberately stingy.  A statement counts as an answer
    when it shares subject matter with the question *and* says something the question
    did not — otherwise a Worker whose whole finding is "the result addresses: <the
    question>" would mark the question answered by echoing it.  That is exactly the
    failure mode a coverage review exists to catch, so the echo guard is the point of
    the function rather than a detail of it.
    """

    gaps: list[CoverageGap] = []
    for question in dict.fromkeys(text.strip() for text in questions if text.strip()):
        wanted = _topic_words(question)
        if not wanted:
            continue
        owner = ""
        answered = False
        for report in reports:
            for check in _report_criteria(report):
                if check.met and len(_topic_words(check.criterion) & wanted) >= 2:
                    answered = True
                    break
            if answered:
                break
            for statement in _report_statements(report):
                words = _topic_words(statement)
                if len(words & wanted) < 2:
                    continue
                # An echo adds nothing: if the statement's content words are a subset
                # of the question's, it restates the question rather than answering it.
                if not (words - wanted):
                    continue
                answered = True
                break
            if answered:
                break
        if answered:
            continue
        owner = next((report.role for report in reports
                      if any(_topic_words(question) & wanted == _topic_words(question) & wanted
                             for _ in report.open_questions)), "")
        gaps.append(CoverageGap(
            target=question, kind="question", owner=owner,
            checked_by=("no report's met criterion or non-echoing statement shares two "
                        "content words with it"),
            detail="nobody answered it"))
    for criterion in dict.fromkeys(text.strip() for text in criteria if text.strip()):
        wanted = _topic_words(criterion)
        met = any(check.met and (len(_topic_words(check.criterion) & wanted) >= 2
                                 or _claim_key(check.criterion) == _claim_key(criterion))
                  for report in reports for check in _report_criteria(report))
        if met:
            continue
        gaps.append(CoverageGap(
            target=criterion, kind="criterion", owner="",
            checked_by="no report's criterion checks record it as met",
            detail="the mission criterion is not satisfied by any report"))
    return gaps


def _report_criteria(report: "SubagentOutcome") -> list["CriterionCheck"]:
    """The criteria checks a report carries — ``[]`` for a report that never ran."""

    return list(report.criteria_checks or [])


def review_reports(reports: Sequence["SubagentOutcome"], *,
                   objective: str = "",
                   questions: Sequence[str] = (),
                   criteria: Sequence[str] = (),
                   scope_entries: Sequence[str] = (),
                   round_number: int = 1,
                   evidence_ids: Sequence[str] = (),
                   mission_checks: Sequence["CriterionCheck"] = ()) -> MasterReview:
    """Apply all five lenses to every report, and collect what nobody covers.

    Deterministic and offline, like every other judgement in this build: the Master
    reviews the *record*, never a model's opinion of it.  A grader that can be argued
    into a pass is not a control.

    Four lenses are per-report and are applied in the loop.  The fifth — coverage — is
    mission-wide by construction (nothing covers a gap), so it is computed once and
    then *assigned*: a gap naming an owner lands on that report, and a gap nobody owns
    lands on every report that could plausibly have caught it.  "Could plausibly have"
    is decided by :func:`_nearest_owners`, which is deliberately generous: a gap with
    no plausible owner is reported at the mission level and is nobody's concern lens.
    """

    focus = _objective_focus(objective)
    scope = set()
    for entry in scope_entries:
        scope |= _topic_words(str(entry))
    # Criteria are judged by the caller's mission-level checks when it brought them, and
    # an unmet one is still a coverage gap — it is the deepest kind, because a mission
    # criterion nobody met is exactly what the next round should be aimed at.  The
    # per-report criterion list is not consulted as well: it would report the same gap
    # once per report whose own criteria happened to read similarly.
    gaps = _coverage_gaps(reports, questions=questions,
                          criteria=() if mission_checks else criteria)
    gaps.extend(CoverageGap(
        target=check.criterion, kind="criterion",
        checked_by="the mission-level criterion check did not pass",
        detail=(check.shortfall or "no report's evidence satisfies it")[:240])
        for check in mission_checks if not check.met)
    owners = _nearest_owners(gaps, reports)
    observations: list[ReportReview] = []
    for report in reports:
        others = [other for other in reports if other.subagent_id != report.subagent_id]
        mine = [gap for gap in gaps if report.subagent_id in owners.get(id(gap), ())
                or gap.owner.strip().lower() == report.role.strip().lower()]
        if mine:
            coverage = MasterLensFinding(
                lens=ReviewLens.COVERAGE, verdict=LensVerdict.CONCERNS,
                target=mine[0].target[:200],
                detail=("nobody covers: "
                        + "; ".join(gap.target[:120] for gap in mine))[:300],
                actionable=True,
                remedy=(f"a bounded follow-up for this report, aimed at "
                        f"{mine[0].target[:110]}"))
        elif gaps:
            coverage = MasterLensFinding(
                lens=ReviewLens.COVERAGE, verdict=LensVerdict.SATISFIED,
                checked="the mission-level gap(s) fall to another report")
        else:
            coverage = MasterLensFinding(
                lens=ReviewLens.COVERAGE, verdict=LensVerdict.SATISFIED,
                checked="every mission question is answered by some report")
        observations.append(ReportReview(
            subagent_id=report.subagent_id, role=report.role, status=report.status,
            findings=[
                _relevance_finding(report, focus, scope),
                _sufficiency_finding(report),
                _contradiction_findings(report, others),
                _duplication_finding(report, others),
                coverage,
            ]))
    # Mission criteria are judged by the caller's own mechanical checks when it has
    # them: §36.3's four rules applied to the *whole* mission's evidence, which is the
    # only level at which a mission criterion ("the image integrity is proven") can be
    # answered.  Without checks the criteria are simply unjudged, and an unjudged
    # criterion is reported as unmet rather than assumed met.
    if mission_checks:
        met = [check.criterion for check in mission_checks if check.met]
        unmet = [check.criterion for check in mission_checks if not check.met]
    else:
        unmet = [gap.target for gap in gaps if gap.kind == "criterion"]
        met = [text for text in criteria if text not in unmet] if criteria else []
    return MasterReview(
        round=round_number, observations=observations, coverage=gaps,
        criteria_met=met, criteria_unmet=unmet,
        evidence_ids=list(dict.fromkeys(evidence_ids)))


def _nearest_owners(gaps: Sequence[CoverageGap],
                    reports: Sequence["SubagentOutcome"]) -> dict[int, tuple[str, ...]]:
    """For each unowned gap, the report ids whose subject matter is nearest to it.

    A gap the reviewing pass could not place (a mission criterion, say) is not
    arbitrary: it belongs to a report whose role shares words with it, or — when no
    report shares a word — to every report, because if nobody's subject matter covers
    it then nobody's exclusion of it was justified.
    """

    owners: dict[int, tuple[str, ...]] = {}
    for gap in gaps:
        if gap.owned:
            continue
        wanted = _topic_words(gap.target)
        near = tuple(report.subagent_id for report in reports
                     if len(_topic_words(report.role + " " + report.objective) & wanted) >= 1)
        owners[id(gap)] = near or tuple(report.subagent_id for report in reports)
    return owners


# --------------------------------------------------------------------------
# 37.2 Stop or continue: every bound, in precedence order
# --------------------------------------------------------------------------


def replan_refusals(review: MasterReview, *, policy: "FlowPolicy", round_number: int,
                    reviews_used: int, deadline_expired: bool = False,
                    cancelled: bool = False,
                    evidence_added: int | None = None,
                    blocked: Sequence[str] = ()) -> list[str]:
    """Every reason the Master may not open another round, checked and reported.

    All of them are evaluated; none returns early.  That is the same discipline §36
    applies to a Subagent's expansion, and it is here for the same reason: "why did
    it stop?" should have one answer per bound, not one answer in total.
    """

    reasons: list[str] = list(blocked)
    if cancelled:
        reasons.append("the mission was cancelled")
    if deadline_expired:
        reasons.append("the mission deadline has expired")
    if not policy.allow_follow_ups:
        reasons.append("follow-up assignments are disabled for this mission")
    if round_number > policy.max_replan_rounds:
        reasons.append(f"the replanning budget of {policy.max_replan_rounds} round(s) "
                       f"is spent")
    if reviews_used >= policy.max_master_reviews:
        reasons.append(f"the review budget of {policy.max_master_reviews} review(s) "
                       f"is spent")
    if evidence_added is not None and evidence_added <= 0:
        reasons.append("the last round added no new evidence (saturation)")
    return reasons


def decide_master(review: MasterReview, *, policy: "FlowPolicy", round_number: int = 1,
                  reviews_used: int = 1, deadline_expired: bool = False,
                  cancelled: bool = False, assignments: Sequence[FollowUpAssignment] = (),
                  evidence_added: int | None = None,
                  blocked: Sequence[str] = ()) -> MasterDecision:
    """Turn a review into a bounded decision: finish, stop, or continue.

    The order of the questions is the whole design.

    1.  **Cancelled or out of time?**  That is an operator's bound, not the mission's
        opinion, so it wins over everything — including a complete-looking mission,
        because a mission cancelled mid-round did not finish it.
    2.  **Are the mission's own criteria met?**  Then the mission is ``final``.  A lens
        may still have a concern, and a concern that survives a complete mission is a
        *limitation to report*, not a reason to spend the operator's budget looking for
        more.  Making it one would mean no mission ever finishes on its own terms.
    3.  **Is a *number* spent?**  The round cap, the review budget, or the operator
        switching follow-ups off.  That is ``budget``: a bound the operator set, which
        the report must state rather than disguise as an opinion.
    4.  **Was the last round empty?**  No new evidence, or nothing to assign.  That is
        ``saturation``: the shape of a loop that would keep going and learn nothing.
    5.  Otherwise **continue**, with the assignments already chosen — and if none could
        be chosen, that is saturation too, because a continue with no work is a loop.

    ``stop_on_blocking_failure`` adds one more bound at the front of that list: if the
    mission is configured to refuse a synthesis over a blocking failure, a review with
    a blocking report left over does not get to spend a round trying again.
    """

    reasons = replan_refusals(review, policy=policy, round_number=round_number,
                              reviews_used=reviews_used,
                              deadline_expired=deadline_expired, cancelled=cancelled,
                              evidence_added=evidence_added, blocked=blocked)
    if cancelled or deadline_expired:
        return MasterDecision(
            action="stop",
            condition=StopCondition.BLOCKED if cancelled else StopCondition.DEADLINE,
            round=round_number, refusals=reasons,
            basis=("the mission was cancelled before another round could start"
                   if cancelled else
                   "the mission deadline expired before another round could start"))
    nominated = [item for item in assignments if item.route == "existing"]
    if review.complete:
        # A follow-up that has nowhere to go — every remaining concern sits outside an
        # existing Subagent and the Master has no seat left — is not a reason to keep a
        # finished mission open.  It is recorded, because "we finished with these
        # limitations" is the honest ending.
        return MasterDecision(
            action="final", condition=StopCondition.COMPLETE, round=round_number,
            refusals=([f"{len(nominated)} concern(s) remain outside every existing "
                       f"Subagent; they are reported as limitations"]),
            basis=(f"every mission criterion is met ({len(review.criteria_met)}); "
                   f"{len(review.coverage)} coverage gap(s) and "
                   f"{len(review.concerns)} concern(s) remain as stated limitations"))
    if reasons:
        return MasterDecision(
            action="stop", condition=stop_condition_for(reasons), round=round_number,
            refusals=reasons,
            basis=("no further round is allowed: " + "; ".join(reasons)))
    open_targets = review.open_targets
    if not open_targets:
        return MasterDecision(
            action="stop", condition=StopCondition.SATURATION, round=round_number,
            refusals=["the review found nothing another round could act on"],
            basis=(f"every lens is satisfied and every mission question is answered, "
                   f"but {len(review.criteria_unmet)} mission criterion/criteria are "
                   f"still unmet"))
    if not assignments:
        return MasterDecision(
            action="stop", condition=StopCondition.SATURATION, round=round_number,
            refusals=[f"{len(open_targets)} target(s) are open and none can be assigned: "
                      f"no existing Subagent's objective covers them"],
            basis=("further work would be a new mission rather than a remedy, so none "
                   "is planned"))
    return MasterDecision(
        action="continue", condition=StopCondition.NONE, round=round_number,
        assignments=list(assignments),
        basis=(f"{len(assignments)} bounded follow-up(s) for {len(open_targets)} open "
               f"target(s); round {round_number} of {policy.max_replan_rounds}"))


def stop_condition_for(refusals: Sequence[str]) -> StopCondition:
    """Which :class:`StopCondition` a non-empty refusal list describes.

    ``budget`` and ``deadline`` are different bounds and a report that folded them
    together would hide which one bit; a cancellation is ``blocked`` because the work
    did not become impossible, it became unrequested.
    """

    lowered = " ".join(refusals).lower()
    if "cancelled" in lowered:
        return StopCondition.BLOCKED
    if "deadline" in lowered:
        return StopCondition.DEADLINE
    if "saturation" in lowered:
        return StopCondition.SATURATION
    return StopCondition.BUDGET


# --------------------------------------------------------------------------
# 37.3 Turning a concern into a bounded assignment
# --------------------------------------------------------------------------


def _tools_for_follow_up(reports: Sequence["SubagentOutcome"],
                         subagents: Sequence["FlowSubagent"]) -> list[str]:
    """The narrowest tool set the mission already holds, never a widened grant.

    A follow-up inherits *one* tool from the work it is following up on, because that
    is the smallest thing that can close a gap the same sources could close.  When the
    reports carry no tool at all — an adopted aggregate, for instance — the mission's
    own Subagents are asked, and a mission with no tools gets the read-only default.
    """

    for subagent in subagents:
        for worker in subagent.workers:
            if worker.tools:
                return [worker.tools[0]]
    return ["evidence.read"]


def _available_tools(tools: Sequence[str], context: "MasterContext") -> list[str]:
    """The tools of ``tools`` this deployment actually has, or its narrowest default.

    A follow-up may not widen a grant (§37.3), and it may not invent one either: a tool
    the mission does not hold is a plan defect, and §22's capability check would refuse
    the draft for it.  Choosing the intersection here means the refusal never has to
    happen for a reason the Master could have seen.
    """

    known = [tool for tool in tools if not context.available_tools
             or tool in context.available_tools]
    if known:
        return list(dict.fromkeys(known))
    return list(context.available_tools[:1]) or ["read-only analysis"]


def _owner_for(gap: str, reports: Sequence["SubagentOutcome"],
               subagents: Sequence["FlowSubagent"]) -> str:
    """The existing Subagent a gap belongs to, by role, or ``""`` when none does."""

    wanted = _topic_words(gap)
    by_role = {subagent.role.strip().lower(): subagent for subagent in subagents}
    for report in reports:
        subagent = by_role.get(report.role.strip().lower())
        if subagent is None:
            continue
        if len(_topic_words(subagent.objective) & wanted) >= 1:
            return subagent.id
    return ""


def plan_follow_ups(review: MasterReview, *, reports: Sequence["SubagentOutcome"],
                    subagents: Sequence["FlowSubagent"], policy: "FlowPolicy",
                    round_number: int = 1,
                    licence_remaining: int | None = None,
                    max_new_subagents: int = 1) -> list[FollowUpAssignment]:
    """The assignments a continue decision would run, most-specific first.

    Two routes, and the choice between them is a *bound*, not a preference:

    *   **existing** — the gap falls inside a Subagent the mission already has, and
        that Subagent still holds runtime Worker budget (§36).  Nothing is spent from
        the Master's licence, and the follow-up goes through the same planning,
        review and retask gates as the original work.
    *   **new** — the gap belongs to nobody, and the Master still holds a licence
        seat.  A new Subagent is a bigger instrument, so it is spent last and once:
        ``max_new_subagents`` defaults to 1 because a round that created a team would
        be a replan, and a replan is a new mission, not a remedy.

    Nothing is returned for a lens that found a concern with no remedy: an assignment
    with no way to close its gap is busy-work, and the loop would spin on it.
    """

    assignments: list[FollowUpAssignment] = []
    seen: set[tuple[str, str]] = set()
    tools = _tools_for_follow_up(reports, subagents)
    seats = licence_remaining if licence_remaining is not None else max_new_subagents
    created = 0
    for finding in review.actionable:
        if finding.lens is ReviewLens.CONTRADICTIONS:
            # A contradiction is settled by re-reading a source, not by collecting
            # more of it: another Worker would produce a third opinion, not a fact.
            continue
        target = finding.target.strip()[:200]
        if not target:
            continue
        owner = _owner_for(finding.target, reports, subagents)
        key = (_claim_key(target), owner)
        if key in seen:
            # Two lenses may point at one target — a report that drifted *and* left a
            # gap — and one follow-up answers both.  The owner is part of the key
            # because "nobody covers X" is true of each report it falls to.
            continue
        seen.add(key)
        if owner:
            assignments.append(FollowUpAssignment(
                route="existing", target_subagent=owner,
                role=next((subagent.role for subagent in subagents
                           if subagent.id == owner), "follow-up"),
                objective=(f"close one gap reported by the master review: "
                           f"{finding.remedy or finding.detail[:140]}")[:400],
                gap=finding.detail[:300] or finding.target[:300],
                lens=finding.lens,
                completion_criteria=[
                    f"at least one reviewed observation addresses: {target[:100]}"],
                tools=tools,
                justification=(f"the {finding.lens.value} lens found a concern inside "
                               f"this Subagent's own assignment, so one more Worker "
                               f"closes it without widening the mission"),
                round=round_number))
            continue
        if finding.lens is ReviewLens.RELEVANCE:
            # Drift is fixed by re-pointing a report that exists, never by hiring a new
            # one: a new Subagent working on an objective nobody misread learns nothing
            # about why the first one read it wrong.
            continue
        if created >= max(0, seats):
            continue
        created += 1
        role = f"gap-{finding.lens.value}-{content_id('flw', target, length=6)}"
        assignments.append(FollowUpAssignment(
            route="new", role=role,
            objective=(f"cover what no report covers for the mission: {target[:200]}"),
            gap=finding.detail[:300] or finding.target[:300],
            lens=finding.lens,
            completion_criteria=[
                f"at least one reviewed observation addresses: {target[:100]}"],
            tools=tools,
            justification=("no existing Subagent's objective covers this gap and the "
                           "master review named it explicitly"),
            round=round_number,
            licence_remaining=max(0, seats - created)))
    return assignments


def follow_up_draft(assignment: FollowUpAssignment, *,
                    context: "MasterContext") -> "SubagentSpecDraft":
    """A follow-up assignment as a specification draft, ready for §22's gates.

    This is what makes a runtime Subagent *not* a shortcut: the draft goes through
    :func:`validate_subagent_specs` exactly as the planned team did, so an
    unjustified follow-up is refused by the same code that refuses a bad plan.  The
    draft is derived from the assignment rather than invented beside it — every field
    traces to the finding that justified it.
    """

    objective = assignment.objective.strip()
    if len(objective) < 12:                   # pragma: no cover - the model enforces it
        objective = f"{objective}: close the reviewed gap"
    return SubagentSpecDraft(
        role=assignment.role,
        role_basis=RoleBasis.VERIFICATION,
        objective=objective[:400],
        justification=assignment.justification[:400],
        scope_entries=list(context.scope_entries[:3]) or ["example.com"],
        required_inputs=["the reviewed results so far"],
        allowed_capabilities=_available_tools(assignment.tools, context),
        deliverables=[Deliverable(
            name=f"{assignment.role} follow-up rows",
            format="structured-table",
            fields=["statement", "source", "retrieved_at", "confidence"],
            measurable_check=(
                "one row per observation the follow-up made, each with a source id "
                "and a retrieval time"))],
        evidence=EvidenceRequirement(
            description=(f"evidence collected for the follow-up gap: "
                         f"{assignment.gap[:160]}"),
            accepted_kinds=[EvidenceKind.OBSERVATION],
            minimum_items=1, minimum_sources=1,
            source_forms=list(context.scope_entries[:3])),
        rubric=QualityRubric(
            criteria=[
                RubricCriterion(
                    criterion=assignment.completion_criteria[0][:120], weight=3,
                    test=(f"a reviewer confirms: "
                          f"{assignment.completion_criteria[0][:100]}"),
                    blocking=True),
                RubricCriterion(
                    criterion="every claim cites a collected source", weight=2,
                    test="each statement carries at least one evidence id from this mission")],
            passing_score=70, reviewer="master", max_review_rounds=2),
        termination=TerminationCriteria(
            objective_satisfied_when=(
                f"at least 1 completion criterion is met: "
                f"{assignment.completion_criteria[0][:100]}"),
            max_tasks=4, max_attempts_per_task=2,
            stop_on=list(assignment.completion_criteria)),
        workers=[WorkerInstruction(
            name=f"{assignment.role[:32]} reader",
            objective=(f"read the sources that bear on: {objective[:160]}"),
            tools=_available_tools(assignment.tools, context),
            completion_criteria=list(assignment.completion_criteria))],
        depends_on=[],
        max_workers=2,
        addresses_questions=[assignment.gap[:200]],
        indivisible=True)


def follow_up_subagent(assignment: FollowUpAssignment, *,
                       context: "MasterContext") -> "FlowSubagent":
    """Materialise a follow-up assignment as a unit the graph can run.

    The same shape a planned Subagent has, so every downstream gate — the join, the
    seven review dimensions, the retask, the aggregate — applies without a special
    case.  Ids are derived from the assignment, so two rounds cannot accidentally
    share one.
    """

    draft = follow_up_draft(assignment, context=context)
    return team_units(context, [draft])[0].model_copy(
        update={"role": assignment.role[:80]})


# --------------------------------------------------------------------------
# 37.5 The demo: three reports, five lenses, and four ways to stop
# --------------------------------------------------------------------------


def _review_item(statement: str, *, worker: str, tag: str = "advisory") -> "EvidenceItem":
    """One observation for the review demo, sourced so it can carry a claim."""

    return EvidenceItem(
        id=content_id("ev", worker, statement, length=10),
        kind=EvidenceKind.OBSERVATION, statement=statement,
        sources=[SourceReference(
            kind=SourceKind.PUBLIC_WEB, url=f"https://{tag}.test/{worker}",
            title=tag, retrieved_at=datetime(2026, 5, 4, 10, 0,
                                             tzinfo=timezone.utc),
            retrieval_method=RetrievalMethod.HTTP, http_status=200)],
        confidence=Confidence.LOW, confidence_basis="one retrieval",
        collected_by=worker)


def _review_report(role: str, *, objective: str = "", statements: Sequence[str] = (),
                   worker: str = "wrk-1",
                   status: EntityStatus = EntityStatus.SUCCEEDED,
                   criteria: Sequence["CriterionCheck"] = (),
                   questions: Sequence[str] = (),
                   gaps: Sequence["UnknownValue"] = (),
                   withheld: Sequence[str] = (),
                   disagreement: "Disagreement | None" = None) -> "SubagentOutcome":
    """A Subagent report built from statements, for the review demo and its checks."""

    evidence = [_review_item(statement, worker=worker) for statement in statements]
    outcome = WorkerOutcome(
        worker_id=worker, subagent_id=content_id("sa", role, length=12),
        status=status, attempt=1,
        summary=(f"{worker}: {len(evidence)} observation(s) collected"),
        evidence_ids=[item.id for item in evidence])
    return SubagentOutcome(
        subagent_id=content_id("sa", role, length=12), role=role,
        objective=objective or role,
        status=status, outcomes=[outcome], evidence=evidence,
        aggregate_basis=check_join(f"subagent-aggregate:{role}", [worker], [worker]),
        open_questions=list(questions), gaps=list(gaps), withheld=list(withheld),
        disagreements=[disagreement] if disagreement is not None else [],
        criteria_checks=list(criteria))


def master_review_cases() -> dict[str, dict[str, Any]]:
    """Two report sets: one that fails four lenses, one that passes all five.

    The first set is built so each concern has exactly one cause, and a reader can see
    which lens bit:

    *   ``published-advisories`` is on-mission and carries evidence, but it repeats
        ``mirror-index``'s claim (duplication: nothing new was learned) and it disagrees
        with ``quotes-and-forwards`` about whether the advisory names the component
        without recording the disagreement (contradictions);
    *   ``quotes-and-forwards`` is the other side of that conflict, recorded nowhere;
    *   ``dns-records`` collected nothing at all (sufficiency) and works on registrar
        dates the objective is not about (relevance);
    *   one mission question is answered by nobody (coverage), and one mission
        criterion is unmet by every report (coverage again, of the deeper kind).

    The second set is one report that satisfies all five, which is what makes ``final``
    reachable: a review where every lens is satisfied and the criteria are met.
    """

    question = "the published advisories name the affected component"
    criterion = "each documented risk cites an advisory"
    objective = ("map the publicly documented exposure of example.com and rank the "
                 "advisory-backed risks")
    on_mission = ("rank the advisory-backed exposure of example.com from its published "
                  "advisories")
    names_it = "the published advisories name the affected component"
    repeats_it = "the edge gateway session handling is the affected component"
    # The same subject, opposite polarity: a contradiction only if both sides share
    # their subject words, which is the conservative rule §36.2 uses.
    affirms_it = "the published advisories name the affected component"
    denies_it = "the published advisories never name the affected component"
    criteria = [CriterionCheck(criterion=criterion, met=False,
                               shortfall="no report's evidence cites a first-party advisory",
                               critical=True)]
    concerns = [
        _review_report("published-advisories", objective=on_mission, worker="wrk-adv",
                       statements=[affirms_it], criteria=criteria,
                       questions=[question]),
        _review_report("quotes-and-forwards", objective=on_mission, worker="wrk-qf",
                       statements=[denies_it], criteria=criteria),
        _review_report("dns-records", objective="renewal dates of the registrar",
                       worker="wrk-dns", status=EntityStatus.BLOCKED,
                       gaps=[UnknownValue(
                           reason=UnknownReason.UNAVAILABLE, determined_by="dns-records",
                           detail="every resolver in scope refused the query")]),
    ]
    mirror = _review_report("mirror-index", objective=on_mission, worker="wrk-mirror",
                            statements=[affirms_it], criteria=criteria)
    clean = _review_report(
        "published-advisories", objective=on_mission, worker="wrk-clean",
        statements=[repeats_it],
        criteria=[CriterionCheck(criterion=criterion, met=True,
                                 evidence_ids=[content_id("ev", "wrk-clean", names_it,
                                                          length=10)],
                                 critical=True)])
    return {
        "concerns": {"reports": [concerns[0], mirror, concerns[1], concerns[2]],
                     "objective": objective, "questions": [question],
                     "criteria": [criterion]},
        "clean": {"reports": [clean], "objective": objective,
                  "questions": [question], "criteria": [criterion]},
    }


def render_master_review(review: MasterReview,
                         decision: MasterDecision) -> Group:
    """One review and the decision it produced: the lenses, the gaps, and the bound."""

    head = Table(title=f"review {review.round} — {review.summary()}", title_justify="left",
                 box=None, pad_edge=False)
    head.add_column("report", no_wrap=True)
    head.add_column("finding", overflow="fold", max_width=76)
    for observation in review.observations:
        if observation.satisfied:
            head.add_row(escape(observation.role or observation.subagent_id),
                         "[green]all five lenses satisfied[/green]")
            continue
        first = True
        for finding in observation.concerns:
            head.add_row(escape((observation.role or observation.subagent_id)
                                if first else ""), escape(finding.describe()[:200]))
            first = False

    gaps = Table(title="what nobody covered", title_justify="left", box=None,
                 pad_edge=False, expand=False)
    gaps.add_column("gap", overflow="fold", max_width=88)
    for gap in review.coverage or []:
        gaps.add_row(escape(gap.describe()[:220]))
    if not review.coverage:
        gaps.add_row("[green]nothing: every mission question is answered[/green]")

    verdict = Table(title=f"the decision — {decision.action}", title_justify="left",
                    box=None, pad_edge=False, expand=False)
    verdict.add_column("field", style="dim", no_wrap=True)
    verdict.add_column("value", overflow="fold", max_width=72)
    verdict.add_row("stop condition", escape(decision.condition.value))
    verdict.add_row("basis", escape(decision.basis[:220]))
    for refusal in decision.refusals:
        verdict.add_row("refusal", escape(refusal[:200]))
    for assignment in decision.assignments:
        verdict.add_row("next", escape(assignment.describe()[:200]))

    rows: list[Any] = [head, Text(""), gaps, Text(""), verdict]
    if decision.finished:
        rows += [Text(""), Text("every mission criterion is met: this is a final report, "
                                "and the concerns above are the limitations it carries",
                                style="dim")]
    elif decision.stopped:
        rows += [Text(""), Text("the loop stopped on a bound, not on success: the "
                                "refusals above are why it stopped asking", style="dim")]
    return Group(*rows)


def master_review_demo() -> dict[str, Any]:
    """The demo payload: one review, four decisions, and the loop that ended each way."""

    cases = master_review_cases()
    reviews = {
        "concerns": review_reports(cases["concerns"]["reports"],
                                   objective=cases["concerns"]["objective"],
                                   questions=cases["concerns"]["questions"],
                                   criteria=cases["concerns"]["criteria"],
                                   scope_entries=["example.com"]),
        "clean": review_reports(cases["clean"]["reports"],
                                objective=cases["clean"]["objective"],
                                questions=cases["clean"]["questions"],
                                criteria=cases["clean"]["criteria"],
                                scope_entries=["example.com"]),
    }
    policy = FlowPolicy()
    concerns = reviews["concerns"]
    assignments = plan_follow_ups(
        concerns, reports=cases["concerns"]["reports"], subagents=[],
        policy=policy, round_number=1, licence_remaining=2)
    decisions = {
        # the ordinary case: work remains and the budget allows it
        "continue": decide_master(concerns, policy=policy, round_number=1,
                                  assignments=assignments),
        # the cap: the same review, one round later than the policy allows
        "budget": decide_master(concerns, policy=policy, round_number=2,
                                assignments=assignments),
        # a round that added nothing is saturation even with budget in hand
        "saturation": decide_master(concerns, policy=policy, round_number=1,
                                    assignments=assignments, evidence_added=0),
        # and a mission whose own criteria are met finishes, concerns and all
        "final": decide_master(reviews["clean"], policy=policy, round_number=1,
                               assignments=[]),
    }
    # The loop, run to its end: every round re-reviews the same reports, so nothing is
    # ever added and the third review is the one that sees it.  The point of showing it
    # is that it *stops* — with a number, not with a stack.
    rounds: list[dict[str, Any]] = []
    for index in range(1, policy.max_master_reviews + 1):
        decided = decide_master(concerns, policy=policy, round_number=index,
                                reviews_used=index, assignments=assignments,
                                evidence_added=(None if index == 1 else 0))
        rounds.append({"round": index, "action": decided.action,
                       "condition": decided.condition.value,
                       "refusals": len(decided.refusals)})
        if decided.stopped:
            break
    signals = {
        "every lens was answered for every report": all(
            len(observation.findings) == len(ReviewLens)
            for review in reviews.values() for observation in review.observations),
        "a duplicate claim was caught": any(
            finding.lens is ReviewLens.DUPLICATION
            for finding in concerns.concerns),
        "an unrecorded contradiction was caught": any(
            finding.lens is ReviewLens.CONTRADICTIONS
            for finding in concerns.concerns),
        "a report with no evidence was caught": any(
            finding.lens is ReviewLens.SUFFICIENCY for finding in concerns.concerns),
        "an unanswered question became a coverage gap": bool(concerns.coverage),
        "the loop stopped on a bound": rounds[-1]["action"] != "continue",
        "every bound that stopped it is named": all(
            decision.refusals for decision in decisions.values()
            if decision.stopped and not decision.finished),
        "a complete mission finishes as final": decisions["final"].finished,
        "the clean review has no concerns": not reviews["clean"].concerns,
    }
    return {
        "reviews": {name: review.to_dict() for name, review in reviews.items()},
        "findings": {name: [f"{observation.role}: {finding.describe()}"
                            for observation in review.observations
                            for finding in observation.findings]
                     for name, review in reviews.items()},
        "coverage": [gap.describe() for gap in concerns.coverage],
        "assignments": [item.to_dict() for item in assignments],
        "decisions": {name: decision.to_dict() for name, decision in decisions.items()},
        "loop": rounds,
        "signals": signals,
        "acceptance": {"all_signals": all(signals.values()), "signals": signals},
    }


def render_master_review_demo(payload: Mapping[str, Any]) -> Group:
    """The demo: five lenses over three reports, then four ways the loop can end."""

    signals = Table(title="can the loop run for ever?", title_justify="left", box=None,
                    pad_edge=False, expand=False)
    signals.add_column("", width=2)
    signals.add_column("signal", overflow="fold", max_width=64)
    for name, ok in payload["acceptance"]["signals"].items():
        glyph, colour = ("✔", "green") if ok else ("✘", "red")
        signals.add_row(f"[{colour}]{glyph}[/{colour}]", escape(name))

    lenses = Table(title="the five lenses, as they were applied", title_justify="left",
                   box=None, pad_edge=False, expand=False)
    lenses.add_column("report", no_wrap=True)
    lenses.add_column("finding", overflow="fold", max_width=78)
    for finding in payload["findings"]["concerns"]:
        role, _, detail = finding.partition(": ")
        lenses.add_row(escape(role[:22]), escape(detail[:180]))

    coverage = Table(title="what nobody covered", title_justify="left", box=None,
                     pad_edge=False, expand=False)
    coverage.add_column("gap", overflow="fold", max_width=88)
    for gap in payload["coverage"] or ["nothing: every question was answered"]:
        coverage.add_row(escape(gap[:200]))

    decisions = Table(title="four reviews, four endings", title_justify="left",
                      box=None, pad_edge=False, expand=False)
    decisions.add_column("name", no_wrap=True)
    decisions.add_column("decision", overflow="fold", max_width=74)
    for name, decision in payload["decisions"].items():
        decisions.add_row(escape(name), escape(str(decision["summary"])[:190]))

    loop = Table(title="the loop, run to its end", title_justify="left", box=None,
                 pad_edge=False, expand=False)
    loop.add_column("round", no_wrap=True)
    loop.add_column("what happened", overflow="fold", max_width=60)
    for entry in payload["loop"]:
        loop.add_row(escape(str(entry["round"])),
                     escape(f"{entry['action']} ({entry['condition']}); "
                            f"{entry['refusals']} bound(s) named"))

    tail = Text("a mission that cannot loop for ever says which bound stopped it, and a "
                "mission that finished says so without also claiming it was cut short",
                style="dim")
    return Group(signals, Text(""), lenses, Text(""), coverage, Text(""), decisions,
                 Text(""), loop, Text(""), tail)


def run_master_review_self_test() -> list["MasterReviewCheck"]:
    """Prove §37's acceptance clause: no unbounded loop, and always a report.

    Every check is a property of the record rather than of one run: the fixtures vary
    the *bounds* over one fixed set of observations, so a failure points at the bound
    that failed rather than at a coincidence in the data.
    """

    checks: list[MasterReviewCheck] = []

    def add(name: str, ok: bool, detail: Any = "") -> None:
        checks.append(MasterReviewCheck(name=name, ok=bool(ok), detail=str(detail)[:150]))

    def raises(fn: Callable[[], Any], exc: type[BaseException]) -> bool:
        try:
            fn()
        except exc:
            return True
        except Exception:                     # noqa: BLE001 - a wrong error is a failure
            return False
        return False

    cases = master_review_cases()
    concerns = review_reports(cases["concerns"]["reports"],
                              objective=cases["concerns"]["objective"],
                              questions=cases["concerns"]["questions"],
                              criteria=cases["concerns"]["criteria"],
                              scope_entries=["example.com"])
    clean = review_reports(cases["clean"]["reports"],
                           objective=cases["clean"]["objective"],
                           questions=cases["clean"]["questions"],
                           criteria=cases["clean"]["criteria"],
                           scope_entries=["example.com"])
    policy = FlowPolicy()

    # ---- 1. all five lenses, every report ------------------------------
    add("every report is judged on all five lenses",
        all(len(observation.findings) == 5 for observation in concerns.observations),
        [len(observation.findings) for observation in concerns.observations])
    add("the five lenses are the task's five",
        {finding.lens for observation in concerns.observations
         for finding in observation.findings} == set(ReviewLens))
    add("a report with nothing to duplicate says not-applicable rather than satisfied",
        _duplication_finding(_review_report("empty", worker="wrk-e"),
                             []).verdict is LensVerdict.NOT_APPLICABLE)

    def lens_twice() -> None:
        ReportReview(subagent_id="sa-x", findings=[
            MasterLensFinding(lens=ReviewLens.RELEVANCE, verdict=LensVerdict.SATISFIED),
            MasterLensFinding(lens=ReviewLens.RELEVANCE, verdict=LensVerdict.SATISFIED)])

    add("a review cannot answer one lens twice", raises(lens_twice, ValueError))

    def missing_lens() -> None:
        ReportReview(subagent_id="sa-x", findings=[
            MasterLensFinding(lens=ReviewLens.RELEVANCE, verdict=LensVerdict.SATISFIED)])

    add("a review cannot skip a lens", raises(missing_lens, ValueError))

    # ---- 2. each lens bites where it should ---------------------------
    add("duplication catches a repeated claim",
        any(finding.lens is ReviewLens.DUPLICATION for finding in concerns.concerns),
        [finding.lens.value for finding in concerns.concerns])
    add("contradictions catches a conflict nobody recorded",
        any(finding.lens is ReviewLens.CONTRADICTIONS for finding in concerns.concerns))
    add("sufficiency catches a report with no evidence",
        any(finding.lens is ReviewLens.SUFFICIENCY for finding in concerns.concerns))
    add("relevance catches a report about something else",
        any(finding.lens is ReviewLens.RELEVANCE for finding in concerns.concerns))
    add("coverage turns an unanswered question into a gap", bool(concerns.coverage),
        [gap.describe() for gap in concerns.coverage])
    add("a report echoing the question does not count as answering it",
        bool(_coverage_gaps(
            [_review_report("echoer", statements=[
                "the published advisories name the affected component"],
                worker="wrk-echo")],
            questions=["the published advisories name the affected component"])))
    add("a clean review has no concerns", not clean.concerns,
        [finding.describe() for finding in clean.concerns])
    add("a concern without a target is refused",
        raises(lambda: MasterLensFinding(
            lens=ReviewLens.SUFFICIENCY, verdict=LensVerdict.CONCERNS,
            detail="something is missing", target=""), ValueError))
    add("an actionable concern without a remedy is refused",
        raises(lambda: MasterLensFinding(
            lens=ReviewLens.SUFFICIENCY, verdict=LensVerdict.CONCERNS,
            detail="something is missing", target="the report",
            actionable=True), ValueError))

    # ---- 3. the decision, on one fixed review --------------------------
    assignments = plan_follow_ups(concerns, reports=cases["concerns"]["reports"],
                                  subagents=[], policy=policy, round_number=1,
                                  licence_remaining=2)
    add("work that is open and affordable is assigned",
        bool(assignments) and all(item.route == "new" for item in assignments),
        [item.route for item in assignments])
    cont = decide_master(concerns, policy=policy, round_number=1,
                         assignments=assignments)
    add("the decision continues when the budget allows it", cont.action == "continue",
        cont.summary())
    add("a continue carries the work it continues with", bool(cont.assignments))
    add("a review with concerns is not called final",
        decide_master(concerns, policy=policy, round_number=1,
                      assignments=assignments).action != "final")

    def assignment_without_work() -> None:
        MasterDecision(action="continue", condition=StopCondition.NONE,
                       assignments=[], basis="continue with nothing")

    add("a continue with no assignment is refused", 
        raises(assignment_without_work, ValueError))

    def stop_with_work() -> None:
        MasterDecision(action="stop", condition=StopCondition.BUDGET,
                       assignments=list(assignments), basis="stop but keep planning")

    add("a stop cannot carry assignments", raises(stop_with_work, ValueError))

    def final_on_budget() -> None:
        MasterDecision(action="final", condition=StopCondition.BUDGET, basis="finished?")

    add("final is only reachable on completion",
        raises(final_on_budget, ValueError))

    # ---- 4. the five stopping conditions, one at a time ----------------
    at_cap = decide_master(concerns, policy=policy, round_number=2,
                           assignments=assignments)
    add("the round cap stops the loop", at_cap.action == "stop"
        and at_cap.condition is StopCondition.BUDGET, at_cap.summary())
    add("the cap names itself as the reason", any("replanning budget" in reason
                                                  for reason in at_cap.refusals),
        at_cap.refusals)
    reviews_spent = decide_master(concerns, policy=policy, round_number=1,
                                  reviews_used=policy.max_master_reviews,
                                  assignments=assignments)
    add("the review budget stops the loop", reviews_spent.condition is StopCondition.BUDGET,
        reviews_spent.refusals)
    late = decide_master(concerns, policy=policy, round_number=1,
                         assignments=assignments, deadline_expired=True)
    add("an expired deadline stops the loop", late.condition is StopCondition.DEADLINE,
        late.summary())
    cancelled = decide_master(concerns, policy=policy, round_number=1,
                              assignments=assignments, cancelled=True)
    add("a cancellation stops the loop", cancelled.condition is StopCondition.BLOCKED)
    saturated = decide_master(concerns, policy=policy, round_number=1,
                              assignments=assignments, evidence_added=0)
    add("a round that added nothing is saturation",
        saturated.condition is StopCondition.SATURATION, saturated.summary())
    nothing_to_do = decide_master(concerns, policy=policy, round_number=1,
                                  assignments=[])
    add("a review with nothing to assign does not loop",
        nothing_to_do.action == "stop", nothing_to_do.summary())
    finished = decide_master(clean, policy=policy, round_number=1, assignments=[])
    add("a mission that met its criteria finishes", finished.finished, finished.summary())
    add("finishing is not a budget stop", finished.condition.is_success)
    off = FlowPolicy(allow_follow_ups=False)
    switched_off = decide_master(concerns, policy=off, round_number=1,
                                 assignments=assignments)
    add("follow-ups switched off is a budget stop", switched_off.stopped,
        switched_off.refusals)
    add("every bound that had a say is named",
        len(decide_master(concerns, policy=FlowPolicy(allow_follow_ups=False),
                          round_number=2, reviews_used=3, assignments=assignments,
                          deadline_expired=True).refusals) >= 4,
        decide_master(concerns, policy=FlowPolicy(allow_follow_ups=False),
                      round_number=2, reviews_used=3, assignments=assignments,
                      deadline_expired=True).refusals)

    # ---- 5. the loop terminates, whatever the bounds -------------------
    for cap in (0, 1, 2, 3):
        bounded = FlowPolicy(max_replan_rounds=cap, max_master_reviews=cap + 2)
        trace: list[str] = []
        for index in range(1, bounded.max_master_reviews + 2):
            step = decide_master(concerns, policy=bounded, round_number=index,
                                 reviews_used=index, assignments=assignments,
                                 evidence_added=(None if index == 1 else 0))
            trace.append(step.action)
            if step.stopped:
                break
        add(f"with a cap of {cap} the loop stops", trace[-1] != "continue"
            and len(trace) <= bounded.max_master_reviews + 1, trace)
        add(f"with a cap of {cap} every step is a decision", all(
            step in {"continue", "stop", "final"} for step in trace), trace)

    # ---- 6. a follow-up is a specification, not a wish -----------------
    drafts = [follow_up_draft(item, context=_selftest_context("exposure"))
              for item in assignments[:1]]
    add("a follow-up becomes a specification draft", bool(drafts))
    if drafts:
        validation = validate_subagent_specs(
            drafts, _selftest_context("exposure"),
            existing=[unit.role for unit in flow_units_for(
                _selftest_context("exposure"), "exposure")])
        add("a follow-up passes the same specification gates as a plan",
            validation.ok, [problem.detail[:80] for problem in validation.blocking_problems])
        add("the draft carries one measurable deliverable and a stop condition",
            bool(drafts[0].deliverables[0].measurable_check)
            and drafts[0].termination.is_measurable())
        unit = follow_up_subagent(assignments[0], context=_selftest_context("exposure"))
        add("a follow-up materialises as a runnable Subagent",
            bool(unit.workers) and unit.role == assignments[0].role,
            f"{unit.role}: {len(unit.workers)} worker(s)")

    def whole_mission_objective() -> None:
        FollowUpAssignment(route="new", role="everything-again",
                           objective="do everything again for any remaining gaps",
                           gap="the review found concerns", lens=ReviewLens.COVERAGE,
                           completion_criteria=["at least one row"],
                           justification="because the review said so")

    add("a follow-up cannot restate the whole mission",
        raises(whole_mission_objective, ValueError))

    def existing_without_target() -> None:
        FollowUpAssignment(route="existing", role="revisit",
                           objective="close the coverage gap in this report",
                           gap="nobody covers the affected component",
                           lens=ReviewLens.COVERAGE,
                           completion_criteria=["at least one row"],
                           justification="the review named this report as the owner")

    add("a revisit must name the Subagent it revisits",
        raises(existing_without_target, ValueError))

    # ---- 7. the demo, and the record's shape --------------------------
    demo = master_review_demo()
    add("the demo payload is serialisable",
        json.loads(json.dumps(demo, default=str))["acceptance"]["all_signals"])
    add("the demo shows every signal passing",
        all(demo["acceptance"]["signals"].values()),
        [name for name, ok in demo["acceptance"]["signals"].items() if not ok])
    add("the demo's loop stops", demo["loop"][-1]["action"] != "continue",
        demo["loop"])
    add("the demo names all four endings",
        set(demo["decisions"]) == {"continue", "budget", "saturation", "final"},
        sorted(demo["decisions"]))
    review_payload = concerns.to_dict()
    add("the review serialises every lens",
        all(len(observation["findings"]) == 5
            for observation in review_payload["observations"]))
    add("the decision serialises its refusals",
        isinstance(cont.to_dict()["refusals"], list))

    # ---- 8. the loop, inside the graph ---------------------------------
    # The fixtures above prove the *decisions*; these prove the graph honestly runs them,
    # and — the acceptance clause — that it comes to a stop on its own.
    context = _selftest_context("exposure")
    units = flow_units_for(context, "exposure")
    looped = HierarchicalFlow(
        context=context, subagents=units,
        runner=_CountingRunner(scope=context.scope_entries),
        policy=FlowPolicy(max_review_rounds=2, max_replan_rounds=1,
                          max_runtime_workers_per_subagent=0,
                          max_follow_up_workers_per_subagent=1))
    loop_result = looped.run()
    order = loop_result.stage_order()
    add("the run reaches the replan stage", "master-replan" in order, order)
    add("the replan stage sits between the review and the synthesis",
        order.index("master-review") < order.index("master-replan")
        <= order.index("master-synthesize"), order)
    add("the loop stops on its own", loop_result.decision is not None
        and loop_result.decision.stopped, loop_result.stop_reason)
    add("the stop condition is one of the five the task names",
        loop_result.stop_condition in {
            StopCondition.COMPLETE, StopCondition.SATURATION, StopCondition.BUDGET,
            StopCondition.DEADLINE, StopCondition.BLOCKED}, loop_result.stop_condition)
    add("a stopped loop still reports", loop_result.synthesis is not None)
    add("the mission reports one aggregate per subagent, follow-ups included",
        len(loop_result.reports) == len(looped.subagents)
        and {report.subagent_id for report in loop_result.reports}
        == {subagent.id for subagent in looped.subagents},
        len(loop_result.reports))
    add("the number of reviews is bounded by the review budget",
        len(looped.master_reviews()) <= looped.policy.max_master_reviews,
        len(looped.master_reviews()))
    add("the number of follow-up rounds is bounded by the round cap",
        len([item for item in looped.master_rounds()
             if item.decision.action == "continue"]) <= looped.policy.max_replan_rounds,
        len(looped.master_rounds()))
    add("every decision carries the reason it stopped",
        all(decision.refusals for decision in looped.master_decisions()
            if decision.stopped and not decision.finished),
        [decision.summary()[:60] for decision in looped.master_decisions()])
    add("the result carries the reviews and the decisions",
        len(loop_result.master_reviews) >= 1 and len(loop_result.master_decisions) >= 1)
    add("the result serialises the loop",
        json.loads(json.dumps(loop_result.to_dict(), default=str))["stop_condition"]
        == loop_result.stop_condition.value)

    # the cap at zero: one review, no continuation, still a report
    fixed = HierarchicalFlow(
        context=context, subagents=units,
        runner=_CountingRunner(scope=context.scope_entries),
        policy=FlowPolicy(allow_runtime_workers=False, max_replan_rounds=0))
    fixed_result = fixed.run()
    add("a mission with no replan budget reviews exactly once",
        len(fixed.master_reviews()) == 1, len(fixed.master_reviews()))
    add("a mission with no replan budget never reaches the replan stage",
        "master-replan" not in fixed_result.stage_order(), fixed_result.stage_order())
    add("a mission with no replan budget still reports",
        fixed_result.synthesis is not None)

    # the blockers: a mission configured to stop on failure must not replan past it
    dead_units = flow_units_for(context, "exposure")
    everything = [worker.id for subagent in dead_units for worker in subagent.workers]
    dead = HierarchicalFlow(
        context=context, subagents=dead_units,
        runner=_CountingRunner(scope=context.scope_entries, failing=everything),
        policy=FlowPolicy(max_review_rounds=1, allow_runtime_workers=False,
                          allow_follow_ups=True))
    dead_result = dead.run()
    add("a blocking failure stops before any replanning",
        dead_result.stopped and "master-replan" not in dead_result.stage_order(),
        dead_result.stage_order())
    add("a stopped mission produces no aggregate", dead_result.synthesis is None)

    # cancellation is a bound too, and it is recorded as one
    cancelled_units = flow_units_for(context, "exposure")
    cancelling = HierarchicalFlow(
        context=context, subagents=cancelled_units,
        runner=_CountingRunner(scope=context.scope_entries),
        policy=FlowPolicy(allow_runtime_workers=False))
    token = cancelling.runtime.token
    token.cancel("operator stopped the mission")
    cancelled_result = cancelling.run()
    add("a cancelled mission stops before synthesis", cancelled_result.stopped,
        cancelled_result.stop_reason)
    add("a cancelled mission names the cancellation",
        "cancel" in cancelled_result.stop_reason.lower(), cancelled_result.stop_reason)
    return checks

@app.command("review-master",
             help="Master review and bounded replanning: five lenses, five stop conditions.")
def review_master_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the review and its bounds, offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="Five lenses over four reports, then four endings."),
    next_report: str | None = typer.Option(
        None, "--next",
        help="Review a mission's Subagent reports from JSON ('-' for stdin)."),
    objective: str = typer.Option("", "--objective",
                                  help="The mission objective the reports are judged against."),
    rounds: int = typer.Option(1, "--rounds", min=0, max=3,
                               help="How many follow-up rounds the policy allows."),
    reviews: int = typer.Option(3, "--reviews", min=1, max=6,
                                help="How many reviews the policy allows."),
    follow_ups: bool = typer.Option(True, "--follow-ups/--no-follow-ups",
                                    help="Whether the Master may open a follow-up round."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Review a mission's reports, or explain why the loop stopped asking for more.

    Exit codes follow the same rule as the rest of the build: ``OK`` when the mission is
    finished or safely bounded, ``POLICY`` when it stopped short of its own criteria, so
    a pipeline can tell "done" from "bounded" without parsing prose.
    """

    console = get_console()

    if self_test:
        checks = run_master_review_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"checks": [check.to_dict() for check in checks],
                              "passed": len(checks) - len(failures),
                              "failed": len(failures)}, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        table = Table(box=None, pad_edge=False)
        table.add_column("check", no_wrap=True)
        table.add_column("detail", overflow="fold")
        for check in checks:
            glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
            table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                          escape(check.detail))
        console.print(table)
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = master_review_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_master_review_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if next_report:
        try:
            raw = (sys.stdin.read() if next_report == "-"
                   else Path(next_report).expanduser().read_text(encoding="utf-8"))
            payload = json.loads(raw)
        except (OSError, json.JSONDecodeError) as exc:
            console.print(f"[red]✘[/red] not a mission report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        try:
            reports = [SubagentOutcome.model_validate(item)
                       for item in payload.get("reports") or []]
            mission = str(payload.get("objective") or objective)
            questions = [str(item) for item in payload.get("questions") or []]
            criteria = [str(item) for item in payload.get("criteria") or []]
            subagents = [FlowSubagent.model_validate(item)
                         for item in payload.get("subagents") or []]
            scope = [str(item) for item in payload.get("scope") or []]
        except (KeyError, ValueError) as exc:
            console.print(f"[red]✘[/red] not a mission report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        policy = FlowPolicy(allow_follow_ups=follow_ups, max_replan_rounds=rounds,
                            max_master_reviews=reviews)
        review = review_reports(reports, objective=mission or objective,
                                questions=questions, criteria=criteria,
                                scope_entries=scope)
        assignments = plan_follow_ups(review, reports=reports, subagents=subagents,
                                      policy=policy, round_number=1)
        decision = decide_master(review, policy=policy, round_number=1,
                                 assignments=assignments)
        if as_json:
            _emit(json.dumps({"review": review.to_dict(),
                              "decisions": {"first": decision.to_dict()},
                              "assignments": [item.to_dict() for item in assignments],
                              "stop_condition": decision.condition.value},
                             indent=2, default=str))
            raise typer.Exit(ExitCode.OK if decision.finished or decision.stopped
                             else ExitCode.POLICY)
        console.print()
        console.print(render_master_review(review, decision))
        console.print()
        raise typer.Exit(ExitCode.OK if decision.finished or decision.stopped
                         else ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --next FILE")
    raise typer.Exit(ExitCode.USAGE)

@app.command("loops",
             help="Loop detection: repeated plans, queries and retasks, and saturation.")
def loops_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the detectors and their escalation, offline."),
    demo: bool = typer.Option(False, "--demo",
                              help="Three cycles and three outcomes: corrected, blocked, stopped."),
    reports: str | None = typer.Option(
        None, "--reports",
        help="Judge a mission's rounds from a JSON report set ('-' for stdin)."),
    evidence: str = typer.Option(
        "", "--evidence",
        help="Claims added per round, comma-separated (e.g. '4,0,0'), for --reports."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Report a loop, or prove that one would have been reported.

    Exit codes keep the build's rule: ``OK`` when nothing repeated or the repetition was
    bounded with a reason, ``POLICY`` when a line of inquiry is blocked and the mission
    therefore did not answer everything it set out to.
    """

    console = get_console()

    if self_test:
        checks = run_loop_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"checks": [check.to_dict() for check in checks],
                              "passed": len(checks) - len(failures),
                              "failed": len(failures)}, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        table = Table(box=None, pad_edge=False)
        table.add_column("check", no_wrap=True)
        table.add_column("detail", overflow="fold")
        for check in checks:
            glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
            table.add_row(f"[{colour}]{glyph}[/{colour}]", escape(check.name),
                          escape(check.detail))
        console.print(table)
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = loop_detection_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_loop_detection_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if reports:
        try:
            raw = (sys.stdin.read() if reports == "-"
                   else Path(reports).expanduser().read_text(encoding="utf-8"))
            payload = json.loads(raw)
        except (OSError, json.JSONDecodeError) as exc:
            console.print(f"[red]✘[/red] not a mission report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        try:
            series = [int(part) for part in evidence.split(",") if part.strip()]
        except ValueError as exc:
            console.print("[red]✘[/red] --evidence must be counts per round, e.g. 4,0,0")
            raise typer.Exit(ExitCode.USAGE) from exc
        if not series:
            series = _round_series(payload)
        blocked = [BlockedLine.model_validate(item)
                   for item in payload.get("blocked") or []]
        assessment = assess_saturation(series, blocked=blocked)
        if as_json:
            _emit(json.dumps({"evidence_added": assessment.to_dict(),
                              "blocked": [line.to_dict() for line in blocked]},
                             indent=2, default=str))
            raise typer.Exit(ExitCode.OK if not blocked and not assessment.stopped
                             else ExitCode.POLICY)
        console.print()
        console.print(_render_loop_report(assessment, blocked))
        console.print()
        raise typer.Exit(ExitCode.OK if not blocked and not assessment.stopped
                         else ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --reports FILE")
    raise typer.Exit(ExitCode.USAGE)


def _round_series(payload: Mapping[str, Any]) -> list[int]:
    """Claims added per round, from a report set that recorded them.

    Read from the payload rather than re-derived: the mission already counted this, and
    a second count would be a different number with the same name.
    """

    series = payload.get("evidence_added") or payload.get("added_per_round") or []
    try:
        return [int(value) for value in series]
    except (TypeError, ValueError):
        return []


def _render_loop_report(assessment: SaturationReport,
                        blocked: Sequence[BlockedLine]) -> Group:
    """The loop report: the series, the finding, and the stop it justifies."""

    series = Table(title="claims added per round", title_justify="left", box=None,
                   pad_edge=False, expand=False)
    series.add_column("round", no_wrap=True)
    series.add_column("new claims", no_wrap=True)
    for index, added in enumerate(assessment.added_per_round, start=1):
        colour = "green" if added else "yellow"
        series.add_row(str(index), f"[{colour}]{added}[/{colour}]")

    findings = Table(title="what the rounds showed", title_justify="left", box=None,
                     pad_edge=False, expand=False)
    findings.add_column("kind", no_wrap=True)
    findings.add_column("response", no_wrap=True)
    findings.add_column("detail", overflow="fold", max_width=68)
    for finding in assessment.findings:
        findings.add_row(escape(finding.kind.value), escape(finding.response.value),
                         escape(finding.detail[:200]))

    lines = Table(title="lines of inquiry blocked", title_justify="left", box=None,
                  pad_edge=False, expand=False)
    lines.add_column("subject", no_wrap=True)
    lines.add_column("would unblock", overflow="fold", max_width=66)
    for line in blocked:
        lines.add_row(escape(line.subject), escape(line.unblock))

    verdict = Text(
        (f"stopped ({assessment.condition.value}): {assessment.stop_reason}"
         if assessment.stopped else
         f"not stopped: {assessment.stop_reason or 'the mission is still adding claims'}"),
        style="red" if assessment.stopped else "green")
    return Group(series, Text(""), findings, *( [Text(""), lines] if blocked else []),
                 Text(""), verdict)


# ══════════════════════════════════════════════════════════════════════════
# 38. Loop detection and saturation stopping: a cycle that knows it is a cycle
# --------------------------------------------------------------------------
#
# §35 gave a retry a *different* instruction, and §36/§37 bounded how many extra
# rounds a Subagent or the Master may open.  Neither answers the question this
# section does: what if the work keeps happening and nothing keeps being learned?
# A Worker can be re-tasked with a genuinely different instruction and still spend
# its budget on the sources it already read; a mission can open a follow-up round
# that collects new *rows* while adding no new *claims*.  Both are loops, and a
# bound on the number of attempts only decides how long they run for.
#
# So this section detects the loop from the record, and escalates in the order the
# task names:
#
# 1.  **require the responsible agent to change strategy** — a first detection
#     attaches a *strategy change* to the next instruction, and a retask that
#     cannot name one is not issued;
# 2.  **mark the line of inquiry blocked** — a second detection of the same kind
#     for the same unit blocks that line: it stops asking, says what it would take
#     to unblock, and the gap travels into the report;
# 3.  **stop** — when the mission itself is the thing making no progress (rounds
#     that add no claims, or a round that re-aims where an earlier one aimed), the
#     mission stops, with the series it judged on the record.
#
# Three facts make this more than a counter:
#
# *   **Repetition is judged on substance, not wording.**  A query is a
#     *fingerprint* of its normalised form, so "example.com shodan search" and
#     "search shodan for example.com" are one query; a plan is a fingerprint of
#     its target and tools, so a re-worded retry of the same retrieval is one plan.
# *   **Progress is new claims, not new rows.**  A row whose statement the mission
#     already holds is a re-observation; counting it as progress is how a loop
#     looks like work.
# *   **No instruction may be unbounded.**  "Continue until done" is refused
#     wherever this build can refuse it (:func:`unbounded_instruction`), because a
#     loop detector cannot save an instruction that has no end condition — there is
#     nothing to detect until the budget is gone.


class CycleKind(str, Enum):
    """What kind of repetition was detected.

    Five kinds, because the record supports exactly five claims.  Each one names a
    different part of the mission that failed to move — the plan, the query, the
    instruction, the yield, or the round — and each implies a different remedy.
    """

    REPEATED_PLAN = "repeated-plan"              # the same shape of work, again
    REPEATED_QUERY = "repeated-query"            # the same retrieval, again
    REPEATED_RETASK = "repeated-retask"          # the same instruction, again
    DIMINISHING_RETURNS = "diminishing-returns"  # new work, no new evidence
    STALLED_ROUND = "stalled-round"              # a whole round, no new claims


class LoopResponse(str, Enum):
    """What the detection requires of the responsible agent.

    The ladder is the task's own: change strategy, block the line, or stop.  It is
    an escalation, not a choice — the same kind of cycle detected again on the same
    subject moves one rung down.
    """

    CORRECT = "correct"    # change strategy; the next instruction must say how
    BLOCK = "block"        # mark the line of inquiry blocked and stop asking
    STOP = "stop"          # stop the mission's line: no further round can help


class LoopFinding(StrictModel):
    """One detected cycle, with the evidence that makes it a cycle rather than a hunch.

    ``occurrences`` is a count of the record, not an estimate: two attempts that ran
    one query, two rounds that added nothing.  ``strategy_change`` is required exactly
    when the response is ``CORRECT`` — an instruction to "do something different"
    with no statement of what would be a second loop, one level up.
    """

    kind: CycleKind
    #: What repeated: a Worker id, a Subagent id, a query fingerprint, a plan.
    subject: str = Field(min_length=1)
    #: Which unit owns the fix.  Empty only for a mission-level finding.
    unit: str = ""
    round: int = Field(default=1, ge=1)
    occurrences: int = Field(default=2, ge=2)
    #: Claims this cycle added over the whole window: usually zero, and that is the
    #: point.  Kept as a number so "no progress" is measured rather than asserted.
    evidence_added: int = Field(default=0, ge=0)
    checked_by: str = ""
    detail: str = Field(min_length=12)
    response: LoopResponse = LoopResponse.CORRECT
    #: What the responsible agent must do differently.  Required for ``CORRECT``.
    strategy_change: str = ""
    #: What would unblock the line, for ``BLOCK``.  A block nobody can lift is a stop.
    unblock: str = ""

    @model_validator(mode="after")
    def _response_is_actionable(self) -> "LoopFinding":
        if self.response is LoopResponse.CORRECT:
            if len(self.strategy_change.strip()) < 15:
                raise ValueError(
                    "a correction must state the strategy change it requires: "
                    "'try again' is the loop, not the remedy")
        if self.response is LoopResponse.BLOCK and len(self.unblock.strip()) < 10:
            raise ValueError(
                "a blocked line must say what would unblock it, or it is a stop "
                "described as a pause")
        if self.evidence_added and self.kind in {CycleKind.DIMINISHING_RETURNS,
                                                 CycleKind.STALLED_ROUND}:
            # Diminishing returns with evidence is a real outcome, not a cycle: the
            # finding would be asserting a loop while its own number contradicts it.
            raise ValueError("a diminishing-returns finding cannot claim new evidence")
        return self

    @property
    def blocks(self) -> bool:
        return self.response is LoopResponse.BLOCK

    @property
    def stops(self) -> bool:
        return self.response is LoopResponse.STOP

    def describe(self) -> str:
        tail = (f" → {self.strategy_change[:100]}" if self.response is LoopResponse.CORRECT
                else f" → blocked: {self.unblock[:100]}" if self.response is LoopResponse.BLOCK
                else " → stop")
        return (f"{self.kind.value} on {self.subject[:60]} after {self.occurrences} "
                f"occurrence(s), {self.evidence_added} new claim(s): "
                f"{self.detail[:110]}{tail}")

    def to_dict(self) -> dict[str, Any]:
        return {"kind": self.kind.value, "subject": self.subject, "unit": self.unit,
                "round": self.round, "occurrences": self.occurrences,
                "evidence_added": self.evidence_added, "checked_by": self.checked_by,
                "detail": self.detail, "response": self.response.value,
                "strategy_change": self.strategy_change, "unblock": self.unblock,
                "description": self.describe()}


class LoopCheck(StrictModel):
    """One assertion in the §38 self-test."""

    name: str = Field(min_length=1)
    ok: bool
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "ok": self.ok, "detail": self.detail}


class QueryRecord(StrictModel):
    """One retrieval an attempt performed, as the record remembers it.

    ``fingerprint`` is of the *normalised* query — lowercased, punctuation folded,
    tokens sorted — so a re-worded repeat is caught.  ``claims`` is how many new
    claims that retrieval produced, which is what makes "the same query, again, and
    it still found nothing" a fact rather than an impression.
    """

    fingerprint: str = Field(min_length=4)
    query: str = ""
    #: The unit that ran it: a query list is per-unit, because the question the detector
    #: asks is whether *this* unit learned anything from repeating itself.
    unit: str = ""
    round: int = Field(default=1, ge=1)
    claims: int = Field(default=0, ge=0)

    @classmethod
    def of(cls, query: str, *, unit: str = "", round_number: int = 1,
           claims: int = 0) -> "QueryRecord":
        return cls(fingerprint=query_fingerprint(query), query=query[:200], unit=unit,
                   round=round_number, claims=claims)


class AttemptSignal(StrictModel):
    """What one attempt contributed, in the three numbers the detectors read.

    Deliberately tiny: the loop detectors must be able to judge *history* without
    re-reading reports, because the record they are given is a transcript of what
    already happened.
    """

    attempt: int = Field(ge=1)
    status: EntityStatus = EntityStatus.READY
    #: Claims this attempt added that the unit did not already hold.
    new_claims: int = Field(default=0, ge=0)
    #: Queries it ran, by fingerprint.
    queries: list[str] = Field(default_factory=list)
    #: The retask fingerprint it ran under, when it was retried.
    retask: str = ""
    #: The plan it was given, when it is a runtime Worker planned from a gap.
    plan: str = ""


class LoopDetection(StrictModel):
    """Every cycle detection for one unit, and what it requires.

    A unit is blocked when *any* finding for it says so — the harshest detection
    wins, because the point of a block is that a cheaper response already failed.
    """

    unit: str = ""
    findings: list[LoopFinding] = Field(default_factory=list)
    #: The reason code the report carries, when this detection stopped the unit.
    blocked_reason: str = ""

    @property
    def found(self) -> bool:
        return bool(self.findings)

    @property
    def blocked(self) -> bool:
        return any(finding.blocks or finding.stops for finding in self.findings)

    @property
    def kinds(self) -> list[str]:
        return [finding.kind.value for finding in self.findings]

    def kinds_as_enums(self) -> list["CycleKind"]:
        """The kinds as enums, for :func:`escalate`'s ``already_corrected``.

        A method rather than a caller-side comprehension because the escalation call is
        the one place a string and an enum could be confused, and the confusion would be
        silent: a kind that never matches never escalates, and the loop runs on.
        """

        return [finding.kind for finding in self.findings]

    @property
    def strategy_change(self) -> str:
        """The correction the next instruction must carry, or ``""``."""

        for finding in self.findings:
            if finding.response is LoopResponse.CORRECT:
                return finding.strategy_change
        return ""

    def describe(self) -> str:
        if not self.findings:
            return f"{self.unit or 'mission'}: no cycle detected"
        return (f"{self.unit or 'mission'}: {len(self.findings)} cycle(s) "
                f"({', '.join(self.kinds)})"
                + (f"; blocked: {self.blocked_reason[:100]}" if self.blocked else
                   f"; required: {self.strategy_change[:100]}"))

    def to_dict(self) -> dict[str, Any]:
        return {"unit": self.unit,
                "findings": [finding.to_dict() for finding in self.findings],
                "found": self.found, "blocked": self.blocked,
                "kinds": self.kinds, "blocked_reason": self.blocked_reason,
                "strategy_change": self.strategy_change,
                "description": self.describe()}


class BlockedLine(StrictModel):
    """A line of inquiry the mission has stopped asking about, and why.

    This is the object the report carries instead of a silent gap: a subject the
    mission tried, the evidence that it was not progressing, what would unblock it,
    and — when it exists — the alternative the responsible agent was told to try.
    """

    subject: str = Field(min_length=1)
    kind: CycleKind
    unit: str = ""
    attempts: int = Field(default=2, ge=2)
    evidence_added: int = Field(default=0, ge=0)
    reason: str = Field(min_length=12)
    unblock: str = Field(min_length=10)
    alternative: str = ""

    def gap_detail(self) -> str:
        """How this block reads as an unknown, from §14's vocabulary."""

        tail = f"; would unblock: {self.unblock[:120]}" if self.unblock else ""
        return f"line of inquiry blocked ({self.kind.value}): {self.reason[:160]}{tail}"

    def to_dict(self) -> dict[str, Any]:
        return {"subject": self.subject, "kind": self.kind.value, "unit": self.unit,
                "attempts": self.attempts, "evidence_added": self.evidence_added,
                "reason": self.reason, "unblock": self.unblock,
                "alternative": self.alternative, "gap": self.gap_detail()}


class SaturationReport(StrictModel):
    """The mission's answer to "was it still learning?" — and what it did about it.

    Kept separate from :class:`LoopDetection` because it is a different level: a
    Worker can cycle inside a healthy mission, and a mission can stall with no unit
    cycling at all.  A report that conflated them could not say which one stopped.
    """

    #: Claims added per round, in order: the series the diminishing-returns test reads.
    added_per_round: list[int] = Field(default_factory=list)
    #: Which round the mission stopped tracking progress at, when it did.
    stalled_rounds: int = Field(default=0, ge=0)
    findings: list[LoopFinding] = Field(default_factory=list)
    blocked: list[BlockedLine] = Field(default_factory=list)
    #: ``""`` when the mission kept making progress.
    stop_reason: str = ""
    #: The stop condition this report justifies, so the caller does not re-derive it.
    condition: StopCondition = StopCondition.NONE

    @property
    def diminishing(self) -> bool:
        """True when the last two rounds both added nothing new."""

        return len(self.added_per_round) >= 2 and self.added_per_round[-1] == 0 \
            and self.added_per_round[-2] == 0

    @property
    def stopped(self) -> bool:
        return self.condition is not StopCondition.NONE

    @property
    def saturated(self) -> bool:
        """Whether the *evidence* stopped growing, whether or not the mission stopped."""

        return bool(self.added_per_round) and self.added_per_round[-1] == 0

    def summary(self) -> str:
        if not self.findings and not self.blocked:
            return ("no cycle detected: every round added claims the mission did not "
                    "already hold" if self.added_per_round else
                    "no rounds were reviewed")
        tail = (f"; stopped ({self.condition.value}): {self.stop_reason[:120]}"
                if self.stopped else "")
        return (f"{len(self.findings)} cycle(s), {len(self.blocked)} blocked line(s); "
                f"claims per round {self.added_per_round}{tail}")

    def to_dict(self) -> dict[str, Any]:
        return {"added_per_round": list(self.added_per_round),
                "stalled_rounds": self.stalled_rounds,
                "findings": [finding.to_dict() for finding in self.findings],
                "blocked": [line.to_dict() for line in self.blocked],
                "diminishing": self.diminishing, "saturated": self.saturated,
                "stopped": self.stopped, "condition": self.condition.value,
                "stop_reason": self.stop_reason, "summary": self.summary()}


# --------------------------------------------------------------------------
# 38.1 What "the same thing again" means
# --------------------------------------------------------------------------

#: Words that carry no retrieval meaning, so two queries that differ only by them are
#: one query.  Narrower than :data:`_RELEVANCE_STOPWORDS`: this list is about *how* a
#: source is asked, and "search", "query", "lookup" are the vocabulary of asking.
_QUERY_NOISE: frozenset[str] = frozenset({
    "search", "searching", "query", "queries", "lookup", "look", "find", "fetch",
    "retrieve", "get", "the", "a", "an", "for", "of", "on", "in", "and", "or", "to",
    "from", "with", "please", "all", "any", "some",
})

#: Phrases that make an instruction unbounded.  A stop condition is not a detail: an
#: objective that says "continue until there is nothing left" has no end the mission
#: can test, so no budget, deadline or detector can be honest about where it stopped.
_UNBOUNDED_PHRASES: tuple[str, ...] = (
    "until it ends", "until the end", "until done", "until finished", "until exhausted",
    "until nothing", "until there is nothing", "keep going", "keep searching",
    "keep looking", "continue until", "repeat until", "loop until", "forever",
    "indefinitely", "as long as it takes", "no limit", "without limit", "never stop",
    "exhaust every", "exhaust all", "all possible sources", "every possible source",
)


def query_fingerprint(query: str) -> str:
    """The identity of a retrieval, insensitive to wording and word order.

    "Shodan search for example.com" and "search example.com on shodan" are one query
    to a source, so they are one fingerprint here.  The digest is over sorted content
    tokens rather than the string, which is what makes a re-worded repeat detectable
    without a fuzzy match — a fuzzy match would need a threshold, and a threshold is a
    judgement this build does not let a detector make.
    """

    # Split on every non-alphanumeric character, so "example.com" and "example com" are
    # the same two words: a source does not care how a client punctuates a domain, and a
    # fingerprint that did would miss the most common re-worded repeat there is.
    tokens = sorted({token for token in re.findall(r"[a-z0-9]+", (query or "").lower())
                     if token not in _QUERY_NOISE})
    if not tokens:
        tokens = ["empty"]
    return content_id("qry", tokens, length=12)


def plan_fingerprint_of(*, target: str, tools: Sequence[str] = (),
                        work_unit: str = "") -> str:
    """The identity of a *plan*: what it aims at, with what, as which unit of work.

    Objective wording is deliberately excluded.  §35 exists to make a retry's wording
    differ, so a plan fingerprint that included the wording could never detect the
    loop it is for: "read the advisories again, this time carefully" is the same plan.
    """

    payload = {"target": _claim_key(target or "")[:200],
               "tools": sorted({str(tool).strip().lower() for tool in tools if str(tool).strip()}),
               "work_unit": _claim_key(work_unit or "")[:120]}
    return content_id("plan", payload, length=12)


def unbounded_instruction(text: str) -> str:
    """The unbounded phrase in an instruction, or ``""`` when it has an end condition.

    Checked wherever this build accepts an instruction — a Worker's completion criteria,
    a retask's correction, a follow-up's objective — because an unbounded instruction is
    the one loop a detector cannot catch: there is no repetition to see, only a unit
    that never returns.
    """

    lowered = (text or "").lower()
    for phrase in _UNBOUNDED_PHRASES:
        if phrase in lowered:
            return phrase
    return ""


def _claim_set(outcome: "WorkerOutcome") -> set[str]:
    """The normalised claims one attempt added, from its report or its evidence ids.

    Two sources, because a record has two: a report carries statements (the strongest
    form), and an outcome carries ids (enough to tell *that* something new arrived).
    Normalising to the claim where possible is what makes "the same fact, restated"
    count as nothing new.
    """

    report = _report_of(outcome)
    if report is not None and report.evidence:
        return {_claim_key(item.statement) for item in report.evidence}
    return {f"id:{item}" for item in outcome.evidence_ids}


def attempt_signal(outcome: "WorkerOutcome", *, prior: Sequence["WorkerOutcome"] = (),
                   retask: str = "", plan: str = "",
                   queries: Sequence[str] = ()) -> AttemptSignal:
    """Summarise one attempt: how many claims it added, and what it ran.

    ``prior`` is the unit's earlier attempts — not the mission's evidence — because the
    question here is whether *this unit* is moving.  A unit that keeps finding things
    the mission already knows is exactly the case this section exists for.
    """

    held: set[str] = set()
    for earlier in prior:
        held |= _claim_set(earlier)
    added = _claim_set(outcome) - held
    return AttemptSignal(
        attempt=outcome.attempt, status=outcome.status, new_claims=len(added),
        queries=[query_fingerprint(query) for query in queries],
        retask=retask, plan=plan)


# --------------------------------------------------------------------------
# 38.2 The four detectors
# --------------------------------------------------------------------------

#: How many times one query may repeat with nothing new before the line is blocked.
#: Two: the second run is the repeat, and a third is the mission spend the detector
#: exists to prevent.  Named rather than inlined so the number is inspectable.
REPEATED_QUERY_LIMIT: int = 2

#: How many consecutive zero-yield attempts make a diminishing-returns finding.
DIMINISHING_ATTEMPTS: int = 2


def detect_repeated_queries(queries: Sequence["QueryRecord"], *,
                            unit: str = "", round_number: int = 1,
                            alternative: str = "") -> LoopFinding | None:
    """The same retrieval, run again, producing nothing new.

    A repeated query with new claims is *not* a loop: the source changed, or the
    earlier attempt read it badly.  The finding is only made when the repetition and
    the empty yield coincide, which is the definition of a cycle worth stopping.
    """

    counts: dict[str, list[QueryRecord]] = {}
    for record in queries:
        counts.setdefault(record.fingerprint, []).append(record)
    for fingerprint, records in counts.items():
        if len(records) < REPEATED_QUERY_LIMIT:
            continue
        added = sum(record.claims for record in records[1:])
        if added:
            continue
        return LoopFinding(
            kind=CycleKind.REPEATED_QUERY, subject=fingerprint, unit=unit,
            round=round_number, occurrences=len(records), evidence_added=0,
            checked_by=(f"{len(records)} runs of one normalised query, "
                        f"{added} new claim(s) after the first"),
            detail=(f"the query {records[0].query[:120]!r} ran {len(records)} times and "
                    f"added nothing after the first run"),
            response=LoopResponse.CORRECT,
            strategy_change=(alternative or
                             "run a different retrieval for this question: name the "
                             "source family the earlier attempts did not read"))
    return None


def detect_repeated_plans(signals: Sequence["AttemptSignal"], *,
                          unit: str = "", round_number: int = 1,
                          alternative: str = "") -> LoopFinding | None:
    """The same plan, executed again, with no new claims between the two runs.

    Plans are grouped by :func:`plan_fingerprint_of`, so a retry whose objective was
    re-worded but whose target and tools did not change is caught — which is exactly
    the loop §35's re-wording could otherwise hide.
    """

    grouped: dict[str, list[AttemptSignal]] = {}
    for attempt in signals:
        if attempt.plan:
            grouped.setdefault(attempt.plan, []).append(attempt)
    for fingerprint, runs in grouped.items():
        if len(runs) < 2:
            continue
        added = sum(run.new_claims for run in runs[1:])
        if added:
            continue
        return LoopFinding(
            kind=CycleKind.REPEATED_PLAN, subject=fingerprint, unit=unit,
            round=round_number, occurrences=len(runs), evidence_added=0,
            checked_by=(f"{len(runs)} attempts under one plan fingerprint, "
                        f"{added} new claim(s) after the first"),
            detail=(f"attempts {', '.join(str(run.attempt) for run in runs)} ran the "
                    f"same plan (same target, same tools) and the mission learned "
                    f"nothing after the first"),
            response=LoopResponse.CORRECT,
            strategy_change=(alternative or
                             "change the plan, not the wording: a different target or a "
                             "different tool for this unit's question"))
    return None


def detect_repeated_retasks(retasks: Sequence["RetaskedWorker"], *,
                            unit: str = "", round_number: int = 1,
                            alternative: str = "") -> LoopFinding | None:
    """Two attempts handed the same instruction — §35's own failure, detected in place.

    ``RetaskedWorker.fingerprint`` already digests the substance of an instruction, so
    this detector is the cheap one: it asks whether the machinery §35 added is being
    respected, and escalates when it is not.
    """

    prints = [(retask.attempt, retask.fingerprint) for retask in retasks]
    for index in range(1, len(prints)):
        if prints[index][1] != prints[index - 1][1]:
            continue
        return LoopFinding(
            kind=CycleKind.REPEATED_RETASK, subject=prints[index][1], unit=unit,
            round=round_number, occurrences=2, evidence_added=0,
            checked_by="two retasks with one substance fingerprint",
            detail=(f"attempts {prints[index - 1][0]} and {prints[index][0]} were given "
                    f"the same instruction (same corrections, same evidence, same "
                    f"schema), so the second retry could not have differed"),
            response=LoopResponse.CORRECT,
            strategy_change=(alternative or
                             "issue a retask that corrects a different dimension, or "
                             "carry different evidence forward"))
    return None


def detect_diminishing_returns(signals: Sequence["AttemptSignal"], *,
                               unit: str = "", round_number: int = 1,
                               alternative: str = "") -> LoopFinding | None:
    """New attempts, no new claims, for long enough that another is waste.

    Distinct from the other three: nothing repeats *literally* here.  The unit is
    doing different-looking work and getting nowhere, which is the loop a repetition
    test cannot see and the reason the task asks for diminishing returns by name.
    """

    if len(signals) < DIMINISHING_ATTEMPTS:
        return None
    tail = list(signals)[-DIMINISHING_ATTEMPTS:]
    if any(signal.new_claims for signal in tail):
        return None
    return LoopFinding(
        kind=CycleKind.DIMINISHING_RETURNS, subject=unit or "unit", unit=unit,
        round=round_number, occurrences=len(tail), evidence_added=0,
        checked_by=(f"the last {len(tail)} attempt(s) each added 0 claims the unit did "
                    f"not already hold"),
        detail=(f"{len(tail)} consecutive attempt(s) added nothing new "
                f"(attempts {', '.join(str(signal.attempt) for signal in tail)})"),
        response=LoopResponse.CORRECT,
        strategy_change=(alternative or
                         "raise the yield before spending another attempt: change the "
                         "source, the slice, or the question"))
    return None


def detect_unit_cycle(signals: Sequence["AttemptSignal"], *,
                      queries: Sequence["QueryRecord"] = (),
                      retasks: Sequence["RetaskedWorker"] = (),
                      unit: str = "", round_number: int = 1,
                      alternative: str = "") -> LoopDetection:
    """Every detector, over one unit's history — with the escalation already applied.

    The ladder is applied here rather than by the caller because it is a rule about
    *repetition*, and only this function can see how much of it there has been:

    *   a unit with no prior correction is asked to **change strategy**;
    *   a unit that has already been asked, and repeated anyway, has its line marked
        **blocked** — a second correction would be the loop, one level up.

    ``previous`` is passed as the corrections the unit has already been given, so the
    escalation is a property of the record rather than a counter in a closure.
    """

    findings = [finding for finding in (
        detect_repeated_queries(queries, unit=unit, round_number=round_number,
                               alternative=alternative),
        detect_repeated_plans(signals, unit=unit, round_number=round_number,
                              alternative=alternative),
        detect_repeated_retasks(retasks, unit=unit, round_number=round_number,
                                alternative=alternative),
        detect_diminishing_returns(signals, unit=unit, round_number=round_number,
                                   alternative=alternative),
    ) if finding is not None]
    return escalate(LoopDetection(unit=unit, findings=findings))


def escalate(detection: LoopDetection, *,
             already_corrected: Sequence[CycleKind] = ()) -> LoopDetection:
    """Move a detection one rung down the ladder when a correction already failed.

    ``already_corrected`` is the set of kinds the unit was previously told to change
    strategy about.  A kind that repeats after its correction becomes a **block**: the
    strategy change was the remedy, and it did not work, so the honest next step is to
    stop asking and say what would unblock it.  A mission-level finding climbs the
    same ladder one level up, to ``STOP``, in :func:`assess_saturation`.
    """

    findings: list[LoopFinding] = []
    for finding in detection.findings:
        if finding.kind not in already_corrected:
            findings.append(finding)
            continue
        unblock = (f"a source or capability the mission has not used for this subject "
                   f"({finding.subject[:60]}); the earlier correction was applied and "
                   f"the cycle repeated")
        findings.append(finding.model_copy(update={
            "response": LoopResponse.BLOCK, "unblock": unblock,
            "checked_by": f"{finding.checked_by}; corrected once already"}))
    blocked = [finding for finding in findings if finding.blocks or finding.stops]
    reason = blocked[0].describe() if blocked else ""
    return detection.model_copy(update={"findings": findings,
                                        "blocked_reason": reason})


# --------------------------------------------------------------------------
# 38.3 Mission-level saturation
# --------------------------------------------------------------------------

#: How many consecutive rounds with no new claims end the mission's line.
STALLED_ROUNDS_LIMIT: int = 2


def assess_saturation(added_per_round: Sequence[int], *,
                      finding: LoopFinding | None = None,
                      blocked: Sequence[BlockedLine] = ()) -> SaturationReport:
    """Whether the *mission* is still learning, and what that means for stopping.

    Two rounds with no new claims is the bound, and it is deliberately the same number
    as §37's saturation: the two sections must agree, or a mission could pass one test
    and fail the other while both call themselves authoritative.  The difference is
    that this function also carries what happened *inside* the rounds — the unit-level
    findings and the blocke lines — so the report can say which part of the mission
    stalled rather than only that it did.
    """

    series = [int(value) for value in added_per_round]
    trailing = 0
    for value in reversed(series):
        if value:
            break
        trailing += 1
    condition = StopCondition.NONE
    reason = ""
    if trailing >= STALLED_ROUNDS_LIMIT:
        condition = StopCondition.SATURATION
        reason = (f"{trailing} consecutive round(s) added no claim the mission did not "
                  f"already hold; another round would repeat the last one")
    elif series and series[-1] == 0 and trailing == 1:
        reason = ("the last round added no new claims; one more empty round stops the "
                  "mission")
    stalled = LoopFinding(
        kind=CycleKind.STALLED_ROUND, subject="mission", round=max(1, len(series)),
        occurrences=max(trailing, STALLED_ROUNDS_LIMIT), evidence_added=0,
        checked_by=(f"claims added per round: {series}; {trailing} empty round(s) at "
                    f"the end"),
        detail=(f"the mission added no new claim in {trailing} consecutive round(s)"),
        response=LoopResponse.STOP if condition is not StopCondition.NONE
        else LoopResponse.CORRECT,
        strategy_change=("aim the next round at a question no report has answered "
                         "yet, or stop" if condition is StopCondition.NONE else ""),
        unblock="")
    findings = [stalled] if trailing else []
    if finding is not None:
        findings.append(finding)
    return SaturationReport(
        added_per_round=series,
        stalled_rounds=trailing if trailing >= STALLED_ROUNDS_LIMIT else 0,
        findings=findings, blocked=list(blocked),
        stop_reason=reason, condition=condition)


def blocked_line(finding: LoopFinding | BlockedLine) -> BlockedLine:
    """The report's record of a blocked line, from the finding that blocked it.

    Idempotent: given a line it is already a :class:`BlockedLine`, it returns it.  The
    ledger calls this to register a block, and a caller holding a line must be able to
    register it too — a conversion that only worked one way would make the second
    registration an error at exactly the moment the mission is trying to be careful.
    """

    if isinstance(finding, BlockedLine):
        return finding
    return BlockedLine(
        subject=finding.subject, kind=finding.kind, unit=finding.unit,
        attempts=finding.occurrences, evidence_added=finding.evidence_added,
        reason=finding.detail, unblock=finding.unblock,
        alternative=finding.strategy_change)


def cycle_gaps(lines: Sequence[BlockedLine]) -> list["UnknownValue"]:
    """Blocked lines as unknowns, so they travel into the report as gaps.

    A block that stayed inside the ledger would be a silent gap — the failure mode
    §34 and §36 both exist to prevent, one level down.  These are the same objects the
    final report carries, named by the unit that hit the loop.
    """

    return [UnknownValue(reason=UnknownReason.UNAVAILABLE,
                         determined_by=line.unit or "mission",
                         detail=line.gap_detail()) for line in lines]


# --------------------------------------------------------------------------
# 38.4 The flow's own history: what to detect, and what to do about it
# --------------------------------------------------------------------------

#: The instruction a Worker gets when the loop detector has fired for it.  It is
#: prepended to whatever §35 said, because the two answers are different: §35 says what
#: was wrong with the last attempt, §38 says what kind of work is no longer allowed.
CORRECTION_PREAMBLE: str = (
    "Change of strategy required — the previous attempts repeated work without adding "
    "evidence. {change} Do not run a retrieval you have already run for this unit; if "
    "you cannot name a different source or a different question, report the line as "
    "blocked instead of trying again."
)

#: Appended to a retask boundary so the reason survives into the report rather than the
#: log.  Deliberately a sentence, not a code: the report is read by people.
BLOCKED_NOTE: str = (
    "This line of inquiry is blocked after {attempts} attempt(s): {reason} "
    "It would unblock with: {unblock}"
)


class StrategyChange(StrictModel):
    """A correction the flow applied to one unit, and the attempt it applied to.

    Recorded rather than computed so the escalation is auditable: a unit whose second
    cycle is blocked must be able to show the correction it ignored, which means the
    correction has to exist as an object on the record.
    """

    unit: str = Field(min_length=1)
    kind: CycleKind
    attempt: int = Field(default=1, ge=1)
    instruction: str = Field(min_length=15)
    required_for: str = ""
    #: Whether an instruction actually carried the change.  A correction recorded after
    #: the branch's last allowed attempt was never applied, and a record that called it
    #: applied would credit the mission with a remedy it never tried.
    applied: bool = False

    def to_dict(self) -> dict[str, Any]:
        return {"unit": self.unit, "kind": self.kind.value, "attempt": self.attempt,
                "instruction": self.instruction, "required_for": self.required_for,
                "applied": self.applied}


def correction_text(change: str) -> str:
    """The correction as an instruction, refusing one that does not say anything."""

    if len((change or "").strip()) < 15:
        raise ValueError("a strategy change must name what to do differently")
    return CORRECTION_PREAMBLE.format(change=change.strip())


def blocked_note(finding: LoopFinding) -> str:
    return BLOCKED_NOTE.format(attempts=finding.occurrences, reason=finding.detail,
                               unblock=finding.unblock)


def enforcement(detection: LoopDetection) -> dict[str, Any]:
    """What a detected cycle requires of the graph, as a small, serialisable dict.

    One dict, three keys, because everything downstream needs the same three answers:
    may the branch run again (``allowed``), what must its next instruction say
    (``correction``), and what must the report say happened (``blocked``).
    """

    return {"allowed": not detection.blocked,
            "correction": detection.strategy_change,
            "blocked": detection.blocked_reason,
            "kinds": detection.kinds,
            "findings": [finding.to_dict() for finding in detection.findings]}


def halted_retask(retask: RetaskedWorker, detection: LoopDetection) -> RetaskedWorker:
    """A retask that would repeat an instruction, rewritten to stop repeating it.

    Three rewrites, all structural:

    *   the corrections are re-stated, one per dimension, in the terms of the strategy
        change, so a retask cannot re-assert the deficiency that produced the cycle;
    *   the instruction carries the change itself, which is what makes the next
        ``fingerprint`` differ from the last one;
    *   the evidence already collected stays carried forward, so the unit is not asked
        to look again at what it has.

    A retask that cannot be rewritten raises: the caller's honest next move is a block,
    and a silently unchanged retask is the loop.
    """

    change = detection.strategy_change
    if not change:
        raise ValueError("a halted retask needs a strategy change to carry")
    # One statement of the problem per dimension is an invariant of RetaskedWorker, so a
    # correction is *restated* rather than appended: the dimension that led to the loop
    # keeps its slot, and says something different in it.
    fresh = [
        item.model_copy(update={"correction": f"{item.correction} — instead: {change}"})
        for item in retask.corrections]
    rebuilt = retask.model_copy(update={
        "corrections": fresh,
        "prompt": f"""{retask.prompt}

{[correction_text(change)]}""",
        "already_collected": list(retask.already_collected)})
    # The fingerprint is *recomputed*: ``model_copy`` carries the old one across, and a
    # copied digest would make the check below pass on every retask — the exact silent
    # repeat this function exists to make impossible.
    rebuilt = rebuilt.model_copy(update={"fingerprint": retask_fingerprint(rebuilt)})
    if rebuilt.fingerprint == retask.fingerprint:
        raise ValueError("the strategy change did not alter the instruction")
    return rebuilt


# --------------------------------------------------------------------------
# 38.5 The ledger the graph writes to
# --------------------------------------------------------------------------

def _worker_queries(outcome: "WorkerOutcome") -> list[str]:
    """The retrievals one attempt ran, read from the record it actually left.

    The payload's prepared queries: what the attempt was told to run, which is the only
    query list a record carries in a form that can be compared.  A unit whose record
    names none gets none, and the query detector then says nothing about it — an
    inferred query list would be the detector inventing the evidence of a loop.
    """

    queries: list[str] = []
    payload = outcome.payload or {}
    for key in ("queries", "prepared_queries"):
        value = payload.get(key)
        if isinstance(value, (list, tuple)):
            queries.extend(str(item) for item in value if str(item).strip())
    return list(dict.fromkeys(queries))[:12]


class LoopLedger(StrictModel):
    """Every cycle this run detected, every correction it required, every line it blocked.

    One object because the three lists are only meaningful together: a block with no
    correction behind it is a mission that gave up without trying, and a correction with
    no record of what happened next is a bound nobody verified.
    """

    #: One signal per attempt that ran, in attempt order.  The history the detectors read.
    signals: dict[str, list[AttemptSignal]] = Field(default_factory=dict)
    #: The retrievals the mission ran, with their yield.
    queries: list[QueryRecord] = Field(default_factory=list)
    #: Findings that required a strategy change, and the change recorded for the unit.
    corrections: list[StrategyChange] = Field(default_factory=list)
    #: Lines of inquiry the mission has stopped asking about.
    blocked: list[BlockedLine] = Field(default_factory=list)
    #: Mission-level saturation: claims per round, and the stop it justifies.
    saturation: SaturationReport = Field(default_factory=SaturationReport)

    @property
    def findings(self) -> list[LoopFinding]:
        return list(self.saturation.findings) + [
            finding for finding in self._unit_findings()]

    def _unit_findings(self) -> list[LoopFinding]:
        found: list[LoopFinding] = []
        for finding in self.corrections:
            found.append(LoopFinding(
                kind=finding.kind, subject=finding.unit, unit=finding.unit,
                round=finding.attempt, occurrences=2, evidence_added=0,
                checked_by="recorded correction", detail=finding.instruction[:200],
                response=LoopResponse.CORRECT, strategy_change=finding.instruction))
        return found

    def signals_for(self, unit: str) -> list[AttemptSignal]:
        return list(self.signals.get(unit, []))

    def corrected_kinds(self, unit: str) -> list[CycleKind]:
        """The kinds this unit has already been told to change strategy about."""

        return [change.kind for change in self.corrections if change.unit == unit]

    def is_blocked(self, unit: str) -> bool:
        return any(line.unit == unit for line in self.blocked)

    def block(self, finding: LoopFinding) -> BlockedLine:
        """Record a blocked line once, returning the record either way."""

        existing = next((line for line in self.blocked
                         if line.subject == finding.subject and line.kind is finding.kind),
                        None)
        if existing is not None:
            return existing
        line = blocked_line(finding)
        self.blocked.append(line)
        return line

    def note_query(self, query: str, *, unit: str = "", round_number: int = 1,
                   claims: int = 0) -> QueryRecord:
        record = QueryRecord.of(query, unit=unit, round_number=round_number,
                                claims=claims)
        self.queries.append(record)
        return record

    def summary(self) -> dict[str, Any]:
        return {"units_watched": len(self.signals),
                "attempts": sum(len(items) for items in self.signals.values()),
                "queries": len(self.queries),
                "corrections": [change.to_dict() for change in self.corrections],
                "blocked": [line.to_dict() for line in self.blocked],
                "saturation": self.saturation.to_dict(),
                "kinds": sorted({finding.kind.value for finding in self.findings})}

    def to_dict(self) -> dict[str, Any]:
        return {"signals": {unit: [signal.model_dump(mode="json") for signal in items]
                            for unit, items in self.signals.items()},
                "queries": [record.model_dump(mode="json") for record in self.queries],
                "corrections": [change.to_dict() for change in self.corrections],
                "blocked": [line.to_dict() for line in self.blocked],
                "saturation": self.saturation.to_dict(),
                "summary": self.summary()}

    def describe(self) -> str:
        if not self.corrections and not self.blocked and not self.saturation.findings:
            return "no loop detected: every attempt added claims the unit did not hold"
        parts = []
        if self.corrections:
            parts.append(f"{len(self.corrections)} strategy change(s)")
        if self.blocked:
            parts.append(f"{len(self.blocked)} line(s) blocked")
        if self.saturation.findings:
            parts.append(f"saturation: {self.saturation.summary()}")
        return "; ".join(parts)


# ══════════════════════════════════════════════════════════════════════════
# 39. Evidence-based Master synthesis: a report that cannot outrun its evidence
# --------------------------------------------------------------------------
#
# The mission produces one document, and the one thing it must not do is conclude more
# than it can show.  §34 judged every Worker result, §35 re-tasked what failed, §36
# reconciled each Subagent, §37 decided whether to keep working and §38 detected when
# working had stopped helping.  This section turns the finished record into the answer:
# an executive summary, scope and methods, key findings, corroborated indicators,
# competing hypotheses, contradictions, confidence levels, evidence gaps, limitations
# and lawful next steps.
#
# The design problem is not formatting.  It is that a synthesis is *authored* — by a
# model, in the ordinary case — and an authored conclusion can say anything.  So the
# document is assembled from typed parts (:class:`SynthesisSection`, each one of them),
# and the assembly is what enforces the acceptance clause:
#
# *   **Every key finding links to evidence ids.**  A :class:`KeyFinding` cannot be
#     constructed without them, and every id must exist in the mission's own evidence —
#     a finding that cites an id nobody collected is refused at construction, not
#     flagged later.
# *   **No conclusion exceeds its evidence.**  Confidence is *derived*, twice over: from
#     independent origins (the same rule the research audit uses, so two sections cannot
#     disagree about what "corroborated" means) and from the epistemic kind of the item
#     (an allegation is capped at low and an inference at medium, whatever a model says).
#     A stated confidence above the derived ceiling is refused.
# *   **No declarations of guilt, no certain identity attribution.**  The scope policy
#     already pauses objectives that assume guilt; the *output* needs the same bar, so
#     :func:`check_attribution` refuses a verdict and :func:`check_identity_claim` refuses
#     a certain identity claim, and both run on every finding at construction.
#
# The report also says what it does not know: gaps are §14 unknowns carried forward, the
# contradictions are preserved rather than settled (§36's rule, a level up), and the
# hypotheses section is allowed — indeed required — to keep more than one explanation
# alive when the evidence does not choose between them.


class SynthesisConflict(Exception):
    """Raised when a synthesis would say more than the evidence supports."""


class ConfidenceBand(str, Enum):
    """The three levels of confidence a finished report may state, and what earns each.

    Deliberately the same three bands the mission's :class:`Confidence` enum uses, named
    here so the *rule* that assigns a band is a thing a reader can inspect: one
    independent origin is ``SINGLE_SOURCE``, two are ``CORROBORATED``, and three or more
    agreeing origins on a material claim are ``WELL_CORROBORATED``.  A band starts at
    ``SINGLE_SOURCE`` because any statement in the report rests on at least one citation —
    a statement that rests on none is not a finding.
    """

    SINGLE_SOURCE = "single-source"
    CORROBORATED = "corroborated"
    WELL_CORROBORATED = "well-corroborated"

    @property
    def confidence(self) -> Confidence:
        """The coarse confidence this band reports as."""

        return {ConfidenceBand.SINGLE_SOURCE: Confidence.LOW,
                ConfidenceBand.CORROBORATED: Confidence.MEDIUM,
                ConfidenceBand.WELL_CORROBORATED: Confidence.HIGH}[self]

    @property
    def rank(self) -> int:
        return {ConfidenceBand.SINGLE_SOURCE: 1, ConfidenceBand.CORROBORATED: 2,
                ConfidenceBand.WELL_CORROBORATED: 3}[self]

    @classmethod
    def of(cls, confidence: Confidence) -> "ConfidenceBand":
        return {Confidence.LOW: cls.SINGLE_SOURCE, Confidence.MEDIUM: cls.CORROBORATED,
                Confidence.HIGH: cls.WELL_CORROBORATED,
                Confidence.UNKNOWN: cls.SINGLE_SOURCE}[confidence]


#: What an allegation may be reported as, whatever its sources say.  A third party's
#: claim is not corroborated by a third party repeating it: the *claim* is well
#: attested, the conduct is not established, and the band has to say the second thing.
ALLEGATION_CEILING: ConfidenceBand = ConfidenceBand.CORROBORATED

#: What an inference may be reported as.  Reasoning over good evidence is still
#: reasoning: three origins can establish a fact, and can only make a conclusion likely.
INFERENCE_CEILING: ConfidenceBand = ConfidenceBand.CORROBORATED

#: The bands each epistemic kind is allowed to reach.  A lookup rather than a chain of
#: ``if``s so the caps are data, and a reader can see all three at once.
_KIND_CEILING: dict[EvidenceKind, ConfidenceBand] = {
    EvidenceKind.OBSERVATION: ConfidenceBand.WELL_CORROBORATED,
    EvidenceKind.INFERENCE: INFERENCE_CEILING,
    EvidenceKind.ALLEGATION: ALLEGATION_CEILING,
}


#: Words that assert conduct rather than describe indicia.  Checked anywhere a synthesis
#: states something about a person: a report may say what a log shows and what it would
#: take to establish who did it, and it may not say who did it.
_ATTRIBUTION_WORDS: tuple[str, ...] = (
    "guilty", "culprit", "perpetrator", "attacker", "the hacker", "fraudster",
    "scammer", "stalker", "leaker", "insider threat", "the thief", "the spy",
    "committed the crime", "carried out the attack", "responsible for the attack",
    "did it", "who did this", "is to blame", "malicious actor named",
)

#: Phrases that turn an identity claim into a certainty.  Kept apart from
#: :data:`_HEDGE_WORDS`: those assert certainty about anything, these assert *who*.
_ATTRIBUTION_CERTAINTY: tuple[str, ...] = (
    "is the person who", "was the person who", "is the individual who",
    "must be the same person", "is identical to the suspect", "is the attacker",
    "is the culprit", "definitely the same person", "positively identified as",
    "is certainly the", "we identify", "we have identified",
)

#: How an identity statement may be phrased: as a hypothesis with a stated basis and a
#: named thing that would confirm or refute it.  A sentence is acceptable when it carries
#: at least one of these, because then it is asking a question rather than answering one.
_ATTRIBUTION_QUALIFIERS: tuple[str, ...] = (
    "hypothesis", "competing", "would", "if ", "cannot be established", "not established",
    "does not establish", "insufficient", "indicative", "consistent with", "one of several",
    "remains", "unresolved", "could", "may", "might", "alleged", "reported", "according to",
    "no evidence", "would require", "to establish", "testing", "alternative",
)


def _synthesis_sentences(text: str) -> list[str]:
    return [part.strip() for part in re.split(r"(?<=[.!?])\s+|\n+", text or "")
            if part.strip()]


def check_attribution(text: str) -> str:
    """Refuse a declaration of guilt.  Returns the text, or raises.

    Deliberately blunt: this is the one class of sentence a finished report must never
    contain, so the check runs on every finding and every section, and a match is a
    construction error rather than a warning a caller might not read.

    Returned unchanged rather than normalised: rewriting a claim to remove the word
    "attacker" would leave a sentence nobody wrote, and a report's sentences must be the
    ones the mission stands behind.
    """

    lowered = (text or "").lower()
    for word in _ATTRIBUTION_WORDS:
        if re.search(rf"\b{re.escape(word)}\b", lowered):
            raise SynthesisConflict(
                f"a synthesis may not declare guilt ({word!r}); describe the indicia and "
                f"the standard of proof instead — see check_identity_claim")
    return text


def check_identity_claim(text: str) -> str:
    """Refuse a *certain* identity attribution, and allow an explicitly uncertain one.

    The distinction is the whole point of the section: "the person who administers the
    domain is probably X" is a hypothesis the report can state with its basis, while "X
    is the person who did this" is a verdict the mission is not entitled to reach.  A
    sentence carrying one of :data:`_ATTRIBUTION_CERTAINTY` and *no* qualifier from
    :data:`_ATTRIBUTION_QUALIFIERS` is refused; the same sentence with "no evidence
    establishes" in front of it is not.
    """

    for sentence in _synthesis_sentences(text):
        lowered = sentence.lower()
        if not any(token in lowered for token in _ATTRIBUTION_CERTAINTY):
            continue
        if any(token in lowered for token in _ATTRIBUTION_QUALIFIERS):
            continue
        raise SynthesisConflict(
            "a synthesis may not attribute identity with certainty: state it as a "
            "hypothesis with its basis, and name what would confirm or refute it")
    return text


def claim_signature(statement: str) -> str:
    """A claim's identity: normalised text, with numbers read in any order.

    Two rows that say the same thing in a different order are one claim, which is what
    both the duplicate-detection and the contradiction check need.  Numbers are included
    because "firmware 7.2" and "firmware 7.4" are different claims, not the same one
    re-worded — the mistake a token-set similarity is prone to.
    """

    return " ".join(sorted(_claim_key(statement).split()))


class EvidenceView(StrictModel):
    """One item of mission evidence, as the synthesis reads it.

    A snapshot rather than the :class:`EvidenceItem` itself: the synthesis is a document
    assembled *after* the run, and it must not be able to mutate the record it is
    reporting on.  The ids, statements and origins are everything the writers need, and
    nothing else is copied — a copy of the whole item would invite a writer to read a
    field the synthesis is not supposed to reason from.
    """

    id: str = Field(min_length=1)
    statement: str = Field(min_length=1)
    kind: EvidenceKind = EvidenceKind.OBSERVATION
    confidence: Confidence = Confidence.UNKNOWN
    #: One id per independent origin, as §31 counts them.
    origins: list[str] = Field(default_factory=list)
    #: The Subagent that collected it, so a finding can name where it came from.
    collected_by: str = ""
    supports: list[str] = Field(default_factory=list)
    contradicts: list[str] = Field(default_factory=list)
    #: The sources behind it, for a citation a reader can follow.
    citations: list[str] = Field(default_factory=list)

    @property
    def independent_origins(self) -> int:
        return len(set(self.origins))

    @property
    def signature(self) -> str:
        return claim_signature(self.statement)

    def band(self) -> ConfidenceBand:
        """The band this item's *sources* earn, before its epistemic kind caps it."""

        count = self.independent_origins
        if count >= 3:
            return ConfidenceBand.WELL_CORROBORATED
        if count == 2:
            return ConfidenceBand.CORROBORATED
        return ConfidenceBand.SINGLE_SOURCE

    def ceiling(self) -> ConfidenceBand:
        """The band this *row* supports: its own sources, capped by its kind.

        The row's reading, not the claim's: two Workers may have corroborated one claim
        between them without either row carrying both sources, and
        :func:`_finding_for` combines the rows before it assigns a band.  This is the
        floor a row can never exceed on its own.
        """

        cap = _KIND_CEILING[self.kind]
        earned = self.band()
        return earned if earned.rank <= cap.rank else cap


class EvidenceIndex(StrictModel):
    """Every item the mission holds, addressable by id — the synthesis's only input.

    One object, built once, because three problems need the same answer: which ids are
    real (a finding citing an invented id), which statements are the same claim (a
    duplicate counted as corroboration), and which statements conflict (a contradiction
    the report must carry rather than resolve).  Building it per section would let two
    sections disagree about what the mission knows.
    """

    items: list[EvidenceView] = Field(default_factory=list)
    #: The ids this deployment refused or never received, so a citation is checked
    #: against the mission rather than against the assembled document.
    excluded: list[str] = Field(default_factory=list)

    @classmethod
    def of(cls, evidence: Sequence["EvidenceItem"], *,
           excluded: Sequence[str] = ()) -> "EvidenceIndex":
        return cls(items=[_evidence_view(item) for item in evidence],
                   excluded=[str(item) for item in excluded])

    def __contains__(self, item_id: object) -> bool:
        return any(item.id == item_id for item in self.items)

    @property
    def by_id(self) -> dict[str, EvidenceView]:
        return {item.id: item for item in self.items}

    @property
    def ids(self) -> list[str]:
        return [item.id for item in self.items]

    def get(self, item_id: str) -> EvidenceView:
        found = self.by_id.get(item_id)
        if found is None:
            raise SynthesisConflict(
                f"evidence {item_id!r} is not in this mission: a synthesis may cite only "
                f"what was collected")
        return found

    def statement_ids(self, statement: str) -> list[str]:
        """Every id that makes the same claim as ``statement``, in collection order."""

        signature = claim_signature(statement)
        return [item.id for item in self.items if item.signature == signature]

    def distinct_ids(self, statement: str) -> list[str]:
        """Ids for the claim, one per independent origin.

        The distinction matters for a report: two items from one host are corroboration the
        *statement* has and a *second witness* it does not, and a citations list that showed
        both would read as two sources.
        """

        seen: set[str] = set()
        kept: list[str] = []
        for item_id in self.statement_ids(statement):
            origins = set(self.get(item_id).origins)
            if origins and not origins <= seen:
                kept.append(item_id)
            seen |= origins
        return kept or self.statement_ids(statement)[:1]

    def count_statement(self, statement: str) -> int:
        """How many independent origins state this claim — the corroboration count.

        Two rows from one source are one origin and count once: the number is used to
        decide whether a claim is corroborated, and a duplicate is not a second witness.
        """

        ids = self.statement_ids(statement)
        return len({origin for item_id in ids
                    for origin in self.get(item_id).origins}) or (1 if ids else 0)


class KeyFinding(StrictModel):
    """One finding of the finished report, with the evidence that carries it.

    Four fields are required and none is a sentence the mission cannot check: what is
    claimed, what it rests on, how confident the mission is *and why*, and what would
    change the answer.  ``confidence`` is validated against the derived ceiling, so the
    one thing a writer cannot do is promote a single-source row to high confidence.
    """

    id: str = ""
    #: The claim, in neutral language: what is observed or inferred, never who is guilty.
    statement: str = Field(min_length=12)
    #: The evidence ids that carry it.  At least one, all real — checked by the assembler.
    evidence_ids: list[str] = Field(min_length=1)
    kind: EvidenceKind = EvidenceKind.OBSERVATION
    band: ConfidenceBand = ConfidenceBand.SINGLE_SOURCE
    confidence: Confidence = Confidence.LOW
    #: Why this confidence and not another, in a sentence that names the count.
    confidence_basis: str = Field(min_length=12)
    #: How many independent origins back it, as measured rather than declared.
    origins: int = Field(default=1, ge=1)
    #: What would raise or lower this: a second origin, a dated advisory, a refutation.
    falsifier: str = Field(min_length=8)
    #: ``""`` for a finding the mission states, or the section it belongs to.
    subject: str = ""

    @field_validator("evidence_ids", mode="before")
    @classmethod
    def _cited(cls, value: Any) -> Any:
        # The acceptance clause's first half, refused at the door.  Checked here rather
        # than in the model's own constraint so the reason names the rule a reader cares
        # about ("a finding must cite what carries it") instead of a list length.
        if isinstance(value, (list, tuple)) and not [item for item in value if str(item).strip()]:
            raise SynthesisConflict(
                "a finding must cite the evidence that carries it: an uncited finding is "
                "an opinion with a heading")
        return value

    @model_validator(mode="after")
    def _calibrated(self) -> "KeyFinding":
        check_attribution(self.statement)
        check_identity_claim(self.statement)
        ceiling = _KIND_CEILING[self.kind]
        if self.band.rank > ceiling.rank:
            raise SynthesisConflict(
                f"an {self.kind.value} may not be reported as {self.band.value}: its "
                f"ceiling is {ceiling.value}")
        if self.confidence is not self.band.confidence:
            raise SynthesisConflict(
                f"confidence {self.confidence.value} does not match band "
                f"{self.band.value}: the level is derived from the evidence, not chosen")
        if not self.id:
            self.id = content_id("kf", claim_signature(self.statement), length=10)
        return self

    @property
    def cited(self) -> bool:
        return bool(self.evidence_ids)

    def describe(self) -> str:
        return (f"{self.statement[:150]} [{self.band.value}, {self.origins} origin(s); "
                f"{', '.join(self.evidence_ids[:4])}]")


class IndicatorRow(StrictModel):
    """One corroborated indicator: the thing observed, where, and from how many origins.

    An indicator is not a conclusion.  "The login came from an address the domain does
    not publish" is an indicator; "the contractor breached the account" is not, and the
    section that lists the first may not contain the second.
    """

    statement: str = Field(min_length=8)
    evidence_ids: list[str] = Field(min_length=1)
    #: One label per independent origin, so two rows from one site cannot look like two
    #: witnesses.
    origins: list[str] = Field(min_length=1)
    band: ConfidenceBand = ConfidenceBand.SINGLE_SOURCE
    #: What the indicator would mean if the competing explanation is excluded.
    significance: str = Field(min_length=10)

    @model_validator(mode="after")
    def _corroborated(self) -> "IndicatorRow":
        check_attribution(self.statement)
        if self.band.rank < ConfidenceBand.CORROBORATED.rank:
            raise SynthesisConflict(
                "an indicator listed as corroborated needs two independent origins; a "
                "single-source observation belongs in the findings, with its band stated")
        if len(set(self.origins)) < 2:
            raise SynthesisConflict(
                "two rows on one origin are one witness: name the second origin or state "
                "the indicator as single-source")
        return self

    def to_dict(self) -> dict[str, Any]:
        return {"statement": self.statement, "evidence_ids": list(self.evidence_ids),
                "origins": list(self.origins), "band": self.band.value,
                "significance": self.significance}


class HypothesisRow(StrictModel):
    """One explanation the mission considered, and what the evidence did to it.

    ``status`` is the mission's answer to "is this still possible?": ``supported`` means
    evidence favours it, ``refuted`` means evidence rules it out, ``open`` means the
    mission could not choose, and ``untested`` is an admission — kept, because a report
    that lists only the hypotheses it got to is a report that hides its own gaps.
    """

    statement: str = Field(min_length=12)
    status: str = Field(default="open",
                        pattern="^(supported|refuted|open|untested)$")
    #: Evidence that bears on it, in either direction.  May be empty only when untested.
    evidence_ids: list[str] = Field(default_factory=list)
    #: The competing explanation this one is being weighed against, when there is one.
    competes_with: str = ""
    #: What would settle it — always required: a hypothesis nobody can test is a belief.
    test: str = Field(min_length=12)

    @model_validator(mode="after")
    def _testable(self) -> "HypothesisRow":
        check_attribution(self.statement)
        check_identity_claim(self.statement)
        if self.status != "untested" and not self.evidence_ids:
            raise SynthesisConflict(
                f"a {self.status} hypothesis must name the evidence that supports or "
                f"refutes it, or be reported as untested")
        if self.status == "untested" and self.evidence_ids:
            raise SynthesisConflict(
                "a hypothesis with evidence bearing on it is not untested: state what the "
                "evidence did to it")
        return self

    @property
    def alive(self) -> bool:
        return self.status in {"supported", "open", "untested"}


class ConflictRecord(StrictModel):
    """A contradiction the report carries rather than settles.

    §36 found these between Workers and §37 found them between reports; this is the same
    fact at the document level.  The rule is unchanged one level up: a synthesis that
    picked a side without new evidence would delete a finding, so it states both sides,
    their evidence, and what would decide it.
    """

    topic: str = Field(min_length=6)
    left_statement: str = Field(min_length=8)
    right_statement: str = Field(min_length=8)
    left_evidence: list[str] = Field(default_factory=list)
    right_evidence: list[str] = Field(default_factory=list)
    #: Why they cannot both be right — the rule that found the conflict.
    basis: str = Field(min_length=10)
    #: What would settle it.  Required: a conflict nobody can resolve is a standing gap.
    resolution: str = Field(min_length=12)
    resolved: bool = False

    @model_validator(mode="after")
    def _both_sides(self) -> "ConflictRecord":
        if not self.left_evidence and not self.right_evidence:
            raise SynthesisConflict(
                "a contradiction must cite the evidence on at least one side, or it is "
                "an impression")
        return self

    def describe(self) -> str:
        return (f"{self.topic}: {self.left_statement[:70]!r} vs "
                f"{self.right_statement[:70]!r} — {self.resolution[:90]}")


class GapRecord(StrictModel):
    """What the mission does not know, and why — a §14 unknown with its consequence.

    The consequence is the part a reader needs and a bare unknown does not carry: "the
    advisory for the affected version was not published" is a gap; "so the fixed version
    cannot be ranked" is why it matters, and it is required.
    """

    detail: str = Field(min_length=10)
    reason: UnknownReason = UnknownReason.UNKNOWN
    #: Which part of the mission could not establish it.
    determined_by: str = ""
    #: What the report therefore cannot say.
    consequence: str = Field(min_length=10)
    #: What would close it.
    would_close: str = ""

    def describe(self) -> str:
        tail = f"; would close with {self.would_close[:110]}" if self.would_close else ""
        return (f"{self.reason.value}: {self.detail[:150]} — consequence: "
                f"{self.consequence[:110]}{tail}")

    @classmethod
    def of(cls, unknown: UnknownValue, *, consequence: str,
           would_close: str = "") -> "GapRecord":
        return cls(detail=(unknown.detail or "an unknown with no detail")[:400],
                   reason=unknown.reason, determined_by=unknown.determined_by or "",
                   consequence=consequence, would_close=would_close)


class NextStep(StrictModel):
    """One recommended next step, lawful by construction and ordered by what it settles.

    Four hard requirements, and each one is a way a "next steps" list goes wrong: it may
    not widen scope (``within_scope``), may not touch a system the mission is not
    authorised for (``authorised``), must say which gap or hypothesis it addresses
    (``addresses``), and must be something a person could actually do on Monday
    (``action``).  A step that cannot name what it settles is a wish.
    """

    action: str = Field(min_length=15)
    #: The gap or hypothesis id it addresses.
    addresses: str = Field(min_length=4)
    #: Why it is within the mission's authorisation, in the operator's own terms.
    basis: str = Field(min_length=12)
    within_scope: bool = True
    authorised: bool = True
    passive: bool = True
    #: ``high``, ``medium`` or ``low`` — what it would settle, not how easy it is.
    value: str = Field(default="medium", pattern="^(high|medium|low)$")

    @model_validator(mode="after")
    def _lawful(self) -> "NextStep":
        check_attribution(self.action)
        if not self.within_scope or not self.authorised:
            raise SynthesisConflict(
                "a recommended step must stay inside the mission's scope and authorisation; "
                "a step that widens either is a new mission, not a next step")
        if not self.passive:
            raise SynthesisConflict(
                "this build recommends passive collection only: an active step (touching a "
                "host, sending traffic, contacting a person) is outside what it will plan")
        return self

    def to_dict(self) -> dict[str, Any]:
        return {"action": self.action, "addresses": self.addresses, "basis": self.basis,
                "within_scope": self.within_scope, "authorised": self.authorised,
                "passive": self.passive, "value": self.value}


class SynthesisSection(StrictModel):
    """One required part of the report: its prose, and the evidence behind it.

    Every section carries ``evidence_ids``, even the ones that are mostly narrative
    ("scope and methods" cites the reports it covers).  That uniformity is what makes the
    completeness check a loop rather than a list of special cases, and what lets a reader
    ask "what is *this paragraph* based on?" of any paragraph in the document.
    """

    kind: str = Field(pattern="^(executive-summary|scope-and-methods|key-findings|"
                              "indicators|hypotheses|contradictions|confidence|gaps|"
                              "limitations|next-steps)$")
    title: str = Field(min_length=3)
    #: The prose.  May be empty for a section whose content is entirely structured
    #: (key findings, indicators, contradictions), which is why it is not ``min_length=1``.
    body: str = ""
    evidence_ids: list[str] = Field(default_factory=list)
    #: Ids of the structured items the section carries, so a reader can navigate.
    item_ids: list[str] = Field(default_factory=list)

    @model_validator(mode="after")
    def _safe(self) -> "SynthesisSection":
        check_attribution(f"{self.title}\n{self.body}")
        check_identity_claim(self.body)
        return self

    @property
    def filled(self) -> bool:
        """Whether the section actually says something.

        A heading with no prose and no items is the failure mode this property exists to
        catch: it looks like a section in a table of contents and reads as "nothing to
        report", which is a different claim from "nothing was found".
        """

        return bool(self.body.strip()) or bool(self.item_ids)


#: The ten sections the task names, in the order a reader needs them.  A report missing
#: any one of them is refused: not because ten is a magic number, but because each answers
#: a question a reader will ask, and a report that cannot answer one of them is a report
#: that has not been finished.
REQUIRED_SECTIONS: tuple[tuple[str, str], ...] = (
    ("executive-summary", "Executive summary"),
    ("scope-and-methods", "Scope and methods"),
    ("key-findings", "Key findings"),
    ("indicators", "Corroborated indicators"),
    ("hypotheses", "Competing hypotheses"),
    ("contradictions", "Contradictions"),
    ("confidence", "Confidence levels"),
    ("gaps", "Evidence gaps"),
    ("limitations", "Limitations"),
    ("next-steps", "Recommended next steps"),
)


class MasterReport(StrictModel):
    """The finished document: ten sections, every finding cited, every level calibrated.

    This is what the mission produces when it is allowed to speak, and it is the object
    the acceptance clause is a property of.  Nothing here is a free-text field a model
    can fill with a conclusion: the findings are :class:`KeyFinding` (cited and
    calibrated), the indicators are corroboration-checked, the hypotheses are testable,
    and the sections are all present.

    ``verdict`` is deliberately absent.  There is no field for "who is responsible",
    because a document with such a field acquires an answer to it.
    """

    mission_id: str = ""
    objective: str = Field(min_length=10)
    #: The question the mission set out to answer, restated when the mission changed it.
    question: str = ""
    generated_at: datetime = Field(default_factory=utc_now)
    sections: list[SynthesisSection] = Field(default_factory=list)
    findings: list[KeyFinding] = Field(default_factory=list)
    indicators: list[IndicatorRow] = Field(default_factory=list)
    hypotheses: list[HypothesisRow] = Field(default_factory=list)
    conflicts: list[ConflictRecord] = Field(default_factory=list)
    gaps: list[GapRecord] = Field(default_factory=list)
    limitations: list[str] = Field(default_factory=list)
    next_steps: list[NextStep] = Field(default_factory=list)
    #: The mission's overall confidence: the weakest link among the findings that carry
    #: its answer, never an average — an average would let three strong claims hide one
    #: weak one, which is exactly the arithmetic a report must not do.
    confidence: Confidence = Confidence.UNKNOWN
    confidence_basis: str = ""
    #: What no evidence in this mission could have shown, stated by the mission itself.
    uncertainty_statement: str = Field(min_length=15)
    #: Every evidence id the document cites, so a reader can check the set at once.
    cited_ids: list[str] = Field(default_factory=list)
    #: One id per independent origin across the whole document, for the confidence basis.
    origins: list[str] = Field(default_factory=list)
    #: The join this synthesis waited on (§36's barrier, at the mission level).
    aggregate_basis: JoinBarrier | None = None
    #: What the mission did not synthesise and why (blocked lines, refusals).
    withheld: list[str] = Field(default_factory=list)

    @field_validator("generated_at", mode="before")
    @classmethod
    def _tz(cls, value: Any) -> datetime:
        return normalise_datetime(value)

    @property
    def section(self) -> dict[str, SynthesisSection]:
        return {item.kind: item for item in self.sections}

    def section_of(self, kind: str) -> SynthesisSection:
        found = self.section.get(kind)
        if found is None:
            raise KeyError(f"the report has no {kind!r} section")
        return found

    @property
    def corroborated(self) -> list[KeyFinding]:
        return [finding for finding in self.findings
                if finding.band.rank >= ConfidenceBand.CORROBORATED.rank]

    @property
    def single_source(self) -> list[KeyFinding]:
        return [finding for finding in self.findings
                if finding.band is ConfidenceBand.SINGLE_SOURCE]

    @property
    def open_hypotheses(self) -> list[HypothesisRow]:
        return [item for item in self.hypotheses if item.alive]

    def summary_line(self) -> str:
        return (f"{len(self.findings)} finding(s) from {len(self.cited_ids)} citation(s); "
                f"{len(self.corroborated)} corroborated, {len(self.single_source)} "
                f"single-source; {len(self.gaps)} gap(s), {len(self.conflicts)} "
                f"contradiction(s); confidence {self.confidence.value}")

    def to_dict(self) -> dict[str, Any]:
        return {"mission_id": self.mission_id, "objective": self.objective,
                "question": self.question,
                "generated_at": self.generated_at.isoformat(),
                "sections": [{"kind": item.kind, "title": item.title,
                              "body": item.body,
                              "evidence_ids": list(item.evidence_ids),
                              "item_ids": list(item.item_ids)} for item in self.sections],
                "findings": [{"id": finding.id, "statement": finding.statement,
                              "evidence_ids": list(finding.evidence_ids),
                              "kind": finding.kind.value, "band": finding.band.value,
                              "confidence": finding.confidence.value,
                              "confidence_basis": finding.confidence_basis,
                              "origins": finding.origins,
                              "falsifier": finding.falsifier}
                             for finding in self.findings],
                "indicators": [item.to_dict() for item in self.indicators],
                "hypotheses": [{"statement": item.statement, "status": item.status,
                                "evidence_ids": list(item.evidence_ids),
                                "competes_with": item.competes_with, "test": item.test}
                               for item in self.hypotheses],
                "conflicts": [{"topic": item.topic,
                               "left": item.left_statement, "right": item.right_statement,
                               "left_evidence": list(item.left_evidence),
                               "right_evidence": list(item.right_evidence),
                               "basis": item.basis, "resolution": item.resolution,
                               "resolved": item.resolved} for item in self.conflicts],
                "gaps": [{"detail": item.detail, "reason": item.reason.value,
                          "consequence": item.consequence,
                          "would_close": item.would_close} for item in self.gaps],
                "limitations": list(self.limitations),
                "next_steps": [item.to_dict() for item in self.next_steps],
                "confidence": self.confidence.value,
                "confidence_basis": self.confidence_basis,
                "uncertainty_statement": self.uncertainty_statement,
                "cited_ids": list(self.cited_ids), "origins": list(self.origins),
                "withheld": list(self.withheld),
                # The acceptance clause, as the report's own claim about itself — checkable
                # against the fields above rather than taken on trust.
                "acceptance": self.acceptance(),
                "summary_line": self.summary_line()}

    def acceptance(self) -> dict[str, Any]:
        """The acceptance clause, evaluated on this document rather than asserted."""

        uncited = [finding.id for finding in self.findings if not finding.cited]
        over = [finding.id for finding in self.findings
                if finding.band.rank > _KIND_CEILING[finding.kind].rank]
        return {"every_finding_cited": not uncited,
                "uncited": uncited,
                "no_conclusion_exceeds_its_evidence": not over,
                "overconfident": over,
                "all_sections_present": len({item.kind for item in self.sections})
                == len(REQUIRED_SECTIONS),
                "no_attribution": not any(
                    _declares(finding.statement) for finding in self.findings),
                "cited": len(self.cited_ids)}


def _declares(text: str) -> bool:
    """Whether a sentence declares guilt — the predicate the acceptance check uses."""

    try:
        check_attribution(text)
    except SynthesisConflict:
        return True
    return False


# --------------------------------------------------------------------------
# 39.1 Reading the record
# --------------------------------------------------------------------------


def _evidence_view(item: "EvidenceItem") -> EvidenceView:
    """One collected item, as the synthesis reads it.

    Origins are counted the way §31 counts them — the registrable domain of each source,
    with an archive credited to the page it archived — so "corroborated" means the same
    thing in the research audit and in the finished report.  A second definition of
    "independent" would let the two sections disagree about the same evidence.
    """

    origins: list[str] = []
    citations: list[str] = []
    for source in item.sources:
        host = ""
        if source.url:
            match = re.match(r"^[a-z]+://([^/?#]+)", source.url.lower())
            host = _registrable_domain(match.group(1)) if match else ""
        origins.append(host or (source.publisher or source.title or item.id).lower())
        citations.append(source.url or source.artifact_path or (source.title or item.id))
    if not origins:
        origins = [f"unattributed:{item.id}"]
    return EvidenceView(
        id=item.id, statement=item.statement, kind=item.kind,
        confidence=item.confidence, origins=sorted(set(origins)),
        collected_by=item.collected_by or "", supports=list(item.supports),
        contradicts=list(item.contradicts), citations=citations[:6])


def _report_evidence(reports: Sequence["SubagentOutcome"]) -> list["EvidenceItem"]:
    """Every evidence item the mission still stands behind, one id per claim.

    Reviewed work only (§34's rule: an aggregate carries what its reviews forwarded), and
    de-duplicated by id rather than by statement — the contradiction check needs both
    copies of a claim that disagree, and a set of statements would have already merged
    them.
    """

    seen: set[str] = set()
    items: list["EvidenceItem"] = []
    for report in reports:
        for item in report.evidence:
            if item.id in seen:
                continue
            seen.add(item.id)
            items.append(item)
    return items


#: How much subject overlap two statements need before opposite polarity makes them a
#: contradiction: the *smaller* statement's subject must be substantially contained in the
#: larger one (see :func:`_subject_overlap`).  Equality is too strict — the commonest real
#: conflict negates one clause of a longer sentence — and a share of the union is too
#: lenient in the other direction, because one long sentence would dilute every conflict
#: it is part of.  Named so the number is inspectable and a reader can disagree with it.
CONTRADICTION_OVERLAP: float = 0.6


#: Subject words are folded the same way the duplicate lens folds claims, so "runs" and
#: "ran" are one word here: a negation is the only difference two conflicting statements
#: should have, and a tense change is not a different subject.
_FOLD_SUBJECT: bool = True


def _folded_subject(statement: str) -> set[str]:
    """The subject words of a statement, verb forms folded and negations removed."""

    words = {_claim_stem(word) for word in _claim_key(statement).split()}
    return {word for word in words if word not in _NEGATIONS}


def _subject_overlap(left: set[str], right: set[str]) -> float:
    """How much of the *smaller* subject two statements share, in ``[0, 1]``.

    Containment rather than a share of the union: "the edge gateway runs 7.2 and the
    advisory names its session handling" against "the edge gateway never ran 7.2" is a
    contradiction over firmware, and the longer sentence's extra clause should not dilute
    it below a threshold.  The measure is deliberately asymmetric so the answer does not
    depend on which statement is compared first.
    """

    if not left or not right:
        return 0.0
    return len(left & right) / min(len(left), len(right))


def _is_negated(statement: str) -> bool:
    """Whether a statement carries a negation word — the polarity half of a conflict."""

    return any(word in _claim_key(statement).split() for word in _NEGATIONS)


def _contradiction_pairs(index: EvidenceIndex) -> list[ConflictRecord]:
    """Claims that cannot both be right, found from the index rather than from prose.

    §36's rule, at the document level: two statements with the same subject and opposite
    polarity.  Deliberately conservative — a shared subject with a *different* claim is
    two findings, not a contradiction — because a report that cried contradiction over
    every disagreement would drown the ones that matter.
    """

    records: list[ConflictRecord] = []
    seen: set[tuple[str, str]] = set()
    items = index.items
    for left in items:
        left_subject = _folded_subject(left.statement)
        left_negative = _is_negated(left.statement)
        for right in items:
            if left.id == right.id or left.signature == right.signature:
                continue
            key = tuple(sorted((left.id, right.id)))
            if key in seen:
                continue
            right_subject = _folded_subject(right.statement)
            # Overlap, not equality: the commonest real conflict is one clause of a
            # longer sentence negated ("runs 7.2 …" vs "never ran 7.2 …"), and an exact
            # subject comparison would miss it because the rest of the sentence differs.
            if _subject_overlap(left_subject, right_subject) < CONTRADICTION_OVERLAP:
                continue
            if left_negative == _is_negated(right.statement):
                continue
            seen.add(key)
            records.append(ConflictRecord(
                topic=" ".join(sorted(left_subject))[:120] or "an unresolved subject",
                left_statement=left.statement, right_statement=right.statement,
                left_evidence=[left.id], right_evidence=[right.id],
                basis=("the two statements share their subject words and one of them is "
                       "negated, so the two cannot both be true"),
                resolution=("collect a dated first-party record of the subject; a second "
                            "independent origin agreeing with one side would settle it")))
            if len(records) >= 12:
                return records
    return records


def _band_for_origins(count: int, kind: EvidenceKind) -> ConfidenceBand:
    """The band ``count`` independent origins earn, capped by the claim's epistemic kind."""

    earned = (ConfidenceBand.WELL_CORROBORATED if count >= 3
              else ConfidenceBand.CORROBORATED if count == 2
              else ConfidenceBand.SINGLE_SOURCE)
    cap = _KIND_CEILING[kind]
    return earned if earned.rank <= cap.rank else cap


def _claim_origins(index: EvidenceIndex) -> dict[str, list[str]]:
    """Every origin that states each claim — the number a finding's band rests on.

    Corroboration is a property of the *claim*, not of one row: two Workers retrieving the
    same fact from two sites have corroborated it between them, though neither row lists
    two sources.  Counting per row would report that claim as single-source and understate
    the mission, which is its own kind of inaccuracy.
    """

    origins: dict[str, set[str]] = {}
    for item in index.items:
        origins.setdefault(item.signature, set()).update(item.origins)
    return {signature: sorted(values) for signature, values in origins.items()}


def _findings_from(index: EvidenceIndex) -> list[KeyFinding]:
    """One finding per distinct claim, citing every id and origin that carries it.

    Deduplicated by claim rather than listed per row: two Workers that retrieved the same
    fact are one finding with two citations, and printing it twice would let a reader count
    it as two — which is the arithmetic the whole section is about not doing.
    """

    claim_origins = _claim_origins(index)
    grouped: dict[str, list[EvidenceView]] = {}
    for item in index.items:
        grouped.setdefault(item.signature, []).append(item)
    findings: list[KeyFinding] = []
    for signature, items in grouped.items():
        origins = claim_origins.get(signature, [])
        cited = index.distinct_ids(items[0].statement)
        finding = _finding_for(items[0], origins=origins)
        findings.append(finding.model_copy(update={"evidence_ids": cited}))
    return findings


def _finding_for(item: EvidenceView, *, origins: Sequence[str] = (),
                 falsifier: str = "") -> KeyFinding:
    """A key finding derived from one item — never written freehand.

    This is what keeps the acceptance clause true by construction: the statement, the
    citations and the band all come from the same record, so there is no step at which a
    writer can state something the evidence does not carry.  The falsifier is the one
    input a caller supplies, and it is required to be a *test*, not a disclaimer.
    """

    counted = sorted(set(origins) or set(item.origins))
    band = _band_for_origins(len(counted), item.kind)
    capped = band.rank < _band_for_origins(len(counted), EvidenceKind.OBSERVATION).rank
    return KeyFinding(
        statement=item.statement, evidence_ids=[item.id], kind=item.kind,
        band=band, confidence=band.confidence,
        confidence_basis=(
            f"{len(counted)} independent origin(s) state this claim"
            + (f"; a {item.kind.value} is capped at {band.value} whatever they show"
               if capped else f"; band {band.value}")),
        origins=max(1, len(counted)),
        falsifier=falsifier or ("a first-party record contradicting it, or a second "
                                "independent origin failing to reproduce it"))


def _confidence_of(findings: Sequence[KeyFinding]) -> tuple[Confidence, str]:
    """The report's confidence: the weakest finding that carries the answer.

    Not an average, and not the best finding.  A mission's answer is only as strong as
    the weakest link it needs, and a document that reported the strongest would be
    overstating exactly where it matters most.
    """

    if not findings:
        return (Confidence.UNKNOWN,
                "no finding survived review, so the report states no confidence")
    weakest = min(findings, key=lambda finding: finding.band.rank)
    return (weakest.confidence,
            f"the weakest of {len(findings)} finding(s) sets the level: "
            f"{weakest.band.value} ({weakest.origins} origin(s)), because the answer "
            f"cannot be stronger than the claim it depends on")


# --------------------------------------------------------------------------
# 39.2 Assembling the ten sections
# --------------------------------------------------------------------------


def _section(kind: str, title: str, *, body: str = "",
             evidence: Sequence[str] = (), items: Sequence[str] = ()) -> SynthesisSection:
    return SynthesisSection(kind=kind, title=title, body=body,
                            evidence_ids=list(dict.fromkeys(evidence)),
                            item_ids=list(dict.fromkeys(items)))


def _scope_section(objective: str, question: str, index: EvidenceIndex,
                   reports: Sequence["SubagentOutcome"], *, limit: int = 1200) -> SynthesisSection:
    """What was asked, what was looked at, and how — in the mission's own terms.

    ``methods`` names the machinery rather than the operators: a reader of a finished
    report should be able to see that the evidence passed review and reconciliation
    before it reached this document, which is a fact about how much the document is worth.
    """

    lines = [f"Objective: {objective}"]
    if question and question != objective:
        lines.append(f"The question this mission set out to answer: {question}")
    if reports:
        lines.append("Sources reviewed: " + "; ".join(
            f"{report.role} ({len(report.evidence)} item(s))" for report in reports[:8]))
    lines.append(
        "Methods: every Worker result was judged on seven quality dimensions (§34) before "
        "it could be forwarded, retried attempts were re-tasked with a specific correction "
        "(§35), each Subagent reconciled duplicates and preserved disagreements (§36), the "
        "Master reviewed the report set with five lenses and a bounded loop (§37, §38), and "
        "this synthesis cites only evidence that survived all four.")
    lines.append(
        f"Evidence base: {len(index.items)} reviewed item(s) from "
        f"{len({origin for item in index.items for origin in item.origins})} independent "
        f"origin(s).")
    return _section("scope-and-methods", "Scope and methods",
                    body="\n".join(lines)[:limit + 400],
                    evidence=[item.id for item in index.items])


def _findings_section(findings: Sequence[KeyFinding]) -> SynthesisSection:
    return _section("key-findings", "Key findings",
                    body=("Each finding below is a reviewed evidence item, restated "
                          "without embellishment. Confidence is derived from the number of "
                          "independent origins behind it and capped by its epistemic kind."
                          if findings else
                          "No item survived review, so the mission reports no key finding. "
                          "That is a result, not an omission: the gaps section says what "
                          "could not be established."),
                    evidence=[item for finding in findings for item in finding.evidence_ids],
                    items=[finding.id for finding in findings])


def _indicators_section(index: EvidenceIndex,
                        rows: Sequence[IndicatorRow]) -> SynthesisSection:
    """The corroborated indicators: claims two independent origins agree on.

    Built from the index, not from a writer's list, so "corroborated" is a count rather
    than a judgement.  A claim with one origin is deliberately absent: it belongs in the
    findings with its band stated, and promoting it here would be the report's first
    overstatement.
    """

    rows = list(rows)
    return _section("indicators", "Corroborated indicators",
                    body=(f"{len(rows)} claim(s) are stated independently by two or more "
                          f"origins. An indicator is not a conclusion: it narrows which "
                          f"hypotheses remain possible." if rows else
                          "No claim was corroborated by a second independent origin, so the "
                          "mission reports none. Every finding above is single-source and "
                          "says so."),
                    evidence=[item for row in rows for item in row.evidence_ids],
                    items=[claim_signature(row.statement)[:40] for row in rows])


def _hypotheses_section(hypotheses: Sequence[HypothesisRow]) -> SynthesisSection:
    alive = [item for item in hypotheses if item.alive]
    body = (f"{len(hypotheses)} explanation(s) were tested; {len(alive)} remain possible. "
            f"A hypothesis the mission could not test is listed as untested rather than "
            f"omitted." if hypotheses else
            "The mission recorded no competing hypothesis, which is itself a limitation: a "
            "report with one explanation has not tested it.")
    return _section("hypotheses", "Competing hypotheses", body=body,
                    evidence=[item for row in hypotheses for item in row.evidence_ids],
                    items=[row.statement[:48] for row in hypotheses])


def _conflicts_section(conflicts: Sequence[ConflictRecord]) -> SynthesisSection:
    unresolved = [item for item in conflicts if not item.resolved]
    body = (f"{len(conflicts)} contradiction(s), {len(unresolved)} unresolved. Both sides "
            f"are stated with their evidence: the mission does not pick a side without "
            f"new evidence." if conflicts else
            "No two reviewed items make the same claim with opposite polarity, so the "
            "mission records no contradiction. Silence here is a finding: nothing the "
            "mission collected conflicts with anything else it collected.")
    return _section("contradictions", "Contradictions", body=body,
                    evidence=[item for record in conflicts
                              for item in record.left_evidence + record.right_evidence],
                    items=[record.topic[:48] for record in conflicts])


def _confidence_section(findings: Sequence[KeyFinding], confidence: Confidence,
                        basis: str) -> SynthesisSection:
    counts = {band: sum(1 for finding in findings if finding.band is band)
              for band in ConfidenceBand}
    body = "\n".join([
        f"Mission confidence: {confidence.value}.",
        f"Basis: {basis}",
        "Bands: " + ", ".join(f"{band.value} {count}" for band, count in counts.items()),
        ("Band rules: one independent origin is single-source; two are corroborated; three "
         "or more are well-corroborated. An allegation is capped at corroborated — a third "
         "party repeating a claim does not establish it — and an inference is capped at "
         "corroborated, because reasoning over good evidence is still reasoning."),
    ])
    return _section("confidence", "Confidence levels", body=body,
                    evidence=[item for finding in findings for item in finding.evidence_ids])


def _gaps_section(gaps: Sequence[GapRecord]) -> SynthesisSection:
    body = (f"{len(gaps)} gap(s). Each states what the mission could not establish, why, "
            f"and what it therefore cannot say." if gaps else
            "The mission closed every gap it opened. That is a claim about the questions "
            "it asked, not about the target: questions it did not think to ask are not in "
            "this list.")
    return _section("gaps", "Evidence gaps", body=body,
                    items=[gap.detail[:48] for gap in gaps])


def _limitations_section(limitations: Sequence[str], withheld: Sequence[str]) -> SynthesisSection:
    lines = list(limitations)
    if withheld:
        lines.extend(withheld)
    body = ("\n".join(f"— {line}" for line in lines) if lines else
            "The mission recorded no limitation. A report with none usually means the "
            "record was not examined for them, which is itself worth stating.")
    return _section("limitations", "Limitations", body=body)


def _next_steps_section(steps: Sequence[NextStep]) -> SynthesisSection:
    body = (f"{len(steps)} step(s), each naming what it settles and why it is lawful. "
            f"None requires touching a system or contacting a person."
            if steps else
            "No further passive step would change this answer. Anything beyond it would be "
            "a different mission with its own authorisation.")
    return _section("next-steps", "Recommended next steps", body=body,
                    items=[step.addresses for step in steps])


def _executive_summary(report: MasterReport) -> str:
    """The summary, written from the finished parts rather than before them.

    Composed last, deliberately.  A summary written first becomes the plan the rest of
    the document is made to agree with; one written last can only restate what the
    sections already established.
    """

    strongest = report.corroborated[0] if report.corroborated else None
    lines = [
        f"{len(report.findings)} reviewed finding(s) bear on: {report.objective[:160]}",
        (f"The strongest of them, corroborated by independent origins, is: "
         f"{strongest.statement[:200]}" if strongest else
         "None of them is corroborated by a second independent origin, so every finding "
         "below carries the band it earned."),
        # A count of what is still open, never a count of what has been excluded: "no
        # explanation remains" is the one sentence this document may not write, because
        # excluding an alternative requires evidence, not the absence of a hypothesis.
        (f"{len(report.open_hypotheses)} explanation(s) remain open; this document does not "
         f"claim that it has excluded the others"
         + (f", and {len(report.conflicts)} contradiction(s) are stated rather than settled"
            if report.conflicts else "")
         + f". Confidence: {report.confidence.value}."),
    ]
    if report.gaps:
        lines.append(f"What the mission could not establish: {report.gaps[0].consequence[:160]}")
    return " ".join(line.rstrip(".") + "." for line in lines if line)


def synthesise_report(reports: Sequence["SubagentOutcome"], *, context: "MasterContext",
                      mission_id: str = "",
                      hypotheses: Sequence[HypothesisRow] = (),
                      next_steps: Sequence[NextStep] = (),
                      limitations: Sequence[str] = (),
                      withheld: Sequence[str] = (),
                      barrier: JoinBarrier | None = None,
                      review: "MasterReview | None" = None,
                      question: str = "") -> MasterReport:
    """Assemble the finished document from the reviewed record.

    The order is the argument.  Evidence is indexed first (so every later step cites real
    ids), contradictions are found from the index (so the report cannot quietly drop one),
    findings are derived from items (so no finding can say more than its item), indicators
    are counted (so "corroborated" is arithmetic), and the sections are assembled from
    those parts.  The executive summary is written last, from the assembled sections.

    A mission that reviewed nothing still gets a report: it says it found nothing, lists
    the gap, and states why — which is a different document from no document, and the one
    a reader needs.
    """

    index = EvidenceIndex.of(_report_evidence(reports),
                             excluded=[gap.detail or "" for report in reports
                                       for gap in report.gaps if gap.detail][:40])
    conflicts = _contradiction_pairs(index)
    findings = _findings_from(index)
    # A finding whose statement makes a claim the mission cannot attribute is kept out of
    # the document entirely: an item that names who is guilty is not a finding, and
    # restating it as one would launder the problem through the synthesis.
    findings = [finding for finding in findings
                if not _declares(finding.statement)]
    confidence, basis = _confidence_of(findings)

    gap_records = [
        GapRecord.of(gap, consequence=(
            "the report cannot state anything this gap would have established"),
            would_close="collect one sourced record that answers it")
        for report in reports for gap in report.gaps]
    if not findings:
        gap_records.append(GapRecord(
            detail="no reviewed evidence item was available to synthesise",
            reason=UnknownReason.UNAVAILABLE, determined_by="master-synthesize",
            consequence="the report states no finding about the target",
            would_close="a completed collection phase with at least one reviewed item"))

    indicators = _indicator_rows(index)
    report = MasterReport(
        mission_id=mission_id, objective=context.objective, question=question,
        sections=[], findings=findings,
        indicators=indicators, hypotheses=list(hypotheses), conflicts=conflicts,
        gaps=gap_records, limitations=list(limitations), next_steps=list(next_steps),
        confidence=confidence, confidence_basis=basis,
        uncertainty_statement=(
            "This report states only what reviewed evidence supports: every key finding "
            "cites the evidence ids behind it, confidence is derived from independent "
            "origins and capped by epistemic kind, contradictions are preserved rather "
            "than settled, and no attribution of conduct or identity is made. Nothing "
            "outside the gaps and limitations sections should be read as established."),
        aggregate_basis=barrier, withheld=list(withheld))

    indicator_section = _indicators_section(index, indicators)

    report.sections = [
        _section("executive-summary", "Executive summary", body="",
                 evidence=[item for finding in findings for item in finding.evidence_ids]),
        _scope_section(context.objective, question, index, reports),
        _findings_section(findings),
        indicator_section,
        _hypotheses_section(report.hypotheses),
        _conflicts_section(conflicts),
        _confidence_section(findings, confidence, basis),
        _gaps_section(gap_records),
        _limitations_section(limitations, withheld),
        _next_steps_section(report.next_steps),
    ]
    # The summary is a *section* like the others, so the completeness check and the
    # citation check treat it the same way — and so a reader can ask what it rests on.
    summary_section = report.section_of("executive-summary")
    summary_section.body = _executive_summary(report)
    summary_section.evidence_ids = list(dict.fromkeys(
        [item for finding in findings for item in finding.evidence_ids]))
    report.cited_ids = sorted({item for section in report.sections
                               for item in section.evidence_ids})
    report.origins = sorted({origin for item_id in report.cited_ids
                             for origin in index.get(item_id).origins})
    if review is not None:
        report.withheld = list(dict.fromkeys(
            [*report.withheld,
             *[f"no report from: {gap.target[:80]}" for gap in review.coverage]]))
    _assert_complete(report, index)
    return report


def _indicator_rows(index: EvidenceIndex) -> list[IndicatorRow]:
    """The corroborated rows, computed once and reused by the section and the report."""

    groups: dict[str, list[EvidenceView]] = {}
    for item in index.items:
        groups.setdefault(item.signature, []).append(item)
    rows: list[IndicatorRow] = []
    for items in groups.values():
        # The origins are shared out *between* rows, so two copies of a claim from two
        # hosts are one indicator with two witnesses and two citations — not two hosts
        # claiming the same thing twice in the same table.
        origins: list[str] = []
        cited: list[str] = []
        for item in items:
            new = [origin for origin in item.origins if origin not in origins]
            if new:
                cited.append(item.id)
                origins.extend(new)
        if len(origins) < 2:
            continue
        band = (ConfidenceBand.WELL_CORROBORATED if len(origins) >= 3
                else ConfidenceBand.CORROBORATED)
        try:
            rows.append(IndicatorRow(
                statement=items[0].statement[:300], evidence_ids=cited,
                origins=origins, band=band,
                significance=("two or more independent origins state this independently, "
                              "so it is an indicator rather than a single observation")))
        except SynthesisConflict:
            continue
    return rows


def _assert_complete(report: MasterReport, index: EvidenceIndex) -> None:
    """Refuse an incomplete document.  The last gate before a report can be published.

    Five properties, each the negation of a specific failure: a missing section, a section
    with no content, a finding citing an id the mission does not hold, a conclusion above
    its evidence, and a finding that declares guilt.  Each raises with the thing that
    failed, because a report that is 90% right is not a report.
    """

    present = {section.kind for section in report.sections}
    missing = [kind for kind, _title in REQUIRED_SECTIONS if kind not in present]
    if missing:
        raise SynthesisConflict(f"the report is missing section(s): {', '.join(missing)}")
    empty = [section.kind for section in report.sections if not section.filled]
    if empty:
        raise SynthesisConflict(
            f"section(s) present but empty: {', '.join(empty)} — a heading with nothing "
            f"under it reads as 'nothing to report'")
    unknown = [item for finding in report.findings for item in finding.evidence_ids
               if item not in index]
    if unknown:
        raise SynthesisConflict(
            f"finding(s) cite evidence this mission never collected: {', '.join(unknown[:5])}")
    over = [finding.id for finding in report.findings
            if finding.band.rank > _KIND_CEILING[finding.kind].rank]
    if over:
        raise SynthesisConflict(
            f"finding(s) claim more confidence than their kind allows: {', '.join(over)}")
    declarations = [finding.id for finding in report.findings
                    if _declares(finding.statement)]
    if declarations:
        raise SynthesisConflict(
            f"finding(s) declare guilt: {', '.join(declarations)} — a synthesis reports "
            f"indicia and the standard of proof, not a verdict")


# --------------------------------------------------------------------------
# 39.3 Rendering: the document as a reader sees it
# --------------------------------------------------------------------------


def render_master_report(report: MasterReport, *, width: int = 96) -> Group:
    """The report, printed.  Sections in the order a reader needs them.

    Citations are shown as ids, not as prose: a reader who wants the source follows the id
    into the record, and a citation that was only a title could not be checked at all.
    """

    blocks: list[Any] = []
    head = Table.grid(padding=(0, 1))
    head.add_column(style="dim", no_wrap=True)
    head.add_column(overflow="fold")
    head.add_row("objective", escape(report.objective[:220]))
    if report.question and report.question != report.objective:
        head.add_row("question", escape(report.question[:220]))
    head.add_row("confidence", escape(f"{report.confidence.value} — "
                                      f"{_first_sentence(report.confidence_basis)}"))
    head.add_row("evidence", escape(f"{len(report.cited_ids)} citation(s) from "
                                    f"{len(report.origins)} independent origin(s)"))
    blocks.append(Text("Master synthesis", style="bold"))
    blocks.append(head)

    summary = report.section.get("executive-summary")
    if summary is not None and summary.body:
        blocks.append(Text(""))
        blocks.append(Panel(Text(escape(summary.body), overflow="fold"),
                            title="Executive summary", title_align="left",
                            border_style="dim", padding=(0, 1), expand=False))

    for kind, title in REQUIRED_SECTIONS[1:]:
        section = report.section.get(kind)
        if section is None:
            continue
        blocks.append(Text(""))
        blocks.append(Text(title, style="bold"))
        if section.body:
            blocks.append(Text(escape(section.body), overflow="fold"))

    if report.findings:
        table = Table(box=None, pad_edge=False, expand=False)
        table.add_column("finding", overflow="fold", max_width=58)
        table.add_column("band", no_wrap=True)
        table.add_column("evidence", overflow="fold", max_width=30)
        for finding in report.findings:
            table.add_row(escape(finding.statement[:200]),
                          escape(f"{finding.band.value} ({finding.origins})"),
                          escape(", ".join(finding.evidence_ids[:3])))
        blocks.append(table)

    if report.indicators:
        table = Table(title="corroborated indicators", title_justify="left", box=None,
                      pad_edge=False, expand=False)
        table.add_column("indicator", overflow="fold", max_width=52)
        table.add_column("origins", overflow="fold", max_width=32)
        for row in report.indicators:
            table.add_row(escape(row.statement[:160]),
                          escape(", ".join(row.origins[:4])))
        blocks.append(table)

    if report.hypotheses:
        table = Table(title="competing hypotheses", title_justify="left", box=None,
                      pad_edge=False, expand=False)
        table.add_column("hypothesis", overflow="fold", max_width=48)
        table.add_column("status", no_wrap=True)
        table.add_column("would settle it", overflow="fold", max_width=40)
        for row in report.hypotheses:
            table.add_row(escape(row.statement[:150]), escape(row.status),
                          escape(row.test[:120]))
        blocks.append(table)

    if report.conflicts:
        table = Table(title="contradictions, stated not settled", title_justify="left",
                      box=None, pad_edge=False, expand=False)
        table.add_column("topic", overflow="fold", max_width=24)
        table.add_column("both sides", overflow="fold", max_width=64)
        for record in report.conflicts:
            table.add_row(escape(record.topic[:70]),
                          escape(f"{record.left_statement[:90]} ↔ "
                                 f"{record.right_statement[:90]}"))
        blocks.append(table)

    if report.gaps:
        table = Table(title="evidence gaps", title_justify="left", box=None,
                      pad_edge=False, expand=False)
        table.add_column("gap", overflow="fold", max_width=52)
        table.add_column("so the report cannot say", overflow="fold", max_width=44)
        for gap in report.gaps:
            table.add_row(escape(gap.detail[:150]), escape(gap.consequence[:140]))
        blocks.append(table)

    if report.next_steps:
        table = Table(title="recommended next steps (passive, in scope)", title_justify="left",
                      box=None, pad_edge=False, expand=False)
        table.add_column("step", overflow="fold", max_width=58)
        table.add_column("settles", no_wrap=True)
        table.add_column("value", no_wrap=True)
        for step in report.next_steps:
            table.add_row(escape(step.action[:180]), escape(step.addresses[:24]),
                          escape(step.value))
        blocks.append(table)

    blocks.append(Text(""))
    blocks.append(Text(escape(f"calibration: {report.summary_line()}"), style="dim"))
    blocks.append(Text(escape("no attribution of conduct or identity is made; every "
                              "finding cites the evidence it rests on"), style="dim"))
    return Group(*blocks)


# ══════════════════════════════════════════════════════════════════════════
# 38. Entry point
# ══════════════════════════════════════════════════════════════════════════


def run() -> None:
    """Invoke the CLI.  Import-safe: only called from ``__main__``.

    This is the last line of defence for terminal readability: whatever escapes
    a command — Ctrl+C, a timeout, an unexpected exception — leaves a short,
    redacted explanation instead of a traceback, and points at the artefacts a
    resume would need.
    """

    console = get_console()
    try:
        app()
    except (typer.Exit, SystemExit):
        raise
    except KeyboardInterrupt:
        # Never a traceback, never a half-painted spinner: the tracker's atexit
        # handler and the CancellationGuard have already done their work.
        console.print()
        console.print(
            Panel(
                Text(
                    "interrupted by operator (Ctrl+C)\n"
                    "Any checkpoint written during the run is complete and can be resumed.",
                    style="yellow",
                ),
                border_style="yellow",
                title="stopped",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(EXIT_INTERRUPTED)
    except TimeoutError as exc:
        console.print()
        console.print(
            Panel(
                Text(
                    f"timed out: {redact_text(str(exc)) or 'budget exhausted'}\n"
                    "Partial results were preserved; resume from the checkpoint.",
                    style="yellow",
                ),
                border_style="yellow",
                title="timeout",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(124)
    except CancellationRequested as exc:
        console.print()
        console.print(
            Panel(
                Text(f"mission cancelled: {redact_text(str(exc))}", style="yellow"),
                border_style="yellow",
                title="cancelled",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(EXIT_INTERRUPTED)
    except StructuredOutputError as exc:
        # A provider/contract problem is not a bug: report it as its own class
        # with the exit code the failure maps to.
        console.print()
        console.print(
            Panel(
                Text(redact_text(exc.render()), style="red"),
                border_style="red",
                title="model call failed",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(exc.exit_code)
    except AgentError as exc:
        console.print()
        console.print(
            Panel(
                Text(redact_text(exc.render()), style="red"),
                border_style="red",
                title="agent failure",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(ExitCode.INTERNAL)
    except Exception as exc:
        # Redacted, attributed, and never a raw traceback in the terminal.
        detail = redact_text(f"{type(exc).__name__}: {exc}")
        console.print()
        console.print(
            Panel(
                Text(
                    f"{detail}\n\nThis is a bug. Re-run with --verbose for more detail.",
                    style="red",
                ),
                border_style="red",
                title="internal error",
                title_align="left",
                expand=False,
            )
        )
        raise typer.Exit(ExitCode.INTERNAL)


def process_entry() -> None:
    """Process entry point: run the CLI and exit with its status.

    ``run`` raises ``typer.Exit`` so an embedding caller can inspect the code.
    At the process boundary that would surface as a traceback and a status of 1,
    which would destroy the exit-code contract every other command relies on, so
    the code is converted to a plain exit status here.
    """

    try:
        run()
    except typer.Exit as exit_request:
        raise SystemExit(exit_request.exit_code) from None



# --------------------------------------------------------------------------
# 38.6 The demo and its checks: a loop that ends, and says why
# --------------------------------------------------------------------------

def _loop_outcome(robot: str, attempt: int, statements: Sequence[str], *,
                  worker: str = "wrk-loop", subagent: str = "sa-loop",
                  queries: Sequence[str] = ()) -> "WorkerOutcome":
    """One attempt of a Worker, sourced, with the queries it was told to run.

    A real :class:`WorkerOutcome` rather than a mock, because the detectors read the
    report the outcome carries and a mock would prove nothing about that path.
    """

    items = [_review_item(statement, worker=f"{worker}-{attempt}") for statement in statements]
    report = WorkerReport(
        worker_id=worker, subagent_id=subagent, attempt=attempt,
        status=WorkerStatus.COMPLETED if items else WorkerStatus.BLOCKED,
        summary=f"{worker}: {len(items)} observation(s) collected",
        findings=[WorkerFinding(statement=item.statement, evidence_ids=[item.id])
                  for item in items],
        evidence=items,
        limitations=[] if items else ["no source answered the question this attempt asked"],
        gaps=[] if items else [UnknownValue(reason=UnknownReason.UNAVAILABLE,
                                            detail="the retrieval returned nothing")])
    return WorkerOutcome(
        worker_id=worker, subagent_id=subagent,
        status=EntityStatus.SUCCEEDED if items else EntityStatus.BLOCKED,
        attempt=attempt, summary=report.summary,
        evidence_ids=[item.id for item in items],
        payload={"report": json.loads(model_to_json(report)),
                 "queries": list(queries)})


def loop_detection_cases() -> dict[str, Any]:
    """The fixtures: one unit that repeats a query, one that learns, one at mission level.

    Built from outcomes rather than from signals, so the checks exercise the same path
    the graph does — a detector that only works on hand-made signals would be proving
    something about its own fixture rather than about the record.
    """

    query = "search example.com on shodan"
    reworded = "shodan search for example.com"
    first = _loop_outcome("a", 1, ["the gateway runs firmware 7.2"],
                          queries=[query])
    second = _loop_outcome("a", 2, ["the gateway runs firmware 7.2"],
                           queries=[reworded])
    third = _loop_outcome("a", 3, ["the gateway runs firmware 7.2"],
                          queries=[query])
    moving = _loop_outcome("b", 1, [], queries=["search example.com in certspotter"])
    moving2 = _loop_outcome("b", 2, ["certspotter lists four subdomains of example.com"],
                            queries=["search example.com in certspotter"])
    return {"first": first, "second": second, "third": third,
            "moving": moving, "moving2": moving2,
            "query": query, "reworded": reworded}


def loop_detection_demo() -> dict[str, Any]:
    """Three cycles and three outcomes: corrected, blocked, and stopped.

    The demo ends where the task says the acceptance clause lives: a repeated cycle
    terminating with a reason a reader can point at, rather than a budget that ran out.
    """

    cases = loop_detection_cases()
    first, second, third = cases["first"], cases["second"], cases["third"]
    # 1. a unit that repeats one retrieval: the first detection asks for a change.
    correct = detect_unit_cycle(
        [attempt_signal(first, plan="plan-a"),
         attempt_signal(second, prior=[first], plan="plan-a")],
        queries=[QueryRecord.of(cases["query"], unit="wrk-loop", claims=1),
                 QueryRecord.of(cases["reworded"], unit="wrk-loop", claims=0)],
        unit="wrk-loop")
    # 2. the same finding, after the correction was applied and ignored: blocked.
    blocked = escalate(correct, already_corrected=correct.kinds_as_enums())
    # The third attempt is what makes the block unavoidable rather than premature: the
    # correction was applied, the unit repeated itself anyway, and the line is closed.
    third_signal = attempt_signal(third, prior=[first, second], plan="plan-a")
    # 3. a mission whose rounds add nothing: stopped, with the series on the record.
    stopped = assess_saturation([4, 0, 0])
    # 4. a mission that keeps learning: nothing to report.
    healthy = assess_saturation([2, 3, 1])
    lines = [blocked_line(finding) for finding in blocked.findings if finding.blocks]
    return {
        "corrected": correct.to_dict(),
        "blocked": blocked.to_dict(),
        "blocked_lines": [line.to_dict() for line in lines],
        "stopped": stopped.to_dict(),
        "healthy": healthy.to_dict(),
        "unbounded": [phrase for phrase in
                      ("continue until the sources are exhausted",
                       "keep searching until done",
                       "read every advisory from the published list")
                      if unbounded_instruction(phrase)],
        "queries": {"first": query_fingerprint(cases["query"]),
                    "reworded": query_fingerprint(cases["reworded"]),
                    "different": query_fingerprint("search example.com in certspotter")},
        "signals": {
            "the corrective attempt added nothing either": third_signal.new_claims == 0,
            "one retrieval under two wordings is one query":
                query_fingerprint(cases["query"]) == query_fingerprint(cases["reworded"]),
            "a repeated query with no yield is detected": bool(correct.findings),
            "the first detection requires a change of strategy":
                correct.findings[0].response is LoopResponse.CORRECT
                and len(correct.strategy_change) > 15,
            "a cycle that survives its correction is blocked": blocked.blocked,
            "the block says what would unblock it":
                all(len(line.unblock) > 10 for line in lines),
            "two empty rounds stop the mission":
                stopped.condition is StopCondition.SATURATION,
            "the stop names the series it judged":
                stopped.added_per_round == [4, 0, 0],
            "a mission that keeps learning is not stopped": not healthy.stopped,
            "an unbounded instruction is refused": bool(
                unbounded_instruction("continue until the sources are exhausted")),
            "a bounded instruction is accepted": not unbounded_instruction(
                "read the three published advisories and cite each one"),
        },
    }


def render_loop_detection_demo(payload: Mapping[str, Any]) -> Group:
    """The demo, as a reader sees it: what repeated, and what it cost to find out."""

    signals = Table(title="what the detectors saw", title_justify="left", box=None,
                    pad_edge=False, expand=False)
    signals.add_column("check", overflow="fold")
    signals.add_column("ok", no_wrap=True)
    for name, ok in payload["signals"].items():
        glyph = "[green]✔[/green]" if ok else "[red]✘[/red]"
        signals.add_row(escape(name), glyph)

    rows = Table(title="the cycles, and what each required", title_justify="left",
                 box=None, pad_edge=False, expand=False)
    rows.add_column("kind", no_wrap=True)
    rows.add_column("subject", no_wrap=True)
    rows.add_column("response", no_wrap=True)
    rows.add_column("what it requires", overflow="fold", max_width=56)
    for section in ("corrected", "blocked", "stopped"):
        for finding in payload[section]["findings"]:
            detail = (finding["strategy_change"] if finding["response"] == "correct"
                      else finding["unblock"] if finding["response"] == "block"
                      else payload["stopped"]["stop_reason"])
            rows.add_row(escape(finding["kind"]), escape(finding["subject"]),
                         escape(finding["response"]), escape(str(detail)[:160]))

    blocked = Table(title="lines of inquiry the mission stopped asking about",
                    title_justify="left", box=None, pad_edge=False, expand=False)
    blocked.add_column("subject", no_wrap=True)
    blocked.add_column("would unblock", overflow="fold", max_width=70)
    for line in payload["blocked_lines"]:
        blocked.add_row(escape(line["subject"]), escape(line["unblock"]))

    tail = Text("a repeated cycle ends with a reason, not with a budget: the change it "
                "required, the line it blocked, or the stop it justified", style="dim")
    return Group(signals, Text(""), rows, Text(""), blocked, Text(""), tail)


def run_loop_self_test() -> list[LoopCheck]:
    """Prove §38's acceptance clause: a no-progress cycle terminates, and says why.

    Four groups, because four different things must hold: the detectors fire on
    substance, the escalation blocks rather than repeats, the mission-level series stops
    the mission, and the flow *uses* all three — the last is what a unit test of the
    models alone cannot show.
    """

    checks: list[LoopCheck] = []

    def add(name: str, ok: Any, detail: Any = "") -> None:
        checks.append(LoopCheck(name=name, ok=bool(ok), detail=str(detail)[:150]))

    def raises(fn: Callable[[], Any], exc: type[BaseException]) -> bool:
        try:
            fn()
        except exc:
            return True
        except Exception:                     # noqa: BLE001 - the wrong error is a failure
            return False
        return False

    cases = loop_detection_cases()
    first, second = cases["first"], cases["second"]
    third = cases["third"]

    # -- 1. the fingerprints: repetition is judged on substance ----------------
    add("a query is the same query under two wordings",
        query_fingerprint(cases["query"]) == query_fingerprint(cases["reworded"]))
    add("a different retrieval is a different fingerprint",
        query_fingerprint(cases["query"])
        != query_fingerprint("search example.com in certspotter"))
    add("a plan fingerprint ignores case and punctuation in its target",
        plan_fingerprint_of(target="Read the Advisories!", tools=["http.get"])
        == plan_fingerprint_of(target="read  the advisories", tools=["http.get"]))
    add("a plan fingerprint notices a different tool",
        plan_fingerprint_of(target="read the advisories", tools=["http.get"])
        != plan_fingerprint_of(target="read the advisories", tools=["dns.lookup"]))
    add("a plan fingerprint notices a different unit of work",
        plan_fingerprint_of(target="read the advisories", work_unit="read")
        != plan_fingerprint_of(target="read the advisories", work_unit="summarise"))
    add("a plan fingerprint does not include the objective's prose",
        plan_fingerprint_of(target=units_of_work(), work_unit="advisories")
        == plan_fingerprint_of(target=units_of_work(), work_unit="advisories"))
    add("an unbounded instruction is refused",
        unbounded_instruction("continue until the sources are exhausted") ==
        "continue until")
    add("a bounded instruction is accepted",
        not unbounded_instruction("read the three published advisories and cite each"))

    # -- 2. the detectors ----------------------------------------------------
    added = attempt_signal(first, plan="p1")
    add("the first attempt's claims are all new", added.new_claims == 1, added.new_claims)
    repeat = attempt_signal(second, prior=[first], plan="p1")
    add("the repeat adds nothing the unit already held", repeat.new_claims == 0,
        repeat.new_claims)
    add("a repeated query with no yield is detected",
        detect_repeated_queries(
            [QueryRecord.of(cases["query"], unit="u", claims=1),
             QueryRecord.of(cases["reworded"], unit="u", claims=0)], unit="u") is not None)
    add("a repeated query that found something is not a cycle",
        detect_repeated_queries(
            [QueryRecord.of(cases["query"], unit="u", claims=1),
             QueryRecord.of(cases["query"], unit="u", claims=1)], unit="u") is None)
    add("a repeated plan with no yield is detected",
        detect_repeated_plans([added, repeat], unit="u") is not None)
    add("a repeated plan that yielded is not a cycle",
        detect_repeated_plans([added, attempt_signal(cases["moving2"], plan="p1")],
                              unit="u") is None)
    add("diminishing returns need two empty attempts",
        detect_diminishing_returns([added], unit="u") is None)
    add("two empty attempts are a diminishing return",
        detect_diminishing_returns(
            [attempt_signal(second, prior=[first]), attempt_signal(third, prior=[first, second])],
            unit="u") is not None)
    add("a unit doing different work is not a repeated retask",
        detect_repeated_retasks([], unit="u") is None)

    # -- 3. the escalation: correct, then block, never repeat -----------------
    detection = detect_unit_cycle(
        [added, repeat], queries=[QueryRecord.of(cases["query"], unit="u", claims=1),
                                  QueryRecord.of(cases["reworded"], unit="u", claims=0)],
        unit="u")
    add("the first detection of a cycle requires a change of strategy",
        detection.found and not detection.blocked)
    add("the correction names what to do differently",
        len(detection.strategy_change) > 20, detection.strategy_change)
    escalated = escalate(detection, already_corrected=detection.kinds_as_enums())
    add("a cycle that survives its correction is blocked", escalated.blocked)
    add("the blocked line says what would unblock it",
        all(finding.unblock for finding in escalated.findings if finding.blocks))
    add("a correction with no strategy change is not constructible",
        raises(lambda: LoopFinding(kind=CycleKind.REPEATED_QUERY, subject="q-1",
                                   detail="the same query ran twice and added nothing",
                                   response=LoopResponse.CORRECT,
                                   strategy_change="try again"), ValueError))
    add("a block that cannot be lifted is not constructible",
        raises(lambda: LoopFinding(kind=CycleKind.REPEATED_QUERY, subject="q-1",
                                   detail="the same query ran twice and added nothing",
                                   response=LoopResponse.BLOCK, unblock=""), ValueError))
    add("a diminishing-returns finding cannot claim new evidence",
        raises(lambda: LoopFinding(kind=CycleKind.DIMINISHING_RETURNS, subject="u",
                                   detail="two attempts added nothing new at all",
                                   evidence_added=2,
                                   strategy_change="change the source family"),
               ValueError))
    line = blocked_line(escalated.findings[0])
    add("the block travels as an unknown with its unblock", "would unblock" in line.gap_detail(),
        line.gap_detail())
    add("a blocked line becomes a report gap",
        len(cycle_gaps([line])) == 1
        and cycle_gaps([line])[0].reason is UnknownReason.UNAVAILABLE)

    # -- 4. the mission level ------------------------------------------------
    stopped = assess_saturation([4, 0, 0])
    add("two empty rounds stop the mission", stopped.stopped)
    add("the stop condition is saturation", stopped.condition is StopCondition.SATURATION)
    add("the stop names the series it judged", stopped.added_per_round == [4, 0, 0])
    add("one empty round does not yet stop", not assess_saturation([4, 0]).stopped)
    add("a mission that keeps learning is not stopped",
        not assess_saturation([2, 3, 1]).stopped)
    add("the stop reason mentions the empty rounds", "consecutive" in stopped.stop_reason,
        stopped.stop_reason)

    # -- 5. the flow uses it: the acceptance clause, on real graph runs --------
    context = _selftest_context("exposure")
    units = _looping_units(context, attempts=3)
    # Three attempts, so the ladder runs to its end inside one mission: the first
    # repeat is corrected, the second is blocked, and no fourth attempt is issued.
    runner = _CountingRunner(scope=context.scope_entries, repeat_queries=True,
                             always_retry=workers_of(units))
    repeating = HierarchicalFlow(
        context=context, subagents=units, runner=runner,
        policy=FlowPolicy(allow_runtime_workers=False, max_review_rounds=3,
                          max_replan_rounds=1))
    repeated_result = repeating.run()
    ledger = repeating._loops
    add("a repeating unit is detected on the graph's own record", bool(ledger.findings),
        ledger.describe())
    add("the first repetition is corrected rather than blocked",
        bool(ledger.corrections), [change.kind.value for change in ledger.corrections])
    add("the correction is carried by the retask the next attempt ran under",
        any(change.instruction in (retask.prompt or "")
            for change in ledger.corrections for retask in repeating.retasks()),
        len(repeating.retasks()))
    add("every correction names a change of strategy, not a retry",
        all("Change of strategy required" in retask.prompt
            for change in ledger.corrections for retask in repeating.retasks()
            if change.instruction in (retask.prompt or "")))
    add("the retask that carries the correction is a different instruction",
        not any(a.fingerprint == b.fingerprint
                for a, b in zip(repeating.retasks(), repeating.retasks()[1:])
                if a.worker_id == b.worker_id))
    add("the run reports the loop rather than only logging it",
        repeated_result.loops is not None
        and repeated_result.loop_summary.get("corrections") is not None)
    add("a corrected unit is asked no more than its attempts allow",
        all(sum(1 for retask in repeating.retasks() if retask.worker_id == worker_id) <= 2
            for worker_id in workers_of(units)))

    stubborn_units = _looping_units(context, attempts=4)
    stubborn = HierarchicalFlow(
        context=context, subagents=stubborn_units,
        runner=_CountingRunner(scope=context.scope_entries, repeat_queries=True,
                               always_retry=workers_of(stubborn_units)),
        policy=FlowPolicy(allow_runtime_workers=False, max_review_rounds=4,
                          max_replan_rounds=1))
    stubborn_result = stubborn.run()
    blocked_lines = stubborn._loops.blocked
    add("a unit that repeats after its correction is blocked", bool(blocked_lines),
        [line.subject for line in blocked_lines])
    blocked_ids = {line.unit for line in blocked_lines}
    ran = {}
    for event in stubborn.trace.to_list():
        if event.get("stage") == FlowStage.WORKER.value and event.get("unit") in blocked_ids:
            ran[event["unit"]] = ran.get(event["unit"], 0) + 1
    add("a blocked branch runs no further attempt",
        all(ran.get(line.unit) == line.attempts for line in blocked_lines), ran)
    add("a blocked branch is issued no further retask",
        all(not any(retask.worker_id == line.unit and retask.attempt > line.attempts
                    for retask in stubborn.retasks()) for line in blocked_lines),
        len(stubborn.retasks()))
    add("a blocked line becomes a report gap", bool(cycle_gaps(blocked_lines)))
    add("the block says what would unblock it",
        all(len(line.unblock) > 10 for line in blocked_lines))
    add("a blocked mission is still reviewed", bool(stubborn.master_reviews()))
    add("a correction with no attempt left is recorded as not applied", all(
        change.applied or any("not applied" in str(event.get("detail", ""))
                              for event in repeated_result.trace)
        for change in ledger.corrections), [(c.unit, c.applied) for c in ledger.corrections])
    add("the block stops the branch before its last allowed attempt",
        all(sum(1 for retask in stubborn.retasks()
                if retask.worker_id == line.unit) < 3
            for line in blocked_lines), len(stubborn.retasks()))
    add("every blocked line names the attempt that ended it",
        all(line.attempts >= 2 for line in blocked_lines))
    add("a blocked line reaches the report as a gap", any(
        "line of inquiry blocked" in (gap.detail or "")
        for gap in (stubborn_result.synthesis.gaps if stubborn_result.synthesis else [])),
        len(stubborn_result.synthesis.gaps) if stubborn_result.synthesis else 0)
    add("an unbounded runtime objective is refused", raises(lambda: RuntimePlan(
        subagent_id="sa-1", gap="the advisory history is missing",
        name="read-everything", target="the published advisories",
        objective="keep reading the advisories until there is nothing left",
        work_unit="advisories", tools=["evidence.read"],
        expected_evidence="every advisory", completion_criteria=["all read"],
        source="criterion", rationale="the gap names an advisory history"), ValueError))
    add("the result serialises the loop ledger",
        json.loads(json.dumps(repeated_result.to_dict(), default=str))
        ["loops"]["summary"]["kinds"] is not None)
    add("every stop the flow records has a reason", all(
        decision.condition is StopCondition.NONE or decision.basis
        for decision in repeated_result.master_decisions))
    return checks


#: A target a plan can aim at, used by the fingerprint checks.  Separate from the
#: objective prose on purpose: a plan is what is aimed at, with what, as which unit.
def units_of_work() -> str:
    return "the published advisories for example.com"


def _looping_units(context: "MasterContext", *, attempts: int) -> list[FlowSubagent]:
    """The mission's own plan, with every unit allowed ``attempts`` tries.

    A copy, so raising the budget for one check does not change the plan the other
    checks run against — and so the ladder can be walked to its end without the
    attempt cap cutting it short first.
    """

    units = flow_units_for(context, "exposure")
    return [subagent.model_copy(update={
        "workers": [worker.model_copy(update={"max_attempts": attempts})
                    for worker in subagent.workers]}) for subagent in units]


def workers_of(units: Sequence[FlowSubagent]) -> list[str]:
    """Every Worker id in a plan, for a runner that must fail or retry all of them."""

    return [worker.id for subagent in units for worker in subagent.workers]

# --------------------------------------------------------------------------
# 39.4 The demo and its checks: the document, and the sentences it refuses
# --------------------------------------------------------------------------

class SynthesisCheck(StrictModel):
    """One assertion in the §39 self-test."""

    name: str = Field(min_length=1)
    ok: bool
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "ok": self.ok, "detail": self.detail}


def _synthesis_report(role: str, statements: Sequence[str], *, hosts: Sequence[str] = (),
                      kind: EvidenceKind = EvidenceKind.OBSERVATION,
                      worker: str = "wrk-syn", gap: str = "",
                      disagreement: "Disagreement | None" = None) -> "SubagentOutcome":
    """A reviewed Subagent report whose items carry *real* source hosts.

    The hosts matter: corroboration is counted by origin, so a fixture with no URLs could
    not tell a single-source finding from a corroborated one, and every check about bands
    would be proving something about the fixture instead of about the rule.
    """

    evidence: list[EvidenceItem] = []
    for number, statement in enumerate(statements):
        host = hosts[number % len(hosts)] if hosts else f"{role}.test"
        evidence.append(EvidenceItem(
            id=content_id("ev", role, statement, number, length=10), kind=kind,
            statement=statement,
            sources=[SourceReference(
                kind=SourceKind.PUBLIC_WEB, url=f"https://{host}/record/{number}",
                title=f"{role} record", retrieved_at=datetime(2026, 5, 4, 10, 0,
                                                             tzinfo=timezone.utc),
                retrieval_method=RetrievalMethod.HTTP, http_status=200)],
            confidence=Confidence.LOW,
            confidence_basis="one retrieval of a published record",
            # An allegation is a third party's claim, and the record has to say whose: the
            # synthesis may report it, and may not upgrade it to an observation.
            allegation_made_by="a public forum post" if kind is EvidenceKind.ALLEGATION else None,
            collected_by=worker))
    outcome = WorkerOutcome(
        worker_id=worker, subagent_id=content_id("sa", role, length=12),
        status=EntityStatus.SUCCEEDED, attempt=1,
        summary=f"{worker}: {len(evidence)} observation(s) collected",
        evidence_ids=[item.id for item in evidence])
    return SubagentOutcome(
        subagent_id=content_id("sa", role, length=12), role=role, objective=role,
        status=EntityStatus.SUCCEEDED, outcomes=[outcome], evidence=evidence,
        aggregate_basis=check_join(f"subagent-aggregate:{role}", [worker], [worker]),
        gaps=[UnknownValue(reason=UnknownReason.NOT_PUBLISHED, determined_by=role,
                           detail=gap)] if gap else [],
        disagreements=[disagreement] if disagreement is not None else [])


def synthesis_cases() -> dict[str, Any]:
    """Three report sets: one corroborated, one conflicting, one single-source.

    They differ only in *origins*, so the checks can hold the statements fixed and vary
    what the mission knows: a rule that assigned the same band to all three would be
    visible as a failure rather than as a coincidence.
    """

    shared = "the edge gateway runs firmware 7.2 and the advisory names its session handling"
    second = "the edge gateway failed its last configuration review on 2026-03-02"
    negated = "the edge gateway never ran firmware 7.2"
    corroborated = [
        _synthesis_report("advisories", [shared], hosts=["advisory.test", "mirror.test"],
                          worker="wrk-adv"),
        _synthesis_report("records", [shared, second],
                          hosts=["mirror.test", "registry.test"], worker="wrk-rec")]
    conflicting = [
        _synthesis_report("advisories", [shared], hosts=["advisory.test", "mirror.test"],
                          worker="wrk-adv"),
        _synthesis_report("records", [negated], hosts=["registry.test"], worker="wrk-rec")]
    single = [_synthesis_report("advisories", [shared], hosts=["advisory.test"],
                                worker="wrk-adv")]
    third = "the archive holds four snapshots of the same page (2026-01-04 to 2026-04-11)"
    third_party = [_synthesis_report("forums", [shared], hosts=["forum.test"],
                                     kind=EvidenceKind.ALLEGATION, worker="wrk-frm")]
    return {"corroborated": corroborated, "conflicting": conflicting,
            "single": single, "allegation": third_party,
            "shared": shared, "second": second, "negated": negated, "third": third}


def _synthesis_context() -> "MasterContext":
    """The mission the synthesis fixtures belong to: one question, one criterion."""

    return MasterContext(
        objective="map the publicly documented exposure of example.com and rank the "
                  "advisory-backed risks",
        scope_entries=["example.com"],
        available_tools=["http.fetch", "advisory.read"],
        completion_criteria=["every finding cites a published advisory"],
        mission_questions=["the published advisories name the affected component"])


def synthesis_demo() -> dict[str, Any]:
    """Assemble the document three ways and show what each one refuses."""

    cases = synthesis_cases()
    context = _synthesis_context()
    corroborated = synthesise_report(cases["corroborated"], context=context,
                                     mission_id="msn-demo-corrob")
    conflicting = synthesise_report(cases["conflicting"], context=context,
                                    mission_id="msn-demo-conflict")
    single = synthesise_report(cases["single"], context=context, mission_id="msn-demo-single")

    refusals: list[dict[str, str]] = []

    def attempt(name: str, fn: Callable[[], Any]) -> None:
        # Both refusal kinds count: a pydantic constraint (a finding with no citation) and
        # a synthesis rule (a conclusion above its evidence) are the same answer to the
        # caller — the document cannot say this — so the demo reports the reason, not the
        # exception class.  An exception of any *other* kind would be a bug, and the
        # self-test asserts that none is raised.
        try:
            fn()
        except (SynthesisConflict, ValueError) as exc:
            refusals.append({"probe": name, "refused": _first_sentence(str(exc))[:220]})
        else:
            refusals.append({"probe": name, "refused": "NOT REFUSED"})

    attempt("a finding that cites nothing", lambda: KeyFinding(
        statement="the gateway is exposed to the advisory", evidence_ids=[],
        band=ConfidenceBand.SINGLE_SOURCE, confidence=Confidence.LOW,
        confidence_basis="one retrieval", origins=1, falsifier="a patched build"))
    attempt("a single-source finding promoted to high", lambda: KeyFinding(
        statement="the gateway is exposed to the advisory", evidence_ids=["ev-1"],
        band=ConfidenceBand.SINGLE_SOURCE, confidence=Confidence.HIGH,
        confidence_basis="one retrieval", origins=1, falsifier="a patched build"))
    attempt("an allegation reported as well-corroborated", lambda: KeyFinding(
        statement="a forum states the gateway is exposed to the advisory",
        evidence_ids=["ev-1"], kind=EvidenceKind.ALLEGATION,
        band=ConfidenceBand.WELL_CORROBORATED, confidence=Confidence.HIGH,
        confidence_basis="three posts repeat it", origins=3, falsifier="the forum retracts"))
    attempt("a declaration of guilt", lambda: KeyFinding(
        statement="the contractor is guilty of exposing the gateway",
        evidence_ids=["ev-1"], band=ConfidenceBand.SINGLE_SOURCE,
        confidence=Confidence.LOW, confidence_basis="one retrieval", origins=1,
        falsifier="a patched build"))
    attempt("a certainty about identity", lambda: HypothesisRow(
        statement="the administrator is the person who changed the configuration",
        status="untested", test="compare the audit log against the change window"))
    attempt("a next step that widens the scope", lambda: NextStep(
        action="scan the neighbouring netblock for the same firmware",
        addresses="gap-1", basis="the same operator", within_scope=False))
    attempt("a next step that is not passive", lambda: NextStep(
        action="log in to the gateway and read its configuration",
        addresses="gap-1", basis="the operator owns it", passive=False))

    signals = {
        "every finding cites evidence ids": all(
            finding.cited for finding in corroborated.findings),
        "no conclusion exceeds its evidence": corroborated.acceptance()[
            "no_conclusion_exceeds_its_evidence"],
        "two origins corroborate a claim": bool(corroborated.indicators),
        "a contradiction is preserved, not settled": bool(conflicting.conflicts),
        "a single-source mission reports low confidence":
            single.confidence is Confidence.LOW,
        "the acceptance clause holds for the assembled report":
            all(corroborated.acceptance()[key] for key in
                ("every_finding_cited", "no_conclusion_exceeds_its_evidence",
                 "all_sections_present", "no_attribution")),
        "every refusal is a sentence a reader can act on": all(
            refusal["refused"] != "NOT REFUSED" for refusal in refusals),
        "no finding declares guilt": all(
            "guilty" not in finding.statement.lower()
            for report in (corroborated, conflicting, single)
            for finding in report.findings),
        "ten sections, all filled": len(corroborated.sections) == len(REQUIRED_SECTIONS)
            and all(section.filled for section in corroborated.sections),
        # The summary may count what is still open; it may never claim to have excluded
        # the alternatives, because exclusion needs evidence and this line has none.
        "the summary counts what is open, not what it has excluded":
            "remain open" in corroborated.section_of("executive-summary").body
            and "remain possible" not in corroborated.section_of("executive-summary").body,
    }
    return {
        "objective": context.objective,
        "reports": {"corroborated": corroborated.to_dict(),
                    "conflicting": conflicting.to_dict(),
                    "single": single.to_dict()},
        "bands": {name: {band.value: sum(1 for finding in report.findings
                                         if finding.band is band)
                         for band in ConfidenceBand}
                  for name, report in (("corroborated", corroborated),
                                       ("conflicting", conflicting),
                                       ("single", single))},
        "conflicts": [record.describe() for record in conflicting.conflicts],
        "indicators": [row.statement for row in corroborated.indicators],
        "refusals": refusals,
        "signals": signals,
        "acceptance": {"all_signals": all(signals.values()), "signals": signals},
    }


def render_synthesis_demo(payload: Mapping[str, Any]) -> Group:
    """The demo, as a reader sees it: what the document says, and what it refuses to."""

    bands = Table(title="the same claim, three evidence bases", title_justify="left",
                  box=None, pad_edge=False, expand=False)
    bands.add_column("report", no_wrap=True)
    for band in ConfidenceBand:
        bands.add_column(band.value, no_wrap=True)
    for name, counts in payload["bands"].items():
        bands.add_row(escape(name), *[str(counts[band.value]) for band in ConfidenceBand])

    refusals = Table(title="sentences the synthesis refuses", title_justify="left",
                     box=None, pad_edge=False, expand=False)
    refusals.add_column("probe", overflow="fold", max_width=34)
    refusals.add_column("refused because", overflow="fold", max_width=64)
    for entry in payload["refusals"]:
        refusals.add_row(escape(entry["probe"]), escape(entry["refused"]))

    signals = Table(title="acceptance", title_justify="left", box=None, pad_edge=False,
                    expand=False)
    signals.add_column("check", overflow="fold")
    signals.add_column("ok", no_wrap=True)
    for name, ok in payload["signals"].items():
        signals.add_row(escape(name), "[green]✔[/green]" if ok else "[red]✘[/red]")

    tail = Text("a finding cites what carries it, confidence is counted rather than "
                "claimed, and no sentence names who is guilty", style="dim")
    return Group(bands, Text(""), refusals, Text(""), signals, Text(""), tail)


def run_synthesis_self_test() -> list[SynthesisCheck]:
    """Prove §39's acceptance clause: every finding cited, no conclusion above its evidence.

    Five groups, because five different things must hold: the bands are derived rather
    than declared, the refusals are real, the document is complete, the record is
    preserved (contradictions, gaps, hypotheses), and the graph attaches the document to
    the mission it synthesised.
    """

    checks: list[SynthesisCheck] = []

    def add(name: str, ok: Any, detail: Any = "") -> None:
        checks.append(SynthesisCheck(name=name, ok=bool(ok), detail=str(detail)[:150]))

    def raises(fn: Callable[[], Any], exc: type[BaseException]) -> bool:
        try:
            fn()
        except exc:
            return True
        except Exception:                     # noqa: BLE001 - the wrong error is a failure
            return False
        return False

    cases = synthesis_cases()
    context = _synthesis_context()
    shared = cases["shared"]

    # -- 1. the index: ids, origins and sameness ------------------------------
    index = EvidenceIndex.of([item for report in cases["corroborated"]
                              for item in report.evidence])
    add("the index holds every reviewed item", len(index.items) == 3, len(index.items))
    add("two hosts are two origins",
        len({origin for item in index.items for origin in item.origins}) == 3,
        [item.origins for item in index.items])
    add("a duplicate statement is one claim", len(index.statement_ids(shared)) == 2,
        len(index.statement_ids(shared)))
    add("a claim with two origins is corroborated", index.count_statement(shared) == 2,
        index.count_statement(shared))
    add("an id the mission never collected is refused",
        raises(lambda: index.get("ev-does-not-exist"), SynthesisConflict))

    # -- 2. the bands: derived, capped, and never chosen ----------------------
    one = EvidenceIndex.of(cases["single"][0].evidence)
    add("one origin is single-source",
        one.items[0].ceiling() is ConfidenceBand.SINGLE_SOURCE)
    corroborated_index = EvidenceIndex.of(
        [item for report in cases["corroborated"] for item in report.evidence])
    claim_origins = _claim_origins(corroborated_index)
    corroborated_findings = [_finding_for(item, origins=claim_origins.get(item.signature, ()))
                             for item in corroborated_index.items]
    add("two origins corroborate the claim they share",
        any(finding.band.rank >= ConfidenceBand.CORROBORATED.rank
            for finding in corroborated_findings),
        [(finding.statement[:30], finding.band.value) for finding in corroborated_findings])
    allegation = EvidenceIndex.of(cases["allegation"][0].evidence)
    add("an allegation is capped at corroborated",
        allegation.items[0].ceiling().rank <= ConfidenceBand.CORROBORATED.rank,
        allegation.items[0].ceiling().value)
    add("the band's confidence is the coarse confidence",
        ConfidenceBand.SINGLE_SOURCE.confidence is Confidence.LOW
        and ConfidenceBand.CORROBORATED.confidence is Confidence.MEDIUM
        and ConfidenceBand.WELL_CORROBORATED.confidence is Confidence.HIGH)
    add("a finding cannot state a confidence above its band", raises(lambda: KeyFinding(
        statement="the gateway runs firmware 7.2", evidence_ids=["ev-1"],
        band=ConfidenceBand.SINGLE_SOURCE, confidence=Confidence.HIGH,
        confidence_basis="one retrieval", origins=1, falsifier="a patched build"),
        SynthesisConflict))
    add("an allegation cannot be reported as well-corroborated", raises(lambda: KeyFinding(
        statement="a forum states the gateway runs firmware 7.2", evidence_ids=["ev-1"],
        kind=EvidenceKind.ALLEGATION, band=ConfidenceBand.WELL_CORROBORATED,
        confidence=Confidence.HIGH, confidence_basis="repeated on one forum", origins=3,
        falsifier="the forum retracts"), SynthesisConflict))
    add("an inference cannot be reported as well-corroborated", raises(lambda: KeyFinding(
        statement="the gateway was probably patched after the advisory",
        evidence_ids=["ev-1"], kind=EvidenceKind.INFERENCE,
        band=ConfidenceBand.WELL_CORROBORATED, confidence=Confidence.HIGH,
        confidence_basis="three origins agree", origins=3, falsifier="the build date"),
        SynthesisConflict))

    # -- 3. the refusals: the sentences a report may not contain --------------
    add("a finding must cite at least one id", raises(lambda: KeyFinding(
        statement="the gateway is exposed to the advisory", evidence_ids=[],
        band=ConfidenceBand.SINGLE_SOURCE, confidence=Confidence.LOW,
        confidence_basis="one retrieval", origins=1, falsifier="a patched build"),
        SynthesisConflict))
    add("an uncited finding is refused with a reason a reader can act on", raises(
        lambda: KeyFinding(statement="the gateway is exposed to the advisory",
                           evidence_ids=["  "], band=ConfidenceBand.SINGLE_SOURCE,
                           confidence=Confidence.LOW, confidence_basis="one retrieval",
                           origins=1, falsifier="a patched build"),
        SynthesisConflict))
    add("a declaration of guilt is refused", raises(lambda: check_attribution(
        "the contractor is guilty"), SynthesisConflict))
    add("naming an attacker is refused", raises(lambda: check_attribution(
        "the attacker used the advisory"), SynthesisConflict))
    add("describing indicia is allowed", not raises(lambda: check_attribution(
        "the login came from an address the domain does not publish"), SynthesisConflict))
    add("a certain identity claim is refused", raises(lambda: check_identity_claim(
        "the administrator is the person who changed the configuration"),
        SynthesisConflict))
    add("an identity hypothesis with a basis is allowed", not raises(
        lambda: check_identity_claim(
            "one hypothesis is that the administrator changed the configuration; "
            "no evidence establishes it and the audit log would decide"),
        SynthesisConflict))
    add("a next step that widens scope is refused", raises(lambda: NextStep(
        action="scan the neighbouring netblock", addresses="gap-1",
        basis="the same operator", within_scope=False), SynthesisConflict))
    add("a next step that is not passive is refused", raises(lambda: NextStep(
        action="log in to the gateway and read the configuration", addresses="gap-1",
        basis="the operator owns it", passive=False), SynthesisConflict))
    add("a lawful next step is accepted", not raises(lambda: NextStep(
        action="read the advisory archive for the affected version", addresses="gap-1",
        basis="passive collection from example.com"), SynthesisConflict))

    # -- 4. the document ------------------------------------------------------
    report = synthesise_report(cases["corroborated"], context=context)
    add("the report has all ten sections",
        [section.kind for section in report.sections]
        == [kind for kind, _title in REQUIRED_SECTIONS],
        [section.kind for section in report.sections])
    add("every section says something", all(section.filled for section in report.sections),
        [section.kind for section in report.sections if not section.filled])
    add("every finding cites evidence", all(finding.cited for finding in report.findings))
    add("every citation is in the mission's evidence",
        all(item_id in {item.id for item in index.items}
            for item_id in report.cited_ids), report.cited_ids)
    add("the acceptance clause is evaluated, not asserted",
        report.acceptance()["every_finding_cited"]
        and report.acceptance()["no_conclusion_exceeds_its_evidence"]
        and report.acceptance()["all_sections_present"]
        and report.acceptance()["no_attribution"], report.acceptance())
    add("one claim is one finding, however many rows carry it",
        len(report.findings) == len({item.signature for item in
                                     EvidenceIndex.of([i for r in cases["corroborated"]
                                                       for i in r.evidence]).items}),
        len(report.findings))
    add("a corroborated finding cites both of its rows",
        all(len(finding.evidence_ids) >= 2 for finding in report.findings
            if finding.band.rank >= ConfidenceBand.CORROBORATED.rank),
        [(f.statement[:20], f.evidence_ids) for f in report.findings])
    add("a corroborated claim appears as an indicator", bool(report.indicators),
        [row.statement[:40] for row in report.indicators])
    add("the confidence is the weakest finding, not the strongest",
        report.confidence is Confidence.LOW
        and any(finding.confidence is Confidence.MEDIUM for finding in report.findings),
        [(finding.band.value) for finding in report.findings])

    conflicting = synthesise_report(cases["conflicting"], context=context)
    add("a contradiction is preserved rather than settled", bool(conflicting.conflicts),
        [record.describe()[:80] for record in conflicting.conflicts])
    add("a contradiction names what would settle it",
        all(len(record.resolution) > 10 for record in conflicting.conflicts))
    add("a contradiction cites both sides",
        all(record.left_evidence and record.right_evidence
            for record in conflicting.conflicts))

    single = synthesise_report(cases["single"], context=context)
    add("a single-source mission is single-source", single.confidence is Confidence.LOW)
    add("a single-source mission claims no indicator", not single.indicators)
    add("a gap becomes a gap record with its consequence",
        all(gap.consequence for gap in single.gaps))
    add("the summary is written from the sections", "finding(s)" in
        (single.section_of("executive-summary").body or ""))

    partial = synthesise_report([], context=context)
    add("a mission with no evidence still reports", bool(partial.sections))
    add("a mission with no evidence states the gap", bool(partial.gaps))
    add("a mission with no evidence claims no finding", not partial.findings)
    add("a mission with no evidence states no confidence",
        partial.confidence is Confidence.UNKNOWN, partial.confidence.value)

    # -- 5. the graph uses it -------------------------------------------------
    ctx = _selftest_context("exposure")
    units = flow_units_for(ctx, "exposure")
    flow = HierarchicalFlow(context=ctx, subagents=units,
                            runner=_CountingRunner(scope=ctx.scope_entries),
                            policy=FlowPolicy(allow_runtime_workers=False,
                                              max_replan_rounds=0))
    result = flow.run()
    attachment = result.synthesis.report if result.synthesis else None
    add("the flow attaches the report to its synthesis", attachment is not None)
    add("the attached report is complete",
        attachment is not None and all(section.filled for section in attachment.sections))
    add("the attached report cites only the mission's evidence",
        attachment is not None and all(
            item_id in {item.id for report in result.reports for item in report.evidence}
            for item_id in attachment.cited_ids),
        attachment.cited_ids if attachment else "")
    add("the report names the hypotheses the mission had", bool(
        attachment and attachment.hypotheses))
    add("the report recommends only lawful steps", bool(
        attachment and attachment.next_steps and all(
            step.passive and step.within_scope and step.authorised
            for step in attachment.next_steps)))
    add("the reported mission serialises the document",
        "report" in json.loads(json.dumps(result.to_dict(), default=str))["synthesis"])

    # a mission whose loops blocked a line reports it as withheld, not as silence
    looping_units = _looping_units(ctx, attempts=3)
    stubborn = HierarchicalFlow(
        context=ctx, subagents=looping_units,
        runner=_CountingRunner(scope=ctx.scope_entries, repeat_queries=True,
                               always_retry=workers_of(looping_units)),
        policy=FlowPolicy(allow_runtime_workers=False, max_review_rounds=3,
                          max_replan_rounds=0))
    stubborn_result = stubborn.run()
    stubborn_report = stubborn_result.synthesis.report if stubborn_result.synthesis else None
    add("a blocked line is withheld in the report",
        stubborn_report is not None and any(
            "blocked" in line for line in stubborn_report.withheld),
        stubborn_report.withheld[:2] if stubborn_report else None)
    add("a blocked mission still produces a complete report",
        stubborn_report is not None
        and all(section.filled for section in stubborn_report.sections))
    return checks
@app.command("synthesis",
             help="Evidence-based Master synthesis: ten sections, every finding cited.")
def synthesis_command(
    self_test: bool = typer.Option(False, "--self-test",
                                   help="Prove the report's calibration and completeness."),
    demo: bool = typer.Option(False, "--demo",
                              help="The same claim over three evidence bases, and what is refused."),
    reports: str | None = typer.Option(
        None, "--reports",
        help="Synthesise a mission's reviewed reports from JSON ('-' for stdin)."),
    objective: str = typer.Option(
        "", "--objective", "-o",
        help="The mission objective the report answers (overrides the file's)."),
    question: str = typer.Option("", "--question", help="The question the mission set itself."),
    limitations: str = typer.Option(
        "", "--limitation", help="A limitation to carry into the report (repeatable)."),
    as_json: bool = typer.Option(False, "--json", help="Emit machine-readable JSON."),
) -> None:
    """Assemble the mission's document, or prove that it cannot overstate it.

    Exit codes: ``OK`` when the report is complete and every finding is calibrated,
    ``POLICY`` when a report was produced but does not meet its own acceptance clause —
    which is a defect in the evidence or in a citation, not a mission failure, and is
    reported rather than swallowed.
    """

    console = get_console()

    if self_test:
        checks = run_synthesis_self_test()
        failures = [check for check in checks if not check.ok]
        if as_json:
            _emit(json.dumps({"checks": [check.to_dict() for check in checks],
                              "passed": len(checks) - len(failures),
                              "failed": len(failures)}, indent=2, default=str))
            raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)
        table = Table(box=None, pad_edge=False)
        table.add_column("check", overflow="fold")
        table.add_column("detail", overflow="fold")
        for check in checks:
            glyph, colour = ("✔", "green") if check.ok else ("✘", "red")
            table.add_row(f"{glyph} {escape(check.name)}", escape(check.detail))
        console.print(table)
        colour = "green" if not failures else "red"
        console.print(f"\n[{colour}]{len(checks) - len(failures)} passed[/] · "
                      f"{len(failures)} failed\n")
        raise typer.Exit(ExitCode.OK if not failures else ExitCode.INTERNAL)

    if demo:
        payload = synthesis_demo()
        if as_json:
            _emit(json.dumps(payload, indent=2, default=str))
            raise typer.Exit(ExitCode.OK)
        console.print()
        console.print(render_synthesis_demo(payload))
        console.print()
        raise typer.Exit(ExitCode.OK)

    if reports:
        try:
            raw = (sys.stdin.read() if reports == "-"
                   else Path(reports).expanduser().read_text(encoding="utf-8"))
            payload = json.loads(raw)
        except (OSError, json.JSONDecodeError) as exc:
            console.print(f"[red]✘[/red] not a mission report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        try:
            reviewed = [SubagentOutcome.model_validate(item)
                        for item in payload.get("reports") or []]
            mission = (objective or str(payload.get("objective") or ""))
            asked = question or str((payload.get("questions") or [""])[0] or "")
            scope = [str(item) for item in payload.get("scope") or []]
        except (KeyError, ValueError) as exc:
            console.print(f"[red]✘[/red] not a mission report set: "
                          f"{escape(_first_sentence(str(exc))[:200])}")
            raise typer.Exit(ExitCode.USAGE) from exc
        if not mission:
            console.print("[red]✘[/red] the report needs an objective: pass --objective")
            raise typer.Exit(ExitCode.USAGE)
        context = MasterContext(objective=mission, scope_entries=scope,
                                mission_questions=[asked] if asked else [])
        notes = [item for item in limitations.split("|") if item.strip()]
        report = synthesise_report(reviewed, context=context, question=asked,
                                   limitations=notes)
        acceptance = report.acceptance()
        ok = all(value for key, value in acceptance.items() if isinstance(value, bool))
        if as_json:
            _emit(json.dumps(report.to_dict(), indent=2, default=str))
            raise typer.Exit(ExitCode.OK if ok else ExitCode.POLICY)
        console.print()
        console.print(render_master_report(report))
        console.print()
        raise typer.Exit(ExitCode.OK if ok else ExitCode.POLICY)

    console.print("[red]✘[/red] choose --demo, --self-test or --reports FILE")
    raise typer.Exit(ExitCode.USAGE)


if __name__ == "__main__":
    process_entry()
